class Main {
  import java.io._
  import java.util.StringTokenizer

  import scala.collection.mutable
  import scala.util.Sorting
  import math.{abs, max, min}
  import mutable.{ArrayBuffer, ListBuffer}
  import scala.reflect.ClassTag
  import scala.Console

  val MOD = 1000000007

  val pow2 = Array.ofDim[Int](10)
  pow2(0) = 1
  rep(pow2.length - 1)(i => pow2(i + 1) = pow2(i) * 2)

  def solve(): Unit = {
    val H, W, K = ni()

    val dp = Array.ofDim[Int](H + 1, W)
    dp(0)(0) = 1
    rep(H, 1) { i =>
      rep(pow2(W - 1)) { bit =>
        if ((bit & bit << 1) == 0) {
          rep(W) { j =>
            val l = (1 << j - 1 & bit) > 0
            val r = (1 << j & bit) > 0
            if (!l && !r) {
              dp(i)(j) += dp(i - 1)(j)
            } else if (l && !r) {
              dp(i)(j) += dp(i - 1)(j - 1)
            } else if (!l && r) {
              dp(i)(j) += dp(i - 1)(j + 1)
            }
            if (dp(i)(j) >= MOD) dp(i)(j) -= MOD
          }
        }
      }
    }

    println(dp(H)(K - 1))
  }


  class InputReader(reader: BufferedReader) {
    private var tokenizer: StringTokenizer = _

    def next(): String = {
      while (tokenizer == null || !tokenizer.hasMoreTokens)
        tokenizer = new StringTokenizer(reader.readLine)
      tokenizer.nextToken
    }

    def nextInt(): Int = next().toInt
    def nextLong(): Long = next().toLong
    def nextChar(): Char = next().charAt(0)
  }
  val sc = new InputReader(Console.in)
  def ni(): Int = sc.nextInt()
  def nl(): Long = sc.nextLong()
  def nc(): Char = sc.nextChar()
  def ns(): String = sc.next()
  def ns(n: Int): Array[Char] = ns().toCharArray
  def na(n: Int, offset: Int = 0): Array[Int] = map(n)(_ => ni() + offset)
  def na2(n: Int, offset: Int = 0): (Array[Int], Array[Int]) = {
    val A1, A2 = Array.ofDim[Int](n)
    rep(n) { i =>
      A1(i) = ni() + offset
      A2(i) = ni() + offset
    }
    (A1, A2)
  }
  def nm(n: Int, m: Int): Array[Array[Int]] = {
    val A = Array.ofDim[Int](n, m)
    rep(n) { i =>
      rep(m) { j =>
        A(i)(j) = ni()
      }
    }
    A
  }
  def nal(n: Int): Array[Long] = map(n)(_ => nl())
  def nm_c(n: Int, m: Int): Array[Array[Char]] = map(n) (_ => ns(m))
  def rep(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = offset
    val N = n + offset
    while(i < N) { f(i); i += 1 }
  }
  def rep_r(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = n - 1 + offset
    while(i >= offset) { f(i); i -= 1 }
  }

  def map[@specialized A: ClassTag](n: Int)(f: Int => A): Array[A] = {
    val res = Array.ofDim[A](n)
    rep(n)(i => res(i) = f(i))
    res
  }

  def sumL(as: Array[Int]): Long = {
    var s = 0L
    rep(as.length)(i => s += as(i))
    s
  }

  def cumSum(as: Array[Int]) = {
    val cum = Array.ofDim[Int](as.length + 1)
    rep(as.length) { i =>
      cum(i + 1) = cum(i) + as(i)
    }
    cum
  }
}

object Main extends App {

  import scala.io.StdIn._

  val mod = 1000000007L

  val Array(h, w, k) = readLine.trim.split(' ').map(_.toInt)

  implicit val fibonacci = Array.tabulate(w + 3){_ ⇒ 1L}
  fibonacci(1) = 2L
  for (i ← 2 until w){
    fibonacci(i) = (fibonacci(i - 2) + fibonacci(i - 1)) % mod
  }
  println(
    search(h, w, k)
  )
  implicit class ScopeFunc[T](val value: T) {
    def let[A](func: T ⇒ A): A = func(value)
    def also(func: T ⇒ Unit): T = {
      func(value)
      value
    }
  }

  def calUseHorizontal(w: Int, pos: Int)(implicit fibonacci: Array[Long]): Long = {
    w match {
      case _ if !(1 until w).contains(pos) ⇒ 0L
      case 2 ⇒ 1L
      case _ if pos == 1 || pos == w - 1 ⇒ fibonacci(w - 3)
      case _ ⇒ (fibonacci(pos - 1) * fibonacci(w - 1 - (pos + 1))) % mod
    }
  }
  def calNotMoveVertical(w: Int, pos: Int)(implicit fibonacci: Array[Long]): Long = {
    w match {
      case _ if !(1 to w).contains(pos) ⇒ 0L
      case 1 ⇒ 1L
      case _ if pos == 1 || pos == w ⇒ fibonacci(w - 2)
      case _ ⇒ (fibonacci(pos - 1) * fibonacci(w - 1 - pos)) % mod
    }
  }
  def search(h: Int, w: Int, k: Int)(implicit memo: Array[Array[Option[Long]]] = Array.tabulate(h + 1){_ ⇒ Array.tabulate(w + 1){_ ⇒ None: Option[Long]}}): Long = {
    if (h == 0 && k == 1) 1L
    else if (h == 0) 0L
    else if (!(1 to w).contains(k)) 0L
    else {
      memo(h)(k) match {
        case Some(r) ⇒ r
        case None ⇒ {
          (search(h - 1, w, k + 1) * calUseHorizontal(w, k) % mod + search(h - 1, w, k - 1) * calUseHorizontal(w, k - 1) % mod + search(h - 1, w, k) * calNotMoveVertical(w, k) % mod).let{_ % mod}.also{it ⇒
            memo(h)(k) = Some(it)
          }
        }
      }
    }
  }
}

