      value
    }
  }
  def calUseHorizontal(w: Int, pos: Int)(implicit fibonacci: Array[Long]): Long = {
    if (!(1 until w).contains(pos)) 0L
    else {
      if (pos == 1 || pos == w - 1) if (w >= 3) fibonacci(w - 3) else 1L
      else fibonacci(pos - 2) * fibonacci(w - pos - 2) % mod
    }
  }
  def calNotUse(w: Int, pos: Int)(implicit fibonacci: Array[Long]): Long = {
    if (!(1 to w).contains(pos)) 0L
    else {
      if (pos == 1 || pos == w) if (w >= 2) fibonacci(w - 2) else 1L
      else fibonacci(pos - 2) * fibonacci(w - 1 - pos) % mod
    }
  }
  def calPat(h: Int, w: Int, k: Int)(implicit memo: Array[Array[Option[Long]]] = Array.tabulate(h + 1){_ ⇒ Array.tabulate(w + 1){_ ⇒ None:Option[Long]}}): Long = {
    if (h == 0) if (k == 1) 1L else 0L
    else if (!(1 to w).contains(k)) 0L
    else {
      memo(h)(k) match {
        case Some(r) ⇒ r
        case None ⇒ {
          (calPat(h - 1, w, k + 1) * calUseHorizontal(w, k) + calPat(h - 1, w, k - 1) * calUseHorizontal(w, k - 1) + calPat(h - 1, w, k) * calNotUse(w, k)).let{_ % mod}.also(it ⇒ memo(h)(k) = Some(it))
        }
      }
    }
  }

