  val MOD = 1000000007
  val out = new PrintWriter(System.out)


  val pow2 = Array.ofDim[Int](20)
  pow2(0) = 1
  rep(pow2.length - 1)(i => pow2(i + 1) = pow2(i) * 2)

  def solve(): Unit = {
    val H, W, K = ni()

    def comb(n: Int) = {
      n match {
        case 6 => 21
        case 5 => 13
        case 4 => 8
        case 3 => 5
        case 2 => 3
        case 1 => 2
        case 0 => 1
      }
    }

    val memo = Array.fill[Long](H + 1, W)(-1)
    def step(h: Int, w: Int): Long = {
      if (memo(h)(w) == -1) {
        val v = if (h == 0) {
          if (w == 0) 1 else 0
        } else {
          var res = 0L
          // 左から
          if (w > 0) {
            val l = max(0, w - 2)
            val r = max(0, W - 2 - w)
            res += step(h - 1, w - 1) * comb(l) * comb(r) % MOD
          }
          // 右から
          if (w < W - 1) {
            val l = max(0, w - 1)
            val r = max(0, W - 3 - w)
            res += step(h - 1, w + 1) * comb(l) * comb(r)  % MOD
          }
          // 上から
          {
            val l = max(0, w - 1)
            val r = max(0, W - 2 - w)
            res += step(h - 1, w) * comb(l) * comb(r)  % MOD
          }
          res % MOD
        }
        memo(h)(w) = v
      }
      memo(h)(w)
    }

    val ans = step(H, K - 1)
    out.println(ans)
  }


