                //check if two horizontal lines are connecting
                bool ok = true;
                for(int l = 0; l < W - 2 ; ++l){
                    if(((k >> l) & 1) && ((k >> (l + 1)) & 1)){
                        ok = false;
                    }
                }
                if(ok){
                    if(j >= 1 && ((k >> (j - 1)) & 1)){
                        // the case which goes left
                        dp[i + 1][j - 1] += dp[i][j];
                        dp[i + 1][j - 1] %= mod;
                    }else if(j <= W - 2 && ((k >> j) & 1)){
                        //the case which goes right
                        dp[i + 1][j + 1] += dp[i][j];
                        dp[i + 1][j + 1] %= mod;
                    }else{
                        //the case which goes straight
                        dp[i + 1][j] += dp[i][j];
                        dp[i + 1][j] %= mod;
                    }
                }
            }
        }
    }
    cout<< dp[H][K-1] << '\n';
    return 0;
}

