#define mod 1000000007

bool getisvalid(int w, int k)
{
	for(int i = 0; i < w - 2; i++){
		if((k & (1 << i)) > 0 && (k & (1 << (i + 1))) > 0) return false;
	}
	return true;
}

int getnext(int w, int now, int k)
{
	if(now < w && (k & (1 << now)) > 0) return now + 1;
	else if(now > 0 && (k & (1 << (now - 1))) > 0) return now - 1;
	else return now;
}

int main()
{
	int h, w, k;
	cin >> h >> w >> k;
	k--;
	int result[101][8] = {};
	bool isvalid[(1 << 8)];
	for(int i = 0; i < (1 << (w - 1)); i++){
		isvalid[i] = getisvalid(w, i);
	}
	result[0][0] = 1;
	for(int i = 1; i <= h; i++){
		for(int j = 0; j < w; j++){
			for(int l = 0; l < (1 << (w - 1)); l++){
				if(isvalid[l]){
					int next = getnext(w, j, l);
					result[i][next] += result[i - 1][j];
					result[i][next] %= mod;
				}
			}
		}
	}
	cout << result[h][k] << endl;
}

