                        dp[j+1][i+1]%=1000000007;
                    }else{
                        dp[j][i+1] += dp[j][i];
                        dp[j][i+1]%=1000000007;
                    }
                }
            }
        }
    }
    cout << dp[w-1][h] << endl;
}

