typedef long long ll;

struct mint{
    static const long long MOD = 1000000007;

    long long v;

    mint() : v(0) {}
    mint(long long x){
        x = x % MOD;
        if(x < 0){ x += MOD; }
        v = x;
    }
    mint& operator+=(mint a){
        v += a.v;
        if(v >= MOD){ v -= MOD; }
        return *this;
    }
    mint& operator*=(mint a){
        v *= a.v;
        v %= MOD;
        return *this;
    }
    mint& operator-=(mint a){
        v -= a.v;
        if(v < 0){ v += MOD; }
        return *this;
    }
    mint& operator/=(mint a){
        return (*this) *= a.inv();
    }

    mint operator*(mint a) const{
        return mint(v) *= a;
    }

    mint operator+(mint a) const {
        return mint(v) += a;
    }

    mint operator-(mint a) const {
        return mint(v) -= a;
    }

    mint operator/(mint a) const {
        return mint(v) /= a;
    }

    mint pow(long long k) const {
        mint res(1),tmp(v);
        while(k){
            if(k&1) res *= tmp;
            tmp *= tmp;
            k >>= 1;
        }
        return res;
    }
    mint inv(){return pow(MOD - 2); }

    static mint comb(long long n, int k){
        mint res(1);
        for(int i = 0; i < k; ++i){
            res *= mint(n - i);
            res /= mint(i + 1);
        }
        return res;
    }

    static mint factorial(long long n){
        mint res(1);
        for(int i = n; i > 1; --i){
            res *= mint(i);
        }
        return res;
    }

    bool operator<(const mint &a) const {
        return v < a.v;
    };
};

int main(){
    ll h, w, k;
    cin >> h >> w >> k;

    if(w == 1){
        cout << 1 << endl;
        return 0;
    }

    vector<mint> nh(w);
    nh.at(0) = 1; nh.at(1) = 2;
    for(int i = 2; i < w; ++i){
        nh.at(i) = nh.at(i - 1) + nh.at(i - 2);
    }

    vector<mint> num(w);
    num.at(k - 1) = 1;
    // for(int i = 0; i < w; ++i){ cout << num.at(i).v << ' '; }
    // cout << endl;

    for(ll i = 0; i < h; ++i){
        vector<mint> num2(w);
        for(ll j = 0; j < w; ++j){
            // そのまま伸ばす
            num2.at(j) += num.at(j) *
                nh.at(max(j - 1, 0LL)) * nh.at(max(w - j - 2, 0LL));

            // 左
            if(j > 0){
                num2.at(j - 1) += num.at(j) *
                    nh.at(max(j - 2, 0LL)) * nh.at(max(w - j - 2, 0LL));
            }

            // 右
            if(j < w - 1){
                num2.at(j + 1) += num.at(j) *
                    nh.at(max(j - 1, 0LL)) * nh.at(max(w - (j + 1) - 2, 0LL));
            }
        }
        num = num2;

        // for(int i = 0; i < w; ++i){ cout << num.at(i).v << ' '; }
