bool ifokay(ll x, ll w){
    rep(i,w-1){
        if(((x>>i)&1) && ((x>>(i+1))&1)) return false;
    }
    return true;
}

int main(){
    ll h,w,K; cin>>h>>w>>K;
    vector<vector<ll>> dp(h+1, vector<ll>(w+1, 0));
    ll mod=1e9+7;
    dp[0][1]=1;
    for(ll i=1; i<=h; i++){
        rep(j, 1<<(w-1)){
            if(!ifokay(j, w)) continue;
            for(ll k=1; k<=w; k++){
                if(k==1){
                    if(j & 1) dp[i][1]+=dp[i-1][2];
                    else dp[i][1]+=dp[i-1][1];
                }else if(k==w){
                    if((j>>(w-2)) & 1) dp[i][w]+=dp[i-1][w-1];
                    else dp[i][w]+=dp[i-1][w];
                }else{
                    if((j>>(k-2)) & 1) dp[i][k]+=dp[i-1][k-1];
                    else if((j>>(k-1)) & 1) dp[i][k]+=dp[i-1][k+1];
                    else dp[i][k]+=dp[i-1][k];
                }
            }
        }
        rep(j,w) dp[i][j+1]%=mod;
    }
    cout<<dp[h][K]<<endl;
