                dp[h][W] = dp[h-1][W] * fib[W] % MOD + dp[h-1][W-1] * fib[W-1] % MOD;
            } else {
                dp[h][k] = 
                      (dp[h-1][k] * fib[k] % MOD * fib[W-k+1] % MOD
                     + dp[h-1][k-1] * fib[k-1] % MOD * fib[W-k+1] % MOD
                     + dp[h-1][k+1] * fib[k] % MOD * fib[W-k] % MOD) % MOD;
            }
        }
