ll dfs(ll i, ll j) {
    if(i == 0)
        return j == K;
    if(dp[i][j] > 0) {
        return dp[i][j];
    }
    ll ret = 0;
    ret = (ret + dfs(i - 1, j) * fib[W - j] % MOD * fib[j - 1] % MOD) % MOD;
