  cin >> H >> W >> K;

  vector<vector<ll>> dp(H + 1, vector<ll>(W, 0));
  // 1番目からスタート
  dp[0][0] = 1;

  for (ll i = 0; i < H; i++) {
    // 平行線のひき方
    for (ll bit = 0; bit < (1<<(W-1)); bit++) {
      // 隣り合う列に平行にひくのは禁止
      ll invalid = false;
      for (ll k = 1; k <= (W - 1); k++) {
        if (bit & (1 << k) && bit & (1 << (k-1))) {
          invalid = true;
          break;
        }
