      // cout << "line: " << bit << endl;

      for (ll j = 0; j <= W - 1; j++) {
        ll next = j;
        if (j >= 1 && bit & (1 << (j-1))) {
          next -= 1;
        } else if (j <= (W - 1) && bit & (1 << (j))) {
          next += 1;
        }

        dp[i + 1][next] += dp[i][j];
        dp[i + 1][next] %= MOD;
      }
    }
  }

  cout << dp[H][K-1] % MOD << endl;

  return 0;
}

