//再帰的にあみだgo!
void go(int depth, int pos, int h, int w,int k, int& ans,int count) {
    if (depth == h) {
        if (pos == k) {ans++;}
        return;
    }
    depth++;
    for (int i = 0; i < count; i++) {
        int next_pos;
        next_pos = pos + move(w, pos, amida[i]);
        go(depth, next_pos, h, w, k, ans, count);
    }
}


