const int mod = 1000000007;

int main(){
    int h, w, k;
    cin >> h >> w >> k;

    vector<vector<int> > dp(h + 1, vector<int> (w, 0));
    dp[0][0] = 1;

    for(int i = 0; i < h; ++i){
        for(int j = 0; j < w; ++j){
            for(int x = 0; x < (1 << (w - 1)); ++x){
                /*
                to exclude the pattern where two line next set
                */
                bool isOK = true;
                for(int l = 0; l < w - 2; ++l){
                    if((x & (1 << l)) && (x & (1 << (l + 1)))) isOK = false;
                }

                if(isOK){
                    if((j >= 1) && (x & (1 << (j - 1)))){
                        dp[i + 1][j - 1] += dp[i][j];
                        dp[i + 1][j - 1] %= mod;
                    }else if((j <= (w - 2)) && (x & (1 << j))){
                        dp[i + 1][j + 1] += dp[i][j];
                        dp[i + 1][j + 1] %= mod;
                    }else{
                        dp[i + 1][j] += dp[i][j];
                        dp[i + 1][j] %= mod;
                    }
                }

            }
        }
    }
    cout << dp[h][k - 1] << endl;

    return 0;
}

