int H, W, K;
mint dp[105][10];

mint num_of_amida(int n) {
    if (n == 0) return 1;
    n--;
    mint res = 0;
    for (int bit = 0; bit < (1<<n); bit++) {
        bool flag = true;
        for (int i = 0; i < n-1; i++) {
            if (bit<<i & bit<<(i+1)) {
                flag = false;
                break;
            }
        }
        if (flag) res += 1;
    }
    return res;
}

void solve() {
    cin >> H >> W >> K;

    dp[0][1] = 1;
    for (int i = 1; i <= H; i++) {
        for (int j = 1; j <= W; j++) {
            dp[i][j] += dp[i-1][j] * num_of_amida(j-1) * num_of_amida(W-j);
            if(j > 1) dp[i][j] += dp[i-1][j-1] * num_of_amida(j-2) * num_of_amida(W-j);
            if(j < W) dp[i][j] += dp[i-1][j+1] * num_of_amida(j-1) * num_of_amida(W-j-1);
        }
    }

    cout << dp[H][K] << '\n';
}

int main() {
    cin.tie(nullptr);
    ios_base::sync_with_stdio(false);

    solve();

    return 0;
}

