int H,W,K;

const int MOD = 1e9+7;

vector<int> change;
vector<vector<int>> next_w;

void rec(int w){
    if(w == W-1){
        vector<int> n(W,0);
        REP(i,W) n[i] = i;
        REP(i,W-1) if(change[i]==1) swap(n[i],n[i+1]);
        REP(i,W){
            next_w[n[i]][i]++;
        }
        return;
    }


    change[w] = 0;
    rec(w+1);

    change[w] = 1;
    if(w+2 < W) change[w+1]=0, rec(w+2);
    if(w+2 == W) rec(w+1); 
}

int main() {
