        REP(j,W){
            if(j-1>=0){
                ans[i+1][j-1] += ans[i][j] * next_w[j][j-1];
                ans[i+1][j-1] %= MOD;
            }
            ans[i+1][j] += ans[i][j] * next_w[j][j];
            ans[i+1][j] %= MOD;
