const long long int MOD = 1000000007;

int main() {
  long long int H, W, K;
  cin >> H >> W >> K;

  vector<long long int> ways(W);
  ways[0] = 1;
  for (int i = 1; i < W; i++) {
    if (i == 1) {
      ways[i] = 2;
    } else {
      ways[i] = (ways[i - 1] + ways[i - 2]) % MOD;
    }
  }

  vector<vector< long long int> > grid(H + 1, vector<long long int>(W));

  grid[0][0] = 1;
  long long int temp;
  for (int i = 1; i <= H; i++) {
    for (int j = 0; j < W; j++) {
      temp = 1;
      if (j > 0) {
        temp = (temp * ways[j - 1]) % MOD;
      }
      if (j < W - 1) {
        temp = (temp * ways[W - j - 2]) % MOD;
      }
      grid[i][j] = (grid[i][j] + grid[i - 1][j] * temp) % MOD;

      if (j > 0) {
        temp = 1;
        if (j > 1) {
          temp = (temp * ways[j - 2]) % MOD;
        }
        if (j < W - 1) {
          temp = (temp * ways[W -j - 2]) % MOD;
        }
        grid[i][j] = (grid[i][j] + grid[i - 1][j - 1] * temp) % MOD;
      }

      if (j < W - 1) {
        temp = 1;
        if (j < W - 2) {
          temp = (temp * ways[W - j - 3]) % MOD;
        }
        if (j > 0) {
          temp = (temp * ways[j - 1]) % MOD;
        }
        grid[i][j] = (grid[i][j] + grid[i - 1][j + 1] * temp) % MOD;
      }
    }
  }

  cout << grid[H][K - 1] << endl;

  return 0;
}

#include <bits/stdc++.h>

#define REP(i, n) for(int (i)=0;(i)<(n);++(i))
