#define MOD 1000000007

using namespace std;

typedef long long ll;

bool isOK(ll num, ll d)
{
    vector<ll> digit(d);
    bool flag = true;
    REP(i, d)
    {
        ll p = num;
        digit[i] = (p >> i) & 1; 
    }
    REP(i, d - 1)
    {
        if (digit[i] == 1)
        {
            if (digit[i + 1] == 1)
            {
                flag = false;
                break;
            }
        }
    }

    return flag;
}

int main()
{
    ll H, W, K;
    cin >> H >> W >> K;
    vector<ll> down(W, 0), right(W, 0), left(W, 0);
    REP(i, 1 << (W - 1))
    {
        if (isOK(i, W - 1))
        {
            REP(j, W)
            {
                ll num = i;
                if (j < W - 1 && (num >> j) & 1)
                {
                    right[j]++;
                }
                else if (j - 1 >= 0 && (num >> (j - 1)) & 1)
                {
                    left[j]++;
                }
                else
                {
                    down[j]++;
                }
            }
        }
    }

    ll dp[H + 1][W + 1];
    REP(i, H + 1)
    {
        REP(j, W + 1)
        {
            dp[i][j] = 0;
        }
    }
    dp[0][1] = 1;
    for (ll h = 1; h <= H; ++h)
    {
        for (ll w = 1; w <= W; ++w)
        {

            dp[h][w] = (dp[h - 1][w] * down[w - 1]) % MOD;
            if (w + 1 <= W)
            {
                dp[h][w] += (dp[h - 1][w + 1] * left[w]) % MOD;
                dp[h][w] = dp[h][w] % MOD;
            }
            if (w - 1 >= 1)
            {
                dp[h][w] += (dp[h - 1][w - 1] * right[w - 2]) % MOD;
                dp[h][w] = dp[h][w] % MOD;
            }
        }
    }

    cout << dp[H][K] << endl;
}

