modint solve() {
    A[0][0] = modint(1);

    REP(now_h, h) {
        vector<int> xs = {-1, 0, 1};
        REP(now_w, w) {
            vector<int> magni(3, 0);
            REP(bits, 1 << (w - 1)) {
                bool flug = false;
                REP(i, w - 2) {
                    int mask = 1 << i;
                    if ((mask & bits) && ((mask << 1) & bits)) {
                        flug = true;
                        break;
                    }
                }
                if (flug) {
                    continue;
                }
                int mask = 1 << now_w;
                if (bits & (mask >> 1)) {
                    magni[0]++;
                } else if (bits & (mask)) {
                    magni[2]++;
                } else {
                    magni[1]++;
                }
            }
            REP(i, 3) {
                int next_w = now_w + xs[i];
                int next_h = now_h + 1;

                if (next_w >= 0 && next_w <= w) {
                    A[next_h][next_w] += modint(magni[i]) * A[now_h][now_w];
                }
            }
        }
    }

    return A[h][k];
}

