void make_path(int n, int* path){
  if (n == (W-1)) {
    for (int i=0; i<W; i++) {
      if (i>0 && path[i-1] == 1) {
        num_path[i][0]++;
      } else if (i<(W-1) && path[i] == 1) {
        num_path[i][2]++;
      } else {
        num_path[i][1]++;
      }
    }
    return;
  }
  path[n] = 0;
  make_path(n+1, path);
  if (n == 0 || n > 0 && path[n-1] == 0) {
    path[n] = 1;
    make_path(n+1, path);
  }
}

