int H, W, K, M[101], flg[101];

long Calc(void) {
	int meta[8] = {1,1,2,3,5,8,13,21};
	long result = 1;
	for(int i=0; i<H; i++)
		result *= meta[M[i] - 1] * meta[W - M[i] - flg[i]];
	return result % 1000000007;
}

long Map(int X, int Y) {
	if (Y == H)
		switch(X) {
			case K + 1:
				M[Y] = X - 1;
				flg[Y] = 1;
				return Calc();
			case K:
				M[Y] = X;
				flg[Y] = 0;
				return Calc();
			case K - 1:
				M[Y] = X;
				flg[Y] = 1;
				return Calc();
			default:
				return 0;
		}

	M[Y] = X
	flg[Y] = 0;
	long result = Map(X, Y+1);

	if (X > 1) {
		M[Y] = X-1;
		flg[Y] = 1;
		result += Map(X-1, Y+1);
	}

	if (X < W) {
		M[Y] = X;
		flg[Y] = 1;
		result += Map(X+1, Y+1);
	}

	return result % 1000000007;
}

