/**
 *  mod による操作ライブラリ
 */
#define ANS_MOD (1000000007)
class MODINT {
    static SQWORD MOD;
    SQWORD m_x;

public:
    MODINT(SQWORD val) {
        m_x = (val % MOD + MOD) % MOD;
    };
    MODINT() {
        m_x = 0;
    }
    static void Init(SQWORD sqMod) {
        MOD = sqMod;
    }

	MODINT& operator+= (const MODINT a)
    {
        m_x = (m_x + a.m_x) % MOD; 
        return *this;
    };
	MODINT& operator-= (const MODINT a)
    { 
        m_x = (m_x - a.m_x + MOD) % MOD; 
        return *this;
    };
	MODINT& operator*= (const MODINT a)
    {
        m_x = (m_x * a.m_x) % MOD;
        return *this;
    };
    MODINT pow(SQWORD t) const {
        if (!t) return 1;
        MODINT a = pow(t>>1);
        a *= a;
        if (t&1) a *= *this;
        return a;
    }
	MODINT operator+ (const MODINT a) const {
		MODINT res(*this);
		return (res += a);
	}
	MODINT operator- (const MODINT a) const {
		MODINT res(*this);
		return (res -= a);
	}
	MODINT operator* (const MODINT a) const {
		MODINT res(*this);
		return (res *= a);
	}
	MODINT operator/ (const MODINT a) const {
		MODINT res(*this);
		return (res /= a);
	}

    /* 逆元 */
    MODINT inv() const {
        return pow(MOD-2);
    }

    /* 除算 */
    MODINT& operator/=(const MODINT a) {
        return (*this) *= a.inv();
    } 

    /* 整数版 */
	MODINT& operator+= (const SQWORD a) {*this += MODINT(a); return *this;};
	MODINT& operator-= (const SQWORD a) {*this -= MODINT(a); return *this;};
	MODINT& operator*= (const SQWORD a) {*this *= MODINT(a); return *this;};
	MODINT& operator/= (const SQWORD a) {*this /= MODINT(a); return *this;};

    SQWORD getVal() { return m_x; };
};
SQWORD MODINT::MOD = ANS_MOD;

MODINT dfs(bool prevLineExist, int i, int num)
{
	if ((num <= 0)||(num < i)) {
		return 1;
	}

	if (i == num) {
		return 1;
	}

	MODINT cnt = 0;
	int next = i + 1;
	if (prevLineExist) {
		// 引けない
		cnt = dfs(false, next, num);
	} else {
		// 引く or 引かない
		cnt = dfs(true, next, num);
		cnt += dfs(false, next, num);
	}

	return cnt;
}


int main()
{
	int H, W, K;
	cin >> H >> W >> K;

	vector<vector<MODINT>> dp(H + 1, vector<MODINT>(W, 0));
	dp[0][0] = 1;
	REP(i, H) {
		REP(j, W) {
			if (0 < dp[i][j].getVal()) {
				MODINT ptnNoneL = dfs(false, 0, j - 1);
				MODINT ptnExistL = dfs(false, 0, j - 2);
				MODINT ptnNoneR = dfs(false, j + 1, W - 1);
				MODINT ptnExistR = dfs(false, j + 2, W - 1);

				// ひだり
				if (j != 0) {
					dp[i + 1][j - 1] += (dp[i][j] * ptnExistL * ptnNoneR);
				}

				// まんなか
				dp[i + 1][j] += (dp[i][j] * ptnNoneL * ptnNoneR);

				// みぎ
				if (j != W - 1) {
					dp[i + 1][j + 1] += (dp[i][j] * ptnNoneL * ptnExistR);
				}
			}
		}
	}
	cout << dp[H][K-1].getVal() << endl;
	return 0;
}

