int amidaN(int N){
    if(N < 2){
        return 1;
    }else{ switch(N){

        case 2: return 2; break;
        case 3: return 3; break;
        default: return amidaN(N - 1) + amidaN(N - 2); break;
    }
    }

}
unsigned long A(int h,int x,int W){
    if(h == 0){
        switch(x){
            case 1: return 1;
            default: return 0;
        }
    }else if((x <= 0)||(x > W)){
        return 0;
    }else{
        return (amidaN(x - 2)*amidaN(W - x))*A(h-1,x-1,W) 
            +  (amidaN(x - 1)*amidaN(W - x))*A(h-1,x,W)
            +  (amidaN(x - 1)*amidaN(W - x - 1))*A(h-1,x+1,W);
    }
}
