std::vector<std::vector<bool>> calc_swap_patterns(const i64 W) {
  std::vector<std::vector<bool>> swap_patterns;
  swap_patterns.emplace_back(W - 1, false);
  for (i64 i = 0; i <= W - 2; ++i) {
    std::vector<bool> swap_pattern(W - 1, false);
    swap_pattern[i] = true;
    swap_patterns.push_back(swap_pattern);
  }
  for (i64 i = 0; i <= W - 4; ++i) {
    for (i64 j = i + 2; j <= W - 2; ++j) {
      std::vector<bool> swap_pattern(W - 1, false);
      swap_pattern[i] = true;
      swap_pattern[j] = true;
      swap_patterns.push_back(swap_pattern);
    }
  }
  for (i64 i = 0; i <= W - 6; ++i) {
    for (i64 j = i + 2; j <= W - 4; ++j) {
      for (i64 k = j + 2; k <= W - 2; ++k) {
        std::vector<bool> swap_pattern(W - 1, false);
        swap_pattern[i] = true;
        swap_pattern[j] = true;
        swap_pattern[k] = true;
        swap_patterns.push_back(swap_pattern);
      }
    }
  }
  for (i64 i = 0; i <= W - 8; ++i) {
    for (i64 j = i + 2; j <= W - 6; ++j) {
      for (i64 k = j + 2; k <= W - 4; ++k) {
        for (i64 l = k + 2; l <= W - 2; ++l) {
          std::vector<bool> swap_pattern(W - 1, false);
          swap_pattern[i] = true;
          swap_pattern[j] = true;
          swap_pattern[k] = true;
          swap_pattern[l] = true;
          swap_patterns.push_back(swap_pattern);
        }
      }
    }
  }
  return swap_patterns;
}

constexpr u32 P = 1000000007;

class swap_pattern_count {
public:
  tools::int_mod<P> to_left;
  tools::int_mod<P> go_straight;
  tools::int_mod<P> to_right;
};

std::vector<swap_pattern_count> calc_swap_pattern_counts(const i64 W) {
  std::vector<swap_pattern_count> swap_pattern_counts(W);

  for (const std::vector<bool>& swap_pattern : calc_swap_patterns(W)) {
    for (i64 x = 0; x < W; ++x) {
      const bool has_left_line = x > 0 && swap_pattern[x - 1];
      const bool has_right_line = x < W - 1 && swap_pattern[x];
      if (has_left_line) {
        ++swap_pattern_counts[x].to_left;
      } else if (has_right_line) {
        ++swap_pattern_counts[x].to_right;
      } else {
        ++swap_pattern_counts[x].go_straight;
      }
    }
  }

  return swap_pattern_counts;
}

int main() {
  i64 H, W, K;
  std::cin >> H >> W >> K;
  --K;

  std::vector<std::vector<tools::int_mod<P>>> dp(H + 1, std::vector<tools::int_mod<P>>(W));
  dp[0][0] = tools::int_mod<P>(1);

  const std::vector<swap_pattern_count> swap_pattern_counts = calc_swap_pattern_counts(W);

  for (i64 y = 0; y < H; ++y) {
    for (i64 x = 0; x < W; ++x) {
      if (x > 0) dp[y + 1][x - 1] += dp[y][x] * swap_pattern_counts[x].to_left;
      dp[y + 1][x] += dp[y][x] * swap_pattern_counts[x].go_straight;
      if (x < W - 1) dp[y + 1][x + 1] += dp[y][x] * swap_pattern_counts[x].to_right;
    }
  }

  std::cout << static_cast<u32>(dp[H][K]) << std::endl;
  return 0;
}

