ll my_abs(ll a) {
    if(a >= 0) return a;
    else return -1 *a;
}

ll a_n(ll a, ll n) { 
    if(n == 0) return 1;

    ll ret = a, count = 1;
    while(count * 2 < n) {
        ret *= ret;
        count *= 2;
    }
    if(count == n) return ret;
    else return (ret * a_n(a, n-count));
}

ll my_gcd(ll a, ll b) {
    if(b == 0) return a;
    return my_gcd(b, a%b);
}

ll inv(ll a) {
    return a_n(a, MOD-2);
}

ll madd(ll a, ll b, ll c) {
    ll ret = (a+b) % MOD;
    return (ret+c) % MOD;
}

ll msub(ll a, ll b) {
    if(a < b) return (a-b+MOD) % MOD;
    else return (a-b) % MOD;
}

ll mtime(ll a, ll b, ll c) {
    ll ret = (a*b) % MOD;
    return (ret*c) % MOD;
}

#include <iostream>
using namespace std;
int H, W, K, M[101], flg[101];

long Calc(void) {
	int meta[8] = {1,1,2,3,5,8,13,21};
	long result = 1;
	for(int i=1; i<=H; i++)
		result *= meta[M[i] - 1] * meta[W - M[i] - flg[i]];
	return result % 1000000007;
}

long Map(int X, int Y) {
	if (Y == H)
		if (X == K+1) {
			M[Y] = X - 1;
			flg[Y] = 1;
			return Calc();
		} else if (X == K) {
			M[Y] = X;
			flg[Y] = 0;
			return Calc();
		} else if ( X == K-1 ) {
			M[Y] = X;
			flg[Y] = 1;
			return Calc();
		} else {
			return 0;
		}

	M[Y] = X;
	flg[Y] = 0;
	long result = Map(X, Y+1);

	if (X > 1) {
		M[Y] = X-1;
		flg[Y] = 1;
		result += Map(X-1, Y+1);
	}

	if (X < W) {
		M[Y] = X;
		flg[Y] = 1;
		result += Map(X+1, Y+1);
	}

	return result % 1000000007;
}

