struct P
{
	int l, m, r;
	P() :l(0), m(0), r(0) {}
};

signed main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	int H, W, K;
	cin >> H >> W >> K;
	int dp[110][3] = { 0 };
	dp[0][0] = 1;
	rep(i, 1, H + 1)
	{
		vector<P> t(W);
		rep(j, 0, 1LL << (W - 1))
		{
			vector<P> tt(W);
			bool pre = false;
			bool valid = true;
			rep(k, 0, W - 1)
			{
				if ((j&(1LL << k)))
				{
					if (pre)
					{
						valid = false;
						break;
					}
					tt[k].r++;
					tt[k + 1].l++;
					pre = true;
				}
				else
				{
					tt[k].m++;
					pre = false;
				}
			}
			if (W == 1 || (j&(1LL << (W - 2))) == 0)
			{
				tt[W - 1].m++;
			}
			if (valid)
			{
				rep(x, 0, SZ(t))
				{
					t[x].l += tt[x].l;
					t[x].m += tt[x].m;
					t[x].r += tt[x].r;
				}
			}
		}

		rep(x, 0, SZ(t))
		{
			if (0 < x)
			{
				dp[i][x] = (dp[i][x] + dp[i - 1][x - 1] * t[x].l) % MOD;
			}
			dp[i][x] = (dp[i][x] + dp[i - 1][x] * t[x].m) % MOD;
			if (x < SZ(t) - 1)
			{
				dp[i][x] = (dp[i][x] + dp[i - 1][x + 1] * t[x].r) % MOD;
			}
		}
	}

	cout << dp[H][K - 1] << endl;

	return 0;
}

