ll inf = pow(10,9)+7;

int main(){
  int H,W,K; cin>>H>>W>>K;
  ll dp[H+1][W+2];
  for(int h=0;h<=H;++h){
    if(h==0){
      dp[h][1] = 1;
      for(int w=2;w<=W;++w){
        dp[h][w] = 0;
      }
    }else{
      for(int w=1;w<=W;++w){
        int X=0,Y=0,Z=0;
        int C = W-1;
        for(ll bits=0;bits<pow(2,C);++bits){
          bool ok = true;
          for(int i=0;i<C;++i){
            if( ((bits>>(i))&1) && ((bits>>(i+1))&1) ){ ok = false; break;}
          }
          if(!ok){continue;}
          if(w==1){
            if( (bits>>(w-1))&1 ){ ++Z; }
            else{ ++Y;}
          }else if(w==W){
            if( (bits>>(w-2))&1 ){ ++X; }
            else{ ++Y; }
          }else{
            if( (bits>>(w-1))&1 ){ ++Z; }
            else if( (bits>>(w-2))&1 ){ ++X; }
            else{ ++Y; }
          }
        }
        dp[h][w] = X*dp[h-1][w-1];
        dp[h][w] %= inf;
        dp[h][w] += Y*dp[h-1][w];
        dp[h][w] %= inf;
        dp[h][w] += Z*dp[h-1][w+1];
        dp[h][w] %= inf;
      }
    }
  }
  cout << dp[H][K] << "\n";
}

