int main() {

	int h, w, k; cin >> h >> w >> k;

	vector<vector<int>> amida(h+1, vector<int>(w));

	vector<vector<int>> dp(h+1, vector<int>(w));
	//必ず1からスタートする
	dp[0][0] = 1;

	for (int i = 1; i < h+1; i++) {

		//横棒を全列挙
		for (int bar = 0; bar < (1 << w - 1); bar++) {

			bool ng = false;
			//2個続いている場所がないかのチェック

			for (int j = 0; j < w - 2; j++) {
				if ((bar >> j) % 4 == 3) {
					ng = true;
					break;
				}
			}

			if (ng)continue;

			//置換の対応列を作る
			vector<int> swaprow(w);
			for (int j = 0; j < w; j++) {
				swaprow[j] = j;
			}

			for (int j = 0; j < w-1; j++) {
				if ((bar >> j) % 2 == 1) {
					swap(swaprow[j], swaprow[j + 1]);
				}
			}

			//遷移
			//jはswaprow[j]にいく

			for (int j = 0; j < w; j++) {
				dp[i][swaprow[j]] += dp[i - 1][j];
				dp[i][swaprow[j]] %= MOD;
			}

		}
	}

	cout << dp[h][k - 1] << endl;

	return 0;
}

