int main() {
	int h,w,k;
	scanf("%d%d%d", &h,&w,&k);

	int num[8][8];
	REP(i, w) {
		if (i != 0) {
			num[i][i - 1] = getpattern(i - 1)*getpattern(w - (i + 1));
		}
		num[i][i] = getpattern(i)*getpattern(w - (i + 1));
		if (i != w - 1) {
			num[i][i + 1] = getpattern(i)*getpattern(w - (i + 1) - 1);
		}
	}

	ll ans[101][8] = { 0 };
	ans[0][0] = 1;
	REPS(i, h) {
		REP(j, w) {
			if (j != 0) {
				ans[i][j] += (ans[i-1][j - 1] * num[j - 1][j]) % MOD;
			}
			ans[i][j] += (ans[i - 1][j] * num[j][j]) % MOD;
			if (j != w-1) {
				ans[i][j] += (ans[i - 1][j + 1] * num[j + 1][j]) % MOD;
			}
			ans[i][j] %= MOD;
		}
	}
	PRINTL(ans[h][k-1]);
}

