const int64_t MOD = 1000000007;

int h, w, k;
int64_t result[110][10] = {};

void search(int pos, int connection) {
    // cout << pos << ":" << connection << endl;
    for (int i = 1; i <= 6; i++) {
        int checker_right = 1 << (i - 1), checker_left = 1 << i;
        if (connection & checker_left && connection & checker_right) {
            // cout << "Bad!" << endl;
            return;
        }
    }
    // Good Amidakuji
    // cout << "Good!" << endl;
    for (int right = 1; right < w; right++) {
        int mask = 1 << (right - 1);
        if (mask & connection) {
            result[pos][right] += result[pos - 1][right + 1];
            result[pos][right] %= MOD;
            result[pos][right + 1] += result[pos - 1][right];
            result[pos][right + 1] %= MOD;
        } else {
            result[pos][right] += result[pos - 1][right];
            result[pos][right] %= MOD;
        }
        if (connection & 1 << (w - 1)) {
            //曲がってる
        } else {
            //素通り
            result[pos][w] += result[pos - 1][w];
            result[pos][w] %= MOD;
        }
    }

    // for (int i = 1; i <= w; i++) {
    //     cout << "pos" << pos << ",line" << i << ": " << result[pos][i] <<
    //     endl;
    // }
    return;
}

