    cout << std::fixed << std::setprecision(10);
    cin.tie(0);
    std::ios::sync_with_stdio(false);

    cin >> h >> w >> k;
    result[0][1] = 1;
    if (w == 1) {
        cout << 1 << endl;
        return 0;
    }
    for (int i = 1; i <= h; i++) {
        for (int j = 0; j < (1 << (w - 1)); j++) {
            search(i, j);
        }
    }

    cout << result[h][k] % MOD << endl;

    return 0;
}

