const ll mod = 1000000007;

inline bool check(int mask){
	vector<int> vec;
	while(mask){
		vec.push_back(mask&1);
		mask >>= 1;
	}
	for(int i = 1; i < vec.size(); i++){
		if(vec[i] && vec[i - 1])return false;
	}
	return true;
}

inline int getNext(int pos, int mask){
	if(mask&(1<<pos))return pos + 1;
	if(pos == 0)return 0; pos--;
	if(mask&(1<<pos))return pos;
	return pos + 1;
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(NULL);
	cout.tie(NULL);
	cout<<setprecision(32);

	int H, W, K;
	cin>>H>>W>>K;
	int dp[H + 1][W];
	memset(dp, 0, sizeof(dp));
	dp[0][0] = 1;
	for(int h = 1; h <= H; h++){
		for(int mask = 0; mask < (1<<(W - 1)); mask++){
			if(!check(mask))continue;
			for(int pos = 0; pos < W; pos++){
				int npos = getNext(pos, mask);
				dp[h][npos] += dp[h - 1][pos];
				if(dp[h][npos] >= mod)dp[h][npos] -= mod;
			}
		}
	}
	cout<<dp[H][K - 1]<<'\n';

	return 0;
}

