long validYoko[8][10];

long calcYoko(int sz, int idx) {
  if (validYoko[sz][idx] != -1) {
    return validYoko[sz][idx];
  }
  long res;
  if (idx >= sz) {
    res = 1;
  } else if (idx == sz - 1) {
    res = 2;
  } else {
    res = (calcYoko(sz, idx+1) + calcYoko(sz, idx+2));
  }
  validYoko[sz][idx] = res;
  return res;
}

