const int mod = 1000000007;

struct mint {
    ll x;
    mint(ll x=0):x((x%mod+mod)%mod){}
    mint operator-() const { return mint(-x);}
    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += mod-a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
        if (t&1) a *= *this;
        return a;
    }

  // for prime mod
    mint inv() const {
        return pow(mod-2);
    }
    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
};

int main(){
    int h,w,k;
    cin >> h >> w >> k;
    ve<mint> dp(w,mint(0));
    dp[0] = mint(1);

    ve<ve<int>> p(w,ve<int>(3,0));

    rep(i,1<<(w-1)){
        ve<bool> o(w);
        bool fl=false;
        rep(j,w-1){
            if((i>>j)&1){
                o[j] = true;
                if(j!=0)if(o[j-1]){
                    fl = true;
                    break;
                }
            }
        }
        if(fl)continue;

        rep(k,w){
            if(o[k]){
                p[k+1][0]++;
                continue;
            }
            if(k-1>=0)if(o[k-1]){
                p[k-1][2]++;
                continue;
            }
            p[k][1]++;
        }
    }

    rep(i,h){
        ve<mint> dp2(w,mint(0));
        swap(dp,dp2);
        rep(j,w){
            dp[j] += mint(p[j][1]) * dp2[j];
            if(j==0){
                dp[j] += mint(p[j][2]) * dp2[j+1];
                continue;
            }
            if(j==w-1){
                dp[j] += mint(p[j][0]) * dp2[j-1];
                continue;
            }
            dp[j] += mint(p[j][0]) * dp2[j-1];
            dp[j] += mint(p[j][2]) * dp2[j+1];

        }
    }
    cout << dp[k-1].x << endl;
    return 0;
}

