// mod_int {{{
template < int mod >
class mod_int {
    using i32 = int_fast32_t;
    using i64 = int_fast64_t;

    i32 num_;

    public:
    mod_int() : num_(0) {}
    mod_int(i64 num_) : num_(num_ >= 0 ? num_ % mod : (mod + num_ % mod) % mod) {}

    inline i32 num() const { return num_; }
    operator i32() { return num_; }

    inline mod_int inverse() const {
        i32 a = num_, b = mod, u = 1, v = 0, t;
        while (b) { t = a / b; std::swap(a -= t * b, b); std::swap(u -= t * v, v); }
        return mod_int(u);
    }

    mod_int operator~() const { return inverse(); }
    mod_int operator+() const { return *this; }
    mod_int operator-() const { return mod_int(-num_); }

    mod_int &operator+=(const mod_int &rhs) { if ((num_ += rhs.num_) >= mod) num_ -= mod; return *this; }
    mod_int &operator-=(const mod_int &rhs) { if ((num_ -= rhs.num_) <  0)   num_ += mod; return *this; }
    mod_int &operator*=(const mod_int &rhs) { num_ = i64(num_) * rhs.num_ % mod; return *this; }
    mod_int &operator/=(const mod_int &rhs) { return *this *= rhs.inverse(); }

    mod_int operator+(const mod_int &rhs) const { return mod_int(*this) += rhs; }
    mod_int operator-(const mod_int &rhs) const { return mod_int(*this) -= rhs; }
    mod_int operator*(const mod_int &rhs) const { return mod_int(*this) *= rhs; }
    mod_int operator/(const mod_int &rhs) const { return mod_int(*this) /= rhs; }

    bool operator==(const mod_int &rhs) const { return num_ == rhs.num_; }
    bool operator!=(const mod_int &rhs) const { return num_ != rhs.num_; }

    friend std::ostream &operator<<(std::ostream &os, const mod_int &rhs) {
        return os << rhs.num_;
    }

    friend std::istream &operator>>(std::istream &is, mod_int &rhs) {
        i64 num; is >> num; rhs = mod_int< mod >(num);
        return is;
    }

    friend mod_int pow(mod_int lhs, i64 rhs) {
        mod_int res(1);
        for (; rhs; rhs >>= 1) {
            if (rhs & 1) res *= lhs;
            lhs *= lhs;
        }
        return res;
    }
};

using modint = mod_int< mod >;
// }}}

void solver() {
    int H = input(), W = input(), K = input();

    vector< modint > calc(W);
    range(i, 0, W) {
        range(bit, 0, (1 << i)) {
            bool f = true;
            range(k, 1, i) {
                if ((bit & (1 << k)) and (bit & (1 << (k - 1)))) {
                    f = false;
                }
            }
            calc[i] += f;
        }
    }

    vector< modint > dp(W);
    dp[0] = 1;

    range(i, 0, H) {
        auto rec = vector< modint >(W);

        range(i, 0, W - 1) {
            rec[i] += dp[i + 1] * calc[max(i - 1, 0)] * calc[max(W - i - 3, 0)];
            rec[i + 1] += dp[i] * calc[max(i - 1, 0)] * calc[max(W - i - 3, 0)];
        }
        range(i, 0, W) {
            rec[i] += dp[i] * calc[max(i - 1, 0)] * calc[max(W - i - 2, 0)];
        }

        dp = rec;
    }

    cout << dp[K - 1] << endl;
}

signed main(int argc, char *argv[]) {
    solver();
}

