void check (int i) {
    string t="";
    for (int j=(w-2);j>=0;j--) {
        if ((1<<j)&i) t+='1';
        else t+='0';
    }
    for (int i=1;i<t.size();i++) {
        if (t[i]=='1' && t[i-1]=='1') return;
    }
    val.push_back(t);
    //cout<<t<<"\n";
}
ll fnd(int i,int k) {
    if (i==0) return 1;
    ll ans=0;
    if (k==1) {
        for (auto it:val) {
            if (it[i-1]=='1') ans++;
        }
    }
    else {
        for (auto it:val) {
            if (it[i-1]=='0' && (i==1 || it[i-2]=='0')) ans++;
        }
    }
    return ans;
}
ll solve(int i,int j,int k) {
    if (dp[i][j][k]!=(-1)) return dp[i][j][k];
    if (k==0) {
        dp[i][j][k] = (solve(i-1,j,0)*fnd(j,0))%mod+(solve(i-1,j,1)*fnd(j-1,1))%mod+(solve(i-1,j,2)*fnd(j,1))%mod;
        dp[i][j][k] %= mod;
    }
    else if (k==1) {
        dp[i][j][k] = (solve(i,j-1,0)*fnd(j-1,1))%mod;
    }
    else {
        dp[i][j][k] = (solve(i,j+1,0)*fnd(j,1))%mod;
    }
    return dp[i][j][k];
}
