	    ndp[l+1] = ad(ndp[l+1],dp[l]);
	    l++;
	    if(l==w-2){
	      ndp[l+1]=ad(ndp[l+1],dp[l+1]);
	    }
	  }
	  else{
	    if(l==w-2) ndp[l+1]=ad(ndp[l+1],dp[l+1]);
	    ndp[l] = ad(dp[l],ndp[l]);
	  }
	}
      }
      //      cout << bitset<3>(j) << " " << ok << " "  << ndp[2] <<endl;
    }
    rep(i,w) swap(ndp[i],dp[i]);
    rep(i,w) ndp[i]=0;
  }
  if(w!=1) cout << dp[k-1] << endl;
  else cout << 1 << endl;
  return 0;

}

