#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

static const ll MOD = 1000000007;

ll pow_mod(ll m, ll e)
{
	ll v = 1ll;
	for (; e > 0; e >>= 1) {
		if (e & 1)
			v = v * m % MOD;
		m = m * m % MOD;
	}
	return v;
}

int H, W, K;
ll dp[110][10];

int main()
{
	cin >> H >> W >> K;

	dp[0][0] = 1;
	for (int i = 0; i < H; ++i) {
		for (int j = 0; j < W; ++j) {
			dp[i + 1][j] = dp[i][j];
			auto d = (j == 0 || j == W - 1) ? 1 : 2;
			dp[i + 1][j] = dp[i + 1][j] * pow_mod(2, max(0, W - 1 - d)) % MOD;

			if (j - 1 >= 0) {
				auto d = (j == W - 1 || j - 1 == 0) ? 2 : 1;
				auto x = dp[i][j - 1] * pow_mod(2, max(0, W - 1 - d)) % MOD;
				dp[i + 1][j] = (dp[i + 1][j] + x) % MOD;
			}

			if (j + 1 < W) {
				auto d = (j == 0 || j + 1 == W - 1) ? 2 : 1;
				auto x = dp[i][j + 1] * pow_mod(2, max(0, W - 1 - d)) % MOD;
				dp[i + 1][j] = (dp[i + 1][j] + x) % MOD;
			}
		}
	}

	cout << dp[H][K - 1] << endl;
	return 0;
}

