ll Memo[9]; // 本数がidxのときに何通りあるか 

ll dfs(int idx) {
  if (Memo[idx]) return Memo[idx];
  if (idx==0) return 1; 
  ll ret = dfs(idx-1) + dfs(idx-2);
  Memo[idx] = ret;
  return ret;
}

void calc() {
  rep(i, H+1) {
    if (i==0) continue;
    rep(j, W) {
      if (j==0) {
        DP[i][j] = DP[i-1][j]*Memo[W-1]%MOD+DP[i-1][j+1]*Memo[W-2]%MOD;
      } else if (j==W-1) {
        DP[i][j] = DP[i-1][j]*Memo[W-1]%MOD+DP[i-1][j-1]*Memo[W-2]%MOD;
      } else if (j==1) {
        DP[i][j] = DP[i-1][j]*Memo[W-2]%MOD+DP[i-1][j-1]*Memo[W-2]%MOD+DP[i-1][j+1]*Memo[W-3]%MOD; // W>2なのでok
      } else if (j==W-2) {
        DP[i][j] =  DP[i-1][j]*Memo[W-2]%MOD+DP[i-1][j+1]*Memo[W-2]%MOD+DP[i-1][j+1]*Memo[W-3]%MOD; // W>3なのでok
      } else { //  W > 4
        ll left = Memo[j-2]+Memo[W-j-1];
        if (j-2<=1 || W-j-1<=1) left--;
        ll right = Memo[j-1]+Memo[W-j-2];
        if (j-1<=1 || W-j-2<=1) right--;
        ll base =  Memo[j-1]+Memo[W-j-1];
        if (j-1<=1 || W-j-1<=1) base--;
        DP[i][j] = DP[i-1][j-1]*left%MOD+DP[i-1][j]*base%MOD+DP[i-1][j+1]*right%MOD;
      }
    }
  }
}

