  // dp[i][j]
  // i列目について、0からスタートしてj番目に到達するパスの数
  vector<vector<ll>> dp(H + 1, vector<ll>(W, 0));
  dp[0][0] = 1;  // 1(インデックスは0)からスタートする
  for (ll i = 0; i < H; i++) {
    for (ll j = 0; j < W; j++) {
      // stepがiのときの線の入れ方を考える
      // step (i+1)のパスの数を計算する(配るDP)

      // それぞれの区間で線を入れる、入れないの2通り
      for (ll bit = 0; bit < (1<<(W-1)); bit++) {
        ll ok = true;
        // 連続して同じ高さの棒が引かれているか
        for (ll k = 0; k < (W-1); k++) {
          if (bit & (1 << k) && (bit & (1 << (k+1)))) {
            ok = false;
            break;
          }
        }

        if (ok == false) continue;

        // stepがiでj = 1を考える
        // j(=1)bit目が立っているとき
        // 次のstepの総数
        // i:   | | |
        // i+1: | |-|
        //      0 1 2
        if (bit & (1 << j)) {
          dp[i + 1][j + 1] += dp[i][j];
          dp[i + 1][j + 1] %= MOD;
        }
        // stepがiでj = 1を考える
        // j-1(=0)bit目が立っているとき
        // 次のstepの総数
        // i:   | | |
        // i+1: |-| |
        //      0 1 2
        else if ((j - 1 >= 0) && bit & (1 << (j - 1))) {
          dp[i + 1][j - 1] += dp[i][j];
          dp[i + 1][j - 1] %= MOD;
        } else {
          dp[i + 1][j] += dp[i][j];
          dp[i + 1][j] %= MOD;
        }
      }
    }
  }

