int H, W, K;
ll dp[101][10];//dp[x][y]で高さxにおける左からy本目に到達する横棒の置き方
int main() {
	cin >> H >> W >> K;
	fill(dp[0], dp[H + 1], 0);
	for (int i = 0; i < W; ++i) {
		if (i == 0)dp[0][i] = 1;
		else dp[0][i] = 0;
	}
	for (int i = 0; i < H; ++i) {
		for (int j = 0; j < 1 << (W - 1); ++j) {
			bool ignore = false;
			for (int l = 0; l < W - 2; ++l) {
				if (j >> l & 1 && j >> (l + 1) & 1) {
					ignore = true;
				}
			}
			if (!ignore) {
				for (int l = 0; l < W; ++l) {
					if (l != 0 && j >> (l - 1) & 1)dp[i + 1][l] += dp[i][l-1];
					else if (l != W - 1 && j >> l & 1)dp[i + 1][l] += dp[i][l + 1];
					else dp[i + 1][l] += dp[i][l];
					dp[i + 1][l] %= INF;
				}
			}
		}
	}
	cout << dp[H][K - 1] << endl;
	return 0;
}

