    cin >> H >> W >> K;
    vector<int> dummy_dp(8, 0);
    dummy_dp[0] = dummy_dp[1] = 1;
    for(int i = 2; i < 8; i++)
        dummy_dp[i] = dummy_dp[i-1] + dummy_dp[i-2];
    vector<ll> dp(W+1, 0);
    dp[1] = 1;
    for(int h = 0; h < H; h++) {
        vector<ll> new_dp(W+1, 0);
