                new_dp[i] += dp[i-1] * (dummy_dp[i-1-1]) * (dummy_dp[W-i]);
                new_dp[i] %= mod;
            }
            if (i+1 <= W) { // from right
                new_dp[i] += dp[i+1] * (dummy_dp[i-1]) * (dummy_dp[W-i-1]);
                new_dp[i] %= mod;
            }
        }
        dp.swap(new_dp);
    }
