const ll DENOMI = 1000000007;

int main()
{
	ll h, w, k;
	cin >> h >> w >> k;
	auto ans = vector<vector<ll>>(h + 1, vector<ll>(w + 1, 0));
	ans[0][0] = 1;
	auto select = vector<bool>(w);
	auto rec = [&](auto rec, int f, int rem, int s) -> void {
		if(rem == 0){
			for(auto i = 0; i < w; ++i){
				if(select[i]){
					ans[f][i] = (ans[f][i] + ans[f - 1][i + 1]) % DENOMI;
					ans[f][i + 1] = (ans[f][i + 1] + ans[f - 1][i]) % DENOMI;
					++i;
				} else{
					ans[f][i] = (ans[f][i] + ans[f - 1][i]) % DENOMI;
				}
			}
			return;
		}
		if(s >= w - 1){
			return;
		}
		rec(rec, f, rem, s + 1);
		select[s] = true;
		rec(rec, f, rem - 1, s + 2);
		select[s] = false;
	};

	for(auto i = 1; i <= h; ++i){
		for(auto j = 0; j <= w / 2; ++j){
			rec(rec, i, j, 0);
		}
	}

	cout << ans[h][k - 1] << endl;
	return 0;
}

