using mint = ModInt<1000000007>;

mint nccomb(int n) {
    mint ans = 1;
    for (int i = 1; i <= (n+1)/2; ++i) {
        ans += mint::repcomb(n+1-i*2+1, i);
    }
    return ans;
}

