//dp[i][j]=1番からi階層でjにたどり着くあみだくじのi番目までの作り方の総和
signed main() {
	cin >> h >> w >> k;
	dp[0][0] = 1;
	for (int i = 1; i <= h; i++) {
		for (int k = 0; k < (1 << (w - 1)); k++) {
			for (int j = 0; j < w - 2; j++) {
				if (k & (1 << j) && k & (1 << (j + 1))) {
					goto loop;
				}
			}
			for (int j = 0; j < w; j++) {
				if (k & (1 << j)) {
					dp[i][j] = (dp[i][j] + dp[i - 1][j + 1]) % Mod;
					dp[i][j + 1] = (dp[i][j + 1] + dp[i - 1][j]) % Mod;
					j++;
				}
				else {
					dp[i][j] = (dp[i][j] + dp[i - 1][j]) % Mod;
				}
			}
		loop:;
		}
	}
	cout << dp[h][k - 1] << endl;
}

#include "bits/stdc++.h"
using namespace std;
long long Mod = 1000000007;
long long dp[105][10];

void Process( int h , int w ){
	int i , j , k , limit = ( 1 << (w - 1) );
	bool Possible;
	dp[0][0] = 1;

	for( i = 1 ; i <= h ; ++i ){
		for( j = 0 ; j < limit ; ++j ){
			Possible = true;

			for( k = 0 ; k < 6 ; ++k ){
				if( (( j >> k ) & 1) && ((j >> (k + 1)) & 1 ) ){
					Possible = false;
					break;
				}	
			}

			if( Possible == false ) continue;
			if( !(j & 1) ) dp[i][0] = ( dp[i][0] + dp[i - 1][0] ) % Mod;
			if( ( j & 1 ) ) dp[i][0] = ( dp[i][0] + dp[i - 1][1] ) % Mod;

			for( k = 1 ; k < w ; ++k ){
				if( ( ( j >> ( k - 1 ) ) & 1 ) ) dp[i][k] = ( dp[i][k] + dp[i - 1][k - 1] ) % Mod; 
				if( ( ( j >> k ) & 1 ) ) dp[i][k] = ( dp[i][k] + dp[i - 1][k + 1] ) % Mod;
				if( !( ( j >> ( k - 1 ) ) & 1 ) && !( ( j >> k ) & 1 ) )
					dp[i][k] = ( dp[i][k] + dp[i - 1][k]  ) % Mod;	
			}
		}
	}
}

int main(){
	int h , w , k;
	scanf( "%d%d%d" , &h , &w , &k );

	if( w == 1 ){
		puts( "1" );
		return 0;
	}

	Process( h , w );
	printf( "%lld\n" , dp[h][k - 1] );
	return 0;
}

