vecint con;
////////////////////////////////////////////////
void dfs(int i, int iscon) {
  if (i != -1) {
    con[i] = iscon;
  }
  if (i == w - 2) {
    // REP(p, w - 1) { cout << con[p] << " "; }
    // cout << endl;
    REP(p, w) {
      if (p > 0 && con[p - 1]) {
        link[p - 1][p]++;
      } else if (p < w - 1 && con[p]) {
        link[p + 1][p]++;
      } else {
        link[p][p]++;
      }
    }
  } else {
    if (iscon) {
      dfs(i + 1, 0);
    } else {
      dfs(i + 1, 1);
      dfs(i + 1, 0);
    }
  }
}
