      } else if (j == w - 1) {
        dp[i + 1][j] =
            dp[i][j] * link[j][j] % MOD + dp[i][j - 1] * link[j - 1][j] % MOD;
      } else {
        dp[i + 1][j] = dp[i][j] * link[j][j] % MOD +
                       dp[i][j - 1] * link[j - 1][j] % MOD +
                       dp[i][j + 1] * link[j + 1][j] % MOD;
