constexpr int kMod = 1000000007;

int main() {
  int H, W, K; std::cin >> H >> W >> K;
  std::vector<std::vector<long long>> d(H+1, std::vector<long long>(W, 0));

  int countup[8] = {};
  for (int i = 0; i < 9; ++i) {
    if (i == 0)      countup[i] = 1;
    else if (i == 1) countup[i] = 2;
    else if (i == 2) countup[i] = 3;
    else countup[i] = countup[i-2] + countup[i-1];
  }

  d[H][K-1] = 1;
  for (int l = H - 1; l >= 0; --l) {
    for (int w = 0; w < W; ++w) {
      // left
      long long pattern1 = 1;
      int left1 = w-1;
      int right1 = w;
      if (left1>=0) {
        int left_num_edge = left1 - 1;
        if (left_num_edge > 0) pattern1 *= countup[left_num_edge];

        int right_num_edge = W - right1 - 2;
        if (right_num_edge > 0) pattern1 *= countup[right_num_edge];

        d[l][w] += static_cast<long long>(pattern1*d[l+1][left1]);
      }

      // middle
      long long pattern2 = 1;
      int left2 = w;
      int right2 = w;
      {
        int left_num_edge = left2 - 1;
        if (left_num_edge > 0) pattern2 *= countup[left_num_edge];

        int right_num_edge = W - right2 - 2;
        if (right_num_edge > 0) pattern2 *= countup[right_num_edge];

        d[l][w] += static_cast<long long>( pattern2*d[l+1][w]);
      }

      // right
      long long pattern3 = 1;
      int left3 = w;
      int right3 = w + 1;
      if (right3 < W) {
        int left_num_edge = left3 - 1;
        if (left_num_edge > 0) pattern3 *= countup[left_num_edge];

        int right_num_edge = W - right3 - 2;
        if (right_num_edge > 0) pattern3 *= countup[right_num_edge];

        d[l][w] += static_cast<long long>(pattern3*d[l+1][right3]);
      }
     d[l][w] %= kMod;
    }
  }
  std::cout << d[0][0] << std::endl;
}

