const int MOD = 1e9+7;

int main() {
  int H, W, K; cin >> H >> W >> K;
  K--; // 0-indexed

  /* dp[h][x] : 横線がh段で、最終的に縦棒1から縦棒xにたどり着くあみだくじの数 */
  vector<vector<long long>> dp(H+1, vector<long long>(W));
  dp[0][0] = 1;

  for (int h = 0; h < H; h++) {
    /* hからh+1に行くときの横棒の置き方を全探索 */
    for (int b = 0; b < (1 << (W - 1)); b++) {

      /* isOK : 横棒が隣り合わない？ */
      bool isOK = true;
      for (int i = 0; i < W - 2; i++) {
        if ((b >> i) % 4 == 3) isOK = false;
      }
      if (!isOK) {
        continue;
      }

      /* 横棒を置いて位置をswap */
      int perm[W];
      for (int i = 0; i < W; i++) {
        perm[i] = i;
      }
      for (int i = 0; i < W - 1; i++) {
        if ((b >> i) & 1) {
          swap(perm[i], perm[i+1]);
        }
      }

      /* 配る */
      for (int i = 0; i < W; i++) {
        dp[h+1][perm[i]] += dp[h][i];
        dp[h+1][perm[i]] %= MOD;
      }
    }
  }
  cout << dp[H][K] << endl;
}

