// 端点を共有する横棒の存在しない横棒配置パターン
// 左からi番目に横棒が存在 -> 下からibit目が1
const vector<int> valid_k(int W) {
    vector<int> v;
    for (int k=0; k<(1<<(W-1)); k++) {
        bool valid = true;
        for (int l=0; l<W-1; l++) {
            if (bitof(k, l) & bitof(k, l+1)) {
                valid = false;
                break;
            }
        }
        if (valid) {
            v.push_back(k);
        }
    }

    return v;
}

int main(int argc, char *argv[])
{
    int H, W, K;
    cin >> H >> W >> K;

    vector<vector<int>> dp(H+1, vector<int>(W));

    dp[0][0] = 1;
    for (int i=1; i<=H; i++) {
        for (int j=0; j<W; j++) {
            for (const auto k : valid_k(W)) {
                if (j >= 1 && bitof(k, j-1)) {
                    // 左へ移動
                    dp[i][j-1] = (dp[i][j-1] + dp[i-1][j]) % M;
                } else if (j < W-1 && bitof(k, j)) {
                    // 右へ移動
                    dp[i][j+1] = (dp[i][j+1] + dp[i-1][j]) % M;
                } else {
                    // 左右へ移動なし
                    dp[i][j] = (dp[i][j] + dp[i-1][j]) % M;
                }
            }
        }
    }

    cout << dp[H][K-1] << endl;

    return 0;
}

