					dp[r+1][c] += dp[r][c+1];
					dp[r+1][c] %= MOD;
					dp[r+1][c+1] += dp[r][c];
					dp[r+1][c+1] %= MOD;
					++c;
				} else {
					dp[r+1][c] += dp[r][c];
					dp[r+1][c] %= MOD;
				}
			}
		}
	}
	cout << dp[h][z] % MOD << endl;
	return 0;
}

