const ll mod=1000000007;

ll fib(int x){
  if(x==0){return 0;}
  else if(x==1){return 1;}
  else{
    return fib(x-1)+fib(x-2);
  }
}


ll solve(int H, int W, int K){
  vvl dp(H+1, vl(W));
  dp[0][0]=1;

  for (int i=0;i<H;++i){
    for (int j=0;j<W;++j){
      ll L=dp[i][j-1]*fib(j-1)*fib(W-j-1)%mod;
      ll R=dp[i][j+1]*fib(j)*fib(W-j)%mod;
      ll C=dp[i][j]*fib(j-1)*fib(W-j-1)%mod;
      dp[i+1][j]=(L+R+C)%mod;
    }
  }

  return dp[H][K-1];
}

int main(){
  int H, W, K;cin>>H>>W>>K;
  ll ans = solve(H, W,K);
  cout << ans << endl;
  return 0;
}

