    cin >> h >> w >> k;
    vvl dp(h + 1, vl(w, 0));
    dp[0][0] = 1;
    vl cases(8, 0);
    cases[0] = 1;
    for (int i = 1; i <= 7; ++i) {
        for (int j = 0; j < 1 << i; ++j) {
            bool valid = true;
            for (int k = 0; k < i - 1; ++k) {
                if ((j & 1 << k) && (j & 1 << (k + 1))) {
                    valid = false;
                    break;
                }
            }
            if (valid)
                cases[i]++;
        }
    }
    for (int i = 1; i <= h; ++i) {
        for (int j = 0; j < w; ++j) {
            ll tempmid = dp[i - 1][j];
            if (j > 1)
                tempmid = tempmid * cases[j - 1] % MOD;
            if (j < w - 2)
                tempmid = tempmid * cases[w - (j + 2)] % MOD;
            ll templeft = 0;
            ll tempright = 0;
            if (j > 0) {
                templeft = dp[i - 1][j - 1];
                if (j > 2)
                    templeft = templeft * cases[j - 2] % MOD;
                if (j < w - 2)
                    templeft = templeft * cases[w - (j + 2)] % MOD;
            }
            if (j < w - 1) {
                tempright = dp[i - 1][j + 1];
                if (j > 1)
                    tempright = tempright * cases[j - 1] % MOD;
                if (j < w - 3)
                    tempright = tempright * cases[w - (j + 3)] % MOD;
            }
            dp[i][j] = (tempmid + templeft + tempright) % MOD;
        }
    }
    cout << dp[h][k - 1] << endl;
    return 0;
}

#include <bits/stdc++.h>

long long modnum = 1000000007;

long long unrelated(int index, bool ber){
    long long ber_e = (ber == true);
    long long ber_ne = (ber == false);
    while(index > 0){
        long long new_ber_e = ber_ne;
        long long new_ber_ne = (ber_e + ber_ne) % modnum;

        ber_e = new_ber_e;
        ber_ne = new_ber_ne;
        index--;
    }
    return (ber_e + ber_ne) % modnum;
}

int main(){
    int H, W, K;
    std::cin >> H >> W >> K;

    std::vector< std::vector< long long > > cnt(H+1, std::vector< long long >(W, 0));
    cnt[0][0] = 1;
    for(int i=1; i<W; i++){
        cnt[0][i] = 0;
    }

    for(int i=1; i<=H; i++){
        for(int j=0; j<W; j++){
            long long cur = 0;
            long long tmp;
            if(j != 0){
                tmp = (unrelated(j-1, true) * unrelated(W - j - 2, false)) % modnum;
                tmp = (tmp * cnt[i-1][j-1]) % modnum;
                cur = (cur + tmp) % modnum;
            }

            tmp = (unrelated(j-1, false) * unrelated(W - j - 2, false)) % modnum;
            tmp = (tmp * cnt[i-1][j]) % modnum;
            cur = (cur + tmp) % modnum;

            if(j != W-1){
                tmp = (unrelated(j-1, false) * unrelated(W - j - 2, true)) % modnum;
                tmp = (tmp * cnt[i-1][j+1]) % modnum;
                cur = (cur + tmp) % modnum;
            }
            cnt[i][j] = cur;
        }
    }

    std::cout << cnt[H][K-1] << std::endl;;

    return 0;

}

