void getLegal(vector<vector<int> >& bars, const int W) {
  for(int mask = 0; mask < (1<<(W-1)); mask++) {
    bool ok = true;
    REP(i, W-2) {
      if(((mask >> i)&1) != 0) {
        if(((mask >> (i+1))&1) != 0) {
          ok = false;
        }
      }
