Int INF = 1LL << 60;
const Int MOD = 1000000000 + 7;

template<int Modulo = MOD> struct Mint {
	Int val;
	constexpr Mint(Int v = 0) noexcept : val(v% Modulo) {
		if (val < 0) v += Modulo;
	}
	constexpr int getmod() { return Modulo; }
	constexpr Mint operator - () const noexcept { return val ? Modulo - val : 0; }
	constexpr Mint operator + (const Mint& r) const noexcept { return Mint(*this) += r; }
	constexpr Mint operator - (const Mint& r) const noexcept { return Mint(*this) -= r; }
	constexpr Mint operator * (const Mint& r) const noexcept { return Mint(*this) *= r; }
	constexpr Mint operator / (const Mint& r) const noexcept { return Mint(*this) /= r; }
	constexpr Mint& operator += (const Mint& r) noexcept {
		val += r.val;
		if (val >= Modulo) val -= Modulo;
		return *this;
	}
	constexpr Mint& operator -= (const Mint& r) noexcept {
		val -= r.val;
		if (val < 0) val += Modulo;
		return *this;
	}
	constexpr Mint& operator *= (const Mint& r) noexcept {
		val = val * r.val % Modulo;
		return *this;
	}
	constexpr Mint& operator /= (const Mint& r) noexcept {
		Int a = r.val, b = Modulo, u = 1, v = 0;
		while (b) {
			Int t = a / b;
			a -= t * b; swap(a, b);
			u -= t * v; swap(u, v);
		}
		val = val * u % Modulo;
		if (val < 0) val += Modulo;
		return *this;
	}
	constexpr bool operator == (const Mint& r) const noexcept {
		return this->val == r.val;
	}
	constexpr bool operator != (const Mint& r) const noexcept {
		return this->val != r.val;
	}
	friend ostream& operator << (ostream& os, const Mint<Modulo>& x) noexcept {
		return os << x.val;
	}
	friend istream& operator >> (istream& is, Mint<Modulo>& x) noexcept {
		Int tmp; is >> tmp;
		x = Mint<Modulo>(tmp);
		return is;
	}
	friend constexpr Mint<Modulo> modpow(const Mint<Modulo>& a, Int n) noexcept {
		Mint res(1), tmp = a;
		while (n > 0) {
			if (n & 1) res *= tmp;
			tmp *= tmp;
			n >>= 1;
		}
		return res;
	}
};

using mint = Mint<>;

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	Int H, W, K;
	cin >> H >> W >> K;

	vector<vector<mint>> dp(H + 1, vector<mint>(W, mint(0LL)));
	dp[0][0] = 1;

	for (Int i = 0; i < H; i++) {

		//bit全探索で横棒の位置を決定
		for (Int bit = 0; bit < (1LL<<(W-1)); bit++) {

			//横棒が二本連続していないか
			Int flag = 0;
			for (Int j = 0; j < W-2; j++) {
				if ((bit & (1LL << j)) && (bit & (1LL << (j + 1)))) {
					flag = 1;
					break;
				}
			}
			if (flag)continue;

			//dpの遷移
			for (Int j = 0; j < W-1; j++) {
				//横棒がある場合（スワップされる）
				if (bit & (1LL << j)) {
					dp[i + 1][j] += dp[i][j + 1];
					dp[i + 1][j + 1] += dp[i][j];
				}
				//横棒がない場合（そのまま降りる）
				else {
					dp[i + 1][j] += dp[i][j];
					dp[i + 1][j + 1] += dp[i][j + 1];
				}
			}
		}
	}

	if (W == 1) {
		cout << 1 << "\n";
	}
	else {
		cout << dp[H][K - 1] << "\n";
	}
}

