  fill(dp[0],dp[H+1],0);
  dp[0][0] = 1; //dp[h][k] h列目で0からスタートした阿弥陀がkにくる数

  rep(h,H){//H段だけ繰り返す
    for(int b = 0; b < (1 << (W-1)); b++){ //各H段でW-1本まで線が引ける。（ただし、連続はできない）
      bool judge = true; //横線が隣り合っているかどうか判定
      for(int i = 0; i < W - 2;i++){
        if((b >> i) % 4 == 3) judge = false; //bをiだけ右に動かして、末尾がXXXX11となっていたら横線が隣り合っている
      }

      if(!judge) continue;

      int perm[W]; //各始点が何処に移動するか。W本に合わせて用意
      rep(i,W) perm[i] = i; //初期化。
      for(int i=0; i<W-1;i++){
        if((b>>i) & 1) swap(perm[i], perm[i+1]); //i桁目が1だったら、そこに線あるので位置をスワップ
      }

      //配るDP
      rep(i,W){
        dp[h+1][perm[i]] += dp[h][i];
        dp[h+1][perm[i]] %= MOD;
      }
    }
  }

  cout << dp[H][K] << endl;
  return 0;
}

