int mem[102][8];
int dp(int ch, int ik, int K, int W) {
	if (ch == 0) return ik == K;
	if (mem[ch][ik] != -1) return mem[ch][ik];
//	cout << string(ik, '\t') << ch << " " << ik << endl;
	int L = (1 << (W - 1));
	Long w = 0;
	for (int i = 0; i < L; ++i) {
		if ( (i >> 1) & i ) continue;
		if (ik < W-1 && ik > 0) {
			int baf = (i >> (ik)) & 1;
			int bbe = (i >> (ik-1)) & 1;
			if (baf) {
				w += dp(ch-1, ik+1, K, W);
			} else if (bbe) {
				w += dp(ch-1, ik-1, K, W);
			} else {
				w += dp(ch-1, ik, K, W);
			}
		} else if (ik < W-1) {
			int b = (i >> (ik)) & 1;
			if (b) {
				w += dp(ch-1, ik+1, K, W);
			} else {
				w += dp(ch-1, ik, K, W);
			}
		} else if (ik > 0) {
			int b = (i >> (ik - 1)) & 1;
			if (b) {
				w += dp(ch - 1, ik - 1, K, W);
			} else {
				w += dp(ch - 1, ik, K, W);
			}
		} else {
			w += dp(ch-1, ik, K, W);
		}
	}
	return mem[ch][ik] = w % 1000000007;

}

