int pattern[7];

void calc_pattern(int depth, bool exists) {
    if (exists) pattern[depth] += 1;
    else        pattern[depth] += 2;

    if (depth == 6) return;

    calc_pattern(depth + 1, false);
    if (!exists) calc_pattern(depth + 1, true);
}

int main() {
