        if (W - j - 2 >= 0) scale *= pattern[W - j - 2];
        dp[i + 1][j] += dp[i][j - 1] * scale;
        dp[i + 1][j] %= MOD;

        scale = 1;
        if (j - 3 >= 0) scale *= pattern[j - 3];
        if (W - j - 2 >= 0) scale *= pattern[W - j - 2];
