const long long MOD = 1000000007;

ll calcMulti(ll w, ll check, ll W) {
  ll multi = 0;
  for (ll i = 0; i < (1 << W - 1); i++) {
    if (((i >> w) & 1) != check) {
      continue;
    }
    bool flag = true;
    for (ll j = 0; j < W - 1; j++) {
      if (((i >> j) & 1) == 1 && ((i >> (j + 1)) & 1) == 1) {
        flag = false;
        break;
      }
    }
    if (flag) {
      multi++;
    }
  }
  return multi;
}

ll calcMulti2(ll w, ll check, ll w2, ll check2, ll W) {
  ll multi = 0;
  for (ll i = 0; i < (1 << W - 1); i++) {
    if (((i >> w) & 1) != check || (((i >> w2) & 1) != check2)) {
      continue;
    }
    bool flag = true;
    for (ll j = 0; j < W - 1; j++) {
      if (((i >> j) & 1) == 1 && ((i >> (j + 1)) & 1) == 1) {
        flag = false;
        break;
      }
    }
    if (flag) {
      multi++;
    }
  }
  return multi;
}

void solve(long long H, long long W, long long K) {
  if (W == 1) {
    print(1);
    return;
  }

  vector<vl> dp(H + 1, vl(W));
  dp[0][0] = 1;
  rep(h, 1, H + 1) {
    rep(w, 0, W) {
      if (w == 0) {
        dp[h][w] = dp[h - 1][w] * calcMulti(0, 0, W) % MOD;
        dp[h][w] += dp[h - 1][w + 1] * calcMulti(0, 1, W);
        dp[h][w] %= MOD;
      } else if (w == W - 1) {
        dp[h][w] = dp[h - 1][w] * calcMulti(w - 1, 0, W) % MOD;
        dp[h][w] += dp[h - 1][w - 1] * calcMulti(w - 1, 1, W);
        dp[h][w] %= MOD;
      } else {
        dp[h][w] = dp[h - 1][w] * calcMulti2(w - 1, 0, w, 0, W) % MOD;
        dp[h][w] += dp[h - 1][w - 1] * calcMulti(w - 1, 1, W);
        dp[h][w] %= MOD;
        dp[h][w] += dp[h - 1][w + 1] * calcMulti(w, 1, W);
        dp[h][w] %= MOD;
      }
    }
  }
  print(dp[H][K - 1]);
}

int main() {
  long long H;
  scanf("%lld", &H);
  long long W;
  scanf("%lld", &W);
  long long K;
  scanf("%lld", &K);
  solve(H, W, K);
  return 0;
}

