mint dp[110][10];

void solve(ostringstream& aout, long long H, long long W, long long K){

	if (W == 1) {
		cout << 1 << "\n";
		return;
	}

	dp[0][0] = 1;

	REPS(y, H) {
		rep(S, 1 << (W - 1)) {
			bool isOk = true;
			rep(i, 10) {
				if ((S & (1LL << i)) && (S & (1LL << (i+1)))) {
					isOk = false;
				}
			}
			if (!isOk) {
				continue;
			}
			rep(i, W - 1) {
				if (S & (1LL << i)) {
					dp[y][i] += dp[y - 1][i + 1];
					dp[y][i + 1] += dp[y - 1][i];
				}
			}

			// そのまま下へ
			if (!(S & 1LL)) {
				dp[y][0] += dp[y-1][0];
			}
			if (!(S & (1LL << (W - 2)))) {
				dp[y][W-1] += dp[y-1][W-1];
			}
			REP(i, 1, W - 1) {
				if (!(S & (1LL << (i - 1))) && !(S & (1LL << i))) {
					dp[y][i] += dp[y-1][i];
				}
			}

		}
	}

	cout << dp[H][ K - 1 ] << "\n";
}

