                if(k>>l&1 && k>>(l+1)&1) ok = false;
            }
            if(ok){
                if(k>>j&1){
                    dp[i+1][j] += dp[i][j+1];
                    dp[i+1][j-1] %= MOD;
                }
                else if(j >= 1 && k>>(j-1)&1){
                    dp[i+1][j] += dp[i][j-1];
                    dp[i+1][j] %= MOD;
                }
                else{
                    dp[i+1][j] += dp[i][j];
                    dp[i+1][j] %= MOD;
                }
            }
        }
    }
    cout << dp[H][K] << endl;
}

