lint p = 1000*1000*1000 + 7;

lint pattern(lint S, lint K, lint left, lint W) {
  if (S < 1 || S > W) return 0;
  if (left == 1) {
    if (S == K-1) {
      return others(S-2)*others(W-S-2);
    } else if (S == K+1) {
      return others(S-3)*others(W-S-1);
    } else if (S == K) {
      return others(S-2)*others(W-S-1);
    } else {
      return 0;
    }
  } else {
    return (others(S-2)*others(W-S-2)*pattern(S+1, K, left-1, W) % p +
      others(S-3)*others(W-S-1)*pattern(S-1, K, left-1, W) % p +
      others(S-2)*others(W-S-1)*pattern(S, K, left-1, W) % p) % p;
  }
}

lint others(lint width) {
  if (width < 0) return 1;
  lint dp[width+1];
  dp[0] = 1;
  dp[1] = 2;
  for (int i=2; i<width+1; i++) {
    dp[i] = dp[i-1] + dp[i-2];
  }
  return dp[width];
}

