void init(){
    ll i, j;
    tot = 1;
    for(i = 1<<1; i < (1<<W); i+=2){
        bool ok = 1;
        for(j = 1; j <= W-2; ++j){
            if(i>>j & 1 && i>>(j+1) & 1){
                ok = 0;
                break;
            }
        }
        if(ok){
            tot++;
            for(j = 1; j <= W-1; ++j)
                if(i>>j & 1)
                    cnt[j]++;
        }
    }
