ll f(ll h, ll x){
    if(x < 1 || x > W)
        return 0;
    if(dp[h][x] != -1)
        return dp[h][x];
    dp[h][x] = (((tot-cnt[x-1]-cnt[x])*f(h-1,x)%MOD
               + cnt[x-1]*f(h-1,x-1)%MOD)%MOD
               + cnt[x]*f(h-1,x+1)%MOD)%MOD;
    return dp[h][x];
}

