    for(int w = 0; w <= 8; w++){
        for(int i = 0; i < (1 << w); i++){
            bool ok = true;
            for(int bit = 0; bit < w - 1; bit++){
                if((i & (1 << bit)) && (i & (1 << (bit + 1)))){
                    ok = false;
                }
            }
            if(ok){
                row[w]++;
            }
        }
