                    left = row[w - 2];
                }
                long long right = 1;
                if(w <= W - 3){
                    right = row[W - w - 2];
                }
                dp[h][w] += dp[h-1][w-1] * left % mod * right % mod;
                dp[h][w] %= mod;
            }
            if(w < W - 1){
                long long left = 1, right = 1;
                if(w >= 1){
                    left = row[w - 1];
                }
                if(w <= W - 3){
