                } else if(w < W-1 && bs[w]){ // to right side
                    dp[h+1][w+1] = (dp[h+1][w+1] + dp[h][w]) % MOD;
                } else {
                    dp[h+1][w] = (dp[h+1][w] + dp[h][w]) % MOD;
                }
            }
        }
    }
