const int MOD = 1e9+7;

void addM(int & a, int b){
    a = (a+b) % MOD;
}

// numを二進数化した時に2^nのビットがonであるかを判定する
bool is_nth_bit_on(int num, int n){
    return (num >> n) & 1;
}

int main(){
    int H, W, K;
    cin >> H >> W >> K;

    // dp[i][j]:1:1からi：j（i行目のj列目）に移動する場合の数
    auto dp = make_vec<int>(101,8);

    // i本目から次行のj本目に移動する場合の数
    auto num = make_vec<int>(8,8);

    // あみだクジの場合の数を事前準備
    REP(b,1<<(W-1)){
        // 隣合うビットが立っていないかの確認
        bool ok = true;
        REP(i,W-2){
            if(is_nth_bit_on(b, i) && is_nth_bit_on(b, i+1)){
                ok = false;
                break;
            }
        }
        if(!ok) continue;

        vector<int> P(W);iota(all(P),0);

        // i番目のフラグがONである＝その橋を渡って、i番目とi+1番目が次行で入れ替わる
        // i番目のフラグがOFFである＝i番目はそのまま次行に行く
        REP(i,W-1) if(is_nth_bit_on(b, i)) swap(P[i], P[i+1]);

        // 算出結果を数え上げていく
        REP(i,W) num[i][P[i]]++;
    }

    // DP実行
    dp[0][0] = 1;
    REP(i,H) REP(j,W) {
        // そのまま次行に遷移
        addM(dp[i+1][j], dp[i][j] * num[j][j] % MOD);
        // 右のくじに移動して、次行に遷移
        if(j+1<W)  addM(dp[i+1][j+1], dp[i][j] * num[j][j+1] % MOD);
        // 左のくじに移動して、次行に遷移
        if(j-1>=0) addM(dp[i+1][j-1], dp[i][j] * num[j][j-1] % MOD);
    }

    pl(dp[H][K-1]);
    return 0;
}

