ll prob(int f,int e) {
	ll res=1;
	ll l = 1, r = 1;
	l = c[max(0, f)-0];
	r = c[w - 1 - min(e, w - 1)];
	res = l*r;
	return res;
}

ll ans(int h, int k) {
	if (h == 0) {
		if (k == 0)return 1;
		else return 0;
	}
	if (vv[h][k] != -1) {
		return vv[h][k];
	}
	else {
		int hasi = 0;
		if (k == 0 || k == w - 1)hasi++;
		ll res= ans(h - 1, k)*prob(k-1,k+1);
		res %= MOD;
		hasi=(k == 1 || k == w - 1)?1:0;
		if (k != 0) {
			res += ans(h - 1,k - 1) * prob(k - 2, k + 1);
			res %= MOD;
		}
		hasi = (k == 0 || k == w - 2) ? 1 : 0;
		if (k != w - 1) {
			res += ans(h - 1, k + 1) * prob(k - 1, k + 2);
			res %= MOD;
		}
		vv[h][k] = res;
		return res;
	}
}

