const llong MOD = 1e9+7;

llong H, W, K;
vector<llong> table;

//棒の数からあみだの組み合わせを得る
//メモ化再帰
llong num(llong bar) {
    if (bar <= 1) return 1ll;
    if (table[bar] != -1) return table[bar];
    llong res = 0;
    for (int i = 0; i < bar-1; i++) {
        res += num(i)*num(bar-i-1)*2;
        res %= MOD;
    }
    return res;
}

int main() {
    cin >> H >> W >> K; K--;
    table = vector<llong>(W+1, -1);
    for (int i = 0; i <= W; i++) table[i] = num(i);
    vector<vector<llong>> dp(H+1, vector<llong>(W, 0));

    dp[0][0] = 1;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (j != 0) {
                llong coe = table[j-1]*table[W-j-1];
                dp[i+1][j-1] += dp[i][j] * coe;
                dp[i+1][j-1] %= MOD;
            }
            if (j != W-1) {
                llong coe = table[j]*table[W-j-2];
                dp[i+1][j+1] += dp[i][j] * coe;
                dp[i+1][j+1] %= MOD;
            }
            llong coe = table[j]*table[W-j-1];
            dp[i+1][j] += dp[i][j] * coe;
            dp[i+1][j] %= MOD;
        }
    }
    cout << dp[H][K] << endl;
    cout << table[2] << endl;
    return 0;
}

