const ll MOD = 1000000007;

ll modpow(ll x, ll n, ll mod = MOD) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int H, W, K;
    cin >> H >> W >> K;
    K--;

    if (W == 1) {
        cout << 1 << endl;
        return 0;
    }

    vector< vector<int> > vs;
    for (int i = 0; i < (1 << (W - 1)); i++) {
        vector<int> v(W);
        for (int j = 0; j < W; j++) v[j] = j;

        bool flag = true;
        for (int j = 0; j < W - 1; j++) {
            if ((i & (1 << j)) == 0) continue;
            if (i & (1 << (j + 1))) {
                flag = false;
                break;
            }
            swap(v[j], v[j + 1]);
        }

        if (!flag) continue;

        vs.push_back(v);
    }

    vector<ll> dp(W, 0);
    dp[0] = 1;

    for (int i = 0; i < H; i++) {
        vector<ll> ndp(W, 0);
        for (vector<int>& v : vs) {
            for (int j = 0; j < W; j++) {
                (ndp[v[j]] += dp[j]) %= MOD;
            }
        }

        dp = move(ndp);
    }
    cout << dp[K] << endl;
    return 0;
}

