#include<bits/stdc++.h>
const int mod=1000000007;
using namespace std;
int main(){
    int h,w,k;
    cin>>h>>w>>k;
    if(w==1){
        cout<<"1"<<endl;
        return 0;
    }
    int W=1;
    for(int i=0;i<w-1;i++)W*=2;
    long long dp[h+1][w]={};
    dp[0][0]=1;
    for(int i=0;i<h;i++){
        for(int j=0;j<w;j++){
            int left=0,right=0,straight=0;
            for(int l=0;l<W;l++){
                int x=l;
                int line[w-1]={};
                bool b=false;
                for(int m=0;m<w-1;m++){
                    if(x%2){
                        line[m]=1;
                        if(m && line[m-1]){
                            b=true;
                            break;
                        }
                    }
                    x/=2;
                }
                if(b)continue;
                if(j==0){
                    if(line[j])right++;
                    else straight++;
                }
                else if(j==w-1){
                    if(line[j-1])left++;
                    else straight++;
                }
                else{
                    if(line[j-1])left++;
                    else if(line[j])right++;
                    else straight++;
                }
            }
            if(j)dp[i+1][j-1]+=dp[i][j]*left%mod;
            if(j<w-1)dp[i+1][j+1]+=dp[i][j]*right%mod;
            dp[i+1][j]+=dp[i][j]*straight%mod;
        }
    }
    cout<<dp[h][k-1]%mod<<endl;
    return 0;
}

