int mod = 1'000'000'007;

int main(){
    int h, w, k;
    cin >> h >> w >> k;
    if (w == 1) {
        cout << 1 << endl;
        return 0;
    }
    vector<long long> pre_folk(w - 1, 1);
    for (int i = 2; i < w - 1; i++) pre_folk[i] = pre_folk[i - 1] + pre_folk[i - 2];
    vector<long long> rev_folk = pre_folk;
    reverse(rev_folk.begin(), rev_folk.end());
    vector<long long> folk(w - 1);
    for (int i = 0; i < w - 1; i++) folk[i] = pre_folk[i] * rev_folk[i];
    vector<long long> non_folk(w - 1, 1); if (w - 1 > 1) non_folk[1] = 2;
    for (int i = 2; i < w - 1; i++) non_folk[i] = non_folk[i - 1] + non_folk[i - 2];
    vector<vector<long long>> dp(h + 1, vector<long long>(w, 0));
    dp[0][0] = 1;
    for (int i = 0; i < h; i++){
        for (int j = 0; j < w; j++){
            dp[i + 1][j] += dp[i][j] * (non_folk[max(0, j - 1)] * non_folk[max(0, w - j - 2)]) % mod;
            dp[i + 1][j] %= mod;
            if (j != 0) dp[i + 1][j - 1] += dp[i][j] * folk[j - 1] % mod;
            if (j != 0) dp[i + 1][j - 1] %= mod;
            if (j != w - 1) dp[i + 1][j + 1] += dp[i][j] * folk[j] % mod;
            if (j != w - 1) dp[i + 1][j + 1] %= mod;
        }
    }
    cout << dp[h][k - 1] << endl;
}

