#define bigmod 1000000007
#define lli long long int

lli h, w, k, memo[10][110], kombinasi[10];

lli combine(lli x) {
	if (x < 3)
		return (x + 1);
	if (kombinasi[x] != -1)
		return kombinasi[x];
	kombinasi[x] = combine(x - 1) + combine(x - 2);
	return kombinasi[x];
}

lli dp(lli pos, lli tinggi) {
	lli ret, banyak = 1;
	if (tinggi == 0) {
		if (pos == k)
			return 1;
		return 0;
	}
	if (memo[pos][tinggi] != -1)
		return memo[pos][tinggi];
	if (pos > 2)
		banyak *= combine(pos - 2);
	if (pos < w - 1)
		banyak *= combine(w - pos - 1);
	ret = dp(pos, tinggi - 1) * banyak;
	ret %= bigmod;
	if (pos > 1) {
		banyak = 1;
		if (pos > 3)
			banyak *= combine(pos - 3);
		if (w > pos + 1)
			banyak *= combine(w - pos - 1);
		ret += (dp(pos - 1, tinggi - 1) * banyak);
		ret %= bigmod;
	}
	if (pos < w) {
		banyak = 1;
		if (pos > 2)
			banyak *= combine(pos - 2);
		if (w > pos + 2)
			banyak *= combine(w - pos - 2);
		ret += (dp(pos + 1, tinggi - 1) * banyak);
		ret %= bigmod;
	}
	memo[pos][tinggi] = ret;
	return ret;
}

