typedef pair<ll, ll> LP;

ll POW(ll m,ll n)
{
  if(n<0) return 0;
  if(n==0) return 1;
  return m*POW(m,n-1)%MOD;
}

ll gcd(ll u, ll v) {
  ll r;
  while (0 != v) {
    r = u % v; u = v; v = r;
  }
  return u;
}

ll KAI(ll m)
{
  if(m<0) return 0;
  if(m==0) return 1;
  return m*KAI(m-1)%MOD;
}

ll extGCD(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll d = extGCD(b, a%b, y, x);
    y -= a / b * x;
    return d;
}

inline ll mod(ll a, ll m) {
    return (a % m + m) % m;
}

ll modinv(ll a, ll m) {
    ll x, y;
    extGCD(a, m, x, y);
    return mod(x, m);
}

ll COM(ll m,ll n)
{
  if(m<n) return 0;
  if(n<0) return 0;
  if(n==0) return 1;
  if(m==n) return 1;
  return m%MOD*COM(m-1,n)%MOD*modinv(m-n,MOD)%MOD;
}

ll poi(ll x)
{
  if(x<0)return 1;
  if(x==0)return 1;
  if(x==1)return 2;
  if(x==2)return 3;
  if(x==3)return 5;
  if(x==4)return 8;
  if(x==5)return 13;
  if(x==6)return 21;
}

ll mon(ll h,ll w,ll k)
{
  if(k<1)return 0;
  if(k>w)return 0;
  if(h==1&&k==1)return poi(w-2);
  if(h==1&&k==2)return poi(w-3);
  if(h==1)return 0;
  return (mon(h-1,w,k)*poi(w-k-1)*poi(k-2)%MOD+mon(h-1,w,k+1)*poi(w-k-2)*poi(k-2)%MOD+mon(h-1,w,k-1)*poi(w-k-1)*poi(k-3)%MOD)%MOD;
}

int main()
{
  ll h,w,k;
  cin >> h >> w >> k;
  printf("%lld",(mon(h,w,k)+MOD*3)%MOD);
}

