ll dp[110][10];
ll memo_comb[8];

const ll MOD = 1e9+7;

int H, W, K;

calc_dp(int h, int k){

    if(h == 0 && k == 1){
        return dp[h][k] = 1;
    }else if(h == 0){
        return dp[h][k] = 0;
    }

    if(dp[h][k] >= 0) return dp[h][k];

    ll tmp_ans = 0;
    tmp_ans = (tmp_ans + calc_dp(h-1, k) * memo_comb[max(0, k-3)] * memo_comb[max(0, W-k-1)])%MOD;
    tmp_ans = (tmp_ans + calc_dp(h-1, k-1) * memo_comb[max(0, W-k-1)] * memo_comb[max(0, k-4)])%MOD;
    tmp_ans = (tmp_ans + calc_dp(h-1, k+1) * memo_comb[max(0, W-k-2)] * memo_comb[max(0, k-3)])%MOD;
    return dp[h][k] = tmp_ans;
}

