ll dp[MAX_H][MAX_W] = {};
ll H, W, K;
vector<ll> all_pat;

// 現在 i 行 j 列にいるときのパターン数
ll dfs(ll i = 0, ll j = 0) {
    if(i >= H) {
        if(j == K) { return 1; }
        return 0;
    }

    ll& ret = dp[i][j];
    if(~ret) { return ret; }
    ret = 0;

    for(auto& pat : all_pat) {
        if(j > 0 && ((pat >> (j-1)) & 1) ) {
            // 左に移動するパターン
            ret += dfs(i+1, j-1);
            ret %= MOD;
        } else if(j < W-1 && ((pat >> (j)) & 1) ) {
            // 右に移動するパターン
            ret += dfs(i+1, j+1);
            ret %= MOD;
        } else {
            ret += dfs(i+1, j);
            ret %= MOD;
        }
    }

    return ret;
}

signed main()
{
    cin >> H >> W >> K;
    MINUS(dp);
    K--;

    // all_pat の作成
    for(int pat = 0; pat < (1 << (W-1)); ++pat) {
        // 隣り合うビットが 1 のものはダメ
        bool isOk = true;
        for(int i = 0; i < W-2; ++i) {
            if( ((pat >> i) & 1) && ((pat >> (i+1)) & 1) ) {
                isOk = false;
                break;
            }
        }
        if(isOk) { all_pat.push_back(pat); }
    }

    printf("%lld\n", dfs());
    return 0;
}

