const int MAX_H = 105;
const int MAX_W = 10;

int H, W, K;
int dp[MAX_H][MAX_W];

int ww[MAX_W];

int calcW(int w) {
  if(ww[w] != -1) {
    return ww[w];
  }
  if(w <= 1) {
    return ww[w] = 1;
  } else {
    return ww[w] = (calcW(w-1) + calcW(w-2)) % MOD;
  }
}

signed main()
{
  memset(ww, -1, sizeof(ww));
  cin >> H >> W >> K;
  memset(dp, 0, sizeof(dp));
  dp[0][0] = 1;

  REP(h,H) {
    REP(w,W) {
      dp[h+1][w] += (((dp[h][w] * calcW(w) ) % MOD) * calcW(W-w-1) ) % MOD;
      dp[h+1][w] %= MOD;
      //左
      if(w-1 >= 0) {
        dp[h+1][w-1] += (((dp[h][w] * calcW(w-1) ) % MOD) * calcW(W-w-1) ) % MOD;
        dp[h+1][w-1] %= MOD;
      }
      //右
      if(w+1 < W) {
        dp[h+1][w+1] += (((dp[h][w] * calcW(w) ) % MOD) * calcW(W-w-2) ) % MOD;
        dp[h+1][w+1] %= MOD;
      }
    }
  }

  cout << dp[H][K-1] << endl;

  return 0;
}

