void dfs(int i,bool exist,int d,int e){
  if(i == w-2){
    num++;
    return;
  }
  else{
    if(i+1 == d && exist == true){
      return;
    }
    else if(i+1 == d && exist == false){
      dfs(i+1,true,d,e);
    }
    else if(i+1 == e || i+1 == e+1){
      dfs(i+1,false,d,e);
    }
    else if(exist == true){
      dfs(i+1,false,d,e);
    }
    else{
      dfs(i+1,true,d,e);
      dfs(i+1,false,d,e);
    }
  }
  return;
}
