  int p = 1000000007;
  dp[0][0] = 1;
  for(int i=1; i<=H; i++){
    for(int j=0; j<W; j++){
      for(int k=0; k<pow(2, W-1); k++){
        bool flag = false;
        for(int l=0; l<W-2; l++){
          if(((k>>l) & 1) && ((k>>(l+1)) & 1)){
            flag = true;
            break;
          }
        }
        if(flag) continue;
        if(j==0){
          dp[i][j] = (dp[i][j] + dp[i-1][j] * (1-(k&1)) + dp[i-1][j+1] * (k&1)) % p;
        }
        else if(j==W-1){
          dp[i][j] = (dp[i][j] + dp[i-1][j-1] * ((k>>(W-2))&1) + dp[i-1][j] * (1-(k>>W-2)&1)) % p;
        }
        else{
          dp[i][j] = (dp[i][j] + dp[i-1][j-1] * ((k>>(j-1))&1) + dp[i-1][j+1] * ((k>>j)&1)) % p;
