i64 slv(int y, int x)
{
  if (x < 0 || x >= W) abort();

  if (y >= H) {
    if (x == K)
      return 1;
    else
      return 0;
  }

  if (~dp[y][x]) return dp[y][x];

  i64 ans = 0;
  for (int b = 0; b < (1 << (W-1)); ++b) {
    bitset<16> bit(b);
    if (isInvalid(bit)) continue;

    if (bit[x])
      ans = (ans + slv(y+1, x+1)) % MOD;
    else if (bit[x-1])
      ans = (ans + slv(y+1, x-1)) % MOD;
    else
      ans = (ans + slv(y+1, x)) % MOD;
  }

  return dp[y][x] = ans % MOD;
}

