    for(int i = 0; i < H; i++)
    {
        for(int j = 0; j < W; j++)
        {
            // DP(i, j) -> DP(i+1, j-1)への遷移
            if(j == 1) // DP(i, 1) -> DP(i+1, 0) は別処理
            {
                addMod( dp.at(i+1).at(j-1), fib.at(W-2) * dp.at(i).at(j) );
