int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int H, W, K;
    std::cin >> H >> W >> K;

    vector<vector<ll>> dp(H + 1, vector<ll>(W, 0));

    dp[0][0] = 1;
    for(int hi = 1; hi < H + 1; hi++) {
        REP(wi, W) {
            // bit全探索
            for(int i = 0; i < (1 << (W - 1)); i++) {
                [&]() {
                    bool prev_is_assert = false;
                    for(int j = 0; j < W - 1; j++) {
                        if(i & (1 << j)) {
                            if(prev_is_assert) {
                                return;
                            }
                            else {
                                prev_is_assert = true;
                            }
                        }
                        else {
                            prev_is_assert = false;
                        }
                    }

                    bool l = i & (1 << (wi - 1));
                    bool r = i & (1 << wi);
                    if(l) {
                        dp[hi][wi] += dp[hi - 1][wi - 1];
                        dp[hi][wi] %= MOD;
                    }
                    else if(r) {
                        dp[hi][wi] += dp[hi - 1][wi + 1];
                        dp[hi][wi] %= MOD;
                    }
                    else {
                        dp[hi][wi] += dp[hi - 1][wi];
                        dp[hi][wi] %= MOD;
                    }
                }();
