int calc(int h, int w, int s, int e)
{
    if(table[h-1][s][e] != -1) return table[h-1][s][e];

    if(abs(s-e) > h)
        return table[h-1][s][e] = 0;

    int64_t sum = 0;
    if(e > 0)
        sum += mul(calc(h-1, w, s, e-1), calc(1, w, e-1, e));

    sum += mul(calc(h-1, w, s, e), calc(1, w, e, e));

    if(e + 1 < w)
        sum += mul(calc(h-1, w, s, e+1), calc(1, w, e+1, e));

    return table[h-1][s][e] = sum % 1000000007;
}

