	for(ll i=1; i<=w; i++) f[i]=f[i-1]*i%MOD;
	ll invf[9];
	invf[w]=inv(f[w]);
	for(ll i=w-1; i>=0; i--){
		invf[i]=invf[i+1]*(i+1)%MOD;
	}
	for(int i=1; i<w; i++){
		for(int j=0; i+1-j>=j; j++){
			ct[i+1]+=(f[i-j+1]*invf[j]%MOD*invf[i-2*j+1]%MOD);
			ct[i+1]%=MOD;
