long Map(int X, int Y) {
	if (Y == H) {
		long ans = 0;
		if (X == K+1) {
			return meta2[X-1][1];
		} else if (X == K) {
			return meta2[X][0];
		} else if ( X == K-1 ) {
			return meta2[X][1];
		} else
			return 0;
	}

	if (abs(X-K) > abs(H-Y+1)) return 0;

	if (!cache[X][Y]) {
		long result = Map(X, Y+1) * meta2[X][0];
		if (X > 1) {
			result += Map(X-1, Y+1) * meta2[X-1][1];
		}
		if (X < W) {
			result += Map(X+1, Y+1) * meta2[X][1];
		}

		cache[X][Y] = result % MOD;
	}
	return cache[X][Y];
}

