#include <bits/stdc++.h>
using namespace std;

#define MOD 1000000007

long long combination(long long start, long long end, long long W)
{
    long long ret = 0;
    if (start > end)
    {
        swap(start, end);
    }
    if (1 > start)
    {
        return ret;
    }
    if (end > W)
    {
        return ret;
    }
    for (int i = 0; i < (1 << (W - 1)); i++)
    {

        bitset<16> bit(i << 1);
        bool is_valid = true;
        for (int j = 2; j < W; j++)
        {
            if (bit[j - 1] == 1 && bit[j] == 1)
            {
                is_valid = false;
                break;
            }
        }
        if (is_valid)
        {
            if (start == end)
            {
                if (start == 1)
                {
                    if (!bit[1])
                    {
                        ret++;
                    }
                }
                else if (start == W)
                {
                    if (!bit[W - 1])
                    {
                        ret++;
                    }
                }
                else
                {
                    if (!bit[start - 1] && !bit[start])
                    {
                        ret++;
                    }
                }
            }
            else
            {
                if (bit[start])
                {
                    ret++;
                }
            }
        }
    }
    return ret;
}

long long dfs(vector<vector<long long>> &dp, long long h, long long w, long long W)
{
    long long ret = 0;
    // constatnt
    if (w == 0 || w > W)
    {
        return ret;
    }
    if (h == 0)
    {
        if (w == 1)
        {
            ret++;
        }
        return ret;
    }

    // dfs and memolize
    if (dp[h - 1][w - 1] == -1)
    {
        dp[h - 1][w - 1] = dfs(dp, h - 1, w - 1, W);
    }
    if (dp[h - 1][w] == -1)
    {
        dp[h - 1][w] = dfs(dp, h - 1, w, W);
    }
    if (dp[h - 1][w + 1] == -1)
    {
        dp[h - 1][w + 1] = dfs(dp, h - 1, w + 1, W);
    }

    // sum
    ret = (ret + combination(w - 1, w, W) * dp[h - 1][w - 1]) % MOD;
    ret = (ret + combination(w, w, W) * dp[h - 1][w]) % MOD;
    ret = (ret + combination(w + 1, w, W) * dp[h - 1][w + 1]) % MOD;
    return ret;
}

int main()
{
    long long H, W, K;
    cin >> H >> W >> K;
    vector<vector<long long>> dp(H + 1, vector<long long>(W + 2, -1));
    cout << dfs(dp, H, K, W) << endl;
}

