#include <bits/stdc++.h>
using namespace std;
#define mod 1000000007

int h, w, k;
int d[9];

void init() {
  for (int i = 0; i <= w; i++) {
    d[i] = 1;
  }
  for (int i = 2; i <= w; i++) {
    d[i] = d[i-1] + d[i-2];
  }
}

vector<vector<long long> > mul(vector<vector<long long> > a, vector<vector<long long> > b) {
  vector<vector<long long> > v(w, vector<long long>(w, 0));
  for (int i = 0; i < w; i++) {
    for (int j = 0; j < w; j++) {
      long long tmp = 0;
      for (int k = 0; k < w; k++) {
        tmp += a[i][k] * b[k][j];
        tmp %= mod;
      }
      v[i][j] = tmp;
    }
  }
  return v;
}

int main() {
  cin >> h >> w >> k;
  init();
  vector<vector<long long> > v(w, vector<long long>(w, 0));
  vector<vector<long long> > ans(w, vector<long long>(w, 0));
  for (int i = 0; i < w; i++) {
    ans[i][i] = 1;
    for (int j = i; j < w; j++) {
      if (abs(i-j) > 1) continue;
      v[i][j] = d[i] * d[w-j-1];
      v[j][i] = v[i][j];
    }
  }
  while (h != 0) {
    if (h % 2) {
      ans = mul(ans, v);
    }
    h /= 2;
    v = mul(v, v);
  }
  cout << ans[0][k-1] << endl;
  return 0;
}

