ll MOD = 1000000007;

vector<ll> comb0(50, 0);
vector<ll> comb1(50, 0);
vector<ll> comb (50, 0);
void calcComb(){
    comb0[0] = 1;
    comb1[0] = 1;
    comb [0] = 2;
    for(int i=1;i<50;i++){
        comb0[i] = comb0[i-1] + comb1[i-1];
        comb1[i] = comb0[i-1];
        comb [i] = comb0[i] + comb1[i];
        comb [i] %= MOD;
        comb0[i] %= MOD;
        comb1[i] %= MOD;
    }
}

int main()
{
    ll H, W, K;
    cin >> H >> W >> K;
    calcComb();
    vector<vector<ll>> dp(H+1, vector<ll>(W, 0));
    dp[0][0] = 1;
    for(int i=1;i<=H;i++){
        for(int j=0;j<W;j++){
            ll c0 = 1;
            ll c1 = 1;
            ll c2 = 1;
            if(j-2>=0)   c0 *= (comb[j-2]);
            if(W-j-3>=0) c0 *= (comb[W-j-3]);
            if(j-3>=0)   c1 *= (comb[j-3]);
            if(W-j-3>=0) c1 *= (comb[W-j-3]);
            if(j-2>=0)   c2 *= (comb[j-2]);
            if(W-j-4>=0) c2 *= (comb[W-j-4]);

            if(true)  dp[i][j] += dp[i-1][j]   * c0;
            dp[i][j] %= MOD;
            if(j>0)   dp[i][j] += dp[i-1][j-1] * c1;
            dp[i][j] %= MOD;
            if(j<W-1) dp[i][j] += dp[i-1][j+1] * c2;
            dp[i][j] %= MOD;
        }
    }
    cout<<dp[H][K-1]<<endl;

    return 0;
}

