            int b = W - 1;
            while(ptn > 0) {
                if (ptn&0b01) {
                    swap(dst[b-1], dst[b]);
                }
                ptn >>= 1;
                b--;
            }

            REP(j, W) {
                dp[i + 1][dst[j]] += dp[i][j];
                dp[i + 1][dst[j]] %= MOD;
            }
        }
    }

    ll ans = dp[H][K] % MOD;
    cout << ans << endl;

    return 0;
}

