    vector<vector<ll>> down;
    vector<vector<ll>> right;
    vector<vector<ll>> left;

    vector<ll> tmpv;
    tmpv.push_back(1);
    for(int i = 0; i < w - 1; i++) tmpv.push_back(0);
    down.push_back(tmpv);

    if(w != 1){

        for(int i = 0; i < h; i++){
            vector<ll> tmpr;
            vector<ll> tmpl;

            for(int j = 0; j < w - 1; j++){
                tmpr.push_back((down[i])[j]);
                tmpl.push_back((down[i])[j + 1]);
            }

            right.push_back(tmpr);
            left.push_back(tmpl);

            vector<ll> tmpv;
            tmpv.push_back((down[i][0] * combi(w - 2) + left[i][0] * combi(w - 3)) % 1000000007);
            for(int j = 0; j < w - 2; j++) tmpv.push_back((down[i][j + 1] * combi(j) * combi(w - j - 3) + right[i][j] * combi(j - 1) * combi(w - 3 - j) + left[i][j + 1] * combi(j) * combi(w - j - 4)) % 1000000007);
            tmpv.push_back((down[i][w - 1] * combi(w - 2) + right[i][w - 2] * combi(w - 3)) % 1000000007);

            down.push_back(tmpv);

        }

        cout << down[h][k - 1] << endl;

    }else cout << 1 << endl;

    return 0;
}

