ll count_cases_with(int a) {
	int result = 0;
	for (int bits=0; bits<(1<<(W-1)); bits++) {
		if (!(bits & 1<<(a-1))) continue;
		bool valid = true;
		for (int i=0; i<W-1; i++) {
			if ((bits & (1<<i)) && (bits & (1<<(i+1)))) {
				valid = false;
			}
		}
		if (valid) {
			//cout << bitset<8>(bits) << endl; // **** debug ****
			result++;
		}
	}

	return result;
}

ll count_cases_without(int a, int b) {
	int result = 0;
	for (int bits=0; bits<(1<<(W-1)); bits++) {
		if (a >= 1 && (bits & 1<<(a-1))) continue;
		if (b <= W-1 && (bits & 1<<(b-1))) continue;
		bool valid = true;
		for (int i=0; i<W-1; i++) {
			if ((bits & (1<<i)) && (bits & (1<<(i+1)))) {
				valid = false;
			}
		}
		if (valid) {
			//cout << bitset<8>(bits) << endl; // **** debug ****
			result++;
		}
	}

	return result;
}

