                if ((s >> (j - 1) & 1) && (s >> j & 1)) {
                    valid = false;
                    break;
                }
            if (!valid) continue;

            for (int j = 0; j < w.v; ++j) {
                int nxt = j;
                if (0 < j && (s >> (j - 1) & 1)) --nxt;
                if (j < w.v - 1 && (s >> j & 1)) ++nxt;
