vector<int> neighbour(const vector<edge_t>& edges, int k)
{
    vector<int> neighbour_k;
    neighbour_k.reserve(edges.size());

    for(const auto& e : edges)
    {
        if(e.a == k) neighbour_k.push_back(e.b);
        else if(e.b == k) neighbour_k.push_back(e.a);
