			}
			prev = true;

		} else {
			prev = false; 
		}
		cur = cur / 2;
	}
	return true;
}

int pos(int cur, int x) {
	if (x == 0) {
		if (cur & 1) {
			return 1;
		}
		return 0;
	}

	cur = cur >> (x - 1);

	if (cur & 1) {
		return x - 1;
	}
	if (cur & 2) {
		return x + 1;
	}
	return x;
}

