ll row(int n){
    if(n <= 0){
        return 1;
    }
    if(n == 1){
        return 2;
    }
    if(memor[n] != 0){
        return memor[n];
    }
    return memor[n] = row(n - 2) + row(n - 1);
}

ll count(int t, int l){
