    }
    return memoa[t][l] = (count(t - 1, l - 1) * row(l - 2) * row(w - l - 2) + count(t - 1, l) * row(l - 1) * row(w - l - 2) + count(t - 1, l + 1) * row(l - 1) * row(w - l - 3)) % 1000000007;
}

