using ll = long long;
using vll = vector<ll>;
using vvll = vector<vector<ll>>;
using P = pair<ll, ll>;

ll mod = 1000000007; 
int main(){
    ll h, w, k;
    cin >> h >> w >> k;

    //dp[i][j]=i列目でjにいる数
    vvll dp(h + 1, vll(w, 0));
    //i=0について初期化:0列目で線は引けないと見なし, j=0に辿り着くのが1通り, それ以外は0
    dp[0][0] = 1;

    ll bit = (1LL << (w - 1));
    REP(i, h){
        REP(b, bit){
            //used:t番目(0<=t<=w-2)に線が引かれているかどうか
            vll used(w - 1);
            REP(t, w - 1){
                if((b >> t) & 1) used[t] = 1;
            }
            ll ng = 0;
            REP(t, w - 2){
                if(used[t + 1] * used[t]) ng = 1;
            }
            if(ng) continue;
            REP(j, w){
                //左シフト
                if(j >= 1 && used[j - 1]){
                    dp[i + 1][j - 1] += dp[i][j];
					dp[i + 1][j - 1] %= mod;
                }
                //右シフト
                else if(j <= w - 2 && used[j]){
                    dp[i + 1][j + 1] += dp[i][j];
					dp[i + 1][j + 1] %= mod;
                }
                //直下
                else{
                    dp[i + 1][j] += dp[i][j];
					dp[i + 1][j] %= mod;
                }
            }
        }
    }
    cout << dp[h][k - 1] << endl;
    return 0;
}

