int main() {
	int H, W, K; cin >> H >> W >> K;
	vector<vector<int>> dp(H + 1, vector<int>(W, 0));
	dp[0][0] = 1;

	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {

			//横線のパターンを全部発生させる。
			//横線の数は縦線の数-1
			for (int k = 0; k < (1 << (W - 1)); k++) {
				bool ok = true;

				//横線が2個つながっていると無効なので
				//そういう箇所がある場合は使わない
				for (int l = 0; l < W - 2; l++) {
					if (((k >> l) & 1) && ((k >> (l + 1)) & 1)) {
						ok = false;
					}
				}

				if (ok) {
					//左への移動
					//jからj-1への遷移

					//範囲内かつ、辺がはられている場合のみ。
					if (j >= 1 && ((k >> (j - 1)) & 1)) {
						dp[i + 1][j - 1] += dp[i][j];
						dp[i + 1][j - 1] %= MOD;
					}
				}
					//右への移動
				else if (j <= W - 2 && ((k >> j) & 1)) {
					dp[i + 1][j + 1] += dp[i][j];
					dp[i + 1][j + 1] %= MOD;
				}
					//真下は、範囲外も辺の有無も関係ない
				else {
					dp[i + 1][j] += dp[i][j];
					dp[i + 1][j] %= MOD;
				}
			}
		}
	}

	cout << dp[H][K - 1] << endl;
	return 0;
