#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef vector<ll> vl;
typedef vector<vl> vvl;
const ll mod=1000000007;

ll fib(int x){
  if(x==-1){return 0;}
  else if(x==0){return 1;}
  else{
    return fib(x-1)+fib(x-2);
  }
}


ll solve(int H, int W, int K){
  vvl dp(H+1, vl(W));
  dp[0][0]=1;

  for (int i=0;i<H;++i){
    for (int j=0;j<W;++j){
      ll C=dp[i][j]*fib(j)*fib(W-j-1)%mod;
      dp[i+1][j]=C;

      if(j!=0){
        ll L=dp[i][j-1]*fib(j-1)*fib(W-j-1)%mod;
        (dp[i+1][j]+=L)%=mod;
      }

      if (j!=W-1){
        ll R=dp[i][j+1]*fib(j)*fib(W-j-2)%mod;
        (dp[i+1][j]+=R)%=mod;
      }
    }
  }

  return dp[H][K-1];
}

int main(){
  int H, W, K;cin>>H>>W>>K;
  ll ans = solve(H, W,K);
  cout << ans << endl;
  return 0;
}

