#define MAX_PAT_NUM 1000000007

uint64_t getBridgePatternNum(int32_t colNum)
{
    if (colNum <= 0) {
        return 0;
    } else if (colNum == 1) {
        return 1;
    } else if (colNum == 2) {
        return 2;
    } else {
        return getBridgePatternNum(colNum-1) + getBridgePatternNum(colNum-2);
    }
}

uint64_t getPatternNum(int32_t srcCol, int32_t dstCol, uint32_t colNum, uint32_t rowNum)
{
    if (rowNum == 0) {
        if (srcCol == dstCol) {
            return 1;
        } else {
            return 0;
        }
    } else {
        uint64_t retNum = 0;
        int32_t nextSrcCol[3] = {srcCol, srcCol+1, srcCol-1};
        for (uint32_t i = 0; i < 3; ++i) {
            if (0 < nextSrcCol[i] && nextSrcCol[i] <= colNum) {
                uint64_t patNum = getPatternNum(nextSrcCol[i], dstCol, colNum, rowNum-1);

                if (patNum != 0) {
                    int32_t leftColNum = ((srcCol < nextSrcCol[i]) ? srcCol : nextSrcCol[i]) - 1;
                    int32_t rightColNum = colNum - ((srcCol > nextSrcCol[i]) ? srcCol : nextSrcCol[i]);
                    uint64_t leftBridgePatNum = getBridgePatternNum(leftColNum);
                    uint64_t rightBridgePatNum = getBridgePatternNum(rightColNum);
                    patNum = patNum % MAX_PAT_NUM;
                    leftBridgePatNum = leftBridgePatNum % MAX_PAT_NUM;
