#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define DUMP(a, n) REP(_i, n) printf("%d%c", a[_i], _i + 1 == n ? '\n' : ' ')
#define DUMP2D(a, n, m) REP(_i, n) REP(_j, m) printf("%d%c", a[_i][_j], _j + 1 == m ? '\n' : ' '); puts("")

const int H_MAX = 100;
const int W_MAX = 8;
const int S_MAX = 1 << (W_MAX - 1);
const int MOD = 1000000007;

int H, W, K;

int S;
int lcnt[W_MAX];
int ccnt[W_MAX];
int rcnt[W_MAX];
ll dp[H_MAX + 1][W_MAX];

void init_tbl() {
  S = 1 << (W - 1);
  REP(i, S) {
    bool valid = true;
    REP(j, W - 2) {
      if ((i >> j & 1 > 0) && (i >> (j + 1) & 1 > 0)) {
        // printf("invalid: i=%d j=%d\n", i, j);
        valid = false;
        break;
      }
    }
    if (!valid) continue;
    // printf("i: %d\n", i);
    REP(j, W) {
      if ((j > 0) && (i >> (j - 1) & 1 > 0)) {
        // turn left
        lcnt[j]++;
        // printf("%d : L\n", j);
      } else if ((j < W - 1) && (i >> j & 1 > 0)) {
        // turn right
        rcnt[j]++;
        // printf("%d : R\n", j);
      } else {
        // go straight
        ccnt[j]++;
        // printf("%d : C\n", j);
      }
    }
  }
}

void solve() {
  init_tbl();
  dp[0][0] = 1;
  REP(i, H) {
    REP(j, W) {
      if (j > 0) dp[i + 1][j - 1] = (dp[i + 1][j - 1] +(dp[i][j] * lcnt[j] % MOD)) % MOD;
      dp[i + 1][j] = (dp[i + 1][j] + (dp[i][j] * ccnt[j] % MOD)) % MOD;
      if (j < W - 1) dp[i + 1][j + 1] = (dp[i + 1][j + 1] + (dp[i][j] * rcnt[j] % MOD)) % MOD;
    }
  }

  printf("%lld\n", dp[H][K - 1]);
}

void input() {
  scanf("%d%d%d", &H, &W, &K);
}

int main() {
  input();
  solve();
  return 0;
}

