const ll mod = 1e9+7;

ll calc(int l){
	ll memo[10][2];
	memset(memo, 0, sizeof(memo));
	memo[0][0] = 1;
	for (int i = 0;i < W-1;i++){
		if(i == l){
			memo[i+1][1] += memo[i][0];
			continue;
		}
		memo[i+1][0] += memo[i][0]+memo[i][1];
		memo[i+1][1] += memo[i][0];
	}
	return memo[W-1][0]+memo[W-1][1];
}

ll calc2(int l){
	ll memo[10][2];
	memset(memo, 0, sizeof(memo));
	memo[0][0] = 1;
	for (int i = 0;i < W-1;i++){
		if(i == l || i+1 == l){
			memo[i+1][0] += memo[i][0] + memo[i][1];
			continue;
		}
		memo[i+1][0] += memo[i][0]+memo[i][1];
		memo[i+1][1] += memo[i][0];
	}
	return memo[W-1][0]+memo[W-1][1];
}

