			dp[i+1][j] += dp[i][j]*calc2(j);
			dp[i+1][j] %= mod;
			if(j != 0){
				dp[i+1][j-1] += dp[i][j]*calc(j-1);
				dp[i+1][j-1] %= mod;
			}
			if(j != W-1){
				dp[i+1][j+1] += dp[i][j]*calc(j);
				dp[i+1][j+1] %= mod;	
			}
		}
