// O(w)
vll A_(vll bi) {
  vll ret(w, 0);
  rep (i, w) {
    FOR (j, max(i-1,0), min(i+2,w)) {
      ret[i] = (ret[i] + A[i][j] * bi[j]) % mod;
    }
  }
  return ret;
}

int L;
vll C, v0;
vll calc_r(ll a) {
  if (a == 0) {
    return v0;
  }
  vll x = calc_r(a/2);
  vll d(L*2, 0);
  rep (i, L) {
    rep (j, L) {
      int ind = i + j + (a&1);
      d[ind] = (d[ind] + x[i]*x[j]) % mod;
    }
  }
  for (int i = L*2-1; i >= L; --i) {
    FOR (j, 1, L+1) {
      d[i-j] = (d[i-j] + (d[i] * (mod - C[j]))) % mod;
    }
  }
  d.resize(L);
  return d;
}

