int main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	memset(fib, 0LL, sizeof(fib));
	memset(dp, 0LL, sizeof(dp));
	fib[0] = 1LL;
	fib[1] = 1LL;
	for (int i = 2; i < MAX_N; ++i){
		fib[i] = fib[i-1] + fib[i-2];
		fib[i] %= MOD;
	} // end for

	int N, W, K; cin >> N >> W >> K;

	dp[0][0] = 1LL;
	for (int h = 0; h < N; ++h){
		for (int i = 0; i < W; ++i){
			// down 
			dp[h+1][i] += fib[i] * fib[W - i - 1] * dp[h][i];
			dp[h+1][i] %= MOD;
			// right
			if (i == 0){
				dp[h+1][i+1] += fib[i] * fib[W - i - 2] * dp[h][i];
				dp[h+1][i+1] %= MOD;
			}else // left
			if (i == W - 1){
				dp[h+1][i-1] += fib[i-1] * fib[W - i - 1] * dp[h][i];
				dp[h+1][i-1] %= MOD;
			}else{
				dp[h+1][i+1] += fib[i] * fib[W - i - 2] * dp[h][i];
				dp[h+1][i+1] %= MOD;
				dp[h+1][i-1] += fib[i-1] * fib[W - i - 1] * dp[h][i];
				dp[h+1][i-1] %= MOD;
			} // end if
		} // end for
	} // end for

	cout << dp[N][K-1] << endl;

	return 0;
}

