    dp.assign(H + 1, vector<ll>(W));
    dp[0][0] = 1;
    for (int i = 0; i < H; i++) {
        for (vector<ll> line : lines) {
            for (int j = 0; j < W; j++) {
                if (j > 0 && line[j - 1]) {
                    dp[i + 1][j - 1] += dp[i][j];
                    dp[i + 1][j - 1] %= mod;
                }
                else if (j < W && line[j]) {
                    dp[i + 1][j + 1] += dp[i][j];
                    dp[i + 1][j + 1] %= mod;
                }
                else {
                    dp[i + 1][j] += dp[i][j];
                    dp[i + 1][j] %= mod;
                }
            }
        }
    }
}

