  dp[0][0]=1;
  for(ll i=0;i<h;++i){
    for(ll j=0;j<w;++j){
      for(ll bit=0;bit<(1<<(w-1));++bit){
        bool ng=false;
        rep(a,w-1){
          if(((bit>>a)&1)&&((bit>>(a+1))&1))ng=true;
        }
