int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m, K;
    cin >> n >> m >> K;

    if (m == 1) {
        if (K == 1) {
            cout << 1 << '\n';
        } else {
            cout << 0 << '\n';
        }
        return 0;
    }

    const long long MOD = 1000000007;

    int M = 1 << (m - 1);

    vector<vector<long long>> dp(M, vector<long long>(m, 0));
    dp[0][0] = 1;
    auto ndp = dp;

    for (int i = 0; i < n; ++i) {
        for (auto& V : ndp) {
            fill(V.begin(), V.end(), 0);
        }

        for (int j = 0; j < M; ++j) {
            for (int k = 0; k < m; ++k) {
                if (dp[j][k] == 0) {
                    continue;
                }

                for (int nj = 0; nj < M; ++nj) {
                    if (nj & (nj >> 1)) {
                        continue;
                    }
                    int nk = -1;
                    for (int a = -1; a < 1; ++a) {
                        int x = k + a;
                        if (x >= 0 && (nj & (1 << x))) {
                            assert(nk == -1);
                            nk = a < 0 ? k - 1 : k + 1;
                        }
                    }
                    if (nk == -1) {
                        nk = k;
                    }

                    (ndp[nj][nk] += dp[j][k]) %= MOD;
                }
            }
        }
        swap(ndp, dp);
    }

    long long res = 0;
    for (int i = 0; i < M; ++i) {
        res += dp[i][K - 1];
    }
    res %= MOD;
    cout << res << '\n';

    return 0;
}

