int dp(int i,int p,bool last){
  long long rec=0;
  int x=i%(w-1)+1;
  int y=i/(w-1)+1;
  if(memo[i][p][last]!=-1)return memo[i][p][last];
  if(x==1&&y==h+1){
    if(p==k)return 1;
    else return 0;
  }
  if(last==false){
    if(x==p)rec+=dp(i+1,p+1,true);
    else if(x+1==p)rec+=dp(i+1,p-1,true);
    else rec+=dp(i+1,p,true);
  }
  rec+=dp(i+1,p,false);
  return memo[i][p][last]=rec%1000000007;
}

