const long long int d7 = 1000000007;

int irrel(int n) {
    if (n <= 0) {
        return 1;
    } else {
        return irrel(n-1) + irrel(n-2);
    }
}

void solve(int h, int w, int k, std::vector<std::vector<long long int>> &f) {
  f[0][1] = 1;
  for (int i = 1; i <= h; i++) {
    for (int j = 1; j <= std::min(w, i + 1); j++) {
      int dd = irrel(j - 2) * irrel(w - j - 1);
      int dl = irrel(j - 3) * irrel(w - j - 1);
      int dr = irrel(j - 2) * irrel(w - j - 2);
      f[i][j] = ((f[i - 1][j] % d7) * (dd % d7) % d7 +
                 ((f[i - 1][j - 1] % d7) * (dl % d7)) % d7 +
                 ((f[i - 1][j + 1] % d7) * (dr % d7)) % d7) %
                d7;
    }
  }
};

int main() {
  int h, w, k;
  std::cin >> h >> w >> k;
  std::vector<std::vector<long long int>> f(
      h + 2, std::vector<long long int>(w + 2, 0));
  solve(h, w, k, f);
  std::cout << f[h][k] << std::endl;
}

