int64_t getAmidaNum(const int h, const int w, const int k) {
  std::vector<std::bitset<7>> horizontal_candidates;
  for (int i = 0; i < std::pow(2, w - 1); ++i) {
    std::bitset<7> current(static_cast<unsigned long long>(i));
    bool valid = true;
    for (int j = 0; j < w - 2; ++j) {
      if (current[j] && current[j + 1]) {
        valid = false;
      }
    }
    if (valid) {
      horizontal_candidates.emplace_back(std::move(current));
    }
  }

  std::vector<int> bridge_counts(w + 1, 0);
  for (int i = 1; i <= w; ++i) {
    bridge_counts[i] = std::count_if(
        horizontal_candidates.begin(), horizontal_candidates.end(),
        [i](const std::bitset<7> &bit) {
          return (bit & std::bitset<7>(static_cast<unsigned long long>(
                            std::pow(2, i - 1))))
              .any();
        });
  }
  const int candidate_total_num =
      static_cast<int>(horizontal_candidates.size());

  /*
  for (const auto &candi : horizontal_candidates) {
    std::cout << candi << std::endl;
  }
  for (const auto &cnt : bridge_counts) {
    std::cout << cnt << std::endl;
  }
  */

  // edges are guards
  std::vector<int64_t> current_amida_num(w + 2, 0);
  current_amida_num[1] = 1L;
  static const int64_t CONSTANT = 1000000007L;

  for (int i = 0; i < h; ++i) {
    std::vector<int64_t> current_amida_num2(w + 2, 0);
    for (int j = 1; j <= w; ++j) {
      current_amida_num2[j] +=
          (current_amida_num[j] *
           (candidate_total_num - bridge_counts[j] - bridge_counts[j - 1])) %
          CONSTANT;
      current_amida_num2[j - 1] +=
          (current_amida_num[j] * bridge_counts[j - 1]) % CONSTANT;
      current_amida_num2[j + 1] +=
          (current_amida_num[j] * bridge_counts[j]) % CONSTANT;
    }
    current_amida_num = std::move(current_amida_num2);
    for (auto &num : current_amida_num) {
      num %= CONSTANT;
    }
    /*
    std::cout << "i = " << i << ", ";
    for (const auto n : current_amida_num) {
      std::cout << n << " ";
    }
    std::cout << std::endl;
    */
  }

  return current_amida_num[k];
}
int main() {
  int h, w, k;
  std::cin >> h >> w >> k;
  std::cout << getAmidaNum(h, w, k);
  return 0;
}

