	int fib[8] = {1,2,3,5,8,13,21,34};
	dp[0][0] = 1;
	for(int i=1;i<W;i++)dp[0][i] = 0;
	if(W==2){
		for(int i=1;i<H+1;i++){
			dp[i][0] = dp[i-1][0] + dp[i-1][1];
			dp[i][1] = dp[i][0];
		}
		cout << dp[H][K-1] << endl;
	}
	for(int i=1;i<H+1;i++){
		dp[i][0] = dp[i-1][0]*fib[W-2] + dp[i-1][1]*fib[W-3];
		dp[i][1] = dp[i-1][0]*fib[W-3] + dp[i-1][1]*fib[W-3]+dp[i-1][2]
		for(int j=2;j<W-2;j++){
			dp[i][j] = dp[i-1][j-1]*fib[j-2]*fib[W-j-2] + dp[i-1][j]*fib[j-1]*fib[W-j-2] + dp[i-1][j+1]*fib[j-1]*fib[W-j-3];
