				}
				if (!ok) {
					continue;
				}
				//恐らくこの部分は
				int nj = j;
				if (bit & (1 << j)) {
					nj = j + 1;
				}
				else if (j > 0 && (bit & (1 << (j - 1)))) {
					nj = j - 1;
				}
				//
				dp[i + 1][nj] = (dp[i + 1][nj] + dp[i][j]) % MOD;
			}
		}
	}

	cout << dp[H][K-1] << endl;


	return 0;
}

