ll g(ll W, ll K, ll D) {
  ll ans = 0;
  for (auto &&connect : Power(2, W - 1)) {
    if (any_of(begin(), end(max((ll)0, connect.size() - (ll)1)),
               [&](auto i) { return connect[i] && connect[i + 1]; }))
      continue;
    if (!imply(D < 0, (K > 1) && connect[K - 2]))
      continue;
    if (!imply(D > 0, (K < W) && connect[K - 1]))
      continue;
    if (!imply(D == 0,
               (K == 1 || !connect[K - 2]) && (K == W || !connect[K - 1])))
      continue;
    dump(connect);
    ++ans;
  }
  return ans;
}
using Key = tuple<ll, ll>;
struct Data {
  ll W;
};
ll f(Key const &key, Data const &data, u_map<Key, ll> &dp) {
  dump(key);
  ll h = get<0>(key);
  ll k = get<1>(key);
  ll W = data.W;
  if (h == 0)
    return dp[key] = k == 1;
  if (W == 1)
    return dp[key] = 1;
  auto found = dp.find(key);
  if (found != dp.end())
    return found->second;
  ll ans = g(W, k, 0) * f(Key{h - 1, k}, data, dp);
  ans %= MOD;
  if (k > 1) {
    ans += g(W, k, -1) * f(Key{h - 1, k - 1}, data, dp);
    ans %= MOD;
  }
  if (k < W) {
    ans += g(W, k, +1) * f(Key{h - 1, k + 1}, data, dp);
    ans %= MOD;
  }
  return dp[key] = ans;
}
