int main() {
  // 前計算
  int r[10][2];  // 計算用
  memset(r, 0, sizeof(r));
  r[0][0] = 1;
  for (int i = 0; i < 9; i++) {
    r[i + 1][1] += r[i][0];  // 後ろ空いてて、引いた
    r[i + 1][0] += r[i][1];  // 後ろ引いてて、引かない
    r[i + 1][0] += r[i][0];  // 後ろ空いてて、引かない
  }
  vector<int> kumi(10);  // 長さがiの時の正しくできる組み合わせの数
  for (int i = 0; i < 10; i++) kumi[i] = r[i][0] + r[i][1];

  // 入力
  int h, w, k;
  cin >> h >> w >> k;

  ll dp[h + 1][w];
  memset(dp, 0, sizeof(dp));
  dp[0][0] = 1;

  for (int y = 0; y + 1 <= h; y++) {
    for (int s = 0; s < w; s++) {
      // cout << y << "," << s << "=" << dp[y][s] << endl;
      ll add;
      if (s - 1 >= 0) {
        add = dp[y][s] * kumi[max(0, s - 2)] % MOD * kumi[max(0, w - 1 - (s + 1))] % MOD;
        dp[y + 1][s - 1] += add;  // 左に
        dp[y + 1][s - 1] %= MOD;
      }
      if (s + 1 <= w - 1) {
