      }
      add = dp[y][s] * kumi[max(0, s - 1)] % MOD * kumi[max(0, w - 1 - (s + 1))] % MOD;
      dp[y + 1][s] += add;
      dp[y + 1][s] %= MOD;
    }
  }

  cout << dp[h][k - 1] << endl;
}

