#define MAX_H (100)
#define MAX_W (8)
#define MOD (1000000007)

long fib[MAX_H + 1];
long dp[MAX_H + 1][MAX_W];

int main(int argc, char *argv[]) {
  // read inputs
  long H, W, K;
  scanf("%ld %ld %ld", &H, &W, &K);

  // calculate fibonacci
  fib[0] = 1; fib[1] = 2;
  for (int i = 2; i <= MAX_H; i++) {
    fib[i] = fib[i - 1] + fib[i - 2];
  }

  // calculate dp
  for (int s = 0; s < W; s++)
    dp[0][s] = (s == K - 1);
  for (int h = 1; h <= H; h++) {
    for (int s = 0; s < W; s++) {
      long val_down = 0, val_left = 0, val_right = 0;
      // don't move at this level
      val_down = dp[h - 1][s];
      if (s >= 1)
        val_down = (val_down * fib[s - 1]) % MOD;
      if (s <= W - 2)
        val_down = (val_down * fib[W - s - 2]) % MOD;
      // try moving left if possible
      if (s >= 1) {
        val_left = dp[h - 1][s - 1];
        if (s >= 2)
          val_left = (val_left * fib[s - 2]) % MOD;
        if (s <= W - 2)
          val_left = (val_left * fib[W - s - 2]) % MOD;
      }
      // try moving right if possible
      if (s <= W - 2) {
        val_right = dp[h - 1][s + 1];
        if (s >= 1)
          val_right = (val_right * fib[s - 1]) % MOD;
        if (s <= W - 3)
          val_right = (val_right * fib[W - s - 3]) % MOD;
      }
      // printf("%d %d: %d %d %d\n", h, s, val_left, val_down, val_right);
      dp[h][s] = (val_down + val_left + val_right) % MOD;
    }
  }
  printf("%ld\n", dp[H][0]);

  return 0;
}

