int main() {
    int H, W, K;
    cin >> H >> W >> K;
    dp[0][1] = 1;
    for (int h = 1; h <= H; h++) {
        for (int w = 1; w <= W; w++) {
            for (int mask = 0; mask < (1 << (W - 1)); mask++) {
                // 横棒として正しいか確認
                bool is_ok = true;
                for (int i = 0; i < W - 2; i++) {
                    if (((mask >> i) & 1) && ((mask >> (i + 1)) & 1)) {
                        is_ok = false;
                    }
                }
                if (!is_ok) continue;
                // 現在見ている縦棒wの横に棒があるか確認
                if (w == 1 && mask & 1 && w + 1 <= W) {
                    dp[h][w] = (dp[h][w] + dp[h - 1][w + 1]) % MOD;
                }
                else if (w == W && (mask >> (w - 2)) & 1 && w - 1 >= 1) {
                    dp[h][w] = (dp[h][w] + dp[h - 1][w - 1]) % MOD;
                }
                else if (w > 1 && w < W && (mask >> (w - 1)) & 1) {
                    dp[h][w] = (dp[h][w] + dp[h - 1][w + 1]) % MOD;
                }
                else if (w > 1 && w < W && (mask >> (w - 2)) & 1) {
                    dp[h][w] = (dp[h][w] + dp[h - 1][w - 1]) % MOD;
                }
                else {
                    dp[h][w] = (dp[h][w] + dp[h - 1][w]) % MOD;
                }
            }
        }
    }
    cout << dp[H][K] << endl;
    return 0;
}

