typedef long long ll; 

using namespace std;

const ll MOD = 1e9 + 7;

template <typename T>
void mod_add(T& a, const T b) {
	a = (a + b) % MOD;
}

int main() {
	int H, W, K;
	cin >> H >> W >> K;
	vector<int> x(6, 0);
	x[0] = 1, x[1] = 2;
	for (int i = 2; i < x.size(); ++i) {
		x[i] = x[i - 2] + x[i - 1];
	}
	vector<int> y(W, 0);
	for (int i = 1; i < y.size(); ++i) {
		int l = max(0, i - 2), r = max(0, W - i - 2);
		y[i] = x[l] * x[r];
	}

	vector<vector<ll>> dp(H + 2, vector<ll>(W + 1, 0));
	dp[0][1] = 1;
	for (int i = 0; i <= H; ++i) {
		for (int j = 1; j <= W; ++j) {
			if (i == H) {
				dp[i + 1][j] = dp[i][j];
				continue;
			}

			int l = max(0, j - 2), r = max(0, W - j - 1);
			ll add = (((dp[i][j] * x[l]) % MOD) * x[r]) % MOD;
			mod_add(dp[i + 1][j], add);

			if (j - 1 > 0) {
				add = (dp[i][j] * y[j - 1]) % MOD;
				mod_add(dp[i + 1][j - 1], add);
			}
			if (j + 1 <= W) {
				add = (dp[i][j] * y[j]) % MOD;
				mod_add(dp[i + 1][j + 1], add);
			}
		}
	}

	ll res = dp[H + 1][K];
	cout << res << endl;

	return 0;
}

