    cin >> H >> W >> K;

    if(W == 1)
    {
        cout << 1 << endl;
        return 0;
    }

    dp[0][0] = 1ULL;
    for (int h = 1; h <= H; h++)
    {
        for (int x = 0; x < W;x++)
        {
            unsigned long long X, Y, Z;
            X = Y = Z = 0ULL;

            if (x > 0)
            {
                if(x == 1 || W - 1)
                {
                    X = fibt[W - 1];
                }
                else
                {
                    X = fibt[x] * fibt[W - x];
                }
                dp[h][x - 1] += dp[h - 1][x] * X;
                dp[h][x - 1] %= M;
            }

            if (x == 0 || x == W - 1)
            {
                Y = fibt[W];
            }
            else
            {
                Y = fibt[x + 1] * fibt[W - x];
            }
            dp[h][x] += dp[h - 1][x] * Y;
            dp[h][x] %= M;

            if(x < W - 1)
            {
                if (x == W - 2 || x == 0)
                {
                    Z = fibt[W - 1];
                }
                else
                {
                    Z = fibt[x + 1] * fibt[W - x - 1];
                }
                dp[h][x + 1] += dp[h - 1][x] * Z;
                dp[h][x + 1] %= M;
            }
        }
    }

    cout << dp[H][K - 1] << endl;

