int main() {
	int Divider = 1000000007;
	int H, W, K;
	cin >> H >> W >> K;
	int initial = 0;
	switch (W) {
		case 1:
			initial = 0;
			break;
		case 2:
			initial = 1;
			break;
		case 3:
			initial = 1;
			break;
		case 4:
			initial = 2;
			break;
		case 5:
			initial = 3;
			break;
		case 6:
			initial = 5;
			break;
		case 7:
			initial = 7;
			break;
		case 8:
			initial = 11;
			break;
	}
	//Amida[i,j,k]=高さが(i+1)のとき、jからkに到るあみだくじの数
	vector<vector<vector<long>>> AmidaTable;
	AmidaTable.resize(H);
	for (int i = 0; i < H; i++) {
		AmidaTable[i].resize(W);
		for (int j = 0; j < W; j++) {
			AmidaTable[i][j].resize(W);
		}
	}
	//H=1(横棒が1本だけ引ける)
	for (int i = 0; i < W; i++) {
		for (int j = 0; j < W; j++) {
			if (i == j) {
				AmidaTable[0][i][j] = W - 1;
			} else if (abs(i - j) == 1) {
				AmidaTable[0][i][j] = initial;
			} else {
				AmidaTable[0][i][j] = 0;
			}
		}
	}
		//あみだくじを延長する
	for (int h = 1; h < H; h++) {
		for (int i = 0; i < W; i++) {
			for (int j = 0; j < W; j++) {
				AmidaTable[h][i][j] = (AmidaTable[h - 1][i][j] * AmidaTable[0][j][j]);
				if (j != 0) {
					AmidaTable[h][i][j] += (AmidaTable[h - 1][i][j - 1] * AmidaTable[0][j - 1][j]);
				}
				if (j != W - 1) {
					AmidaTable[h][i][j] += (AmidaTable[h - 1][i][j + 1] * AmidaTable[0][j + 1][j]);
				}
				AmidaTable[h - 1][i][j] %= Divider;
			}
		}
	}
	cout << AmidaTable[H - 1][0][K-1] << endl;
}

