ll h, w, k;

ll memo[8][110];

ll dfs(ll pos, ll hei) {
	if(memo[pos][hei] != -1) return memo[pos][hei];
	if(hei == h + 1) {
		if(pos == k) return 1;
		else return 0;
	}
	ll ret = 0;
	REP(i,(1ll<<(w-1))) {
		bitset<7> bi(i);
		bool d = true;
		REP(j,w-2) if(bi[j] == 1 && bi[j + 1] == 1) d = false;
		if(!d) continue;
		bool upd = false;
		if(pos > 0 && bi[pos - 1]) {
			upd =true;
			ret += dfs(pos - 1, hei + 1);
		}
		if(pos < w - 1 && bi[pos]) {
			upd = true;
			ret += dfs(pos + 1, hei + 1);
		}
		if(!upd) ret += dfs(pos, hei + 1);
	}
	return memo[pos][hei] = ret % MOD;
}

