int kazoeage(int now, int sum, int res)
{
    if (res == 0)
        return sum + 1;

    if (now == 1)
        sum = kazoeage(0, sum, res - 1);
    else
    {
        sum = kazoeage(0, sum, res - 1);
        sum = kazoeage(1, sum, res - 1);
    }
    return sum;
}

int memo[10];
int pat(int num)
{
    if (num < 0)
        num = 0;
    if (memo[num] != -1)
    {
        return memo[num];
    }
    else
    {
        memo[num] = kazoeage(0, 0, num);
        return memo[num];
    }
}

