        {
            //左に行く
            if (j != 1 and j - 1 >= K - (H - i))
            {
                num = a[j];
                if (j - 1 == 1 or j == W)
                {
                    num *= pat((W - 1) - 2);
                }
                else
                {
                    num *= pat(j - 3);
                    num *= pat((W - 1) - (j - 3) - 3);
                }
                tmp[j - 1] += num;
                tmp[j - 1] %= MOD;
            }
            //下に行く
            if (j >= K - (H - i) and j <= K + (H - i))
            {
                num = a[j];
                if (j == W or j == 1)
                {
                    num *= pat((W - 1) - 1);
                }
                else
                {
                    num *= pat(j - 2);
                    num *= pat((W - 1) - (j - 2) - 2);
                }
                tmp[j] += num;
                tmp[j] %= MOD;
            }

            //右に行く
            if (j != W and j + 1 <= K + (H - i))
            {
                num = a[j];
                if (j + 1 == W or j == 1)
                {
                    num *= pat((W - 1) - 2);
