typedef long long ll;

int main() {
  ll H, W, K;
  cin >> H >> W >> K;

  vector<vector<ll>> dp(H + 1, vector<ll>(W, 0));
  // 1番目からスタート
  dp[0][0] = 1;

  for (ll i = 0; i < H; i++) {
    // 平行線のひき方
    for (ll bit = 0; bit < (1<<(W-1)); bit++) {
      // 隣り合う列に平行にひくのは禁止
      ll invalid = false;
      for (ll k = 1; k <= (W - 1); k++) {
        if (bit & (1 << k) && bit & (1 << (k-1))) {
          invalid = true;
          break;
        }
      }

      if (invalid) continue;

      for (ll j = 0; j < W - 1; j++) {
        ll next = j;
        if (j >= 1 && bit & (1 << (j-1))) {
          next -= 1;
        } else if (j <= (W - 1) && bit & (1 << (j))) {
          next += 1;
        }

        dp[i + 1][next] += dp[i][j];
      }
    }
  }

  cout << dp[H][K-1] << endl;

  return 0;
}

#include <bits/stdc++.h>

using namespace std;

struct bool_vector_t: vector< bool >
{
    bool invalid( int M ) const
    {
        /// returns true if two consecutive horizontal line segments exist

        for ( int i = 0, j = 1; j < M; i = j++ )
            if ( at( i ) and at( j ) )
                return true;

        return false;
    }
};

struct bits_t: vector< bool_vector_t >
{
    bits_t( int N, int W )
    {
        resize( N );

        /// generate all possible subsets of horizontal M line segments

        for( int k = 0; k < N; k++ )
        {
            at( k ).resize( W, false );

            for( int j = 0, l = k; j < W; j++, l >>= 1 )
                if ( l & 1 )
                    at( k ).at( j ) = true;
        }
    }
};

struct dp_t:  vector< vector< int > >
{
    dp_t( int H, int W )
    {
        resize( H + 1 );

        for( auto& row: *this )
            row.resize( W, 0 );

        at( 0 ).at( 0 ) = 1;
    }

    void add( int i, int j, int k, int M, const bits_t& bit )
    {
        int t = j - 1, u = i + 1, v = 0; /// No change to the vertical line

        if( t >= 0 and bit[ k ][ t ] )
            v = -1; /// move to the vertical line to the left
        else
            if( j < M and bit[ k ][ j ] )
                v = 1; /// move to the vertical line to the right

        at( u ).at( v += j ) += at( i ).at( j ), at( u ).at( v ) %= 1000000007;
    }
};

struct valid_t: vector< bool >
{
    valid_t( int N, int M, bits_t& bit )
    {
        resize( N, false );

        for( int k = 0; k < N; k++ )
            if ( not bit[ k ].invalid( M ) )
                at( k ) = true;
    }
};

int main()
{
    ios_base::sync_with_stdio( false ), cin.tie( nullptr ), cout.tie( nullptr );

    int H, W, K, M, N; cin >> H >> W >> K, M = W - 1, N = 1 << M;

    bits_t bit( N, W ); dp_t dp( H, W ); valid_t valid( N, M, bit );

	for( int i = 0; i < H; i++ )
		for( int j = 0; j < W; j++ )
			for( int k = 0; k < N; k++ )
                if ( valid[ k ] )
                    dp.add( i, j, k, M, bit );

	cout << dp[ H ][ K - 1 ];
}

