            if ((mask >> i) & 1) {
               swap(perm[i], perm[i+1]);
            }
         }

         for (int i = 0; i < W; i++) {
            dp[h+1][perm[i]] += dp[h][i];
            dp[h+1][perm[i]] %= MOD;
         }
      }
