	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	Int H, W, K;
	cin >> H >> W >> K;

	vector<vector<mint>> dp(H + 1, vector<mint>(W, mint(0LL)));
	dp[0][0] = 1;

	for (Int i = 0; i < H; i++) {

		//bit全探索で横棒の位置を決定
		for (Int bit = 0; bit < (1LL<<(W-1)); bit++) {

			//横棒が二本連続していないか
			Int flag = 0;
			for (Int j = 0; j < W-2; j++) {
				if ((bit & (1LL << j)) && (bit & (1LL << (j + 1)))) {
					flag = 1;
					break;
				}
			}
			if (flag)continue;

			//dpの遷移
			for (Int j = 0; j < W-1; j++) {
				//横棒がある場合（スワップされる）
				if (bit & (1LL << j)) {
					dp[i + 1][j] += dp[i][j + 1];
					dp[i + 1][j + 1] += dp[i][j];

					if (j == W - 3) {//右端が飛ばされないように
						dp[i + 1][j + 2] += dp[i][j + 2];
					}
					j++;//余分にインクリメント
				}
				//横棒がない場合（そのまま降りる）
				else {
					dp[i + 1][j] += dp[i][j];

					if (j == W - 2) {//右端の処理
						dp[i + 1][j + 1] += dp[i][j + 1];
					}
				}
			}
		}
	}

	DMP(dp);

	if (W == 1) {
		cout << 1 << "\n";
	}
	else {
		cout << dp[H][K - 1] << "\n";
	}
}

