class Modulo{
public:
    //以下x,y,mod>0を想定している
    ll mod;
    vector<ll> factable = {1};
    vector<ll> invtable = {1};
    Modulo(){
        mod = 1e9+7;
    }
    Modulo(ll _mod){
        mod = _mod;
    }
    ll mul(ll x,ll y){
        return ((x%mod)*(y%mod))%mod;
    }
    ll add(ll x,ll y){
        return ((x%mod)+(y%mod))%mod;
    }
    ll sub(ll x,ll y){
        ll d =((x%mod)-(y%mod))%mod;
        if(d>=0)return d;
        else return d+mod;
    }
    ll pow(ll x,ll y){
        //x^y % mod
        if(y<=0)return 1;
        if(y%2==0){
            ll d = pow(x,y/2);
            return ((d%mod)*(d%mod))%mod;
        }else{
            return (x*pow(x,y-1))%mod;
        }
    }
    ll div(ll x, ll y){
        //x/y % mod = x*y^(mod-2) % mod
        return mul(x,pow(y,mod-2));
    }
    ll fac(ll x){
        //x! % mod
        if(factable.size()<=x){
            ll s = factable.size();
            FOR(i,s,x+1){
                factable.push_back(mul(i,factable.back()));
                invtable.push_back(div(1,factable.back()));
            }
        }
        if(x<0) return 1;
        else return factable[x];
    }
    ll facinv(ll x){
        if(invtable.size()<=x){
            ll s = invtable.size();
            FOR(i,s,x+1){
                factable.push_back(mul(i,factable.back()));
                invtable.push_back(div(1,factable.back()));
            }
        }
        if(x<0) return 1;
        else return invtable[x];
    }
    ll com(ll x,ll y){
        //xCy % mod = x!/((x-y)!*y!) % mod
        if(x-y<y)return com(x,x-y);
        return mul(fac(x),mul(facinv(x-y),facinv(y)));
    }
};

