int dfs(int cur, int w, int target, int state, vector<int>& v)
{
    if(cur == 0)
        rep(i,w) v[i] = 0;

    if(cur == w-1)
    {
        bool valid = true;
        rep(i,w-2)
            if(v[i] == 1 && v[i+1] == 1)
                valid = false;

        if(!valid) return 0;

        if(state == 0)
        {
            if(target > 0)
                valid &= v[target-1] == 0;
            if(target < w-1)
                valid &= v[target] == 0;

            return valid ? 1 : 0;
        }
        else if(state == -1)
        {
            if(target == 0)
                return 0;
            return v[target-1] == 1;
        }
        else
        {
            if(target == w-1)
                return 0;
            return v[target] == 1;
        }
    }

    int cnt = 0;
    v[cur] = 0;
    cnt += dfs(cur+1,w,target,state,v);
    v[cur] = 1;
    cnt += dfs(cur+1,w,target,state,v);

    return cnt;
}

