    dp[0][0] = 1;
    for(int i=1;i<=H;i++){
        for(int bit=0;bit < (1 << (W - 1));bit++){
            // cout << bit << endl;

            // exist bridge between i and i + 1 or not
            bool br[W-1]; // 0, ..., W - 2
            for(int j=0;j<W-1;j++) br[j] = false;
            for(int t=0;t<W-1;t++){
                if(bit & (1 << t)){
                    br[t] = true;
                }
            }

            // check br is valid
            bool isvalid = true;
            for(int j=0;j<W-2;j++){
                if(br[j] && br[j+1]){
                    isvalid = false;
                    break;
                }
            }
            if(!isvalid) continue;

            for(int j=0;j<W;j++){
                if(j-1 >= 0 && br[j-1]){
                    // left
                    dp[i][j] += dp[i-1][j-1];
                    dp[i][j] %= MOD;
                }else if(j <= W-2 && br[j]){
                    // right
                    dp[i][j] += dp[i-1][j+1];
                    dp[i][j] %= MOD;
                }else{
                    dp[i][j] += dp[i-1][j];
                    dp[i][j] %= MOD;
                }
            }
        }
    }
    cout << dp[H][K - 1] << endl;
}

