long long G(int X){
    if(0<=X && X<=7){
        return (long long)kosu[X];
    }else{
        return 1;
    }
}

long long AN(int H, int K, int W){
    if(K<1 || K>W){
        return 0;
    }else if(H==1){
        if(K==2 || K==1) return G(W-K);
        else return 0;
    }else{
        return ((G(K-2)*G(W-K))*AN(H-1,K-1,W))%sosu
        +((G(K-1)*G(W-K))*AN(H-1,K,W))%sosu
        +((G(K-1)*G(W-K-1))*AN(H-1,K+1,W))%sosu;
    }
}



