ll MUL(ll x, ll y) { return x*y % MOD; }
ll POW(ll x, ll e) { ll v=1; for(; e; x=MUL(x,x), e>>=1) if (e&1) v = MUL(v,x); return v; }
ll DIV(ll x, ll y) { /*assert(y%MOD!=0);*/ return MUL(x, POW(y, MOD-2)); }

vector<int> hs;

ll solve(int H, int W, int K) {
    int P = 1 << (W - 1);
    rep(p, P) {
        bool good = true;
        for (int i = 0, m = 3; i < W -2; ++i, m <<= 1) {
            if ((p & m)==m) { good = false; break; }
        }
        if (good) hs.pb(p);
    }
    vector<vector<int>> pat(W, vi(W, 0));
    for (int a=0,ma=1;a<W;++a,ma<<=1) {
        int cnt = 0;
        for (int h : hs) {
            bool good = true;
            if (a>=1 && (h&(ma>>1))) {
                good = false;
                continue;
                 }
            if (a < W-1 && (h&ma)) {
                good = false;
                continue;
            }
            if (good) {
                ++cnt;
            }
        }
        pat[a][a] = cnt;

        if (a<W-1 ) {
            cnt = 0;
            for (int h : hs) {
                if (h & ma) {
                    ++cnt;
                }
            }
            pat[a][a + 1] = pat[a + 1][a] = cnt;
        }

        for (int b = a + 2; b<W; ++b) {
            pat[a][b] = pat[b][a] = 0;
        }
     }

     vector<ll> dp(W, 0);
     dp[0] = 1;
     rep(i, H) {
         vector<ll> dp2(W, 0);
         rep(a, W) rep(b, W) { dp2[b] = ADD(dp2[b], MUL(dp[a], pat[a][b])); }
         dp = dp2;
     }

     return dp[K - 1];
}

int main() {
    int H, W, K;
    cin >> H >> W >> K;
    assert(IN(H, 1, 100));
    assert(IN(W, 1, 8));
    assert(IN(K, 1, W));

    cout << solve(H,W,K) << endl;

    return 0;
}

