        {
            // bitで何処を使ったか状態管理
            for (int bit = 0; bit < (1 << (w - 1)); bit++)
            {
                bool flg = true;
                // 横線を使えるかどうかを調べる
                for (int k = 0; k < w - 2; k++)
                {
