                        // 左
                        (dp[i + 1][j + 1] += dp[i][j]) %= MOD;
                    }
                    else if (j >= 1 && (bit & (1 << (j - 1))))
                    {
                        // 右
                        (dp[i + 1][j - 1] += dp[i][j]) %= MOD;
                    }
                    else
                    {
                        // 上
                        (dp[i + 1][j] += dp[i][j]) %= MOD;
                    }
                }
            }
        }
