ll mod_pow(ll base, ll exp, ll mod)
{
        ll ret = 1;

        for ( ; exp; ) {
                if (exp & 1) {
                        ret *= base;
                        ret %= mod;
                }
                base = (base * base) % mod;
                exp >>= 1;
        }

        return ret;
}

