// 補足説明: loop(i, W) -> インデックス i を 区間 [0, W) でループ
// 変数名 _ は、規格上使うのは望ましくないが、使わない変数であることを明示するために用いている

int main() {
	in(ll, H, W, K);
	// DP遷移の係数
	// ここがarrayなのは初期化の関係上便利だから
	// 境界の処理が面倒なので少し多めに取る
	vector<array<ll, 3>> table(W+2); // [<- , V , ->]
	//bit全探索
	loop(i, 1ll << (W-1)){
		// 隣接するビットが立っていないことをチェック
		{
			ll t = i;
			bool valid = true;
			loop(_, W-1){
				if((t&1) && (t&2))
					valid = false;
				t >>= 1;
			}
			// だめならスキップ
			if(!valid) continue;
		}
		// DP遷移の係数に入れる
		loop(k, W){
			// iのkビット目が1なら
			// (ただし、一番右のやつだと必ず偽 (右に行けないのでそれはそう))
			if(i & (1<<k)){
				// 今の列は右に行く
				++table[k][2];
				// 次の列で本来下に行くはずだったのを左に行くように変更
				++table[k+1][0];
				--table[k+1][1];
			} else {
				// 今の列は下に行く
				++table[k][1];
			}
		}
	}
	// 長さWで0埋めされた配列
	vector<ll> current(W, 0);
	current[0] = 1; // 最初にスタート地点にいるのは1通り
	// DPする
	loop(_, H){
		vector<ll> next(W, 0);
		// 遷移する
		loop(i, W){
			if(i>0)   next[i-1] += current[i] * table[i][0];
			          next[ i ] += current[i] * table[i][1];
			if(i<W-1) next[i+1] += current[i] * table[i][2];
		}
		// MODを取る
		loop(i, W)
			next[i] %= 1000000007;
		// 遷移結果を新しいcurrentにする
		current = next;
	}
	cout << current[K-1] << endl;
}

