signed main() {
  cin >> H >> W >> K;

  m0(dp);
  dp[0][0] = 1;

  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      for (int bit = 0; bit < 1 << (W - 1); bit++) {
        bool flag = true;
        for (int l = 0; l < W - 2; l++) {
          if ((bitcheck(bit, l)) == 1 && (bitcheck(bit, l + 1)) == 1) {
            flag = false;
          }
        }

        if (flag) {
          if (j >= 1 && (bitcheck(bit, j - 1)) == 1) {
            dp[i + 1][j - 1] += dp[i][j];
            dp[i + 1][j - 1] %= MOD;
          } else if (j <= W - 2 && (bitcheck(bit, j)) == 1) {
            dp[i + 1][j + 1] += dp[i][j];
            dp[i + 1][j + 1] %= MOD;
          } else {
            dp[i + 1][j] += dp[i][j];
            dp[i + 1][j] %= MOD;
          }
        }
      }
    }
  }

  cout << dp[H][K - 1] << endl;
  return 0;
