#define in std::cin
#define out std::cout
#define rep(i,N) for(int i=0;i<N;++i)
typedef long long int LL;

const LL mod = 1000000007;
LL H, W, K;
std::vector<std::vector<LL>>memo;

LL dp(LL h, LL w)
{
	if (w < 0 || W <= w) return 0;
	if (h == H)
	{
		if (w == K - 1) return 1;
		return 0;
	}
	if (memo[h][w] != -1) return memo[h][w];
	LL left = 0, str = 0, right = 0;
	for (LL bit = 0; bit < (1LL << (W - 1)); ++bit)
	{
		std::vector<LL>pos;
		rep(k, W - 1)
		{
			if (bit&(1LL << k)) pos.push_back(k);
		}
		bool akan = false;
		rep(i, std::max<LL>(pos.size() - 1, 0))
		{
			if (pos[i] + 1 == pos[i + 1])
			{
				akan = true;
				break;
			}
		}
		if (akan) continue;
		int flag = -1;
		for (auto i : pos)
		{
			if (i == w - 1) flag = 0;
			if (i == w) flag = 1;
		}
		if (flag == 0) ++left;
		if (flag == -1) ++str;
		if (flag == 1) ++right;
	}
	LL res1 = (dp(h + 1, w - 1)*left) % mod;
	LL res2 = (dp(h + 1, w)*str) % mod;
	LL res3 = (dp(h + 1, w + 1)*right) % mod;
	return memo[h][w] = (res1 + res2 + res3) % mod;
}

int main()
{
	in >> H >> W >> K;

	memo.resize(H);
	rep(i, memo.size()) memo[i].resize(W, -1);

	out << dp(0, 0) << std::endl;
	return 0;
}

