  vector<long long> fib(9, 1);
  for (int i=2; i<9; i++) fib[i] = fib[i-1] + fib[i-2];
  vector<pair<long long, long long>> ans;
  ans.push_back(make_pair(1,1));
  for (int i=1; i<=H; i++){
    vector<pair<long long, long long>> nxt;
