      if (k.first>1) nxt.push_back(make_pair(k.first-1, k.second*fib[k.first-2]*fib[W-k.first]%md));
      nxt.push_back(make_pair(k.first, k.second*fib[k.first-1]*fib[W-k.first]%md));
      if (k.first<W) nxt.push_back(make_pair(k.first+1, k.second*fib[k.first-1]*fib[W-k.first-1]%md));
    }
    ans = nxt;
  }
  long long score = 0;
  for (auto k: ans){
    if (k.first==K)
    score += k.second;
    score %= md;
  }
