mint calc(int num) {
    mint ch = (mint)2;
    mint calcans = ch.pow(num);
    for(int i = 2; i <= num; ++i) {
        mint dec = (num-i)+1;
        calcans -= dec;
    }
    return calcans;
}

mint checker(int x, int ww, bool line) {
    int left, right;
    if(line) {
        // その間に線が引かれている場合
        left = max(0, x-1); right = max(0, ww-(x+1)-1);
    }else {
        // その間に線が引かれていない場合
        left = max(0, x); right = max(0, ww-(x+1));
    }

    // left個連続した空間に線が連続しないで何通り引けるか
    // right個も同様
    // cout << "now " << x << " " << line << " sum " << calc(left)+calc(right) << endl;
    return calc(left)*calc(right);
}

mint dchecker(int x, int ww) {
    // x, x-1を引かないとき
    int left = max(0, x-2), right = max(0, ww-(x+1)-1);
    return calc(left)*calc(right);
}

