ll solve(int start, int H, int W, int goal){
  vector<vector<ll>> dp(H+1, vector<ll>(W, 0));
  dp[0][start] = 1;
  rep(i,H){
    rep(j,W){
      if(j-1>=0){
        ll a = j-2;
        ll b = W-1 - (j+1);
        ll p = dp[i][j];
        p *= fib(2, a);
        p %= MOD;
        p *= fib(2, b);
        p %= MOD;
        dp[i+1][j-1] += p;
        dp[i+1][j-1] %= MOD;
      }
      {
        ll a = j-1;
        ll b = W-1 - (j+1);
        ll p = dp[i][j];
        p *= fib(2, a);
        p %= MOD;
        p *= fib(2, b);
        p %= MOD;
        dp[i+1][j] += p;
        dp[i+1][j] %= MOD;
      }
      if(j+1<W){
        ll a = j-1;
        ll b = W-1 - (j+2);
        ll p = dp[i][j];
        p *= fib(2, a);
        p %= MOD;
        p *= fib(2, b);
        p %= MOD;
        dp[i+1][j+1] += p;
        dp[i+1][j+1] %= MOD;
      }
    }
  }
  return dp[H][goal];
}


