using namespace std;

int mod = 1000000007;
ll po(ll k, ll x) {
  if (x == 0) {
    return 1;
  }
  if (x == 1) {
    return k % mod;
  }
  ll y = po(k, x/2);
  y = y * y % mod;
  if (x % 2 == 1) {
    y = y * k % mod;
  }
  return y;
}
auto berlekamp_massey(vll & s) {
  int N = s.size();
  vll C(N, 0);
  C[0] = 1;
  vll B(N, 0);
  B[0] = 1;
  int L = 0;
  int m = 1;
  ll b = 1;
  rep (n, N) {
    ll d = s[n];
    FOR (i, 1, L+1) {
      d = (d + C[i] * s[n-i]) % mod;
    }
    if (d == 0) {
      m = m + 1;
    } else if (2 * L <= n) {
      auto T = C;
      rep (i, N) {
        ll dec = d * po(b, mod-2) % mod * B[(i-m + N) % N] % mod;
        C[i] = (C[i] - dec + mod) % mod;
      }
      L = n + 1 - L;
      B = T;
      b = d;
      m = 1;
    } else {
      rep (i, N) {
        ll dec = d * po(b, mod-2) % mod * B[(i-m + N) % N] % mod;
        C[i] = (C[i] - dec + mod) % mod;
      }
      m = m + 1;
    }
  }
  return make_tuple(L, C);
}

auto berlekamp_massey_vec2(vvll & b) {
  int N = b.size();
  int deg = b[0].size();
  vll u = {54321, 67890};
  vll s(N, 0);
  rep (i, N) {
    rep (j, deg) {
      s[i] = (s[i] + b[i][j] * u[j]) % mod;
    }
  }
  return berlekamp_massey(s);
}

