#define LL long long int
const LL INF = (LL)(1e18)+1;
const int INF_INT = 2147483647-1e6-1;
const LL mod = 1000000007ll;
const int mod_int = 1000000007;

struct mint {
  LL x; 
  mint(LL x=0):x((x%mod+mod)%mod){}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(LL t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

LL H,W,K;

mint ans = 0;

void solve(){
    if(W==1){
        ans.x = 1;
        return;
    }
    //縦棒を上からi刻み分についての入れ方のうち、
    //1からスタートしてj本目に到達するような
    //横線の入れ方の場合の数を
    //dp[i][j]とおく
    vector<vector<mint>> dp(H+1,vector<mint>(W,mint(0)));
    dp[0][0] = mint(1);
    //回収するイメージのDP
    for(int i=0;i<H;i++){
        int pattern = (1<<(W-1));
        //bitが例えば1010なら縦棒1,2間、3,4間に横線を引くと表現する
        for(int bit=0;bit<pattern;bit++){
            //横棒が隣り合うようなbitならfalseを返すラムダ式
            auto ok = [&](){
                for(int b=0;b<(W-1)-1;b++){
                    if(((bit>>b)&1)&&((bit>>(b+1))&1)) return false;
                }
                return true;
            };

            //どの横棒も隣り合わないなら
            if(ok()){
                for(int j=0;j<W;j++){
                    int nj = j;
                    if (bit & (1<<j)) nj++;
                    else if (j > 0 && (bit & (1<<(j-1)))) nj--;
                    dp[i+1][nj] += dp[i][j];
                }
            }
        }
    }
    ans = dp[H][K-1];
}

int main(){
    cin >> H >> W >> K;

    solve();

    cout << ans.x << endl;
    return 0;
}

