        if(i)mat.at(i-1).at(i)=a.at(i-1)*a.at(w-i-1);
    }
    auto mul=[&](auto&&p,auto&&q){
        std::vector<std::vector<mint>>c(w,std::vector<mint>(w));
        for(lint i=0;i<w;i++)for(lint j=0;j<w;j++)for(lint k_=0;k_<w;k_++){
            c.at(i).at(j)+=p.at(i).at(k_)*q.at(k_).at(j);
        }
        return c;
    };
    std::vector<std::vector<mint>>ans(w,std::vector<mint>(w));
    for(lint i=0;i<w;i++)ans.at(i).at(i)=1;
    while(h--)ans=mul(ans,mat);
    std::cout<<ans.at(0).at(k-1)<<'\n';
}

