bool isValid(int n){
    if(n==0) return true;

    bool ret = true;
    if(n%2==0) ret = isValid(n/2);
    else{
        if((n/2)%2==1) ret = false;
        else ret = isValid(n/2);
    }
    return ret;
}

int main(){
    ll mod = 1000000007;
    int H, W, K;  cin >> H >> W >> K;
    vector<vector<ll>> dp;
    dp = vector<vector<ll>>(H+1, vector<ll>(W+1, 0));
    dp[0][1] = 1;
    for(int h=0; h<H; h++){
        for(int w=1; w<=W; w++){
            ll c1 = 0, c2 = 0, c3 = 0;
            int N = (1 << (W - 1));
            for(int i=0; i<N; i++){
                if(!isValid(i)) continue;
                int n = i;
                int j = 0;
                vector<bool> bridge(W+1, false);
                while(n > 0){
                    if(n%2==1) bridge[W-1-j] = true;
                    n/=2;  j++;
                }
                if(!bridge[w] && !bridge[w-1]) c1++;
                if(bridge[w-1]) c2++;
                if(bridge[w]) c3++;
            }
            dp[h+1][w] = c1*dp[h][w]%mod;
            if(w-1>=1) dp[h+1][w] = (dp[h+1][w] + (c2*dp[h][w-1])%mod)%mod;
            if(w+1<=W) dp[h+1][w] = (dp[h+1][w] + (c3*dp[h][w+1])%mod)%mod;
        }
    }

    cout << dp[H][K] << endl;
}

