                for(int j = 0; j < W; ++j)
                {
                    if(bit & (1 << j))
                    {
                        dp[i][j] += dp[i-1][j+1];
                    }
                    else if(j != 0 && (bit & (1 << (j-1))))
                    {
                        dp[i][j] += dp[i-1][j-1];
