void calcCom()
{
  com[0][0] = 1;
  com[0][1] = 1;
  for (int i = 1; i < 10; i++)
  {
    com[i][0] = com[i - 1][0] + com[i - 1][1]; // prevに関わらず選択可能
    com[i][1] = com[i - 1][0];                 // prevが未選択の場合のみ
  }
}

int64_t comb(int64_t w)
{
  if (w < 1)
    return 1; // 選ばないの1通り
  return (com[w - 1][0] + com[w - 1][1]);
}

int main()
{
  int H, W, K;
