  {
    for (int j = 0; j < W; j++)
    {
      if (j == 0)
      {
        (dp[i + 1][j] += dp[i][j] * comb(W - 2) % MOD) %= MOD;
        (dp[i + 1][j + 1] += dp[i][j] * comb(W - 3) % MOD) %= MOD;
      }
      else if (j == W - 1)
      {
        (dp[i + 1][j] += dp[i][j] * comb(W - 2) % MOD) %= MOD;
        (dp[i + 1][j - 1] += dp[i][j] * comb(W - 3) % MOD) %= MOD;
      }
      else
