        (dp[i + 1][j] += dp[i][j] * comb(j - 1) * comb((W - 1) - j - 1) % MOD) %= MOD;
        (dp[i + 1][j + 1] += dp[i][j] * comb(j - 1) * comb((W - 1) - j - 2) % MOD) %= MOD;
