int main() {
	const ll MOD = 1e9 + 7;
	int H, W, K;
	cin >> H >> W >> K;
	vector<int> x(W + 1, 0);
	x[0] = 1, x[1] = 2;
	for (int i = 2; i < x.size(); ++i) {
		x[i] = x[i - 2] + x[i - 1];
	}
	vector<int> y(W, 0);
	for (int i = 1; i < y.size(); ++i) {
		int l = max(0, i - 2), r = max(0, W - i - 2);
		y[i] = x[l] * x[r];
	}
	vector<int> z(W + 1, 0);
	for (int i = 1; i < z.size(); ++i) {
		int l = max(0, i - 2), r = max(0, W - i - 1);
		z[i] = x[l] * x[r];
	}

	vector<vector<ll>> dp(H + 2, vector<ll>(W + 1, 0));
	dp[0][1] = 1;
	for (int i = 0; i <= H; ++i) {
		for (int j = 1; j <= W; ++j) {
			if (i == H) {
				dp[i + 1][j] = dp[i][j];
				continue;
			}

			ll add = (dp[i][j] * z[j]) % MOD;
			dp[i + 1][j] = (dp[i + 1][j] + add) % MOD;

			if (j - 1 > 0) {
				add = (dp[i][j] * y[j - 1]) % MOD;
				dp[i + 1][j - 1] = (dp[i + 1][j - 1] + add) % MOD;
			}
			if (j + 1 <= W) {
				add = (dp[i][j] * y[j]) % MOD;
				dp[i + 1][j + 1] = (dp[i + 1][j + 1] + add) % MOD;
			}
		}
	}

	ll res = dp[H + 1][K];
	cout << res << endl;

	return 0;
}

