const int MOD = (int)1e9 + 7;

int H, W, K;
int amidakuji[8][8];
ll dp[110][10];

//各棒の間を0(横棒なし)と1(横棒あり)で表現
bool isAmidakuji(int bit, int w) {
  for (int i = 0; i < w - 1; i++) {
    if (bit & (1 << i) && bit & (1 << (i + 1))) {
      return false;
    }
  }
  return true;
}

//各jについて，ある段から次の段の位置jへ行く方法の総数を求める
void make_amida() {
  for (int i = 0; i < W; i++) {
    for (int j = 0; j < W; j++) {
      amidakuji[i][j] = 0;
    }
  }
  for (int bit = 0; bit < (1 << (W - 1)); bit++) {
    if (!isAmidakuji(bit, W)) {
      continue;
    }
    bool check[8][8] = {false};
    for (int i = 0; i < W - 1; i++) {
      if (bit & (1 << i)) {
        amidakuji[i][i + 1]++;
        amidakuji[i + 1][i]++;
        check[i][i] = check[i + 1][i + 1] = true;
      }
    }
    for (int i = 0; i < W; i++) {
      if (!check[i][i]) {
        amidakuji[i][i]++;
      }
    }
  }
  return;
}

void solve() {
  for (int i = 0; i <= H; i++) {
    for (int j = 1; j <= W; j++) {
      dp[i][j] = 0;
    }
  }
  dp[0][0] = 1;
  make_amida();
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      ll tmp = 0;
      for (int k = 0; k < W; k++) {
        tmp += amidakuji[k][j] * dp[i][k];
      }
      dp[i + 1][j] = tmp;
      dp[i + 1][j] %= MOD;
    }
  }

  cout << dp[H][K - 1] % MOD << "\n";
  return;
}

int main() {
  cin >> H >> W >> K;
  solve();
  return 0;
}

