	matrix C(A.size(), vec(B[0].size()));
	for (int i = 0; i < (int)C.size(); ++i)
		for (int j = 0; j < (int)C[i].size(); ++j)
			for (int k = 0; k < (int)A[i].size(); ++k) {
				C[i][j] += A[i][k] * B[k][j];
				C[i][j] %= MOD;
			}
	return C;
}
// O( n^3 log e )
matrix mat_pow(const matrix &A, ll e) {
	if (e == 0) return ident(A.size());
	if (e == 1) return A;
	if (e % 2 == 0) {
		matrix tmp = mat_pow(A, e / 2);
		return mul(tmp, tmp);
	} else {
		matrix tmp = mat_pow(A, e - 1);
		return mul(A, tmp);
	}
}


