int dp[105][15], vis[105][15], h, w, k, f[15][2];

void init(){
    memset(dp, 0, sizeof dp);
    dp[h][k] = 1;
    vis[h][k] = 1;

    f[1][1] = f[1][0] = 1;
    for(int i = 2; i <= 8; i++) {
        f[i][1] = f[i-1][0];
        f[i][0] = (f[i-1][1] + f[i-1][0])%p;
    }
}
int cnt(int num){
    if(num<=0) return 1;
    return (f[num][0] + f[num][1]) % p;
}
int dfs(int r, int c){
    if(r > h || r < 0 || c > w || c <= 0) return 0;
    if(vis[r][c])return dp[r][c];
    vis[r][c] = 1;
    dp[r][c] = (dp[r][c] + dfs(r+1, c)   * (cnt(c-1-1) * cnt(w-c-1)%p)%p)%p;
    dp[r][c] = (dp[r][c] + dfs(r+1, c+1) * (cnt(c-1-1) * cnt(w-c-2)%p)%p)%p;
    dp[r][c] = (dp[r][c] + dfs(r+1, c-1) * (cnt(c-2-1) * cnt(w-c-1)%p)%p)%p;
    return dp[r][c];
}
