    {
        for (int x = 0; x < W;x++)
        {
            unsigned long long X, Y, Z;
            X = Y = Z = 0ULL;

            if (x > 0)
            {
                if(x == 1 || x == W - 1)
                {
                    X = fibt[W - 1];
                }
                else
                {
                    X = fibt[x] * fibt[W - x];
                }
                dp[h][x - 1] += dp[h - 1][x] * X;
