            if(x < W - 1)
            {
                if (x == W - 2 || x == 0)
                {
                    Z = fibt[W - 1];
                }
                else
                {
                    Z = fibt[x + 1] * fibt[W - x - 1];
                }
                dp[h][x + 1] += dp[h - 1][x] * Z;
                dp[h][x + 1] %= M;
            }
        }
