mint fanc(vector<ll> &pt, mint now, int j, int w, int mode){
  mint ad1 = now;
  int lc, rc;
  lc = j - 1;
  rc = w - j - 2;
  if(mode == 0) lc--;
  if(mode == 2) rc--;
  if(lc > 0) ad1 *= pt.at(lc);
  if(rc > 0) ad1 *= pt.at(rc);
  return ad1;
}

