            if (j >= 1) dp[i][j] += (dp[i - 1][j - 1] * y) % mod;
            if (j <= W - 2) dp[i][j] += (dp[i - 1][j + 1] * z) % mod;
        }
    }

    cout << dp[H][K - 1] % mod << endl;
}

