#include <iostream>

using namespace std;

typedef long long ll;
const ll mod = 1e9 + 7;

int main() {
    int H, W, K;
    cin >> H >> W >> K;

    ll dp[102][8] = {0};
    dp[0][0] = 1;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            // bit の有無で横棒を表現
            for (int bit = 0; bit < 1<<(W-1); bit++) {
                bool is_valid = true;
                for (int k = 0; k < W - 2; k++) {
                    // 連続して bit が立っていたら invalid
                    if ( ((bit >> k) & 1) && ((bit >> (k + 1)) & 1) ) {
                        is_valid = false;
                    }
                }
                if (!is_valid) { continue; }
                // j 番目の bit が立っていた => 右側に遷移する
                if (bit >> j & 1) {
                    dp[i+1][j+1] += dp[i][j];
                    dp[i+1][j+1] %= mod;
                }
                // j-1 番目の bit が立っていた => 左側に遷移する
                else if ((bit >> (j - 1)) & 1) {
                    dp[i+1][j-1] += dp[i][j];
                    dp[i+1][j-1] %= mod;
                }
                // どちらの bit も立っていない => そのまま下に遷移
                else {
                    dp[i+1][j] += dp[i][j];
                    dp[i+1][j] %= mod;
                }
            }
        }
    }

    cout << dp[H][K-1] << endl;

    return 0;
}

