const int mod = 1000000007;
struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x(x%mod){}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

const int MOD = 1000000007;
const int inf=1e9+7;
const ll longinf=1LL<<60 ;

void addM(ll &a, ll b) {
    a += b;
    if (a >= MOD) a -= MOD;
}

void mulM(ll &a, ll b) {
    a = ((a%MOD)*(b%MOD))%MOD ;
}

ll powM(ll a,ll b) {
    ll ret = 1;
    ll tmp = a;
    while(b>0) {
        if((b&1)==1) ret = (ret * tmp) % MOD;
        tmp = (tmp * tmp) % MOD;
        b = b >> 1;
    }
    return ret;
}

// mod. m での a の逆元 a^{-1} を計算する
ll modinv(ll a, ll m) {
    ll b = m, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);  

  int H, W, K;
  cin >> H >> W >> K;
  K--;

  // あみだくじの遷移マップ
  // num[i][j] := iがjに遷移する場合の数
  auto num = make_vec<mint>(W + 1, W + 1); ;
  fill_v(num, 0);
  REP(i, 1 << (W - 1)){
    bool chk = true;
    REP(k, W){
      if(((i >> k) & 1) && ((i >> (k + 1)) & 1)) {
        chk = false;
        break;
      }
    }
    if(chk) {
      vector<int> P(W);iota(all(P),0);
      REP(k, W - 1) if((i >> k) & 1) swap(P[k], P[k + 1]);
      REP(k, W) num[k][P[k]] += 1;
    }
  }

  auto dp = make_vec<mint>(H + 1, W + 1);
  fill_v(dp, 0);
  dp[0][K] = 1;
  REP(i, H) REP(j, W) {
    dp[i + 1][j] += dp[i][j] * num[j][j];
    if(j + 1 <  W) dp[i + 1][j + 1] += dp[i][j] * num[j][j + 1];
    if(j - 1 >= 0) dp[i + 1][j - 1] += dp[i][j] * num[j][j - 1];
  }
  cout << dp[H][0].x << endl;

  return 0;
}

