void dfs(int n, vector<bool> ju){
	if (n > 0) {
		ju[n] = true;
		dfs(n - 1,ju);
		ju[n] = false;
		dfs(n - 1,ju);
	}
	else {
		ju[n] = true;
		ch(ju);
		ju[n] = false;
		ch(ju);
	}
}

