bool check_amidakuji_bar(int bit) {
    for (int check_bit = 0; check_bit < (1 << (W - 1 - 1)); ++ check_bit) {
        if ((bit & (1 << check_bit)) && (bit & (1 << (check_bit + 1)))) return false;
    }

    return true;
}

