            for (int bit = 0; bit < (1 << (W - 1)); ++bit) {
                if (check_amidakuji_bar(bit)) {
                    if (w < W - 1 && (bit & (1 << w))) dp[h + 1][w + 1] += dp[h][w] % MOD;
                    else if (w - 1 >= 0 && (bit & (1 << (w - 1)))) dp[h + 1][w - 1] += dp[h][w] % MOD;
                    else dp[h + 1][w] += dp[h][w] % MOD;
                }
            }
        }
    }

