    rep(j,W-1){
      x=fib[max(0LL,j-1)]*fib[max(0LL,W-j-2)];
      v[i+1][j]+=v[i][j+1]*x%mod;
      v[i+1][j]%=mod;
      v[i+1][j+1]+=v[i][j]*x%mod;
      v[i+1][j+1]%=mod;
    }
  }
  cin>>x;
  cout<<v[N][x-1]%mod<<endl;
  return 0;
}

