using namespace std;
using ll = long long;
const ll MOD = 1000000007LL;

void SetZero(vector<vector<ll>>& a) {
    int m = a.size();
    for ( int i = 0; i < m; i++ ) {
        for ( int j = 0; j < m; j++ ) {
            a[i][j] = 0;
        }
    }
}

void PlusOn(vector<vector<ll>>& a, vector<vector<ll>>& b) {
    int m = a.size();
    for ( int i = 0; i < m; i++ ) {
        for ( int j = 0; j < m; j++ ) {
            a[i][j] += b[i][j];
            a[i][j] %= MOD;
        }
    }
}

vector<vector<ll>> TMP;
void MultiplyOn(vector<vector<ll>>& a, vector<vector<ll>>& b) {
    int m = a.size();
    SetZero(TMP);
    for ( int i = 0; i < m; i++ ) {
        for ( int j = 0; j < m; j++ ) {
            for ( int k = 0; k < m; k++ ) {
                TMP[i][j] += (a[i][k]*b[k][j]) % MOD;
            }
            TMP[i][j] %= MOD;
        }
    }
    a.swap(TMP);
}

int main() {
    int H, W, K;
    cin >> H >> W >> K;

    vector<vector<ll>> S(W, vector<ll>(W));
    vector<vector<ll>> Sp1(W, vector<ll>(W)), Sp2(W, vector<ll>(W));
    ll n = 0, n1 = 0, n2 = 0;
    n = 1;
    for ( int k = 0; k < W; k++ ) {
        n2 = n1;
        n1 = n;
        n = (n1 + n2) % MOD;
        Sp2.swap(Sp1);
        Sp1.swap(S);
        SetZero(S);
        PlusOn(S, Sp1);
        S[k][k] += n1;
        if ( k > 0 ) {
            PlusOn(S, Sp2);
            S[k-1][k] += n2;
            S[k][k-1] += n2;
        }
    }

    vector<vector<ll>> SH(W, vector<ll>(W));
    for ( int i = 0; i < W; i++ ) {
        SH[i][i] = 1;
    }
    TMP.resize(W, vector<ll>(W));
    for ( int i = 0; i < H; i++ ) {
        MultiplyOn(SH, S);
    }

    ll ans = SH[K-1][0];
    cout << ans << '\n';
    return 0;
}

