ll dp[105][10]; //dp[i][j] i行目までを考えた時のj番目の縦棒にいる組み合わせ総数 mod 1e9+7
long long fac[MAX],   // i!    mod p iの階乗
          finv[MAX],  // i!^-1 mod p iの階乗の逆元
          inv[MAX];   // i^-1  mod p iの逆元 inverse

void comb_init() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++) {
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
long long combination(long long n, long long k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n-k] % MOD) % MOD;
}

/*
j-2 j-1 j  j+1 j+2
 |   |__|   |   |
 |   |  |   |   |

j-2 j-1 j  j+1 j+2
 |   |  |   |   |
 |   |  |   |   |

j-2 j-1 j j+1 j+2
 |   |  |__|   |
 |   |  |  |   |
*/

void init_d() {
    rep(i, 1, 9) {
        ll j = (ll)i-1, k = 1;
        while (j >= k) {
            d[i] += combination(j, k);
            j--; k++;
        }
        d[i] += 1; //一つも横棒なし
    }
}

long long calc_d(long long n) {
    if (n < 1) return 1;
    return d[(int)n];
}

