                    }else{
                        dp[i][k] += dp[i-1][k], dp[i][k] %= mod;
                    }
                }else{
                    if(raw[k] == 1){
                        dp[i][k] += dp[i-1][k+1], dp[i][k] %= mod;
                        dp[i][k+1] += dp[i-1][k], dp[i][k+1] %= mod;
                    }else{
                        if(raw[k-1] == 0){
                            dp[i][k] += dp[i-1][k], dp[i][k] %= mod;
                            if(k == w-2){
                                dp[i][k+1] += dp[i-1][k+1], dp[i][k+1] %= mod;
                            }
                        }
                    }
                }
            }
        }
    }

