	corner(W == 1, 1);
	map<int, ll> mp;
	mp[1] = mp[0] = mp[-1] = mp[-2] = mp[-3] = 1;

	for(int i = 1; i <= 10; ++i){
		for (int j = 0; j < (1 << i); ++j){
			bool flg = true;
			for(int k = 0; k < i - 1; ++k) if ((j << k)&(j << k + 1)) flg = false;
			if (flg) mp[i+1]++;
		}
	}

	V<V<ll>> dp(H+1, V<ll>(W + 2, 0));
	dp[0][1] = 1;
	int l,r;
	for(int i = 0; i<H; ++i){
		for (int j = 1; j <= W; ++j) {

			l = j - 1;
			r = W - j;
			(dp[i + 1][j] += (dp[i][j] * mp[l] * mp[r])%MOD) %= MOD;

			l = j - 2;
			r = W - j;
			(dp[i + 1][j - 1] += (dp[i][j] * mp[l] * mp[r]) % MOD) %= MOD;

			l = j - 1;
			r = W - j - 1;
			(dp[i + 1][j + 1] += (dp[i][j] * mp[l] * mp[r]) % MOD) %= MOD;
		}
	}
	cout << dp[H][K] << endl;

