ll select2(ll p,ll q){
  ll re=1;
  if(p>q) return 0;
  if(p==q) return 0;
  re+=select2(p+2,q);
  re+=select2(p+1,q);
  return re;
}

ll select(ll p,ll q){
  ll re=2;
  if(p>q) return 1;
  if(p==q) return 1;
  re+=select2(p+2,q);
  re+=select2(p+1,q);
  return re;
}


ll pow_ans(ll x, ll n) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) { res = res*x%big; }
        x = x*x%big;
        n >>= 1;
    }
    return res;
}

