            if(((j >> k) & 1) && ((j >> (k + 1)) & 1))
                flg = true;
        }
        if(flg)
            continue;
        rep(k, w) {
            if((k != 0) && (j >> (k - 1)) & 1) {
                dp[i + 1][k] += dp[i][k - 1];
            } else if((k != w - 1) && ((j >> k) & 1)) {
                dp[i + 1][k] += dp[i][k + 1];
            } else {
                dp[i + 1][k] += dp[i][k];
            }
            dp[i + 1][k] %= MOD;
        }
    }
    // rep(i, h + 1) {
    //     rep(j, w) cout << dp[i][j] << " ";
    //     cout << endl;
    // }
    cout << dp[h][k - 1] << endl;
}

