int main(void)
{
    SQWORD sqH = inputSQWORD();
    SQWORD sqW = inputSQWORD();
    SQWORD sqK = inputSQWORD();

    /**
     *  dp_vline[i][j]
     *      i本の縦線に対して、端点を重複せずに横線を引く場合の数
     *      j = 0 左側に横線が引かれていない
     *      j = 1 左側に横線が引かれている
     */
    vector<vector<SQWORD>> vecDpVLine(sqW + 1, vector<SQWORD>(2, 0));
    vecDpVLine[1][0] = 1;
    for (SQWORD sqVIdx = 2; sqVIdx <= sqW; sqVIdx++) {
       vecDpVLine[sqVIdx][0] = vecDpVLine[sqVIdx - 1][0] + vecDpVLine[sqVIdx - 1][1];
       vecDpVLine[sqVIdx][1] = vecDpVLine[sqVIdx - 1][0];
    }
    vector<MODINT> vecDpVLinePat(sqW + 1, 1);
    for (SQWORD sqVIdx = 1; sqVIdx <= sqW; sqVIdx++) {
        SQWORD sqPatNum = vecDpVLine[sqVIdx][0] + vecDpVLine[sqVIdx][1];
        vecDpVLinePat[sqVIdx] = MODINT(sqPatNum);
//        printf("%lld ", vecDpVLinePat[sqVIdx]);
    }
//    printf("\n");

    /**
     *  dp(i)[j]    i番目までの行を考えたとき、
     *              1から出発した線がjに到達する場合の数
     * 
     *  dp(i+1)[j] = dp(i)[j-1]     * (vpat(j-2)) * (vpat(w-j))
     *                 + dp(i)[j]   * (vpat(j-1)) * (vpat(w-j))
     *                 + dp(i)[j+1] * (vpat(j-1)) * (vpat(w-j-1))
     * 
     *  dp()[0], dp()[W+1] は常に0になるようにしておく
     * 
     */

    vector<MODINT> vecDp(sqW+2, 0);
    vecDp[1] = 1;

    for (SQWORD sqIdxH = 0; sqIdxH < sqH; sqIdxH++) {
        vector<MODINT> vecDpNext(sqW + 2, 0);
        for (SQWORD sqIdxW = 1; sqIdxW <= sqW; sqIdxW++) {
            vecDpNext[sqIdxW] = vecDp[sqIdxW - 1]   * vecDpVLinePat[MAX(0, sqIdxW - 2)] * vecDpVLinePat[MAX(0, sqW - sqIdxW)]
                                + vecDp[sqIdxW]     * vecDpVLinePat[MAX(0, sqIdxW - 1)] * vecDpVLinePat[MAX(0, sqW - sqIdxW)]
                                + vecDp[sqIdxW + 1] * vecDpVLinePat[MAX(0, sqIdxW - 1)] * vecDpVLinePat[MAX(0, sqW - sqIdxW - 1)];
        }
        swap(vecDp, vecDpNext);
    }
    printf("%lld\n", vecDp[sqK]);

    return 0;
}

