void makeLines() {
    int upper = 1 << (W - 1);
    vector<int> tmp(W - 1);
    for (int b = 0; b < upper; b++) {
        for (int i = 0; i < W - 1; i++) tmp[i] = b >> i & 1;
        bool canLine = true;
        for (int i = 0; i < W - 2; i++) {
            if (tmp[i] + tmp [i + 1] == 2) {
                canLine = false;
                break;
            }
        }
        if (canLine) lines.push_back(tmp);
    }
}
void calcDPTable() {
    dp.assign(H + 1, vector<mint>(W));
    dp[0][0] = 1;
    for (int i = 0; i < H; i++) {
        for (vector<int> line : lines) {
            for (int j = 0; j < W; j++) {
