bool valid(int mask) {
    bool last=false;
    for (int j=0; j<w-1; j++) {
	if (mask>>j&1) {
	    if (last) return false;
	    last=true;
	} else {
	    last=false;
	}
    }
    return true;
}

ll dfs(int r, int c) {
    if (r<0 || r>h || c<0 || c>=w) return 0;

    //cout<<r<<" "<<c<<endl;

    if (r==0) {
	return c==k-1;
    }

    if (~dp[r][c]) return dp[r][c];

    ll &res = dp[r][c] = 0;

    for (int mask=0; mask<(1<<(w-1)); mask++) {
	if (!valid(mask)) continue;
	//cout<<bitset<4>(mask)<<endl;
	if (mask>>c&1) {
	    res += dfs(r-1,c+1);
	} else if (c>0 && (mask>>(c-1)&1)) {
	    res += dfs(r-1,c-1);
	} else {
	    res += dfs(r-1,c);
	}
	res %= mod;
    }

    return res;
}

