lli coeff( int j , int W ) //between j and j+1
{

  if( W == 2 )
    {
      return 1LL;
    }

  if( j == 0 or j == W - 2 )
    {
      return num[W-3];
    }

  return num[j-1] * num[W-j-3];

}



lli coeff_alone( int j , int W ) 
{

  if( j == 0 or j == W - 1 )
    {
      return num[W-2];
    }

  return num[j-1] * num[W-j-2];

}





