int H, W, K;
vector<vector<ll> > dp;
vector<ll> fib;

void init()
{
	cin >> H >> W >> K;
	dp.resize(H+1, vector<ll>(W, 0));
	dp[0][0] = 1;
	fib.resize(W+10);
	fib[0] = fib[1] = 1;
	reps(i, 2, W+10) {
		fib[i] = fib[i-1] + fib[i-2];
	}
}

void update(int r)
{
	rep(i, W) {
		if (i == 0) {
			ll t = fib[W-1] * dp[r-1][i] % MOD;
			t += fib[W-2] * dp[r-1][i+1] % MOD;
			dp[r][i] += t % MOD;
		} else if (i == W-1) {
			ll t = fib[W-1] * dp[r-1][i] % MOD;
			t += fib[W-2] * dp[r-1][i-1] % MOD;
			dp[r][i] += t % MOD;
		} else {
			ll t = fib[i] * fib[W-i-1] % MOD * dp[r-1][i] % MOD;
			t += fib[i-1] * fib[W-i-1] % MOD * dp[r-1][i-1] % MOD;
			t += fib[i] * fib[W-i-2] % MOD * dp[r-1][i+1] % MOD;
			dp[r][i] += t % MOD;
		}
		dp[r][i] %= MOD;
	}
}

void solve()
{
	if (W == 1) {
		cout << 1 << endl;
		return;
	}
	reps(i, 1, H+1) {
		update(i);
	}
	cout << dp[H][K-1] << endl;
}

