int main(){
    int H,W,K; cin >> H >> W >> K;
    ll dp[H+1][W+1]={};
    dp[0][0]=1;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            for(int mask=0;mask<(1<<W-1);mask++){
                bool flag=true;
                for(int k=0;k<W-2;k++){
                    if((mask&(1<<k))&&(mask&(1<<(k+1)))){
                        flag=false;
                    }
                }
                if(!flag) continue;
                if(mask&(1<<j)){
                    dp[i+1][j+1]+=dp[i][j]%MOD;
                    dp[i+1][j+1]%=MOD;
                }else if(j>0&&mask&(1<<(j-1))){
                    dp[i+1][j-1]+=dp[i][j]%MOD;
                    dp[i+1][j-1]%=MOD;
                }else{
                    dp[i+1][j]+=dp[i][j]%MOD;
                    dp[i+1][j]%=MOD;
                }
            }
        }

    }
    cout << dp[H][K-1]%MOD << endl;
