int kazoeage(int now, int sum, int res)
{
    if (res == 0)
        return sum + 1;

    if (now == 1)
        sum = kazoeage(0, sum, res - 1);
    else
    {
        sum = kazoeage(0, sum, res - 1);
        sum = kazoeage(1, sum, res - 1);
    }
    return sum;
}

int memo[10];
int pat(int num)
{
    if (num < 0)
        num = 0;
    if (memo[num] != -1)
    {
        return memo[num];
    }
    else
    {
        memo[num] = kazoeage(0, 0, num);
        return memo[num];
    }
}

int H, W, K;
int ans;

//一層ずつ考えていく
void dfs(int now_h, int now_w, int num)
{
    int tmp;
    if (now_h == H + 1)
    {
        ans += num;
        ans %= MOD;
        return;
    }
    //左に行く
    if (now_w != 1 and now_w - 1 >= K - (H - now_h))
    {
        tmp = num;
        if (now_w - 1 == 1 or now_w == W)
        {
            tmp *= pat((W - 1) - 2);
        }
        else
        {
            tmp *= pat(now_w - 3);
            tmp *= pat((W - 1) - (now_w - 3) - 3);
        }
        dfs(now_h + 1, now_w - 1, tmp);
    }
    //下に行く
    if (now_w >= K - (H - now_h) and now_w <= K + (H - now_h))
    {
        tmp = num;
        if (now_w == W or now_w == 1)
        {
            tmp *= pat((W - 1) - 1);
        }
        else
        {
            tmp *= pat(now_w - 2);
            tmp *= pat((W - 1) - (now_w - 2) - 2);
        }
        dfs(now_h + 1, now_w, tmp);
    }

    //右に行く
    if (now_w != W and now_w + 1 <= K + (H - now_h))
    {
        tmp = num;
        if (now_w + 1 == W or now_w == 1)
        {
            tmp *= pat((W - 1) - 2);
        }
        else
        {
            tmp *= pat(now_w - 2);
            tmp *= pat((W - 1) - (now_w - 2) - 3);
        }
        dfs(now_h + 1, now_w + 1, tmp);
    }
}

