  put_num[0] = random_num[W-3];
  FOR(i, 1, W-2){
    put_num[i] = (random_num[i-1]*random_num[W-3-i])%DIVIDE;
  }
  put_num[W-2] = random_num[W-3];

  nonput_num[0] = random_num[W-2];
  FOR(i, 1, W-1){
    nonput_num[i] = (random_num[i-1]*random_num[W-2-i])%DIVIDE;
  }
  nonput_num[W-1] = random_num[W-2];

  vll dp(W, 0);
  vll dp2(W, 0);
  dp[0] = 1;
  FOR(i, 0, H){
    dp2[0] = (dp[0]*nonput_num[0] + dp[1]*put_num[0])%DIVIDE;
    FOR(j, 1, W-1){
      dp2[j] = (dp[j-1]*put_num[j-1] + dp[j]*nonput_num[j] + dp[j+1]*put_num[j])%DIVIDE;
    }
    dp2[W-1] = (dp[W-2]*put_num[W-2] + dp[W-1]*nonput_num[W-1])%DIVIDE;

    dp = dp2;
  }

  cout << dp[K-1] << "\n";

  return 0;
}

