using namespace std;

const u_int64_t R = 1'000'000'007;

u_int64_t simple[8 + 1];
u_int64_t amida[100 + 1][8];

u_int64_t withBar(int bar, int width)
{
    if (bar < 0 || bar >= width - 1)
    {
        return 0;
    }
    u_int64_t lSide = simple[bar];
    u_int64_t rSide = simple[width - (bar + 2)];
    return lSide * rSide % R;
}

int main()
{
    int H, W, K;
    cin >> H >> W >> K;
    K--;

    for (int i = 0; i <= W; i++)
    {
        if (i < 2)
        {
            simple[i] = 1;
            continue;
        }
        simple[i] = (simple[i - 1] + simple[i - 2]) % R;
    }

    for (int i = 0; i <= H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if (i == 0)
            {
                amida[i][j] = j == 0 ? 1 : 0;
                continue;
            }

            u_int64_t leftP = withBar(j - 1, W);
            u_int64_t rightP = withBar(j, W);
            u_int64_t centerP = ((simple[W] + R - leftP) % R + R - rightP) % R;
            u_int64_t fromLeft = (j - 1 < 0) ? 0 : (leftP * amida[i - 1][j - 1]) % R;
            u_int64_t fromRight = (j + 1 >= W) ? 0 : (rightP * amida[i - 1][j + 1]) % R;
            u_int64_t fromCenter = centerP * amida[i - 1][j] % R;
            amida[i][j] = ((fromLeft + fromRight) % R + fromCenter) % R;
        }
    }

    cout << amida[H][K] << endl;

    return 0;
}

