void numberofAmidakuji(){
	int H, W, K;
	cin >> H >> W >> K;
	for (int i = 0; i < (1 << (W - 1)); i++)
	{
		bool ok = true;
		for (int j = 0; j < W - 2; j++)
		{
			if (nthbit(i, j) && nthbit(i, j + 1)) {

				ok = false;
				break;
			}
		}
		if (!ok) continue;
		vector<ll> P(W);
		for (int j = 0; j < W; j++)
		{
			P[j] = j;
		}
		for (int j = 0; j < W - 1; j++)
		{
			if (nthbit(i, j)) swap(P[j], P[j + 1]);
		}
		for (int j = 0; j < W; j++)
		{
			num[j][P[j]]++;
		}
	}
	dp[0][0] = 1;
	for (size_t h = 0; h < H; h++)
	{
		for (size_t w = 0; w < W; w++)
		{
			for (size_t k = 0; k < W; k++)
			{
				add(dp[h + 1][k], (dp[h][w] * num[w][k]) % mod);
			}
		}
	}
	cout << dp[H][K - 1] << endl;
}

int main() {
	numberofAmidakuji();
	return 0;
}

