int main()
{
	int H, W, K;
	ll left, mid, right, tmp;

	cin >> H >> W >> K;

	repc(i, 0, W - 1) {
		if (i == 0) line[i] = 1;
		else if (i == 1) line[i] = 2;
		else {
			line[i] = line[i - 1] + line[i - 2];
		}
	}

	repc(h, 1, H) {
		repc(w, 1, W) {
			if (h == 1) {
				if (w == 1) d[h][w] = line[max(0, W - 2)];
				else if (w == 2) d[h][w] = line[max(0, W - 3)];
				else d[h][w] = 0;
				continue;
			}

			if (w == 1) left = 0;
			else {
				tmp = line[max(0, w - 3)];
				tmp *= line[max(0, W - w - 1)];
				left = (d[h - 1][w - 1] * tmp) % MOD;
			}

			tmp = line[max(0, w - 2)];
			tmp *= line[max(0, W - w - 1)];
			mid = (d[h - 1][w] * tmp) % MOD;

			if (w == W) right = 0;
			else {
				tmp = line[max(0, w - 2)];
				tmp *= line[max(0, W - w - 2)];
				right = (d[h - 1][w + 1] * tmp) % MOD;
			}

			d[h][w] = (left + mid + right) % MOD;
		}
	}

	cout << d[H][K] << endl;

	return 0;
}

