using namespace std;

#define M 1000000007

int main() {

	int a[9] = { 0 };//左端に線がない | |-|
	int b[9] = { 0 };//左端に線がある |-| |
	a[0] = 1;
	a[1] = 1;
	b[1] = 0;

	for (int i = 2; i < 9; i++) {
		b[i] = a[i-1];
		a[i] = a[i - 1] + b[i - 1];
		//cout << a[i] + b[i] << endl;
	}

	int h, w, k;
	cin >> h >> w >> k;

	vector< vector<long long int> > dp(h, vector<long long int>(w, 0));
	dp[0][0] = (long long int)a[w];
	if (w > 1) {
		dp[0][1] = (long long int)a[w - 1];
	}
	for (int i = 1; i < h; i++) {
		for (int j = 0; j < w; j++) {
			if (dp[i - 1][j] > 0) {
				if (j == 0) {
					dp[i][j] += dp[i - 1][j] * (long long int)(a[w - 1] + b[w - 1]);
					dp[i][j] %= M;
					if (j + 1 < w) {
						dp[i][j + 1] += dp[i - 1][j] * (long long int)b[w];
						dp[i][j + 1] %= M;
					}
				}
				else if (j == w - 1) {
					dp[i][j] += dp[i - 1][j] * (long long int)(a[w - 1] + b[w - 1]);
					dp[i][j] %= M;
					if (0 <= j - 1) {
						dp[i][j - 1] += dp[i - 1][j] * (long long int)b[w];
						dp[i][j - 1] %= M;
					}
				}
				else {
					dp[i][j] += dp[i - 1][j] * (long long int)((a[j] + b[j]) * (a[w - j - 1] + b[w - j - 1]));
					dp[i][j] %= M;

					dp[i][j - 1] += dp[i - 1][j] * (long long int)((a[j - 1] + b[j - 1]) * (a[w - j - 1] + b[w - j - 1]));
					dp[i][j - 1] %= M;

					dp[i][j + 1] += dp[i - 1][j] * (long long int)((a[j] + b[j]) * (a[w - j - 2] + b[w - j - 2]));
					dp[i][j + 1] %= M;
				}
			}
		}
	}

	cout << dp[h - 1][k - 1] << endl;

	return 0;
}

