ll answer = 0;
ll h, w, k;
ll dp[10][10][105];// [origin][goal][height]
bool lines[10];

bool invalid_kuji(ll w){
    rep(i, w - 2) if (lines[i] && lines[i + 1]) return true;
    return false;
}

void construct_newline(ll tmp, ll w){
    rep(x, w - 1){
        if (tmp % 2 == 0) lines[x] = false;
        else lines[x] = true; 
        tmp /= 2;
    }
}

int main(void){
    in3(h, w, k);
    k--;
    rep(s, w)rep(g, w)rep(y, h) dp[s][g][y] = 0;

    ll upper = power_normal(2, w - 1);

    rep(x, w) dp[x][x][0] = 1;

    rep(y, h){
        rep(cnt, upper){
            ll tmp = cnt; construct_newline(tmp, w);            
            if (invalid_kuji(w)) continue;
            rep(s, w)rep(g, w){
                if (g != 0 && lines[g - 1]) dp[s][g][y + 1] += dp[s][g - 1][y];
                if (g != w - 1 && lines[g]) dp[s][g][y + 1] += dp[s][g + 1][y];
                if (g != 0 && g != w - 1 && !lines[g - 1] && !lines[g]) dp[s][g][y + 1] += dp[s][g][y];
                else if (g == 0 && !lines[g]) dp[s][g][y + 1] += dp[s][g][y];
                else if (g == w - 1 && !lines[g - 1]) dp[s][g][y + 1] += dp[s][g][y];
                dp[s][g][y + 1] %= MOD;
            }
        }
    }

    prl(dp[0][k][h] % MOD);

    return 0;
}

