int h, w, k;

ll dp[MAX_H][MAX_W];
bool arr[MAX_W];
int retain = 0, ls = 1, rs = 2;
ll mv[MAX_W][3];

ll ans;

bool check() {
  for (int l = 1; l <= w - 1; ++l) {
    if (arr[l] && arr[l + 1]) {
      return false;
    }
  }

  return true;
}

int main(void) {
  // Here your code !
  scanf("%d %d %d", &h, &w, &k);

  arr[0] = false;  // guard

  for (int k = 0; k < 1 << (w - 1); ++k) {
    for (int l = 0; l < w - 1; ++l) {
      arr[l + 1] = (k >> l & 1) ? true : false;
    }

    if (!check()) continue;  // in-valid pattern

    for (int j = 1; j <= w; ++j) {
      if (arr[j]) {
        mv[j][rs] += 1;
      } else if (arr[j - 1]) {
        mv[j][ls] += 1;
      } else {
        mv[j][retain] += 1;
      }
    }
  }

  dp[0][1] = 1LL;

  for (int i = 0; i < h; ++i) {
    for (int j = 1; j <= w; ++j) {
      if (j == 1) {
        dp[i + 1][j] += dp[i][j] * mv[j][retain];
        dp[i + 1][j + 1] += dp[i][j] * mv[j][rs];
      } else if (j == w) {
        dp[i + 1][j] += dp[i][j] * mv[j][retain];
        dp[i + 1][j - 1] += dp[i][j] * mv[j][ls];
      } else {
        dp[i + 1][j] += dp[i][j] * mv[j][retain];
        dp[i + 1][j + 1] += dp[i][j] * mv[j][rs];
        dp[i + 1][j - 1] += dp[i][j] * mv[j][ls];
      }

      dp[i + 1][j] %= MOD;
      dp[i + 1][j + 1] %= MOD;
      dp[i + 1][j - 1] %= MOD;
    }
  }

  ans = dp[h][k];

  printf("%lld\n", ans);

  return 0;
}

