void pre() {
	fib[0] = 0, fib[1] = 1;
	for (int i = 2; i < 10; ++i) fib[i] = fib[i - 1] + fib[i - 2];
	int sum = 0;
	for (int i = 0; i < 10; ++i) {
		sum += fib[i];
		fib[i] = sum;
	}
}

int main() {
	cin.sync_with_stdio(0); cin.tie(0);
	cin >> h >> w >> k;
	dp[0][0] = 1;
	pre();

	for (int i = 1; i <= h; ++i) {
		for (int j = 0; j < w; ++j) {
			for (int l = -1; l <= 1; ++l) {
				int width = j + l;
				if (width >= 0 && width < w) {
					// Left slots avail, right slots avail
					ll la = j, ra = w - j - 1;
					--la, --ra;
					if (l == -1) --la;
					if (l == 1) --ra;
					la = max(0ll, la), ra = max(0ll, ra);
					la = fib[la] + 1, ra = fib[ra] + 1;

					ll toAdd = ((dp[i - 1][width] % MOD) * la) % MOD;
					toAdd *= ra, toAdd %= MOD;

					dp[i][j] = (dp[i][j] + toAdd) % MOD;
				}
			}
		}
	}

	cout << dp[h][k - 1] % MOD;
