template <class Abel = int> struct Segtree {
    typedef function<Abel(const Abel&, const Abel&)> opr_t;
    const opr_t opr;
    const Abel idel;
    int range = 1;
    vector<Abel> data;

    Segtree(int sz, Abel init_val, const opr_t &opr = plus<Abel>(), Abel idel = 0) : opr(opr),idel(idel)
    {
        while(sz >= range) range <<= 1;
        init(init_val);
    }

    Segtree(int sz, vector<Abel> init_arr, const opr_t &opr = plus<Abel>(), Abel idel = 0) : opr(opr),idel(idel)
    {
        while(sz >= range) range <<= 1;
        init(init_arr);
    }

    void init(Abel val) {
        data.resize(range << 1);
        fill(begin(data) + range,end(data),val);
        for(int i = range - 1; i; i--) data[i] = opr(data[i * 2],data[i * 2 + 1]);
    }

    void init(vector<Abel> arr) {
        data.resize(range << 1);
        for(int i = 0; i < range; i++) data[i + range] = arr[i];
        for(int i = range - 1; i; i--) data[i] = opr(data[i * 2],data[i * 2 + 1]);
    }

    void update(int idx, Abel val) {
        data[idx += range] = val;
        while(idx >>= 1) data[idx] = opr(data[idx * 2],data[idx * 2 + 1]);
    }

    void add(int idx, Abel diff = 1) { update(idx,data[idx + range] + diff); }

    // for the interval [l,r)
    Abel query(int l, int r, bool is_first = true) {
		if(l >= r) return idel;
		if(is_first) {
			l += range;
			r += range;
		}
		Abel tl = l & 1 ? data[l++] : idel;
		Abel tr = r & 1 ? data[--r] : idel;
		return opr(opr(tl,query(l >> 1,r >> 1,false)),tr);
    }
};

