		pf[i][0]+=pf[i-1][0]+pf[i-1][1];
		(pf[i][1]+=pf[i-1][0])%=mod;
		pf[i][0]%=mod;
		pf2[i]=(pf[i][0]+pf[i][1])%mod;
	}

	cin>>h>>w>>k;
