		i64 *crt=dp[i-1];
		i64 *nxt=dp[i];
		urep(j,1,w) {
			int l = j-1;
			int r = w-j;
			if(j>1) {
				nxt[j-1]+=pf[l][1]*pf[r][0]%mod*crt[j]%mod;
				nxt[j-1]%=mod;
			}
			if(j<w) {
				nxt[j+1]+=pf[l][0]*pf[r][1]%mod*crt[j]%mod;
				nxt[j+1]%=mod;
			}
			nxt[j]+=crt[j]*pf[l][0]%mod*pf[r][0]%mod;
