const ll MOD = 1000000007;
const ll HIGHINF = (ll)1e18;

int main() {
  ll h, w, k; cin >> h >> w >> k;
  ll state = 1LL<<(w-1);
  vvll dp(h+1, vll(w, 0)); dp[0][0] = 1;
  rep(i, 1, h+1) {
    REP(s, state) {
      bool is_valid = true;
      rep(wi, 0, w-2) if (((s>>wi)&1) && ((s>>(wi+1))&1)) {is_valid=false;break;}
      if (!is_valid) continue;
      if (!(s&1)) {dp[i][0] += dp[i-1][0]; if(dp[i][0]>=MOD) dp[i][0]-=MOD;}
      else {dp[i][0] += dp[i-1][1]; if(dp[i][0]>=MOD) dp[i][0]-=MOD;}
      rep(wi, 0, w-2) {
        if ((s>>wi)&1) {dp[i][wi+1] += dp[i-1][wi]; if(dp[i][wi+1]>=MOD) dp[i][wi+1]-=MOD;}
        else if ((s>>(wi+1))&1) {dp[i][wi+1] += dp[i-1][wi+2]; if(dp[i][wi+1]>=MOD) dp[i][wi+1]-=MOD;}
        else {dp[i][wi+1] += dp[i-1][wi+1]; if(dp[i][wi+1]>=MOD) dp[i][wi+1]-=MOD;}
      }
      if ((s>>(w-2))&1) {dp[i][w-1] += dp[i-1][w-2]; if(dp[i][w-1]>=MOD) dp[i][w-1]-=MOD;}
      else {dp[i][w-1] += dp[i-1][w-1]; if(dp[i][w-1]>=MOD) dp[i][w-1]-=MOD;}
    }
  }
  if (w==1) cout << 1 << endl;
  else cout << dp[h][k-1] << endl;
  return 0;
}

