void solve()
{
    ll H, W, K;
    in(H, W, K);
    if (W == 1) {
        if (K == 1) {
            print(1);
        }
        else {
            print(0);
        }
        return;
    }
    ll Wb = 1LL << (W - 1);
    vvll go(W, vll(W));
    for1 (i, Wb) {
        bool ok = true;
        for1 (b, 8) {
            if (((i >> b) & 3) == 3) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;
        vll bar(W);
        for1 (j, W) {
            bar[j] = j;
        }
        for1 (j, W - 1) {
            if (((i >> j) & 1) != 0) {
                swap(bar[j], bar[j + 1]);
            }
        }
        for1 (j, W) {
            go[bar[j]][j]++;
        }
    }
    vector<vector<mint>> dp(H + 1, vector<mint>(W));
    dp[0][0] = 1;
    for1 (i, H) {
        for1 (j, W) {
            for1 (k, W) {
                dp[i + 1][j] += dp[i][k] * go[k][j];
            }
        }
    }
    print(dp[H][K - 1]);
}
