long long int fib(const int n) {
	if (n <= 0) return 1;
	else {
		long long int a = 1, b = 2;
		for (auto i = 0; i < n; ++i) {
			auto temp = b;
			b = (a + b) % mod;
			a = temp;
		}
		return a;
	}
}
long long int count(const int h, const int w, const int k, std::vector<std::vector<long long int>>& memo) {
	if (h == 0) return (k == 1) ? 1 : 0;
	else if (k > w || k < 1) return 0;
	else if (memo[h][k] >= 0) return memo[h][k];
	else return memo[h][k] = (count(h - 1, w, k - 1, memo) * fib(k - 3) % mod * fib(w - k - 1) + count(h - 1, w, k + 1, memo) * fib(k - 2) % mod * fib(w - k - 2) + count(h - 1, w, k, memo) * fib(k - 2) % mod * fib(w - k - 1)) % mod;
}
