int *fib;

unsigned long FOR(int H, int W, int K)
{
	unsigned long ans = 0;
	unsigned long ans1=0, ans2=0, ans3=0;
	// 基底条件
	// H=1の時 K<=2ならOK
	if (H == 1)
	{
		if (K <= 2)
		{
			return(fib[W - K]);
		}
		else
		{
			return(0);
		}
	}
	else if (H < K-1)
	{
		return(0);
	}
	else // 高さを1減らして　K-1, K, K+1の条件で再帰的に呼び出す。
	{
		if (K - 1 > 0)
		{
			ans1 = FOR(H - 1, W, K - 1)*fib[K - 2]*fib[W-K] % 1000000007l;
		}
		if (K + 1 <= W)
		{
			ans3 = FOR(H - 1, W, K + 1)*fib[K-1]*fib[W-K-1] % 1000000007l;
		}
		ans2 = FOR(H - 1, W, K)*fib[K-1]*fib[W-K] % 1000000007l;
	}
	ans = (ans1 + ans2 + ans3) % 1000000007l;

	return(ans);
}


