					mul = pattarn[W - 2];
				}
				else {
					mul = pattarn[j] + pattarn[W - j];
				}
				num[i + 1][j-1] = (num[i + 1][j-1] + num[i][j] * mul) % MOD_NUM;
			}
		}
	}

