    for (int i = 1; i < H+1; ++i) {
        for (int j = 0; j < W; ++j) {
            if (j == 0) {
                dp[i][j] += dp[i-1][j] * (all - t[j]);
                dp[i][j] %= MOD;
                dp[i][j] += dp[i-1][j+1] * t[j];
                dp[i][j] %= MOD;
            } else if (j == W-1) {
                dp[i][j] += dp[i-1][j-1] * t[j-1];
                dp[i][j] %= MOD;
                dp[i][j] += dp[i-1][j] * (all - t[j-1]);
                dp[i][j] %= MOD;
            } else {
                dp[i][j] += dp[i-1][j-1] * t[j-1];
                dp[i][j] %= MOD;
                dp[i][j] += dp[i-1][j] * (all - t[j] - t[j-1]);
                dp[i][j] %= MOD;
                dp[i][j] += dp[i-1][j+1] * t[j];
                dp[i][j] %= MOD;
            }
        }
    }

    cout << dp[H][K] << endl;

    return 0;
}

