const int mod = 1000000007;

struct mint {
    ll x; // typedef long long ll;
    mint(ll x = 0) : x((x % mod + mod) % mod) {}

    mint &operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator-=(const mint a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }

    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }

    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }

    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }

    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod - 2);
    }

    mint &operator/=(const mint a) {
        return (*this) *= a.inv();
    }

    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }

    friend std::istream &operator>>(std::istream &in, mint &o) {
        ll a;
        in >> a;
        o = a;
        return in;
    }

    friend std::ostream &operator<<(std::ostream &out, const mint &o) {
        out << o.x;
        return out;
    }

};

bool is_adjoin(int n, int i) {
    for (int j = 0; j < n - 2; j++) {
        bool a = (i >> j) & 1;
        bool b = (i >> (j + 1)) & 1;
        if (a && b) return true;
    }
    return false;
}

vector<int> get_enable_bars(int n) {
    vector<int> ans;
    for (int i = 0; i < (1 << (n - 1)); i++) {
        if (is_adjoin(n, i)) {
            continue;
        }
        ans.push_back(i);
    }
    return ans;
}


int get_to_left(int x, vector<int> &enable_bars) {
    int ans = 0;
    for (int i : enable_bars) {
        bool b = (i >> (x - 1)) & 1;
        if (b) ans++;
    }
    return ans;
}

int get_to_down(int x, vector<int> &enable_bars) {
    int ans = 0;
    for (int i : enable_bars) {
        bool b = (i >> (x - 1)) & 1;
        bool c = (i >> x) & 1;
        assert(!(b && c));
        bool d = b || c;

        if (!d) ans++;
    }
    return ans;
}

int get_to_right(int x, vector<int> &enable_bars) {
    int ans = 0;
    for (int i : enable_bars) {
        bool b = (i >> x) & 1;
        if (b) ans++;
    }
    return ans;
}

