            }
            ll to_down = get_to_down(x, enable_bars);
            dp[y + 1][x] += dp[y][x] * to_down;
            if (x != w - 1) {
                ll to_right = get_to_right(x, enable_bars);
                dp[y + 1][x + 1] += dp[y][x] * to_right;
            }
        }
    }

    cout << dp.back()[k - 1] << endl;

}

