using namespace std;
/* typedef */
typedef long long ll;
typedef pair<int, int> pii;
/* constant */
const int INF = 1 << 30;
const ll LINF = 1LL << 50;
const int NIL = -1;
const int MAX = 10000;
const int mod = 1000000007;
const double pi = 3.141592653589;
/* global variables */
/* function */
bool checkBridge(int a) {
    int tmp = a;
    // aを2進数表記したときに1が連続した部分がある -> false
    // else true
    vector<int> b;
    while (tmp > 0) {
        b.push_back(tmp % 2);
        tmp /= 2;
    }
    int l = b.size();
    for (int i = 0; i < (l-1); i++) {
        if (b[i] == 1 && b[i+1] == 1) return false;
    }
    return true;
}
/* main */
int main(){
    int H, W, K;
    cin >> H >> W >> K;
    if (W == 1) {
        cout << 1 << '\n';
        return 0;
    }

    vector<ll> dp1(W), dp2(W);
    // init
    dp1[0] = 1LL;
    // calc
    for (int h = 0; h < H; h++) {
        fill(dp2.begin(), dp2.end(), 0);
        for (int b = 0; b < (1 << (W-1)); b++) { // 橋のかけ方
            // 連続した橋がかかってないか
            if (checkBridge(b) == false) continue;
            // b = 0 0 1 0
            //    | | |-| |
            //    0 1 2 3 4
            for (int i = 0; i < W-1; i++) {
                if ((b>>i) % 2) {
                    dp2[i] += dp1[i+1]; dp2[i] %= mod;
                    dp2[i+1] += dp1[i]; dp2[i+1] %= mod;
                    i++;
                }
                else {
                    dp2[i] += dp1[i]; dp2[i] %= mod;
                }
            }
            // 右端の棒の処理
            if ((b >> (W-2)) % 2 == 0) dp2[W-1] += dp1[W-1], dp2[W-1] %= mod;
        }
        swap(dp1, dp2);
    }
    cout << dp1[K-1] << '\n';
}

