void decA(int w) {
	int n = 1; for (int i = 0; i < w - 1; i++) n *= 2;
	for (int i = 0; i < n; i++) {
		int tmp = i;
		vector<bool> V; // V[i] : i番目のひもと(i+1)番目のひもの間に橋があるかどうか
		for (int j = 0; j < w - 1; j++) {
			V.push_back((tmp & 1));
			tmp = tmp >> 1;
		}

		// 橋が連続してないかチェック
		bool flag = true;
		for (int i = 0; i < V.size()-1 && flag; i++) {
			if (V[i] && V[i + 1]) flag = false;
		}

		if (flag) {
			if (V[0]) A[0][1]++;
			else A[0][0]++;
			for (int j = 1; j < w-1; j++) {
				if (V[j - 1]) A[j][j - 1]++;
				else if (V[j]) A[j][j + 1]++;
				else A[j][j]++;
			}
			if (V[w - 2]) A[w - 1][w - 2]++;
			else A[w - 1][w - 1]++;
		}
	}

	// 確認
	/*
	for (int i = 0; i < w; i++) {
		cout << i << "からの移動  : ";
		for (int j = 0; j < w; j++) cout << A[i][j] << " ";
		cout << endl;
	}
	*/
}

ll before[8];
ll after[8];

void onestep(int w){
	for (int i = 0; i < w; i++) after[i] = 0LL;
	for (int i = 0; i < w; i++) {
		for (int j = 0; j < w; j++) {
			after[i] += before[j] * A[j][i];
			after[i] %= MOD;
		}
	}
	for (int i = 0; i < w; i++) before[i] = after[i];
}

