using namespace std;

int64_t kRem = 1000000007;

int64_t make_diff(vector<int64_t>& left_w, vector<int64_t>& right_w, vector<bool>& select, int p, int w)
{
	if (p == w) {
		FOR(i, 1, w) {
			if (select[i] && select[i + 1]) return 0;
		}

		FOR(i, 1, w) {
			if (select[i]) {
				left_w[i]++;
				right_w[i + 1]++;
			}
		}
		return 1;
	}

	select[p] = true;
	int ret = make_diff(left_w, right_w, select, p + 1, w);
	select[p] = false;
	ret += make_diff(left_w, right_w, select, p + 1, w);
	return ret;
}

int main()
{
	int64_t h, w, k; cin >> h >> w >> k;

	if (w == 1) {
		cout << 1 << endl;
		return 0;
	}

	vector<int64_t> left_w(w + 1);
	vector<int64_t> right_w(w + 1);
	vector<int64_t> no_w(w + 1);

	vector<bool> select(w + 1);
	int all_cases = make_diff(left_w, right_w, select, 1, w);
	FOR(i, 1, w + 1) {
		no_w[i] = all_cases - left_w[i] - right_w[i];
	}

	vector<int64_t> cases(w + 1); // 0 origin
	vector<int64_t> new_cases(w + 1);
	cases[1] = 1;

	FOR(i, 0, h) {
		new_cases[1] = (cases[1] * no_w[1] + cases[2] * right_w[2]) % kRem;
		FOR(j, 2, w) {
			new_cases[j] = (cases[j - 1] * left_w[j -1] + cases[j] * no_w[j] + cases[j + 1] * right_w[j + 1]) % kRem;
		}
		new_cases[w] = (cases[w - 1] * left_w[w - 1] + cases[w] * no_w[w]) % kRem;

		copy(new_cases.begin(), new_cases.end(), cases.begin());
	}

	cout << cases[k] << endl;

	return 0;
}

