LL dfs(int h, int w) {
  //DUMP(h, w);
  //show();
  if (h == H - 1 && w == K) {
    LL cnt = 0;
    REP(i, 0, H) {
      REP(j, 0, W) {
        if (!path[i][j]) ++cnt;
      }
    }
    LL ans = modpow(2, cnt);
    //DUMP(ans);
    return ans;
  } else {
    LL ans = 0;
    VEC<pair<int, int>> d = {{h + 1, w}, {h + 1, w - 1}, {h + 1, w + 1}};
    for (auto v : d) {
      int nh = v.first;
      int nw = v.second;
      if (nh < H && 0 <= nw && nw < W && path[nh][nw] == 0) {
        if (nw == w) {
          auto pre = path;
          path[nh][nw] = 1;
          path[h][w] = 1;
          ans = (ans + dfs(nh, nw)) % M;
          path = pre;
        } else {
          auto pre = path;
          path[h][w] = 1;
          path[nh][nw] = 1;
          if (w - 1 >= 0) {
            path[h][w - 1] = 1;
          }
          if (w + 1 < W) {
            path[h][w + 1] = 1;
          }
          ans = (ans + dfs(nh, nw)) % M;
          path = pre;
        }
      }
    }
    //DUMP(ans);
    return ans;
  }
}

