    if(n!=1)ret *= fib[n-2];
    return n_s[n][l] = ret*fib[W-n];
  }else if(l==1){
    return n_s[n][l] = fib[n-1]*fib[W-n];
  }else{
    if(n!=W)ret *= fib[W-n-1];
    return n_s[n][l] = fib[n-1]*ret;
  }
}

