                next = (next + table[h][w] * pat(0, w - 1) * pat(w + 1, W - 1)) % MOD;
            }
            if (0 <= w - 1) {
                // 左からくる
                next = (next + table[h][w - 1] * pat(0, w - 2) * pat(w + 1, W - 1)) % MOD;
            }
            if (w + 1 < W) {
                // 右からくる
                next = (next + table[h][w + 1] * pat(0, w - 1) * pat(w + 2, W - 1)) % MOD;
            }
            table[h + 1][w] = next;
            if (debug) {
                printf("%d ", next);
            }
        }
        if (debug) {
            printf("\n");
        }
    }

    printf("%d\n", table[H][K-1]);

    return 0;
}

