template<typename T>
class Matrix {
private:
    vector<vector<T>> mat_;

public:
    static Matrix zeros(i64 n) {
        return Matrix(n,n);
    }

    static Matrix eye(i64 n) {
        Matrix res(n,n);
        REP(i, n) {
            res.at(i,i) = T(1);
        }
        return res;
    }

    Matrix(i64 nr, i64 nc) : mat_(nr,vector<T>(nc,T(0))) {}

    i64 nrow() const { return SIZE(mat_);    }
    i64 ncol() const { return SIZE(mat_[0]); }

    T&       at(i64 r, i64 c)       { return mat_[r][c]; }
    const T& at(i64 r, i64 c) const { return mat_[r][c]; }

    const Matrix operator-() const {
        REP(r, nrow()) REP(c, ncol()) {
            at(r,c) = -at(r,c);
        }
    }
    Matrix& operator+=(const Matrix& rhs) {
        REP(r, nrow()) REP(c, ncol()) {
            at(r,c) += rhs.at(r,c);
        }
        return *this;
    }
    Matrix& operator-=(const Matrix& rhs) {
        REP(r, nrow()) REP(c, ncol()) {
            at(r,c) -= rhs.at(r,c);
        }
        return *this;
    }
    Matrix& operator*=(T x) {
        REP(r, nrow()) REP(c, ncol()) {
            at(r,c) *= x;
        }
    }
    Matrix& operator/=(T x) {
        REP(r, nrow()) REP(c, ncol()) {
            at(r,c) /= x;
        }
    }
    Matrix& operator*=(const Matrix& rhs) {
        return *this = *this * rhs;
    }

    // 正方行列であること
    Matrix pow(i64 e) const {
        assert(e >= 0);

        Matrix res = eye(nrow());
        Matrix cur = *this;
        while(e > 0) {
            if(e & 1)
                res *= cur;
            cur *= cur;
            e >>= 1;
        }
        return res;
    }

    friend ostream& operator<<(ostream& out, const Matrix& m) {
        out << '[';
        REP(r, m.nrow()) {
            if(r != 0)
                out << ',';
            out << '[' << m.mat_[r] << ']';
        }
        out << ']';
        return out;
    }
};

template<typename T>
const Matrix<T> operator+(const Matrix<T>& lhs, const Matrix<T>& rhs) {
    return Matrix<T>(lhs) += rhs;
}

template<typename T>
const Matrix<T> operator-(const Matrix<T>& lhs, const Matrix<T>& rhs) {
    return Matrix<T>(lhs) -= rhs;
}

template<typename T>
const Matrix<T> operator*(const Matrix<T>& lhs, T rhs) {
    return Matrix<T>(lhs) *= rhs;
}

template<typename T>
const Matrix<T> operator*(T lhs, const Matrix<T>& rhs) {
    return Matrix<T>(rhs) *= lhs;
}

template<typename T>
const Matrix<T> operator/(const Matrix<T>& lhs, T rhs) {
    return Matrix<T>(lhs) /= rhs;
}

template<typename T>
const Matrix<T> operator*(const Matrix<T>& lhs, const Matrix<T>& rhs) {
    i64 nr = lhs.nrow();
    i64 nc = rhs.ncol();
    i64 m  = lhs.ncol();
    Matrix<T> res(nr,nc);
    REP(r, nr) REP(c, nc) {
        REP(i, m) {
            res.at(r,c) += lhs.at(r,i) * rhs.at(i,c);
        }
    }
    return res;
}

template<typename T>
const vector<T> operator*(const Matrix<T>& lhs, const vector<T>& rhs) {
    i64 nr = lhs.nrow();
    i64 m  = lhs.ncol();
    vector<T> res(m, T(0));
    REP(r, nr) {
        REP(i, m) {
            res[r] += lhs.at(r,i) * rhs[i];
        }
    }
    return res;
}

// F(0) = 0
// F(1) = 1
// F(n) = F(n-1) + F(n-2)
template<size_t N>
ModP* fibonacci() {
    static_assert(N >= 2, "");
    static ModP fib[N];

    fib[0] = 0;
    fib[1] = 1;
    FOR(i, 2, N) {
        fib[i] = fib[i-1] + fib[i-2];
    }
    return fib;
}

i64 H, W;
i64 K;

void solve() {
    const ModP* fib = fibonacci<1000>();

    auto m = Matrix<ModP>::zeros(W);
    // 左
    FOR(i, 1, W) {
        m.at(i-1,i) = fib[i] * fib[W-i];
    }
    DBG(m);
    // 右
    FOR(i, 0, W-1) {
        m.at(i+1,i) = fib[i+1] * fib[W-i-1];
    }
    DBG(m);
    // まっすぐ
    FOR(i, 0, W) {
        m.at(i,i) = fib[i+1] * fib[W-i];
    }
    DBG(m);

    m = m.pow(H);

    // 行列を見れば事足りるが、ベクトルとの乗算のverify用に
    vector<ModP> dp(W, 0);
    dp[0] = 1;
    vector<ModP> v = m * dp;

    ModP ans = v[K];

    // MOD はとった?
    PRINTLN(ans);
}

