long long solve() {
  long long now, cnt;
  dp[0][0] = 1;
  for(int i = 1; i <= h; ++i) {
    for(int j = 0; j < w; ++j) {
      now = 0;
      // from left
      if(j > 0) {
        cnt = 1;
        cnt *= memo[max(0LL, w - 1 - (j + 1))];
        cnt *= memo[max(0, j - 2)];
        cnt %= N;
        now += dp[i - 1][j - 1] * cnt % N;
        now %= N;
      }
      // from right
      if(j < w - 1) {
        cnt = 1;
        cnt *= memo[max(0, j - 1)];
        cnt *= memo[max(0LL, w - 1 - (j + 2))];
        cnt %= N;
        now += dp[i - 1][j + 1] * cnt % N;
        now %= N;
      }
      // go straight
      cnt = 1;
      cnt *= memo[max(0, j - 1)];
      cnt *= memo[max(0LL, w - 1 - (j + 1))];
      now += dp[i - 1][j] * cnt % N;
      now %= N;
      dp[i][j] += now;
      dp[i][j] %= N;
    }
  }
  return dp[h][k - 1];
}

long long calc(long long x) {
  long long ans = 1;
  for(long long i = 0; i <= 32; ++i)
    if(((1LL << i) & x) == (1LL << i)) {
      ans *= memo[i] % N;
      ans %= N;
    }
  return ans;
}

