bool are_valid_horizontal_lines( const int s )
{
	REP( i, 8 )
	{
		if ( ( s & 1 << i ) && ( s & 1 << ( i + 1 ) ) )
		{
			return false;
		}
	}
	return true;
}

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	IN( int, H, W, K );

	static int dp[ 128 ][ 8 ];
	dp[0][0] = 1;

	REP( i, H )
	{
		REP( j, W )
		{
			REP( s, 1 << ( W - 1 ) )
			{
				if ( !are_valid_horizontal_lines( s ) )
				{
					continue;
				}

				if ( j && s & 1 << ( j - 1 ) )
				{
					( dp[ i + 1 ][ j - 1 ] += dp[i][j] ) %= MOD;
				}
				else if ( j + 1 < W && s & 1 << j )
				{
					( dp[ i + 1 ][ j + 1 ] += dp[i][j] ) %= MOD;
				}
				else
				{
					( dp[ i + 1 ][j] += dp[i][j] ) %= MOD;
				}
			}
		}
	}

	cout << dp[H][ K - 1 ] << endl;

	return 0;
}

