		dp[i][1] = (dp[i-1][0]*fib[W-3] + dp[i-1][1]*fib[W-3]+dp[i-1][2])%MOD;
		for(int j=2;j<W-2;j++){
			dp[i][j] = (dp[i-1][j-1]*fib[j-2]*fib[W-j-2] + dp[i-1][j]*fib[j-1]*fib[W-j-2] + dp[i-1][j+1]*fib[j-1]*fib[W-j-3])%MOD;
