int main() {
  int H, W, K;
  cin >> H >> W >> K;
  vector<vector<ll>> com(W, vector<ll>(W));
  for (int bit = 0; bit < (1 << (W - 1)); bit++) {
    int prev = 0;
    bool valid = true;
    for (int i = 0; i < W - 1; i++) {
      if (prev == 1 && ((bit >> i) & 1)) valid = false;
      prev = ((bit >> i) & 1);
    }
    if (!valid) continue;

    for (int i = 0; i < W; i++) {
      int left = ((bit >> (i - 1)) & 1) ? i > 0 : 0;
      int right = ((bit >> i) & 1) ? i < W - 1 : 0;
      if (left == 0 && right == 0) com[i][i]++;
      if (left == 0 && right == 1) com[i][i + 1]++, com[i + 1][i]++;
      // if (left == 1 && right == 0) com[i][i - 1]++, com[i - 1][i]++;
    }
  }

  vector<vector<ll>> dp(H + 1, vector<ll>(W, 0));
  dp[0][0] = 1;
  for (int h = 1; h <= H; h++) {
    for (int w = 0; w < W; w++) {
      if (w < W - 1) {
        dp[h][w] += (dp[h - 1][w + 1] * com[w][w + 1]) % MOD;
      }
      if (w > 0) {
        dp[h][w] += (dp[h - 1][w - 1] * com[w][w - 1]) % MOD;
      }
      dp[h][w] += (dp[h - 1][w] * com[w][w]) % MOD;
      dp[h][w] %= MOD;
    }
  }
  cout << dp[H][K - 1] << endl;
}

