int rec(int height, int pos) {
  if(height == 0) {
    return pos == K;
  }
  if(~dp[height][pos]) return dp[height][pos];
  int ret = 0;
  for(int i = 0; i < (1 << (W - 1)); i++) {
    vector< int > ex;
    for(int j = 0; j < W - 1; j++) {
      if((i >> j) & 1) ex.emplace_back(j);
    }
    auto f = false;
    for(int j = 1; j < ex.size(); j++) {
      if(ex[j - 1] + 1 == ex[j]) f = true;
    }
    if(f) continue;

    int curpos = pos;
    for(int j = 0; j < ex.size(); j++) {
      if(ex[j] == curpos) {
        curpos++;
        break;
      }
      if(ex[j] + 1 == curpos) {
        curpos--;
        break;
      }
    }
    (ret += rec(height - 1, curpos)) %= mod;
  }
  return dp[height][pos] = ret;

}

