long long int pow(long long int a, long long int n){
    long long int ans = 1;
    while(n != 0){
        if(n%2 == 1){
            ans = ans * a % MOD;
            n -= 1;
        }else{
            a = a * a % MOD;
            n /= 2;
        }
    }

    return ans;
}

