// dp[h][w] := 上からh個, 左からw個の点にある場合の数
modint dp[111][11];

signed main() {

  SS(int, H, W, K);

  dp[0][0] = 1;
  REP(i, H) {
    REP(a, 1 << (W - 1)) {
      if (a & (a << 1)) continue;
      REP(j, W) {
        // jから右に移動するとき, 1<<jのbitが立っているかで判断
        if (j != W - 1 && (a & (1 << j))) dp[i + 1][j + 1] += dp[i][j];
        // jから左に移動するとき, 1<<(j-1)のbitが立っているかで判断
        if (j != 0 && (a & (1 << (j - 1)))) dp[i + 1][j - 1] += dp[i][j];
        // 移動しないとき
        if (!(a & (1 << j)) && !(a & (1 << (j - 1)))) dp[i + 1][j] += dp[i][j];
      }
    }
  }

  cout << dp[H][K - 1] << ln;

}

