int get_pattern(int w) {
    if (w < 2) return 1;
    else if (w == 2) return 2;
    else if (w == 3) return 3;
    else {
        int cnt = 1;
        rep(i, w - 1) {
            cnt += get_pattern(w - i - 2);
            cnt %= MOD;
        }
        return cnt;
    }
}

int H, W, K;
vv<int> table;
vv<ll> dp;

int main() {
    cin >> H >> W >> K;
    table = vvec(W, W, 0);
    rep(i, W) {
        rep(j, W) {
            if (abs(i - j) == 1) {
                int itmp = i, jtmp = j;
                if (itmp > jtmp) swap(itmp, jtmp);
                int ret = get_pattern(itmp) * get_pattern(W - jtmp - 1);
                table[i][j] = ret % MOD;
            }
            else if (i == j) {
                int ret = get_pattern(i) * get_pattern(W - j - 1);
                table[i][j] = ret % MOD;
            }
        }
    }

    dp = vvec<ll>(H + 1, W, 0);
    dp[0][0] = 1;

    rep(i, 1, H + 1) {
        rep(j, W) {
            // 左
            if (j > 0) {
                dp[i][j - 1] += dp[i - 1][j] * table[j][j - 1];
                dp[i][j - 1] %= MOD;
            }
            // 直下
            dp[i][j] += dp[i - 1][j] * table[j][j];
            dp[i][j] %= MOD;
            // 右
            if (j < W - 1) {
                dp[i][j + 1] += dp[i - 1][j] * table[j][j + 1];
                dp[i][j + 1] %= MOD;
            }
        }
    }

    write(dp[H][K - 1]);
}

