using namespace std;
const int64_t mod = 1e9 + 7;
unordered_map<int64_t, int64_t> memo;
int H, W, K;
vector<int> pattern(9);

int64_t search(int c, int r) {
  if(r == H) {
    if((c+1) == K) return 1;
    else return 0;
  }
  int64_t key = c * 1000 + r;
  if(memo.count(key)) return memo[key];

  int64_t ret = 0;
  int64_t add1, add2, add3;
  add1 = add2 = add3 = 0;
  int64_t pat1, pat2, pat3;
  pat1 = pat2 = pat3 = 0;
  if(c == 0) {
    add1 = search(c, r + 1);
    pat1 = pattern[max(0, W-2)];
    if(1 < W) {
      add2 = search(c + 1, r + 1);
      pat2 = pattern[max(0, W-3)];
    }
  } else if(c == (W - 1)) {
    add1 = search(c, r + 1);
    pat1 = pattern[max(0, W-2)];
    if(1 < W) {
      add2 = search(c - 1, r + 1);
      pat2 = pattern[max(0, W-3)];
    }
  } else {
    add1 = search(c, r + 1);
    pat1 = (pattern[max(0, c-1)] * pattern[max(0, W - 2 - c)]) % mod;
    if((c+1) < W) {
      add2 = search(c + 1, r + 1);
      pat2 = (pattern[max(0, c-1)] * pattern[max(0, W - 3 - c)]) % mod;
    }
    if(0 <= (c-1)) {
      add3 = search(c - 1, r + 1);
      pat3 = (pattern[max(0, c-2)] * pattern[max(0, W - 2 - c)]) % mod;
    }
  }
  add1 = (add1 * pat1) % mod;
  add2 = (add2 * pat2) % mod;
  add3 = (add3 * pat3) % mod;
  ret = (ret + add1) % mod;
  ret = (ret + add2) % mod;
  ret = (ret + add3) % mod;
  return memo[key] = ret;
}

int64_t search0(int c, int cmax, bool before) {
  if(c == cmax) {
    return 1;
  } else if(c > cmax) {
    return 0;
  }
  int ret = 0;
  if(before) {
    ret += search0(c+1, cmax, false);
  } else {
    ret += search0(c+1, cmax, false);
    ret += search0(c+1, cmax, true);
  }
  return ret;
}

int main(void) {
  ios::sync_with_stdio(false);
  cin >> H >> W >> K;
  rep(i, W) {
    pattern[i] = search0(0, i, false);
    //cout << pattern[i] << endl;
  }
  int64_t answer = search(0, 0);
  cout << answer << endl;
  return 0;
}

