using ull = unsigned long long int;

ull mod = 1000000007;

ull dp[101][8] = {};
ull dp1[8][2] = {};
ull dp2[8] = {};


int main(void) {

	dp1[0][1] = dp1[0][0] = 1;

	for (int i = 0; i < 7; i++) {
		dp1[i + 1][0] += dp1[i][0] + dp1[i][1];
		dp1[i + 1][1] += dp1[i][0];
	}
	for (int i = 0; i < 8; i++) {
		dp2[i] = dp1[i][0] + dp1[i][1];
	}

	int H, W, K;

	cin >> H >> W >> K;



	dp[0][0] = 1;

	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			//pattern same
			if (W - (3 - ((j == 0 || j == W - 1) ? 1 : 0)) <= 0) {
				dp[i + 1][j] += dp[i][j];
			}
			else {
				//左側張り付き
				if (j <= 1) {
					dp[i + 1][j] += dp[i][j] * dp2[W - 3 - j];
				}
				//右側張り付き
				else if (j >= W - 2) {
					dp[i + 1][j] += dp[i][j] * dp2[j - 2];
				}
				else {
					dp[i + 1][j] += dp[i][j] * (dp2[j - 2] + dp2[W - j - 3]);
				}
			}
			dp[i + 1][j] %= mod;

			//pattern right
			if (j + 1 != W) {

				if (W - (4 - ((j == 0 || j + 1 == W - 1) ? 1 : 0)) <= 0) {
					dp[i + 1][j + 1] += dp[i][j];
				}
				else {
					//左側張り付き
					if (j <= 1) {
						dp[i + 1][j + 1] += dp[i][j] * dp2[W - 4 - j];
					}
					//右側張り付き
					else if (j >= W - 3) {
						dp[i + 1][j + 1] += dp[i][j] * dp2[j - 2];
					}
					else {
						dp[i + 1][j + 1] += dp[i][j] * (dp2[j - 2] + dp2[W - j - 4]);
					}
				}
				dp[i + 1][j + 1] %= mod;
			}
			//pattern left
			if (j != 0) {

				if (W - (4 - ((j - 1 == 0 || j == W - 1) ? 1 : 0)) <= 0) {
					dp[i + 1][j - 1] += dp[i][j];
				}
				else {
					//左側張り付き
					if (j <= 2) {
						dp[i + 1][j - 1] += dp[i][j] * dp2[W - 3 - j];
					}
					//右側張り付き
					else if (j >= W - 2) {
						dp[i + 1][j - 1] += dp[i][j] * dp2[j - 3];
					}
					else {
						dp[i + 1][j - 1] += dp[i][j] * (dp2[j - 3] + dp2[W - j - 3]);
					}
				}
				dp[i + 1][j - 1] %= mod;
			}
		}
	}

	cout << dp[H][K - 1] << endl;

	return 0;
}

