#include <iostream>
using namespace std;

using ll = long long;

const ll MOD = 1e9+7;

int main() {
   // 入力
   int H, W, K;
   cin >> H >> W >> K;

   // DPテーブルを初期化する
   ll dp[H+1][W];
   fill(dp[0], dp[H+1], 0);
   dp[0][0] = 1;

   for (int h = 0; h < H; h++) { // それぞれの高さについてループを回す
      for (int mask = 0; mask < (1<<(W-1)); ++mask) { // bit全探索のループ

         // 横線が隣り合っていないかチェック
         bool ok = true;
         for (int i = 0; i < W-2; ++i) {
            // これで末尾が11のときにはじくことが出来る
           if (((mask >> i) & 3) == 3) ok = false;
         }
         // 隣り合っていたらこの先の処理を飛ばす
         if (!ok) continue;

         for (int i = 0; i < W; i++) {
            // 横線を見つける
            if ((i < W) && ((mask >> (W - (i+2)))&1)) { // 右と左の遷移
               // 右への遷移と左への遷移を一気に処理する
               dp[h+1][i+1] += dp[h][i];
               dp[h+1][i+1] %= MOD;
               dp[h+1][i] += dp[h][i+1];
               dp[h+1][i] %= MOD;
               i++;
            } else { // まっすぐの遷移:
               dp[h+1][i] += dp[h][i];
               dp[h+1][i] %= MOD;
            }
         }
      }
   }

   cout << dp[H][K-1] << endl;

   return 0;
}

