}

void solve() {
	vector<Modint> wdp(W+1,Modint());
	wdp[0]=1;
	wdp[1]=2;
	for(ll i=2;i<=W;i++)wdp[i]=wdp[i-1]+wdp[i-2];

	vector<vector<Modint>> dp(H+1,vector<Modint>(W,Modint()));
	dp[0][0]=1;

	Modint a(1);

	rep(i,H){
		rep(j,W){
			if(j!=0){
				//左から移動
				if(j==1)dp[i+1][j]+=dp[i][j-1]*(W-3<0?a:wdp[W-3]);
				else dp[i+1][j]+=dp[i][j-1]*(j-2<0?a:wdp[j-2])*(W-j-2<0?a:wdp[W-j-2]);
			}
			if(j!=W-1){
				//右から移動
				if(j==W-2)dp[i+1][j]+=dp[i][j+1]*(W-3<0?a:wdp[W-3]);
				else dp[i+1][j]+=dp[i][j+1]*(j-1<0?a:wdp[j-1])*(W-j-3<0?a:wdp[W-j-3]);
			}
			//まっすぐ移動
			if(j==0||j==W-1)dp[i+1][j]+=dp[i][j]*(W-2<0?a:wdp[W-2]);
			else dp[i+1][j]+=dp[i][j]*(j-1<0?a:wdp[j-1])*(W-j-2<0?a:wdp[W-j-2]);
		}
	}
