// dp[i][j]: i列目を通過した直後，左からj番目の縦棒にいる場合の数
ll dp[102][11] = {};

void solve()
{
  for (int i = 0; i < H; ++i)
  {
    for (int j = 0; j < W; ++j)
    {
      // 2^(W-1) 個探索
      // 2進で1が連続しないようにする
      for (int k = 0; k < (1 << (W - 1)); ++k)
      {
        bool flag = true;
        //端点を共有しない制約
        for (int l = 0; l < W - 2; ++l)
        {
          if (((k >> l) & 1) && ((k >> (l + 1)) & 1))
          {
            flag = false;
          }
        }
        // 全探索
        // 全ての横棒の置き方
        if (flag)
        {
          // 左方向に行ける
          if (j >= 1 && ((k >> (j - 1)) & 1))
          {
            dp[i + 1][j - 1] += dp[i][j];
            dp[i + 1][j - 1] %= MOD;
          }
          // 右方向に行ける
          else if (j <= (W - 2) && ((k >> j) & 1))
          {
            dp[i + 1][j + 1] += dp[i][j];
            dp[i + 1][j + 1] %= MOD;
          }
          // 下に行く
          else
          {
            dp[i + 1][j] += dp[i][j];
            dp[i + 1][j] %= MOD;
          }
        }
      }
    }
  }
}

