		dp[i][W - 1] %= MOD;
		for (int j = 1; j < W - 1; ++j)
		{
			dp[i][j] = dp[i - 1][j - 1] * lines[max(j - 2, 0)] * lines[max(W - j - 2, 0)];
			dp[i][j] += dp[i - 1][j] * lines[max(j - 1, 0)] * lines[max(W - j - 2, 0)];
			dp[i][j] += dp[i - 1][j + 1] * lines[max(j - 1, 0)] * lines[max(W - j - 3, 0)];
			dp[i][j] %= MOD;
		}
	}
	cout << dp[H][K] << endl;
}
