                bool ok = true;
                REP(k, 0, W - 2) if ((bit & (1 << k)) && (bit & (1 << (k + 1)))) ok = false;
                if (!ok) continue;

                int nj = j;
                if (bit & (1 << j)) nj = j + 1;
                else if (j > 0 && (bit & (1 << (j - 1)))) nj = j - 1;

