using namespace std;
typedef long long ll;


vector<vector<int> > V;

ll ami[102][9];
static const ll mod = 1000000007;

int main() {

    int H, W, K;
    cin >> H >> W >> K;

    vector<int> init;
    init.push_back(1);
    V.push_back(init);

    int cnt = 1;

    while (cnt < W) {

        vector<vector<int> > temp;

        for (int i = 0; i < V.size(); i++) {
            vector<int> v = V[i];
            v.push_back(cnt+1);

            temp.push_back(v);
            if (v[cnt-1] != cnt) {
                continue;
            }
            else {
                swap(v[cnt], v[cnt-1]);
                temp.push_back(v);
            }
        }
        cnt++;
        V = temp;
    }
    /*
    for (int i = 0; i < V.size(); i++) {
        for (int j = 0; j < V[i].size(); j++) {
            cout << V[i][j] << ' ';
        }
        cout << '\n';
    }
    */

    ami[0][1] = 1;
    for (int h = 0; h < H; h++) {

        for (int w = 1; w <= W; w++) {
            if (ami[h][w] == 0)
                continue;
            for (int i = 0; i < V.size(); i++) {
                ami[h+1][V[i][w-1]] += ami[h][w];
                ami[h+1][V[i][w-1]] %= mod;
            }
        }
    }

    cout << ami[H][K] << '\n';

}

