int main(int argc, char const *argv[])
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll H, W, K;
    cin >> H >> W >> K;

    DVector dp(H + 1, vector<ll>(W + 1, 0));
    dp[0][1] = 1;
    // dp[0][] が start. dp[1][] は 階層１での移動を終えた結果を表す

    ll num_of_bridge = W - 1;
    bool can_process;
    FOR_EQ(now_level, 1, H){
        // 線の引かれ方のパターン 間なので W - 1
        // 左から決定していく。線を引いたならば、その右側に線は引かれない
        // パターンの加算
        // 左端(col = 1)と右端(col = W)の時は気をつけよう
        for(int bit = 0; bit < (1 << num_of_bridge); bit++){
            can_process = true;
            // 連続して橋がある場合は処理しない
            for(int i = 0; i < num_of_bridge - 1; i++){
                if(((bit >> i) & 1) && (bit >> (i + 1) & 1)){
                    can_process = false;
                    break;
                }
            }

            if(can_process){
                // cout << bitset<10>(bit) << endl;
                // あみだの線に対して、両サイドを確認するべき
                for(int line = 1; line <= W; line++){
                    // line の左右に対する、bit の shift量
                    ll left = line - 2, right = line - 1;
                    ll origin = dp[now_level - 1][line];    // 対象
                    if( line == 1 ){ // 左端
                        if( (bit >> right) & 1){ // 橋がある
                            dp[now_level][line + 1] += origin;
                            dp[now_level][line + 1] %= MOD;
                        }else{
                            dp[now_level][line] += origin;
                            dp[now_level][line] %= MOD;
                        }
                    }else if( line == W ){ // 右端
                        if( (bit >> left) & 1){ // 橋がある
                            dp[now_level][line - 1] += origin;
                            dp[now_level][line - 1] %= MOD;
                        }else{
                            dp[now_level][line] += origin;
                            dp[now_level][line] %= MOD;
                        }
                    }else{   // それ以外
                        // 両方が立つことはエラー案件
                        if( (bit >> left) & 1){ // 左に橋がある
                            dp[now_level][line - 1] += origin;
                            dp[now_level][line - 1] %= MOD;
                        }else if( (bit >> right) & 1){ // 右に橋がある
                            dp[now_level][line + 1] += origin;
                            dp[now_level][line + 1] %= MOD;
                        }else{
                            dp[now_level][line] += origin;
                            dp[now_level][line] %= MOD;
                        }
                    }
                    //DEBUG_VARIABLE(line);
                    //DEBUG_VARIABLE(dp[now_level][line]);
                }
            }
            //cout << endl;
        }
    }
    cout << dp[H][K] << endl;
    return 0;
}

