//最小公倍数(Least Common Multiple)
ll lcm(ll m, ll n){
    //引数に0がある場合は0を返す
    if(m == 0 || n == 0)    return 0;

    //lcm = m * n / gcd(m, n)
    return ((m / gcd(m, n)) * n);
}

// 素因数分解を高速にやるためにエラトステネスの篩を活用する
// エラトステネスの篩
void Eratosthenes(ll n){
    isprime.resize(n + 1, true);    // pisrime の添え字と見たい数は一致させる
    min_factor.resize(n + 1, -1);  // min_factor[num] := numを割り切る最小の素数を格納

    isprime[0] = isprime[1] = false;
    min_factor[0] = 0, min_factor[1] = 1;
    // num を p = min_factor[ num ] で割れるだけ割る」というのを num = 1 となるまで繰り返す
    // min_factorが必要でない。 prime に素数の実態がなくてよい場合
    // iの上限はsqrt(n)まで　素数かどうかの判定はisprimeで可能
    for(int i = 2; i < n; i++){   // 素数
        if(!isprime[i]) continue;
        primes.push_back(i);
        min_factor[i] = i;
        for(int j = i * 2; j <= n; j += i){   // 素数の倍数を省く
            isprime[j] = false;
            if(min_factor[j] == -1) min_factor[i] = 1;
        }
    }
}
// 素因数分解 firstは数。secondは指数。
// vector< vector<pair<ll, ll>> >    map;
// map[i] = prime_factorization
Vec_Pair prime_factorization(ll n){
    Vec_Pair res;
    Eratosthenes(n);

    bool flg = false;
    if(n < 2){  // error処理
        cout << "Error" << endl;
        return res;
    }

    // example
    // n = 120
    // min_factor[120] = 2 → 120 / 2 をし続ける → n = 15
    // min_factor[15] = 3 → 15 / 3 をし続ける → n = 5
    // min_factor[5] = 5 → 5 / 5 をし続ける → n = 1  終わり

    while(n != 1){
        int prime = min_factor[n];
        int cnt = 0;
        while(min_factor[n] == prime){
            cnt++;
            n /= prime;
        }
        res.push_back(make_pair(prime, cnt));
    }
    return res;
}

