      REP(j, W - 2) {
        if(((k >> j) & 1) && ((k >> (j + 1)) & 1)) {
          ok = false;
          break;
        }
      }
      if(ok) {
        REP(j, W) {
          if(j >= 1 && (k >> (j - 1)) & 1) {
            dp[i + 1][j - 1] += dp[i][j];
            dp[i + 1][j - 1] %= mod;
          } else if(j <= W - 2 && (k >> j) & 1) {
            dp[i + 1][j + 1] += dp[i][j];
            dp[i + 1][j + 1] %= mod;
          } else {
            dp[i + 1][j] += dp[i][j];
            dp[i + 1][j] %= mod;
          }
        }
      }
    }
  }
  cout << dp[H][K -1] << endl;
  return 0;
}

