int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m, K;
    cin >> n >> m >> K;

    if (m == 1) {
        if (K == 1) {
            cout << 1 << '\n';
        } else {
            cout << 0 << '\n';
        }
        return 0;
    }

    const long long MOD = 1000000007;

    int M = 1 << (m - 1);

    vector<long long> dp(m, 0);
    dp[0] = 1;

    auto ndp = dp;
    for (int _ = 0; _ < n; ++_) {
        fill(ndp.begin(), ndp.end(), 0);
        for (int i = 0; i < m; ++i) {
            if (dp[i] == 0) {
                continue;
            }
            for (int j = 0; j < M; ++j) {
                if (j & (j >> 1)) {
                    continue;
                }

                int ni = -1;
                for (int k = -1; k < 1; ++k) {
                    int x = i + k;
                    if (x >= 0 && (j & (1 << x))) {
                        assert(ni == -1);
                        ni = k < 0 ? i - 1 : i + 1;
                    }
                }
                if (ni == -1) {
                    ni = i;
                }
                (ndp[ni] += dp[i]) %= MOD;
            }
        }
        swap(ndp, dp);
    }

    cout << dp[K - 1] << '\n';

    return 0;
}

