constexpr lint mod=1e9+7;

int main()
{
	int H,W,K;
	cin >> H >> W >> K;

	lint dp[110][10]={};
	dp[0][1]=1;

	for(int h=1;h<=H;h++)
	{
		for(int bit=0;bit<pow(2,W-1);bit++)
		{
			int tbit=bit;
			int bits[10]={};
			bool con=false;
			for(int j=1;j<=W-1;j++)
			{
				bits[j]=tbit%2;
				tbit/=2;
				if(bits[j-1]==1 && bits[j]==1)con=true;
			}
			if(con)continue;

			for(int j=1;j<=W;j++)
			{
				if(bits[j-1]==0 && bits[j]==0)
					dp[h][j]+=dp[h-1][j];
				else if(bits[j-1]==1)
					dp[h][j]+=dp[h-1][j-1];
				else if(bits[j]==1)
					dp[h][j]+=dp[h-1][j+1];
				dp[h][j]%=mod;
			}
		}
	}

	cout << dp[H][K] << endl;
	return 0;
}

