int dp[808][10];

int calc(int x) {
  int cnt = 0;
  int l = x - 1;
  int r = x + 1;
  rep(i, 1LL<<(w-1LL)) {
    vector<int> v;
    bool ok = false;
    rep(j, w-1) {
      if (i>>j & 1) {
        if (j == x) ok = true;
        v.push_back(j);
      }
    }
    if (!ok) continue;
    rep(j, v.size()) {
      if (v[j] == l || v[j] == r) ok = false;
    }
    if (!ok) continue;
    rep(j, max(0LL, v.size() - 1LL)) {
      if (v[j] + 1 == v[j + 1]) ok = false;
    }
    if (ok) cnt++;
  }
  return cnt;
}

int calc2(int l, int r) {
  int cnt = 0;
  rep(i, 1LL<<(w-1LL)) {
    bool ok = true;
    vector<int> v;
    rep(j, w-1) {
      if (i>>j & 1) {
        if (j == l || j == r) ok = false;
        v.push_back(j);
      }
    }
    if (!ok) continue;
    rep(j, max(0LL, v.size() - 1LL)) {
      if (v[j] + 1 == v[j + 1]) ok = false;
    }
    if (!ok) continue;
    cnt++;
  }
  return cnt;
}

