            dp[i+1][j]=(dp[i+1][j]+dp[i][j]*mul[j]*mul[w-1-j]%MOD)%MOD;
            if(j>0)dp[i+1][j-1]=(dp[i+1][j-1]+dp[i][j]*mul[j-1]*mul[w-1-j]%MOD)%MOD;
            if(j<w-1)dp[i+1][j+1]=(dp[i+1][j+1]+dp[i][j]*mul[j]*mul[w-1-(j+1)]%MOD)%MOD;
        }
    }
    cout<<dp[h][k-1]<<endl;
    return 0;
}

