#include <bits/stdc++.h>
#define rep(i, n) for(ll i=0; i<n; i++)
using namespace std;
typedef long long ll;

const ll MOD = 1000000007;
ll dp[101][9];

int main() {
    ll H, W, K;
    cin >> H >> W >> K;

    //dp[h][x]は、上からh段目にいるとき、左からx番目の縦棒にいる場合の数を
    //記録するdpテーブル。始点は左上端であるため、dp[0][0]のみを1、そのほかを0で初期化している。
    dp[0][0] = 1;
    for(ll h=0; h<H; h++) {
        for(ll x=0; x<W; x++) {

            //横棒を引く位置(左点のある縦棒の番号)をbit列を用いて全探索
            //横棒を引く高さは上からh+1行目
            for(int i=0; i<(1<<(W-1)); i++) {

                //h+1段目に横棒を引く位置を配列に記録する。
                //例として、iがビット列で0100101なら、下のfor文によって
                //{0, 3, 5}という配列が生成される。
                vector<int> vec;
                for(int j=0; j<W-1; j++) {
                    if((i>>j) & 1) vec.push_back(j);
                }


                bool f = false;
                ll pre = -2;
                set<int> st;
                ll len = (ll)vec.size();

                //上で生成した配列によって、正しく横棒が引かれるか検証する。
                for(int k=0; k<len; k++) {
                    if(vec[k] == pre+1) {

                        //横棒の端点は共有できないので、vecの要素が連続していたら
                         //スキップフラグを立てて離脱。
                        f = true;
                        break;
                    } else {

                        //正しく配置された横棒であれば、左端のある横棒の番号を
                        //setに挿入する。これは、set::count関数によって横棒の
                        //有無を簡単に把握できるため。
                        st.insert(vec[k]);
                        pre = vec[k];
                    }
                }

                //fがtrueのときいずれかの端点が共有されているので無効
                if(f) continue;

                //dpテーブルの更新操作
                if(st.count(x-1)) {
                    //x-1を左端とする横棒が引かれるということは、現在いる位置(x)から
                    //左に移動するという事だから、現在までの場合の数を移動先の場合の数に足し込む。
                    dp[h+1][x-1] = (dp[h+1][x-1] + dp[h][x]) % MOD;
                } else if(st.count(x)) {
                    //xを左端とする横棒が引かれるなら、移動先はx+1
                    dp[h+1][x+1] = (dp[h+1][x+1] + dp[h][x]) % MOD;
                } else {
                    //x, x-1のどちらからも横棒が引かれない場合、移動先はそのままで段数だけ下がる。
                    dp[h+1][x] = (dp[h+1][x] + dp[h][x]) % MOD;
                }
            }       
        }
    }

    //dpのインデックスはゼロスタートであることに注意する。
    //最後の段数はH-1ではなくH(問題の図ではH+1段目)
    cout << dp[H][K-1] << endl;
    return 0;
}

