                    if(k == 0){
                        dp[i+1][k] += dp[i][k];
                        dp[i+1][k] %= MOD;
                        continue;
                    }
                    if(k != 0 && !BIT.test(k-1)){
                        dp[i+1][k] += dp[i][k];
                        dp[i+1][k] %= MOD;
                    }
                }
                if(k == W-2 && !BIT.test(k)){
                    dp[i+1][W-1] += dp[i][W-1];
                    dp[i+1][W-1] %= MOD;
                }
            }
        }
    }
    cout << dp[H][K-1] << endl;
}

