/* struct for mod Calculation*/
struct mint {
    ll x;
    mint(ll x = 0):x((x % mod + mod) % mod) {}
    mint operator-() const { return mint(-x); }
    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod - 2);
    }
    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }
};
/* global variables */
int H, W, K;
vector<vector<ll> > lines;
vector<vector<mint> > dp;
/* function */
void makeLines() {
    int upper = 1 << (W - 1);
    vector<ll> tmp(W - 1);
    for (int b = 0; b < upper; b++) {
        for (int i = 0; i < W - 1; i++) tmp[i] = b >> i & 1;
        bool canLine = true;
        for (int i = 0; i < W - 2; i++) {
            if (tmp[i] + tmp [i + 1] == 2) {
                canLine = false;
                break;
            }
        }
        if (canLine) lines.push_back(tmp);
    }
}
void calcDPTable() {
    dp.assign(H + 1, vector<mint>(W));
    dp[0][0] = 1;
    for (int i = 0; i < H; i++) {
        for (vector<ll> line : lines) {
            for (int j = 0; j < W; j++) {
                if (j > 0 && line[j - 1]) { dp[i + 1][j - 1] += dp[i][j]; }
                else if (j < W && line[j]) { dp[i + 1][j + 1] += dp[i][j]; }
                else { dp[i + 1][j] += dp[i][j]; }
            }
        }
    }
}

void calcAns() { cout << dp[H][K - 1].x << '\n'; }
/* main */
int main(){
    cin >> H >> W >> K;
    if (W == 1) { cout << 1 << '\n'; return 0; }
    makeLines();
    calcDPTable();
    calcAns();
}

