	dp[i][j] += dp[i-1][j+1] * comb[max(0,j-2)] * comb[max(0,w-j-2)] % mod;
      }
      dp[i][j] %= mod;
    }
  }

  cout<<dp[h][k]%mod<<endl;
  return 0;
}

