using namespace std;
using ll = long long;
int mod = 1000000007;

ll calc(ll l, ll r){
    if(l >= r) return 1;
    r -= l;
    ll dp[2][r+1];
    dp[0][0] = 1; dp[1][0] = 0;
    for(int i = 1; i <= r; i++){
        dp[0][i] = dp[0][i-1] + dp[1][i-1];
        dp[1][i] = dp[0][i-1];
    }
    return dp[0][r] + dp[1][r];
}

int main(void){
    int H, W, K; cin >> H >> W >> K;
    ll dp[H+1][W]; rep(i, H+1) rep(j, W) dp[i][j] = 0;
    K--;
    dp[0][0] = 1;
    if(W >= 3){
        for(int i = 1; i <= H; i++){
            for(int j = 0; j < W; j++){
                //自分の場所とは無関係な位置に線が引けることを忘れない
                //自分の左にはj本、右にはW-1-j本の線がある
                if(j == 0){
                    dp[i][j] = dp[i-1][0]*calc(1, W-1) + dp[i-1][1]*calc(2, W-1);
                }
                else if(j == W-1){
                    dp[i][j] = dp[i-1][W-1]*calc(0, W-2) + dp[i-1][W-2]*calc(0, W-3);
                }
                else if(j == 1){
                    //右にW-2本 左に1本
                    dp[i][j] = dp[i-1][j-1]*calc(2, W-1) + dp[i-1][j]*calc(2, W-1) + dp[i-1][j+1]*calc(3, W-1);
                }
                else if(j == W-2){
                    dp[i][j] = dp[i-1][j-1]*calc(0, W-4) + dp[i-1][j]*calc(0, W-3) + dp[i-1][j+1]*calc(0, W-3);
                }
                else{
                    //右にW-j-1本 左にj本
                    dp[i][j] = dp[i-1][j-1]*calc(0, j-2)*calc(j+1, W-1) + dp[i-1][j]*calc(0, j-1)*calc(j+1, W-1) + dp[i-1][j+1]*calc(0, j-1)*calc(j+2, W-1);
                }
                dp[i][j] %= mod;
            }
        }
    }
    else if(W == 1){
        dp[H][0] = 1;
    }
    else{
        for(int i = 1; i <= H; i++){
            dp[i][0] = (dp[i-1][0] + dp[i-1][1]) % mod;
            dp[i][1] = (dp[i-1][0] + dp[i-1][1]) % mod;
        }
    }

    cout << dp[H][K] << endl;
    return 0;
}

