			NN[W-1]++;
		}

		//それ以外のケース
		for (int ii = 1; ii < W-1; ++ii){
			if (!bs[ii-1] && !bs[ii]){
				NN[ii]++;
			} else if (bs[ii-1]) {
				YN[ii]++;
			} else {
				NY[ii]++;
			}
		}
	}

	//計算
	vector<vector<ll>> dp(H+1, vector <ll> (W));
	dp[0][0] = 1;
	for (int y = 0; y < H; ++y){
		for (int x = 0; x < W; ++x){
			dp[y+1][x] = (dp[y+1][x] + dp[y][x] * NN[x]) % MOD;
			if (x-1 >= 0){
				dp[y+1][x] = (dp[y+1][x] + dp[y][x-1] * YN[x]) % MOD;
			}
			if (x+1 < W){
				dp[y+1][x] = (dp[y+1][x] + dp[y][x+1] * NY[x]) % MOD;
			}			
		}
	}

	cout << dp[H][K] << "\n";

	return 0;
}

