const ll mod = 1000000007;

int f(ll h, ll w){
    if(h == 0){
        if(w == 1) return 1;
        else return 0;
    }
    if((h < 0) || (h > H + 1) || (w < 1) || (w > W)) return 0;
    if(h == H + 1) return f(h-1, w)%mod;
    ll X = 0;
    ll Y = 0;
    ll Z = 0;
    for(ll bit = 0; bit < (1<<(W-1)); bit++){
        bool isNotNeibour = true;
        for(ll l = 0; l < (W - 2); l++){
            if((bit & (1 << l)) && (bit & (1 << (l + 1)))){
                isNotNeibour = false;
                break;

            }
        }
        if(isNotNeibour){
            if(bit & (1 << (w-2))){
                Y += 1; 
            }else if(bit & (1 << (w-1))){
                Z += 1; 
            }else{
                X += 1; 
            }
        }
    }
    return (X * f(h-1, w)) % mod + (Y * f(h-1, w-1)) % mod + (Z * f(h-1, w+1)) % mod;

}
