llong dp(int now, int where){
	cerr << now << " " << where << endl;
	if(now == H)
		if(where == K-1)
			return 1;
		else
			return 0;

	if(memo[now][where] != -1)
		return memo[now][where];

	llong ret = dp(now+1,where)*many[where][1]%mod;
	if(where < W)
		(ret += dp(now+1,where+1)*many[where][2]) %= mod;
	if(where > 0)
		(ret += dp(now+1,where-1)*many[where][0]) %= mod;

	return memo[now][where] = ret;
}

void getNext(){
	many.resize(W, vector<llong>(3, 0));
	for(int i = 0; i < 1<<(W-1); i++){
		int cp = i;
		bitset<9> bs(i);

		bool check = false;
		for(int i = 0; i < (W-1); i++){
			if(bs.test(i)&bs.test(i+1))
				check = true;
		}
		if(check)
			continue;

		for(int i = 0; i < W; i++){
			if(i == 0){
				if(bs.test(i))
					many[i][2]++;
				else
					many[i][1]++;
			}else if(i == W-1){
				if(bs.test(i-1))
					many[i][0]++;
				else
					many[i][1]++;
			}else{
				if(bs.test(i-1))
					many[i][0]++;
				else if(bs.test(i))
					many[i][2]++;
				else
					many[i][1]++;
			}
		}
	}
}

