const int mod = 1000000007;
struct mint {
	ll x; // typedef long long ll;
	mint(ll x = 0) :x((x%mod + mod) % mod) {}
	mint operator-() const { return mint(-x); }
	mint& operator+=(const mint a) {
		if ((x += a.x) >= mod) x -= mod;
		return *this;
	}
	mint& operator-=(const mint a) {
		if ((x += mod - a.x) >= mod) x -= mod;
		return *this;
	}
	mint& operator*=(const mint a) { (x *= a.x) %= mod; return *this; }
	mint operator+(const mint a) const { return mint(*this) += a; }
	mint operator-(const mint a) const { return mint(*this) -= a; }
	mint operator*(const mint a) const { return mint(*this) *= a; }
	mint pow(ll t) const {
		if (!t) return 1;
		mint a = pow(t >> 1);
		a *= a;
		if (t & 1) a *= *this;
		return a;
	}

	// for prime mod
	mint inv() const { return pow(mod - 2); }
	mint& operator/=(const mint a) { return *this *= a.inv(); }
	mint operator/(const mint a) const { return mint(*this) /= a; }
};
istream& operator>>(istream& is, const mint& a) { return is >> a.x; }
ostream& operator<<(ostream& os, const mint& a) { return os << a.x; }
mint dp[101][8];
int main() {
	int H, W , K;
	cin >> H >> W >> K;

	vector<mint> memo(W);
	memo[0] = 1;
	mint x = 0;//引く
	mint y = 1;//惹かない
	for (int n = 1;n<W;++n) {
		memo[n] = x + y;
		mint tmp = x;
		x = y;
		y = tmp + y;
	}

	dp[0][0] = 1;
	for (int n = 0;n<H;++n) {
		for (int m = 0;m<W;++m) {
			if (0 != m) {
				dp[n + 1][m - 1] += dp[n][m]*memo[m-1]*memo[W-m-1];
			}
			dp[n + 1][m] += dp[n][m]*memo[m]*memo[W-1-m];
			if (W - 1!= m) {
				dp[n + 1][m + 1] += dp[n][m]*memo[m]*memo[W-m-2];
			}
		}
	}
	cout << dp[H][K-1]<<endl;
	return 0;
}

