ll num[10][10], dp[101][10];

int main() {
    int H, W, K;
    cin >> H >> W >> K;

    for (int b=0; b<(1<<(W-1)); ++b) {
        bool ok = true;
        for (int i=0; i<W-2; ++i) {
            if (nth_bit(b, i) and nth_bit(b, i+1)) {
                ok = false;
                break;
            }
        }

        if (!ok) continue;

        vector<int> P(W);
        for (int i=0; i<W; ++i) P[i] = i;
        for (int i=0; i<W-1; ++i) {
            if (nth_bit(b, i)) swap(P[i], P[i+1]);
        }
        for (int i=0; i<W; ++i) num[i][P[i]]++;
    }

    dp[0][0] = 1;
    for (int i=0; i<H; ++i) {
        for (int j=0; j<W; ++j) {
            for (int k=0; k<W; ++k) {
                add(dp[i+1][k], dp[i][j] * num[j][k] % mod);
            }
        }
    }

    cout << dp[H][K-1] << endl;
    return 0;
}

