VL prime_decomposition(ll n) {
	ll i = 2;
	VL table{};
	while (i * i <= n) {
		while (n % i == 0) {
			n /= i;
			table.emplace_back(i);
		}
		++i;
	}
	if (n > 1) {
		table.emplace_back(n);
		return table;
	}
}

int main() {
	ll h, w, k;
	cin >> h >> w >> k;

	VVL dp = VVL(h + 1, VL(w));
	dp[0][0] = 1;
	FOR(i, 1, h + 1) {
		REP(j, w) {
			ll sum = 0;
			ll e = w - 3;
			if (j == 0) { ++e; }
			if (j == w - 1) { ++e; }
			sum += dp[i - 1][j] * pow(2, e);

			if (j > 0) {
				e = w - 4;
				if (j == 1) { ++e; }
				if (j == w - 1) { ++e; }
				sum += dp[i - 1][j - 1] * pow(2, e);
			}
			if (j < w - 1) {
				e = w - 4;
				if (j == 0) { ++e; }
				if (j == w - 2) { ++e; }
				sum += dp[i - 1][j + 1] * pow(2, e);
			}
			sum %= MOD;
			dp[i][j] = sum;
		}
	}
	cout << dp[h][k - 1] << endl;
}

