#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

int main() {
	cin.tie(0);
    ios::sync_with_stdio(false);

    ll mod = pow(10, 9) + 7;

    ll H, W, K;
    cin >> H >> W >> K;
    K--;

    vector<vector<ll> > dp(H + 1, vector<ll>(W, 0));

    vector<ll> t(W);
    vector<ll> y(W - 1);

    for(int i = 0; i < W; i++) {
        for (int bit = 0; bit < (1 << (W - 1)); bit++) {
            vector<ll> S;
            for (ll j = 0; j < (W - 1); j++) {
                if (bit & (1 << j)) {
                    S.push_back(j);
                }
            }

            bool checker = false;
            for(int j = 0; j < S.size(); j++) {
                if(S[j] == i || S[j] == i - 1) {
                    checker = true;
                    break;
                }
                if(j > 0) {
                    if(S[j] - 1 == S[j - 1]) {
                        checker = true;
                        break;
                    }
                }
            }
            if(checker) continue;
            t[i]++;
        }
    }

    for(int i = 0; i < W - 1; i++) {
        for (int bit = 0; bit < (1 << (W - 1)); bit++) {
            vector<int> S;
            for (int j = 0; j < (W - 1); j++) {
                if (bit & (1 << j)) {
                    S.push_back(j);
                }
            }

            bool checker = false;
            bool flag = true;

            for(int j = 0; j < S.size(); j++) {

                if(S[j] == i) flag = false;
                if(j > 0) {
                    if(S[j] - 1 == S[j - 1]) {
                        checker = true;
                        break;
                    }
                }
            }
            if(checker || flag) continue;
            y[i]++;
        }
    }

    dp[0][0] = 1;

    for(int i = 0; i < H; i++) {
        for(int j = 0; j < W; j++) {
            if(dp[i][j] == 0) continue;

            if(j > 0) {
                ll x = dp[i][j] * y[j - 1];
                x %= mod;
                dp[i + 1][j - 1] += x;
                dp[i + 1][j - 1] %= mod;
            }
            if(j < W - 1) {
                ll x = dp[i][j] * y[j];
                x %= mod;
                dp[i + 1][j + 1] += x;
                dp[i + 1][j + 1] %= mod;
            }
            ll x = dp[i][j] * t[j];
            x %= mod;
            dp[i + 1][j] += x;
            dp[i + 1][j] %= mod;
        }
    }
/*
    for(int i = 0; i < W; i++) {
        cerr << dp[H][i] << endl;
    }
*/
    cout << dp[H][K] << endl;
}

