							dp[i + 1][k] =(dp[i+1][k]+ dp[i][k])%mod;
						}
						else if (j >> k & 1) {
							dp[i + 1][k + 1] =(dp[i+1][k+1]+ dp[i][k])%mod;
						}
						else {
							dp[i + 1][k - 1] =(dp[i+1][k-1]+ dp[i][k])%mod;
						}
					}
				}
