/*
 * S
 * |-| |
 * | |-|
 *     K
 *
 * S
 * | | |   | |-|
 * K
 *
 * |0|1|2|3|4|5|6|
 * 縦棒の間に横棒を入れる場所はは最大7つ. ただし、隣接することは出来ない.
 * [0: (1<<W)) のビットパターンのうち、隣接したビットが立っているものを除けば全パターン列挙可能.
 *
 * 高さh_nにおいて、w_mの位置にいる場合、移動可能なのは3通り. (h_n+1, w_m-1), (h_n+1, w_m), (h_n+1, w_m+1)
 * パターン列挙中にこの3パターンと一致する場合 dp[h_n+1][w_m-1] += dp[h_n][w_m]
 *
 * dpの初期値はh=0, w=0が1、その他0
 *
 * 座標と横棒のインデックスが紛らわしいので整理しておく.
 *
 * 0 1 2 3 4 5 6 7
 * |0|1|2|3|4|5|6|  0
 *                  1
 */
int H, W, K;
ll dp[110][10] = {0};
void print() {
  loop(h,0,H+1) {
    loop(w,0,W) {
      cout << dp[h][w] << " ";
    }
    cout << endl;
  }
}

bool nth(ll s, int n) {
  return (s>>n)&1;
}
void solve() {
  cin >> H >> W >> K;
  dp[0][0] = 1;
  loop(h,0,H) loop(w,0,W) {
    for (ll S=0; S<(1<<(W-1)); S++) {
      bool connected = false;
      for (int i=0; i+1<W; i++) {
        connected |= nth(S, i) and nth(S, i+1);
      }
      if (connected) continue;

      // (h, w) -> (h+1, w)
      if (!nth(S, w)) {
        if (w==0) {
          madd(dp[h+1][w], dp[h][w]);
        } else {
          if (!nth(S, w-1)) madd(dp[h+1][w], dp[h][w]);
        }
      }

      // (h, w) -> (h+1, w-1)
      if (w-1>=0 and nth(S, w-1)) madd(dp[h+1][w-1], dp[h][w]);
      // (h, w) -> (h+1, w+1)
      if (w+1<W and nth(S, w)) madd(dp[h+1][w+1], dp[h][w]);
    }
  }
  // print();
  cout << dp[H][K-1] << endl;
}
int main() {
  // cout.precision(15); cout << fixed;

  solve();

  return 0;
}

