struct ModRing {
   int mod, x;
   // constructor
   ModRing(int mod_n) : mod(mod_n), x(0) {}
   ModRing(int a, int mod_n) : mod(mod_n) { x = ((a % mod) + mod) % mod; }

   // methods
   ModRing& operator=(int a) {
      return *this = ModRing(a, mod);
   }
   ModRing operator-() const {
      return ModRing((-x + mod) % mod, mod);
   }
   ModRing& operator+=(const ModRing& a) {
      (x += a.x) %= mod;
      return *this;
   }
   ModRing& operator-=(const ModRing& a) {
      return *this += -a;
   }
   ModRing& operator*=(const ModRing& a) {
      (x *= a.x) %= mod;
      return *this;
   }
   const ModRing operator+(const ModRing& a) const {
      return ModRing(x, mod) += a;
   }
   const ModRing operator-(const ModRing& a) const {
      return ModRing(x, mod) -= a;
   }
   const ModRing operator*(const ModRing& a) const {
      return ModRing(x, mod) *= a;
   }
   ModRing& operator+=(int a) {
      return *this += ModRing(a, mod);
   }
   ModRing& operator-=(int a) {
      return *this -= ModRing(a, mod);
   }
   ModRing& operator*=(int a) {
      return *this *= ModRing(a, mod);
   }
   const ModRing operator+(int a) const {
      return ModRing(x, mod) += a;
   }
   const ModRing operator-(int a) const {
      return ModRing(x, mod) -= a;
   }
   const ModRing operator*(int a) const {
      return ModRing(x, mod) *= a;
   }
};
auto&operator<<(ostream&s,const ModRing&a){s<<a.x;return s;}


struct GaussField : ModRing {
   // constructor
   GaussField(int mod_n) : ModRing(mod_n) {}
   GaussField(int a, int mod_n) : ModRing(a, mod_n) {}
   GaussField(const ModRing& a) : ModRing(a) {}

   // super class
   GaussField& operator=(int a) {
      return *this = GaussField(ModRing::operator=(a));
   }
   GaussField operator-() const {
      return GaussField(ModRing::operator-());
   }
   GaussField& operator+=(const GaussField& a) {
      return *this = GaussField(ModRing::operator+=(a));
   }
   GaussField& operator-=(const GaussField& a) {
      return *this = GaussField(ModRing::operator-=(a));
   }
