   }
   const GaussField operator+(const GaussField& a) const {
      return GaussField(ModRing::operator+(a));
   }
   const GaussField operator-(const GaussField& a) const {
      return GaussField(ModRing::operator-(a));
   }
   const GaussField operator*(const GaussField& a) const {
      return GaussField(ModRing::operator*(a));
   }
   GaussField& operator+=(int a) {
      return *this = GaussField(ModRing::operator+=(a));
   }
   GaussField& operator-=(int a) {
      return *this = GaussField(ModRing::operator-=(a));
   }
   GaussField& operator*=(int a) {
      return *this = GaussField(ModRing::operator*=(a));
   }
   const GaussField operator+(int a) const {
      return GaussField(ModRing::operator+(a));
   }
   const GaussField operator-(int a) const {
      return GaussField(ModRing::operator-(a));
   }
   const GaussField operator*(int a) const {
      return GaussField(ModRing::operator*(a));
   }

   // methods
   GaussField power(int n) const {
      GaussField tmp(x, mod), res(1, mod);
      while (n > 0) {
         if ((n & 1) == 1) res *= tmp;
         tmp *= tmp;
         n >>= 1;
      }
      return res;
   }
   GaussField inverse() const {
      try { if (x == 0) throw "0 have no inverse"; }
      catch (const char* e) { cerr << e << endl; }
      return power(mod-2);
   }
   GaussField& operator/=(const GaussField& a) {
      *this *= a.inverse();
      return *this;
   }
   const GaussField operator/(const GaussField& a) const {
      return GaussField(x, mod) /= a;
   }
   GaussField& operator/=(int a) {
      return *this /= GaussField(a, mod);
   }
   const GaussField operator/(int a) const {
      return GaussField(x, mod) /= a;
   }
};


