#define MOD 1000000007
using namespace std;

long left(int b, int on){
    if(b <= 1) return 1;
    if(on == 1) return left(b-1, 0);
    else return left(b-1, 0) + left(b-1, 1);
}

long right(int b, int on, int W){
    if(b >= W-2) return 1;
    if(on == 1) return right(b + 1, 0, W);
    else return right(b + 1, 0, W) + right(b + 1, 1, W);
}

int main(){

    long H, W, K;
    cin >> H >> W >> K;
    K--;

    long dp[H+1][W];

    for(int i=0; i<W; i++){
        if(i == 0) dp[0][i] = 1;
        else dp[0][i] = 0;
    }
    for(int i=1; i<=H; i++){
        for(int j=0; j<W; j++){
            dp[i][j] = dp[i-1][j] * (left(j, 0) * right(j, 0, W));
            if(j != 0) dp[i][j] += dp[i-1][j-1] * (right(j-1, 1, W) * left(j-1, 0)); 
            if(j != W-1) dp[i][j] += dp[i-1][j+1] * (right(j+1, 0, W) * left(j+1, 1)); 
            dp[i][j] %= MOD;
        }
    }
    cout << dp[H][K] << endl;
    return 0;
}

