/*
 * 縦h, 横wの地点から移動できるマスは、(h+1, w-1), (h+1, w), (h+1, w+1)の3通り.
 * それぞれ移動できる場合の縦h+1における橋の配置方法は、w-1の橋の起点に隣接しないように約2^W
 * 初期値は、初期位置として(0, 0)が1通り. h=0で他のwはありえないので0通り.
 *
 * 橋の配置方法について、(h+1, w)の場合, その前後においてはいけない.
 * あとはそこに置く場合と置かない場合の2^W
 */
int H, W, K;
mint dp[110][10] = {0};

bool nth(ll S, int n) {
  return (S>>n)&1;
}

void print() {
  loop(h,0,H+1) {
    loop(w,0,W) {
      cout << dp[h][w] << " ";
    }
    cout << endl;
  }
}

void solve() {
  cin >> H >> W >> K;
  dp[0][0] = 1;

  loop(h,0,H) {
    loop(k,0,W) {
      for (ll S=0; S<(1<<(W-1)); S++) {
        bool overlap = false;
        loop(i,0,W-2) overlap |= nth(S, i) and nth(S, i+1);
        if (overlap) continue;

        /* 座標とインデックスを混同しないように: 横軸kは座標kとk+1をつなぐ. */

        if (nth(S, k)) dp[h+1][k+1] += dp[h][k]; // 横軸kが存在する <=> kからk+1に移動可能
        else if (k - 1 >= 0 and nth(S, k-1)) dp[h+1][k-1] += dp[h][k]; // 横軸k-1が存在する <=> kからk-1に移動可能
        else dp[h+1][k] += dp[h][k]; // 横軸kもk-1も存在しない <=> 真下に移動可能
      }
    }
  }

  // print();
  cout << dp[H][K-1] << endl;
}
int main() {
  // cout.precision(15); cout << fixed;

  solve();
  return 0;
}

