ll Mod = 1000000007;
int H,W,K;
vector< vector<int> > cand;
void DFS(vector<int> now) {
  if ((int)now.size() == W-1) {
    cand.push_back(now);
  } else {
    int c = now.size();
    if (now[c-1] == 1) {
      now.push_back(0);
      DFS(now);
    } else {
      now.push_back(0);
      DFS(now);
      now.pop_back();
      now.push_back(1);
      DFS(now);
    }
  }
  return ;
}
int main() {
  cin >> H >> W >> K;
  if (W == 1) {
    cout << 1 << endl;
    return 0;
  } 
  K--;
  ll table[W][W];
  for (int i = 0; i < W; i++) {
    for (int j = 0; j < W; j++) {
      table[i][j] = 0;
    }
  }
  DFS({0});
  DFS({1});

  for (int i = 0; i < cand.size(); i++) {
    int next[W];
    for (int j = 0; j < W; j++) {
      next[j] = j;
    }
    for (int j = 0; j < W-1; j++) {
      if (cand[i][j] == 1) {
        swap(next[j],next[j+1]);
      }
    }
    for (int j = 0; j < W; j++) {
      table[j][next[j]]++;
    }
  }

  ll DP[H+1][W];
  for (int i = 0; i < H+1; i++) {
    for (int j = 0; j < W; j++) {
      DP[i][j] = 0;
    }
  }
  DP[0][0] = 1;

  for (int i = 1; i <= H; i++) {
    for (int j = 0; j < W; j++) {
      for (int k = 0; k < W; k++) {
        DP[i][j] += table[j][k] * DP[i-1][k];
        DP[i][j] %= Mod;
      }
    }
  }
  cout << DP[H][K] << endl;
  return 0;
}

