#define ll long long

using namespace std;

ll combi(int n){
    if(n < 1) return 1;
    if(n == 1) return 2;
    if(n == 2) return 3;
    return combi(n - 1) + combi(n - 2);
}

int main(){
    int h,w,k;
    cin >> h >> w >> k;

    vector<vector<ll>> down;
    vector<vector<ll>> right;
    vector<vector<ll>> left;

    vector<ll> tmpv;
    tmpv.push_back(1);
    for(int i = 0; i < w - 1; i++) tmpv.push_back(0);
    down.push_back(tmpv);

    if(w != 1){

        for(int i = 0; i < h; i++){
            vector<ll> tmpr;
            vector<ll> tmpl;

            for(int j = 0; j < w - 1; j++){
                tmpr.push_back((down[i])[j]);
                tmpl.push_back((down[i])[j + 1]);
            }

            right.push_back(tmpr);
            left.push_back(tmpl);

            vector<ll> tmpv;
            tmpv.push_back((down[i][0] * combi(w - 2) + left[i][0] * combi(w - 3)) % 1000000007);
