i64 BIT(i64 x, i64 i) {
    return (x>>i) & 1;
}

i64 H, W;
i64 K;

bool is_ok(i64 i) {
    REP(j, W-2) {
        if(BIT(i,j) && BIT(i,j+1)) return false;
    }
    return true;
}

i64 amida(i64 x, i64 i) {
    if(x != W-1 && BIT(i,x))  // 右
        return x+1;
    else if(x != 0 && BIT(i,x-1))  // 左
        return x-1;
    else
        return x;
}

void solve() {
    // i段目までで点jに辿り着くあみだくじの数
    static ModP dp[101][8] {};
    dp[0][0] = 1;

    FOR(y, 1, H+1) {
        REP(i, (1LL<<(W-1))) {
            if(!is_ok(i)) continue;
            REP(x, W) {
                dp[y][amida(x,i)] += dp[y-1][x];
            }
        }
    }

    ModP ans = dp[H][K];

    // MOD はとった?
    PRINTLN(ans);
}

signed main() {
    RD(H);
    RD(W);
    RD(K); --K;  // 0-based

    solve();

    return 0;
}

