      if (j>1) dp[i+1][j-1] = dp[i+1][j-1] + dp[i][j] * fib[j-2] * fib[W-j];
      dp[i+1][j] = dp[i+1][j] + dp[i][j] * fib[j-1] * fib[W-j];
      if (j<W) dp[i+1][j+1] = dp[i+1][j+1] + dp[i][j] * fib[j-1] * fib[W-j-1];
    }
  }
