int M(LL m){
    return m%MOD;
}

LL dfs(int h,int k,int t){
    if(k<1||k>W)return 0;
    int& ans=dp[h][k][t];
    if(ans!=-1)return ans;

    int lk=k;
    if(t==1)lk=k-1;
    if(t==2)lk=k+1;

    LL ldfs=M(M(dfs(h-1,lk,0)+dfs(h-1,lk,1))+dfs(h-1,lk,2));
    ans=M(ldfs*dpc[t][k]);
    //printf("dfs[%d][%d][%d]=%d\n",h,k,t,ans);
    return ans;
}

int mc[15];

int c(int len){
    if(len<=0)return 1;
    int& ans=mc[len];
    if(ans)return ans;
    return ans=c(len-1)+c(len-2);
}

int c(int a,int b){
    return c(b-a);
}

int main(){
    scanf("%d%d%d",&H,&W,&K);

    memset(dp,-1,sizeof dp);
    memset(mc,0,sizeof mc);

    for(int i=1;i<=W;i++){
        dpc[0][i]=c(1,i-1)*c(i+1,W);
        dpc[1][i]=c(1,i-2)*c(i+1,W);
        dpc[2][i]=c(1,i-1)*c(i+2,W);
    }

    for(int t=0;t<=2;t++)
        for(int i=1;i<=W;i++)
            dp[0][i][t]=0;
    dp[0][1][0]=1;

    printf("%d",M(dfs(H,K,0)+dfs(H,K,1)+dfs(H,K,2)));
    return 0;
}

