int main() {
  //freopen("input.in","r",stdin);
  //freopen("output.out","w",stdout);

  cin >> N >> M >> K;
  fib[0] = 1;
  fib[1] = 1;
  for(int i = 2;i < 10;i++) {
    fib[i] = (fib[i-1] + fib[i-2]) % mod;
  }

  for(int i = 0;i < N;i++) {
    for(int j = 0;j < M;j++) {
      if(i == 0) {
        if(j == 0) dp[i][j] = fib[M-1];
        else if(j == 1) dp[i][j] = fib[M-2];
        else dp[i][j] = 0;
        continue;
      }

      dp[i][j] = (dp[i-1][j]*(fib[j]*fib[M-j-1]) % mod) % mod;
      if(j - 1 >= 0) {
          long long x = (dp[i-1][j-1]*(fib[j-1]*fib[M-j-1]) % mod) % mod;
          dp[i][j] = (dp[i][j] + x) % mod;
      }
      if(j + 1 < M) {
        long long x = (dp[i-1][j+1]*(fib[j]*fib[M-j-2]) % mod) % mod;
        dp[i][j] = (dp[i][j] + x) % mod;
      }
    }
  }

  cout << dp[N-1][K-1] << endl;

