const int MOD = 1000000007;

int main() {
    int H, W, K;
    cin >> H >> W >> K;

    vector<vector<int>> dp(H + 1, vector<int>(W));
    dp[0][0] = 1;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            for (int mask = 0; mask < (1 << W - 1); mask++) {
                bool flag = true;
                for (int k = 0; k < W - 2; k++) {
                    if ((mask >> k) & 1 && (mask >> (k + 1)) & 1) {
                        flag = false;
                    }
                }
                if (flag) {
                    if (j >= 1 && (mask >> (j - 1)) & 1) {
                        dp[i + 1][j - 1] += dp[i][j];
                        dp[i + 1][j - 1] %= MOD;
                    } else if (j < W - 1 && (mask >> j) & 1) {
                        dp[i + 1][j + 1] += dp[i][j];
                        dp[i + 1][j + 1] %= MOD;
                    } else {
                        dp[i + 1][j] += dp[i][j];
                        dp[i + 1][j] %= MOD;
                    }
                }
            }
        }
    }

    cout << dp[H][K - 1] << endl;
    return 0;
}

