                if(from>to)swap(from,to);
                if(l==0){
                    modplus(dp[i+1][j],dp[i][j]*(eline(from-1)*eline(w-to-2)%MOD)%MOD);
                }else if(0<=j+l&&j+l<w){
                    modplus(dp[i+1][j+l],dp[i][j]*(eline(from-1)*eline(w-to-2)%MOD)%MOD);
                }
            }
        }
    }
    cout<<dp[h][g]<<endl;
}

#include <bits/stdc++.h>
using namespace std;

const int MaxH = 100 + 1, MaxW = 8;

int H, W, K;
int dp[MaxH][MaxW][1 << MaxW];

inline bool check(int S) {
    for (int i = 0; i < W - 1; ++i)
        if ((S & (1 << i)) && (S & (1 << i + 1))) return false;
    return true;
}

inline void update(int &x, int v) {
    x += v;
    x %= 1000000007;
}

void solve() {
    dp[0][0][0] = 1;
    for (int i = 1; i <= H; ++i) for (int S = 0; S < (1 << (W - 1)); ++S) {
        if (check(S) == false) continue;
        for (int Q = 0; Q < (1 << W - 1); ++Q) {
            if (check(Q) == false) continue;
            for (int j = 0; j < W; ++j) {
                if (j != 0 && (S & (1 << j - 1)))
                    update(dp[i][j][S], dp[i - 1][j - 1][Q]);
                else if (j != W - 1 && (S & (1 << j)))
                    update(dp[i][j][S], dp[i - 1][j + 1][Q]);
                else
                    update(dp[i][j][S], dp[i - 1][j][Q]);
                // printf("dp[%d][%d][%d] = %d\n", i, j, S, dp[i][j][S]);
            }
        }
    }

    int ans = 0;
    for (int S = 0; S < (1 << W - 1); ++S)
        if (check(S)) update(ans, dp[H][K - 1][S]);
    cout << ans << endl;
}

int main() {
    cin >> H >> W >> K;
    solve();
    return 0;
}

