	ios::sync_with_stdio(false);

	int H, W, K;
	cin >> H >> W >> K;
	vector<int> bits;
	for (int bit = 0;bit < (1 << (W - 1));bit++) {
		int prev = 0;
		bool ok = true;
		int tmp = bit;
		while (tmp) {
			if (tmp % 2 && prev) {
				ok = false;
				break;
			}
			prev = tmp % 2;
			tmp /= 2;
		}
		if (ok) bits.push_back(bit);
	}
	int n = bits.size();
	//REP(k, n) cout << bits[k] << "\n";
	vector<int> left(W, 0), mid(W, 0), right(W, 0);
	for (int j = 0;j < W;j++) {
		for (int k = 0;k < n;k++) {
			left[j] += (j > 0) ? (bool)(bits[k] & (1 << (j - 1))) : 0;
			mid[j] += ((j > 0) ? (bool)(~bits[k] & (1 << (j - 1))) : 1) && ((j < W - 1) ? (bool)(~bits[k] & (1 << j)) : 1);
			right[j] += (j < W - 1) ? (bool)(bits[k] & (1 << j)) : 0;
			//printf("%d %d %d\n", left[j], mid[j], right[j]);
		}

	}
	vector<vector<ll>> dp(H + 1, vector<ll>(W + 2, 0));
	dp[0][1] = 1;
	for (int i = 0;i < H;i++) {
		for (int j = 0;j < W;j++) {
			dp[i + 1][j + 1] = (left[j] * dp[i][j] % p + mid[j] * dp[i][j + 1] % p + right[j] * dp[i][j + 2] % p) % p;
		}
	}
	cout << dp[H][K] << "\n";

	return 0;
}

