/*
あみだくじは隣り合った二元の置換に該当する
1~Wに二元の置換のセットを合計H回行ってK番目に1を置くような組み合わせ

dp[i][j] = i回行ってj番目に1を置くような組み合わせ数

dp[i+1][j] = dp[i][j-1] * f(j-2) * f(j+1) + 
             dp[i][j] * f(j-1) * f(j+1) + 
             dp[i][j+1] * f(j-1) * f(j+2)
*/

ll dp[110][10];
ll memo[20];

ll f(ll n) {
    n--;
    if (n <= 0) return 1;
    if (memo[n] != 0) return memo[n];
    if (n == 1) return 2;
    if (n == 2) return 3;
    ll res = f(n-1) + f(n-2);
    memo[n] = res;
    return res;
}

int main() {
    ll H, W, K;
    cin >> H >> W >> K;
    ll D = 1e9 + 7;
    dp[0][0] = 1;

    for (ll i = 0; i < H; i++) {
        for (ll j = 0; j < W; j++) {
            dp[i+1][j] = dp[i][j] * f(j) * f(W-j-1) % D;
            if (j > 0) {
                dp[i+1][j] += dp[i][j-1] * f(j-1) * f(W-j-1) % D;
            }
            if (j < W-1) {
                dp[i+1][j] += dp[i][j+1] * f(j) * f(W-j-2) % D;
            }
            dp[i+1][j] %= D;
        }
    }

    cout << dp[H][K-1] << endl;



}

