#include<bits/stdc++.h>
using namespace std;

#define DIV 1000000007

long long dp[10][200];
long long H, W, K;

bool has(long long pat, long long left){
	return ((pat>>left)&1);
}

bool check(long long pat){
	for(long long i = 0; i <= W; i++){
		if(has(pat,i) && has(pat, i + 1)){
			return false;
		}
	}
	return true;
}

long long draw(long long left){
	long long count = 0;
	for(long long pat = 0; pat < pow(2, W-1); pat++){
		if(check(pat) && has(pat, left)){
			count++;
		}
	}
	return count;
}

long long blank(long long left){
	long long count = 0;
	for(long long pat = 0; pat < pow(2, W-1); pat++){
		if(check(pat) && !has(pat, left)){
			count++;
		}
	}
	return count;
}


long long doubleblank(long long left1, long long left2){
	long long count = 0;
	for(long long pat = 0; pat < pow(2, W-1); pat++){
		if(check(pat) && !has(pat, left1) && !has(pat,left2)){
			count++;
		}
	}
	return count;
}

int main(){
	cin >> H >> W >> K;K--;
	dp[0][0] = 1;

	for(long long row = 1; row <= H; row++){
		for(long long col = 0; col < W; col++){
			if(col == 0){
				dp[col][row] = dp[col][row-1] * blank(0);
				dp[col][row] += dp[col+1][row-1] * draw(0);
				dp[col][row] %= DIV;
			}else if(col == W-1){
				dp[col][row] = dp[col][row-1] * blank(W-2);
				dp[col][row] += dp[col-1][row-1] * draw(W-2);
				dp[col][row] %= DIV;
			}else{
				dp[col][row] = dp[col][row-1] * doubleblank(col-1, col); //down
				dp[col][row] += dp[col-1][row-1] * draw(col-1); //from left
				dp[col][row] += dp[col+1][row-1] * draw(col); //from right
				dp[col][row] %= DIV;
			}
		}
	}

	cout << dp[K][H] << endl;

}

