            if(j-1>=0)
            dp[i+1][j-1] += dp[i][j]*itoj[j][j-1];
            dp[i+1][j]%=1000000007;
            dp[i+1][j+1]%=1000000007;
            dp[i+1][j-1]%=1000000007;
        }
