            for(int bit=0;bit<(1<<W-1);bit++){
                bool flag=true;
                rep(k,W-2){
                       if(((bit>>k)&1)&&((bit>>(k+1))&1)) flag=false;
                }
                if(flag){
                    if(j==1){
                        if((bit>>(j-1))&1) Z++;
                        else Y++;
                    }else if(j==W){
                        if((bit>>(j-2))&1) X++;
                        else Y++;
                    }else{
                        if((bit>>(j-1))&1) Z++;
                        else if((bit>>(j-2))&1) X++;
                        else Y++;
                    }
                }
            }


            dp[j][h+1]=(((Y*dp[j][h])%MOD+(X*dp[j-1][h])%MOD)%MOD+(Z*dp[j+1][h])%MOD)%MOD;
        }


    }
    cout << dp[K][H] << endl;
}

