long long powp(long long a, long long b) {
    if (b == 0)
        return 1ll;
    else if (b == 1)
        return a % p;
    else if (b % 2 == 0) {
        long long t = powp(a, b/2);
        return t * t % p;
    } else {
        long long t = powp(a, b/2);
        return t * t % p * a % p;
    }
}

long long inv(long long n) {
    return powp(n, p-2) % p;
}

long long fac(long long n) {
    if (fac_dp[n] != 0) {
        return fac_dp[n];
    } else {
        for (long long i = 2; i <= n; i++) {
            if (fac_dp[i] == 0) {
                fac_dp[i] = i * fac_dp[i-1] % p;
            }
        }
        return fac_dp[n];
    }
}

long long fib(long long n) {
    if (fib_dp[n]) {
        return fib_dp[n];
    } else {
        for (long long i = 2; i <= n; i++) {
            if (fib_dp[i] == 0) {
                fib_dp[i] = (fib_dp[i-1] + fib_dp[i]) % p;
            }
        }
        return fib_dp[n];
    }
}

long long nCr(long long n, long long r) {
    return fac(n) * inv(fac(r)) % p * inv(fac(n-r)) % p;
}

