// (num ^ x) % mod
LL pow_mod(LL num, LL x, LL mod)
{
	LL res = 1;
	while (x > 0)
	{
		if (x & 1)
		{
			res = (res*num) % mod;
		}
		num = (num*num) % mod;
		x >>= 1;
	}
	return res;
}

LL dp1(LL h, LL w, LL c)
{
	if (w < 0 || W <= w) return 0;
	if (h == H)
	{
		if (w == K - 1)
		{
			cnt[c]++;
			return 1;
		}
		return 0;
	}
	if (memo[h][w][c] != -1) return memo[h][w][c];
	LL res1 = dp1(h + 1, w + 1, c + 1);
	LL res2 = dp1(h + 1, w - 1, c + 1);
	LL res3 = dp1(h + 1, w, c);
	return memo[h][w][c] = (res1 + res2 + res3) % mod;
}

LL dp2(LL h, LL w, LL c)
{
	if (w <= maxR || W <= w) return 0;
	if (h == H)
	{
		if (w != K - 1)
		{
			cnt[c]++;
			return 1;
		}
		return 0;
	}
	if (memo[h][w][c] != -1) return memo[h][w][c];
	LL res1 = dp2(h + 1, w + 1, c + 1);
	LL res2 = dp2(h + 1, w - 1, c + 1);
	LL res3 = dp2(h + 1, w, c);
	return memo[h][w][c] = (res1 + res2 + res3) % mod;
}

int main()
{
