	cnt.resize(H + 1);
	memo.resize(H + 1);
	rep(i, memo.size())
	{
		memo[i].resize(W + 1);
		rep(j, memo[i].size()) memo[i][j].resize(H + 1, -1);
	}
	dp1(0, 0, 0);
	auto firstRes = cnt;

	std::vector<std::vector<LL>>moreRes;
	maxR = std::max(K, (H - (K - 1)) / 2) - 1;
	for (int i = maxR + 1; i < W - 1; ++i)
	{
		cnt.clear();
		memo.clear();
		cnt.resize(H + 1);
		memo.resize(H + 1);
		rep(i, memo.size())
		{
			memo[i].resize(W + 1);
			rep(j, memo[i].size()) memo[i][j].resize(H + 1, -1);
		}
		dp2(0, i, 0);
		moreRes.push_back(cnt);
	}
	for (int c = 0; c <= H; ++c)
	{
		LL org = firstRes[c] % mod;
		LL sum = 0;
		for (int i = maxR + 1; i < W - 1; ++i)
		{
			for (int j = 0; j <= H - c; ++j)
			{
				sum += moreRes[i - maxR - 1][j];
				sum %= mod;
			}
		}
		if (sum == 0) sum = 1;
		LL res = (org * sum) % mod;
		ans += res;
		ans %= mod;
	}

	out << ans << std::endl;
	return 0;
}

