ll dfs(bool prevLineExist, int i, int num)
{
	if ((num <= 0)||(num < i)) {
		return 1;
	}

	if (i == num) {
		return 1;
	}

	ll cnt = 0;
	int next = i + 1;
	if (prevLineExist) {
		// 引けない
		cnt = dfs(false, next, num);
	} else {
		// 引く or 引かない
		cnt = dfs(true, next, num);
		cnt += dfs(false, next, num);
	}

	cnt %= MOD;
	return cnt;
}


