            f[i][j] = ((j == 1 ? 0 : (f[i - 1][j - 1] * fib[j - 2] % mod * fib[w - j] % mod)) + (j == w ? 0 : (f[i - 1][j + 1] * fib[j - 1] % mod * fib[w - j - 1] % mod)) + f[i - 1][j] * fib[j - 1]%mod * fib[w - j] % mod) % mod;
    cout << f[h][k] << endl;
    return 0;
}

