const ll MOD=1000000007;

int main(){
  int H,W,K;
  cin>>H>>W>>K;
  K--;

  ll dp[H+1][W]; //dp[h][k]=横線h段からなるあみだくじで、0がkに来る者の数
  fill(dp[0],dp[H+1],0); //0からH+1まで0で埋める
  dp[0][0]=1;

  for (int h=0; h<H; ++h) {
    for (int b=0; b<(1<<(W-1)); ++b) {
      //横線が隣り合っていないかチェック
      bool judge = true;
      for (int i=0; i<W-2; ++i){
        if ((b>>i)%4==3) judge=false;
      }
      if (!judge) continue; //continue以下の処理を飛ばして次のループへ

      int perm[W]; //各支店がどこに移動するのかを管理する
      for (int i=0; i<W; ++i) perm[i]=i;
      for (int i=0; i<W-1; ++i) {
        //あみだくじのルールに従って位置をswap
        if ((b>>i)&1) swap(perm[i],perm[i+1]);
      }
      //配る
      for (int i=0; i<W; ++i){
        dp[h+1][perm[i]] += dp[h][i];
        dp[h+1][perm[i]] %= MOD;
      }
    }
  }

  cout << dp[H][K] <<endl;

  return 0;
}

