    --k;
    vector<vector<mint> > dp(h+1, vector<mint>(w));
    if(w==1) {
        cout<<1<<endl;
        return 0;
    }
    dp[1][0]=f(w-2).first+f(w-2).second;
    dp[1][1]=max((ll)1, f(w-3).first+f(w-3).second);
    rep(j, w) cout<<dp[1][j].x<<", ";
    cout<<endl;
    for(int i=2;i<=h;i++){
        rep(j, w){
            if(j==0) {
                pair<ll, ll> fw=f(w-2);
                pair<ll, ll> fw_1=f(w-3);
                mint a=dp[i-1][j]*max((ll)1, fw.first+fw.second);
                mint b=dp[i-1][j+1]*max((ll)1, fw_1.first+fw_1.second);
                dp[i][j]=a+b;
            }
            else if(j==w-1) {
                pair<ll, ll> fw=f(w-2);
                pair<ll, ll> fw_1=f(w-3);
                mint a=dp[i-1][j]*max((ll)1, fw.first+fw.second);
                mint b=dp[i-1][j-1]*max((ll)1, fw_1.first+fw_1.second);
                dp[i][j]=a+b;
            }
            else {
                pair<ll, ll> fk=f(j-1);
                pair<ll, ll> fw=f(w-j-2);
                pair<ll, ll> fk_1=f(j-2);
                pair<ll, ll> fw_1=f(w-j-3);
                mint a=dp[i-1][j]*max((ll)1, fk.first+fk.second)*max((ll)1, fw.first+fw.second);
                mint b=dp[i-1][j-1]*max((ll)1, fk_1.first+fk_1.second)*max((ll)1, fw.first+fw.second);
                mint c=dp[i-1][j+1]*max((ll)1, fk.first+fk.second)*max((ll)1, fw_1.first+fw_1.second);
                dp[i][j]=a+b+c;
            }
            cout<<dp[i][j].x<<", ";
        }
        cout<<endl;
    }
