vector<ll> calc(int h, int w, int x, string out){
    vector<ll> res(3);
    if(out.size() == w-1){
        // print(out);
        if(x-1 >= 0){
            if(out[x-1] == '1'){
                res[0]++;
                return res;
            }
        }
        if(x <= out.size()-1){
            if(out[x] == '1'){
                res[2]++;
                return res;
            }
        }
        res[1]++;
        return res;
    }

    vector<ll> tmp;
    tmp = calc(h, w, x, out + '0');
    res = sum(res, tmp);
    if(out.size()==0 || out[out.size()-1] != '1'){
        tmp = calc(h, w, x, out+ '1');
        res = sum(res, tmp);
    }
    return res;
} 


