        for (int j = i-2; 1 <= j; j--) {
            path[j][0] = path[j+1][0] + path[j+1][1];
            path[j][1] = path[j+1][0];
        }
        ll l = path[1][0] + path[1][1];
        for (int j = i+1; j < W; j++) {
            path[j][0] = path[j-1][0] + path[j-1][1];
            path[j][1] = path[j-1][0];
        }
        ll r = path[W-1][0] + path[W-1][1];
        itok[i][i] = l * r;
    }
    for (int i = 1; i < W; i++) {
        vector<vector<ll>> path(W+1, vector<ll>(2, 0));
        path[i][0] = 0; path[i][1] = 1;
        for (int j = i-1; 1 <= j; j--) {
            path[j][0] = path[j+1][0] + path[j+1][1];
            path[j][1] = path[j+1][0];
