int solve(){
    modint dp[110][10];
    modint cnt_edge_dp[10][2];
    memset(dp,0,sizeof(dp));
    memset(cnt_edge_dp,0,sizeof(cnt_edge_dp));
    dp[0][0] = 1;

    cnt_edge_dp[0][0]=1;
    cnt_edge_dp[0][1]=1;
    cnt_edge_dp[1][0]=1;
    cnt_edge_dp[1][1]=1;

    for (int i = 1; i < W; i++)
    {
        cnt_edge_dp[i+1][0] = cnt_edge_dp[i][0]+cnt_edge_dp[i][1];
        cnt_edge_dp[i+1][1] = cnt_edge_dp[i][0];
    }
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            dp[i+1][j] += dp[i][j]*cnt_edge_dp[j][0]*cnt_edge_dp[W-j-1][0];
            if(j-1>=0) dp[i+1][j] += dp[i][j-1]*cnt_edge_dp[j][1]*cnt_edge_dp[W-j-1][0];
            if(j+1<W)  dp[i+1][j] += dp[i][j+1]*cnt_edge_dp[j][0]*cnt_edge_dp[W-j-1][1];
        }

    }
    cout << dp[H][K] << endl;

    return 0;
}   

