					// 左に横棒があるケース
					dp[i+1][j] += dp[i][j-1];
					dp[i+1][j] %= mod;
				}else if(j <= w-2 && ((k >> j) & 1)){
					// 右に横棒があるケース
					dp[i+1][j] += dp[i][j+1];
					dp[i+1][j] %= mod;
				}else{
					// その他（両脇に横棒がない）
