using namespace std;

const int MOD = 1000 * 1000 * 1000 + 7;

int subcount(int n)
{
	if (n <= 0) {
		return 1;
	}
	int c = 0;
	for (int i = 0; i < (1 << n); ++i) {
		bool ok = true;
		for (int k = 0; k + 1 < n; ++k) {
			if ((i & (1 << k)) && (i & (1 << (k + 1)))) {
				ok = false;
				break;
			}
		}
		if (ok) {
			++c;
		}
	}
	return c;
}

long long memo[100][8 + 1][8 + 1];

long long solve(int H, int W, int K)
{
	if (H == 1) {
		if (K == 1) {
			return subcount(W - 2);
		}
		else if (K == 2) {
			return subcount(W - 3);
		}
		else {
			return 0;
		}
	}
	else {
		if (memo[H][W][K] >= 0) {
			return memo[H][W][K];
		}

		long long ans = 0;
		if (1 < K) {
			ans += 1LL * subcount(K - 3) * subcount(W - K - 1) * solve(H - 1, W, K - 1) % MOD;
			ans %= MOD;
		}

		ans += 1LL * subcount(K - 2) * subcount(W - K - 1) * solve(H - 1, W, K) % MOD;
		ans %= MOD;

		if (K < W) {
			ans += 1LL * subcount(K - 2) * subcount(W - K - 2) * solve(H - 1, W, K + 1) % MOD;
			ans %= MOD;
		}

		return memo[H][W][K] = ans;
	}
}

int main()
{
	int H, W, K;
	cin >> H >> W >> K;

	memset(memo, -1, sizeof memo);
	cout << solve(H, W, K) << endl;
}

