	for (int i = 1;i <= H;++ i) {
		for (int j = 1;j <= W;++ j) {
			dp[i][j] = dp[i - 1][j - 1] * fib[j - 1] * fib[W - j + 1] + dp[i - 1][j] * fib[j] * fib[W - j + 1] + dp[i - 1][j + 1] * fib[j] * fib[W - j];
			dp[i][j] %= MOD; // 忘れずに！
			if (DEBUG) cerr << dp[i][j] << " ";
		}
		if (DEBUG) cerr << endl;
	}
	cout << dp[H][K];
	return 0;
}
/*
31536000のコメント解説欄
ここテンプレで用意してるから、A問題とかだとこの先空欄の危険あり
また、コンテスト後に https://31536000.hatenablog.com/ で解説していると思うので、良かったら読んでねー

上から考えていこう
まず、高さ1の時点での1の存在は、1-2に線が引かれていない場合は1に行き、その組み合わせは2からWまでの全ての横線を引く組み合わせに等しい
そして、1-2に線が引かれていれば2に行き、その組み合わせは3からWまでの全ての横線を引く組み合わせに等しい

……a-b間における組み合わせは先に計算すると良さそうなのでまず考えてみよう
平行移動しても同じなので、b-a=xとする長さを考えてf(x)で定義しよう
まず、f(0)=0, f(1)=1なのは自明
f(2)=f(1)(引かない場合)+f(0)(引いた場合)
以下、f(n)=f(n-1)+f(n-2)と導出できるので、これはフィボナッチ数列になるね

次に、今辿っている位置がxにある時の次の組み合わせを考えよう
・x-1に移動する組み合わせ
・xに移動する組み合わせ
・x+1に移動する組み合わせ
これ以外はあり得ないので、これだけ考えれば良いね
まず、x-1に移動する場合、(x-1)-xにあみだが引かれたので、(x-2)-(x-1)とx-(x+1)にはあみだが引かれない
よって、この組み合わせは1-(x-2)間×(x+1)-W間の組み合わせ、よってf(x-1)*f(W-x+1)となる
次にxに移動する場合は(x-1)-xとx-(x+1)にはあみだが引かれないので、f(x)*f(W-x+1)となるね
最後にx+1に移動する場合はx-(x+1)にあみだが引かれ、(x-1)-xと(x+1)-(x+2)にはあみだが引かれないのでf(x-1)*f(W-x)となる

ということは、これであみだくじを1個下に動く遷移がO(W)でできたので答えはO(HW)、間に合うね
*/

