ll sub(int n){
	if(n <= 0){
		return 1;
	}else if(n == 1){
		return 2;
	}else{
		return sub(n-1) + sub(n-2);
	}
}

void solve(){
	//初期値
	dp[0][0] = 1;
	for(int i=1;i<W;i++){
		dp[0][i] = 0;
	}

	for(int i=1;i<=H;i++){
		for(int j=0;j<W;j++){
			if(j == 0){
				dp[i][j] = sub(W-2)*dp[i-1][j] + sub(W-3)*dp[i-1][j+1];
			}else if(j == W-1){
				dp[i][j] = sub(W-3)*dp[i-1][j-1] + sub(W-2)*dp[i-1][j];
			}else{
				dp[i][j] = sub(j-2)*sub(W-2-j)*dp[i-1][j-1] + sub(j-1)*sub(W-2-j)*dp[i-1][j] + sub(j-1)*sub(W-3-j)*dp[i-1][j+1];
			}
			dp[i][j] %= mod;
		}
	}

