#define MD 1000000007

ll expo(ll x, ll n) {

    if( n <= 0) return 0;

    ll res = 1;
    while(n>0) {
        if(n%2 == 1) res = (res * x)% MD;
        x = (x*x) % MD;
        n = n/2;
    }

    return res;
}

