        default:
            assert(false);
            return -1;
    }
}

int64_t solve(int h, int w, int k) {
    vector<int64_t> current(w + 2, 0);
    vector<int64_t> next(w + 2, 0);

    current[1] = 1;

    for (int hh = 1; hh <= h; ++hh) {
        for (int x = 1; x <= w; ++x) {
            next[x] = (current[x - 1] * fib(x - 2) * fib(w - x) + current[x] * fib(x - 1) * fib(w - x) + current[x + 1] * fib(x - 1) * fib(w - x - 1)) % M;
        }
        current.swap(next);
    }

    return current[k];
} 

