ll dfs(ll i = 0, ll j = 0) {
    if(i >= H) {
        if(j == K) { return 1; }
        return 0;
    }

    ll& ret = dp[i][j];
    if(~ret) { return ret; }
    ret = 0;

    for(auto& pat : all_pat) {
        if(j > 0 && ((pat >> (j-1)) & 1) ) {
            // 左に移動するパターン
            ret += dfs(i+1, j-1);
            ret %= MOD;
        } else if(j < W-1 && ((pat >> (j)) & 1) ) {
            // 右に移動するパターン
            ret += dfs(i+1, j+1);
            ret %= MOD;
        } else {
            ret += dfs(i+1, j);
            ret %= MOD;
        }
    }

    return ret;
}

