                int_probs[i][n] = int_probs[i - 1][n] * valid_amida_pattern(n - 1) * valid_amida_pattern(W - n - 2) % 1000000007
                    + int_probs[i - 1][n + 1] * valid_amida_pattern(n - 1) * valid_amida_pattern(W - n - 3) % 1000000007
                    + int_probs[i - 1][n - 1] * valid_amida_pattern(n - 2) * valid_amida_pattern(W - n - 2) % 1000000007;
            }
            int_probs[i][n] = int_probs[i][n] % 1000000007;
        }
    }
    cout << int_probs[H][K - 1];

    return 0;
}

