template<typename Head,typename... Tail>
void vout(Head&& h,Tail&&... t){cout << ' ' << h;vout(forward<Tail>(t)...);}
void out(){cout << endl;}
template<typename Head,typename... Tail>
void out(Head&& h,Tail&&... t){cout << h;vout(forward<Tail>(t)...);}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout<<fixed<<setprecision(10);

	int H=in(),W=in(),K=in();
	int N=1<<(W-1);
	vector<vector<ll>> dp(H+1,vector<ll>(W,0));
	dp[0][0]=1;

	vector<int> Valid(N,1);
	REP(i,N){
		int v=i;
		int continuous=0;
		while(v){
			if(v&1){
				if(continuous){
					Valid[i]=0;
					break;
				}
				continuous=true;
			}
			else continuous=false;
			v>>=1;
		}
	}

	REP(i,H){
		REP(k,W){
			int offset[3]={-1,0,1};
			REP(l,3){
				int p = k+offset[l];
				if(p<0 || p>=W) continue;

				ll sum=0;
				REP(j,N){
					if(!Valid[j]) continue;
					if(l==0 && (j&(1<<p))) sum++;
					else if(l==2 && (j&(1<<k))) sum++;
					else if(l==1){
						if(k>0 && (j&(1<<(k-1)))) continue;
						if(k<W-1 && (j&(1<<k))) continue;
						sum++;
					}
				}
				dp[i+1][p] += (dp[i][k]*sum)%atcoder_mod;
				dp[i+1][p] %= atcoder_mod;
			}
		}
	}
	out(dp[H][K-1]);
	return 0;
}

