using namespace std;
int H,W,K,M=1e9+7,dp[101][9],i,j,k,l;
bool flag;
int main(){
	cin>>H>>W>>K;
	dp[0][0]=1;
	for(i=0;i<H;++i){
		for(j=0;j<W;++j){
			for(k=0;k<1<<(W-1);++k){//横線の候補は2^{W-1}通りある
				flag=true;
				for(l=0;l<W-2;++l){
					if(((k>>l)&1)&&((k>>(l+1))&1)){//連続二箇所で横棒があったら
						flag=false;//あみだくじの条件を満たさない
					}
				}
				if(flag){
					//下左と移動する場合
					if(j>=1&&((k>>(j-1))&1)){//下左と移動するためには2本目移行にいないといけない、かつ左下の位置から右方向に横棒がないといけない
						dp[i+1][j-1]+=dp[i][j];
						dp[i+1][j-1]%=M;
					}
					//下右と移動する場合
					else if(j<=W-2&&((k>>j)&1)){//下右と移動するためにはW-1本目までにいないといけない、かつ真下の位置から右方向に横棒がないといけない
						dp[i+1][j+1]+=dp[i][j];
						dp[i+1][j+1]%=M;
					}
					//真下へ移動する場合
					else{
						dp[i+1][j]+=dp[i][j];
						dp[i+1][j]%=M;
					}
				}
			}
		}
	}
	cout<<dp[H][K-1]<<endl;
	return 0;
}

