	dp[0][0] = 1;
	int64_t dp2[w + 1]{}; //dp2[i] := 長さiの区間を、2つ以上連続せずに選ぶ通り数
	dp2[0] = 1;
	{
		int64_t dp3[w + 1][2]{}; //dp3[i][j] := 長さiの区間を、2つ以上連続せずに選ぶ通り数(j==0の時iを選ばない、j==1の時選ぶ)
		dp3[0][0] = 1;
		for (int i = 0; i < w; i++)
		{
			for (int j = 0; j < 2; j++)
			{
				(dp3[i + 1][0] += dp3[i][j]) %= mod;
				if (j == 0)
				{
					(dp3[i + 1][1] += dp3[i][j]) %= mod;
				}
			}
			dp2[i + 1] = (dp3[i + 1][0] + dp3[i + 1][1]) % mod;
		}
