	{
		for (int j = 0; j < w; j++)
		{
			if (j)
			{
				(dp[i + 1][j - 1] += dp[i][j] * dp2[max(0, j - 2)] % mod * dp2[max(0, w - j - 2)] % mod) %= mod;
			}
			if (j + 1 != w)
			{
				(dp[i + 1][j + 1] += dp[i][j] * dp2[max(0, j - 1)] % mod * dp2[max(0, w - j - 3)] % mod) %= mod;
			}
			(dp[i + 1][j] += dp[i][j] * dp2[max(0, j - 1)] % mod * dp2[max(0, w - j - 2)] % mod) %= mod;
		}
	}
	cout << dp[h][k - 1] << endl;
	return 0;
