ll fac[binomialmax], finv[binomialmax], inv[binomialmax];

void cominit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (ll i = 2; i < binomialmax; i++){
        fac[i] = modu(fac[i - 1] * i);
        inv[i] = modu(-inv[mod % i] * (mod / i));
        finv[i] = modu(finv[i - 1] * inv[i]);
    }
}

/* 二項係数計算 */
ll com(ll n, ll k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return modu(fac[n] * (modu(finv[k] * finv[n - k])));
}

signed main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout<<fixed<<setprecision(10);
    cominit();
    int H,W,K;
    cin >> H >> W >> K;
    vector<vector<int>> num(H+50,vector<int>(W));
    num[0][0] = 1;
    vector<int> wi(W);
    REP(i,W){
        if(i <= 1){
            wi[i] = 1;
        }else if(i == 2){
            wi[i] = 2;
        }else if(i <= 5){
            wi[i] = com(i-1,2) + 2;
        }else if(i == 6){
            wi[i] = com(i-1,2) + 3;
        }else{
            wi[i] = com(i-1,2) + 6;
        }
    }
    REP(i,H){
        if(W == 1)break;
        REP(l,W){
            if(l == 0){
                num[i+1][l] = modu(num[i][l]*modu(wi[W-l-1]*wi[l]) + num[i][l+1]*modu(wi[W-l-2]*wi[l]));
            }else if(l == W-1){
                num[i+1][l] = modu(num[i][l]*modu(wi[W-l-1]*wi[l]) + num[i][l-1]*modu(wi[W-l-1]*wi[l-1]));
            }else{
                num[i+1][l] = modu(num[i][l]*modu(wi[W-l-1]*wi[l]) + num[i][l-1]*modu(wi[W-l-1]*wi[l-1]) + num[i][l+1]*modu(wi[W-l-2]*wi[l]));
            }
        }
    }
    if(W == 1){
        cout << 1 << "\n";
    }else{
        cout << num[H][K-1] << "\n";
    }
}

