int main(){
	int mod = 1000000007;
	int H, W, K;
	cin >> H >> W >> K;
	int dp[H+1][W] = {};
	dp[0][0] = 1;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			for (int k = 0; k < pow(2,W-1); k++) {
				bool ok = true;
				for (int l = 0; l < W-2; l++) {
					if (((k >> l) & 1) && ((k >> (l+1)) & 1)) {
						ok = false;
						break;
					}
				}
				if (ok) {
					// 左に行くとき
					if ((j > 0) && ((k >> (j-1)) & 1)) {
						dp[i+1][j-1] += dp[i][j];
						dp[i+1][j-1] %= mod;
					} else
					// 右に行くとき
					if ((j < W-1) && ((k >> j) & 1)) {
						dp[i+1][j+1] += dp[i][j];
						dp[i+1][j+1] %= mod;
					} else {
					// そのまま下に行くとき
						dp[i+1][j] += dp[i][j];
						dp[i+1][j] %= mod;
					}
				}
			}
		}
	}
	cout << dp[H][K-1] << endl;

	return 0;
}

