bool check(int j, int W) {
    bool ok = true;
    for (int k = 0; k + 1 < (W - 1); k++) {
        if ((j >> k & 1) && ((j >> (k + 1)) & 1)) ok = false;
    }
    return ok;
}

void solve() {
    int H, W, K;
    const int mod = 1e9 + 7;
    cin >> H >> W >> K;

    vector<vector<int>> dp(H + 1, vector<int>(W));
    dp[0][0] = 1;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            for (int k = 0; k < 1 << (W - 1); k++) {
                if (!check(k, W)) continue;
                int pos = j;

                if (k >> j & 1) pos++;
                else if (j >= 1 && k >> (j - 1) & 1) pos--;

                dp[i + 1][pos] += dp[i][j];
                dp[i + 1][pos] %= mod;
            }
        }
    }
    cout << dp[H][K - 1] << endl;
}

