// あみだの種類数をあらかじめ計算しておくやり方
// f(n)：n本の縦線で1列分の横線がひけるあみだの種類数

const int mod = 1e9 + 7;

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	int h, w, k;
	cin >> h >> w >> k;

	ll dp[h+1][w];
	rep(i, h+1) rep(j, w) dp[i][j] = 0;
	dp[0][0] = 1;

	// あみだの種類数の計算
	// 左端の線について、その線とその右の線の間に、
	// 1.横線がある→その右の線はもうあみだに使えず、２つ右の線以降で残りのあみだ
	// 2.横線がない→その右の線以降で残りのあみだ
	// なのでフィボナッチ数が出てくる
	ll f[20];
	f[0] = 1;
	f[1] = 1;
	f[2] = 2;
	for(int i = 3; i < 20; i++){
		f[i] = f[i-2] + f[i-1];
		f[i] %= mod;
	}

	for(int i = 0; i < h; i++){
		for(int j = 0; j < w; j++){
			// 左の線から移動する、同じ線、右の線から移動するの3パターン
			// （両端の線の場合は左の線からの移動、もしくは右の線からの移動がない）
			// それぞれの場合で左の線と同じ線の間、同じ線と右の線の間が決まり
			// そのほかの線のあみだの種類数を足してゆく。
			// 横棒がある線はあみだに使えないのに注意。

			if(j > 0) dp[i+1][j] += dp[i][j-1] * f[j-1] * f[w-j-1];
			dp[i+1][j] += dp[i][j] * f[j] * f[w-j-1];
			if(j < w-1) dp[i+1][j] += dp[i][j+1] * f[j] * f[w-j-2];
			dp[i+1][j] %= mod;

			// cout << (i+1) << " " << j << " " << dp[i+1][j] << endl;
		}
	}
	// cout << endl;
	cout << dp[h][k-1] << endl;
}

