class ap{
    int_fast64_t mov[90], val[9][200][8];
public:
    constexpr ap(size_t t) : mov(), val(){
        for(auto& i : mov)i = -1;
        mov[0] = 0;
        size_t c = 1, d = 1;
        for(size_t i = 0; i < t; ++i){
            for(size_t j = 0; j < c; ++j){
                mov[j + d] = mov[j] + (1 << i);
            }
            d += c;
            c = d - c;
            for(size_t j = 0; j < 200; ++j){
                for(size_t l = 0; l < i; ++l){
                    val[i][j][l] = 0;
                }
            }
            val[i][0][0] = 1;
            for(size_t j = 1; j < 200; ++j){
                for(size_t kk = 0; kk < c; ++kk){
                    auto k = mov[kk];
                    for(size_t l = 0; l <= i; ++l){
                        if((k >> l) & 1){
                            val[i][j][l] -= val[i][j - 1][l];
                            val[i][j][l] += val[i][j - 1][l + 1];
                            val[i][j][l + 1] -= val[i][j - 1][l + 1];
                            val[i][j][l + 1] += val[i][j - 1][l];
                        }
                        val[i][j][l] += val[i][j - 1][l];
                    }
                    for(size_t l = 0; l <= i; ++l){
                        val[i][j][l] %= 1000000007;
                    }
                }
            }
        }
    }
    constexpr int_fast64_t ans(size_t i, size_t j, size_t k) const{
        return val[j - 1][i][k - 1];
    }
};

