long Map(int X, int Y) {
	if (Y == H)
		if (X == K+1) {
			M[Y] = X - 1;
			flg[Y] = 1;
			return Calc();
		} else if (X == K) {
			M[Y] = X;
			flg[Y] = 0;
			return Calc();
		} else if ( X == K-1 ) {
			M[Y] = X;
			flg[Y] = 1;
			return Calc();
		} else 
			return 0;

	if (abs(X-K) > abs(H-Y+1)) return 0;

	M[Y] = X;
