				s2 = (s2 + dp[h - 1][w + 1]) % MOD;
				//! 使っていない部分に適当に線を引く
				s2 = (s2 * calc(w, w + 1)) % MOD;
			}

			{
				//! wから来る場合
				s3 = (s3 + dp[h - 1][w]) % MOD;
				//! 使っていない部分に適当に線を引く
				s3 = (s3 * calc(w, w)) % MOD;
			}
			dp[h][w] = s1 + s2 + s3;
		}
	}
	cout << dp[H][K - 1] << endl;
	return 0;
}

