void init()
{
	cin >> H >> W >> K;
	dp.resize(H+1, vector<ll>(W, 0));
	dp[0][0] = 1;
}

void update(int r)
{
	rep(i, 1 << (W-1)) {
		if (i & (i >> 1)) continue;
		int bit = 1;
		rep(j, W) {
			if (bit & i) {
				dp[r][j] += dp[r-1][j+1];
				dp[r][j] %= MOD;
			} else if ((bit >> 1) & i) {
				dp[r][j] += dp[r-1][j-1];
				dp[r][j] %= MOD;
			} else {
				dp[r][j] += dp[r-1][j];
				dp[r][j] %= MOD;
			}
			bit <<= 1;
		}
	}
}

