  }
  else {
    if (i == 0) {
      int sum;
      rad[i] = false;
      sum = dfs(i + 1, w);
      rad[i] = true;
      sum += dfs(i + 1, w);
      return sum;
    }
    else {
      int sum = 0;
      if (rad[i - 1]){
        rad[i] = false;
        sum = dfs(i + 1, w);
      }
      else {
        rad[i] = false;
        sum = dfs(i + 1, w);
        rad[i] = true;
        sum += dfs(i + 1, w);
      }
      return sum;
    }
  }
}

void co(int w) {
  for (int i  = 0; i < 2 * w - 1; i++) {
    if (i % 2 == 0) {
      int above = (w - 2) - (i / 2);
      int below = (i / 2) - 1;
      coef[i] = dfs(0, above) * dfs(0, below); 
    }
    else {
      int above = (w - 3) - (i / 2);
      int below = (i / 2) - 1;
      coef[i] = dfs(0, above) * dfs(0, below);
    }
  }
}

