void makeLines() {
    int upper = 1 << (W - 1);
    vector<ll> tmp(W - 1);
    for (int b = 0; b < upper; b++) {
        for (int i = 0; i < W - 1; i++) tmp[i] = b >> i & 1;
        bool canLine = true;
        for (int i = 0; i < W - 2; i++) {
            if (tmp[i] + tmp [i + 1] == 2) {
                canLine = false;
                break;
            }
        }
        if (canLine) lines.push_back(tmp);
    }
}
void calcDPTable() {
    dp.assign(H + 1, vector<ll>(W));
    dp[0][0] = 1;
    for (int i = 0; i < H; i++) {
        for (vector<ll> line : lines) {
            for (int j = 0; j < W; j++) {
                if (j > 0 && line[j - 1]) { dp[i + 1][j - 1] += dp[i][j] %= mod; }
                else if (j < W - 1 && line[j]) { dp[i + 1][j + 1] += dp[i][j] %= mod; }
                else { dp[i + 1][j] += dp[i][j] %= mod; }
            }
        }
    }
}

