ll h, w;
bool bitcheck(int x, int y) { return (x >> y) & 1; }
ll memo[101][9];
ll func(ll r, ll c) {
    if (r == 0) {
        if (c == 0) {
            return 1;
        }
        return 0;
    }
    if (memo[r][c] != -1) {
        return memo[r][c];
    }
    ll ret = 0;
    REP(i, 1 << (w - 1)) {
        bool flag = false;
        rep(j, 1, w - 1) {
            if (bitcheck(i, j) && bitcheck(i, j - 1)) {
                flag = true;
            }
        }
        if (flag) {
            continue;
        }
        if (c > 0 && bitcheck(i, c - 1)) {
            ret += func(r - 1, c - 1);
        } else if (c < w - 1 && bitcheck(i, c)) {
            ret += func(r - 1, c + 1);
        } else {
            ret += func(r - 1, c);
        }
        ret %= mod;
    }
    memo[r][c] = ret;
    return memo[r][c];
}
signed main() {
    Fill(memo, -1);
    ll k;
    cin >> h >> w >> k;
    cout << func(h, k - 1) % mod << endl;
}

