  dp[0][0] = 1;
  rep(i, h) rep(j, bit32(w - 1)) {
    bool ok = true;
    rep(k, w - 2) {
      if ((bit32(k) & j) && (bit32(k + 1) & j)) {
        ok = false;
      }
    }
    if (!ok) {
      continue;
    }
    rep(k, w) {
      int a = (k == w - 1) ? 0 : ((bit32(k) & j) ? 1 : 0);
      int b = (k == 0) ? 0 : ((bit32(k - 1) & j) ? 1 : 0);
      if (a) {
        dp[i + 1][k + 1] += dp[i][k];
      } else if (b) {
        dp[i + 1][k - 1] += dp[i][k];
      } else {
        dp[i + 1][k] += dp[i][k];
      }
    }
  }
  cout << dp[h][k - 1] << endl;
}

