signed main() {
    int H, W, K;
    cin >> H >> W >> K;
    K--;

    vector<vector<int>> dp(H+1, vector<int>(W, 0));

    dp[H][K] = 1;

    for (int i = H - 1; i >= 0; i--) {
        for (int j = 0; j < (1 << (W - 1)); j++) {
            bool skip = false;
            for (int k = 0; k < H - 1; k++) {
                if ((j >> k) & 1 && (j >> (k + 1) & 1)) skip = true;
            }
            if (skip) continue;

            for (int k = 0; k < W; k++) {
                if (k > 0 && (j >> (k-1)) & 1) { // 左にあみだ
                    dp[i][k] += dp[i+1][k-1];
                } else if (k < W - 1 && (j >> k) & 1) { // 右にあみだ
                    dp[i][k] += dp[i+1][k+1];
                } else { // 左右にあみだなし
                    dp[i][k] += dp[i+1][k];
                }

                dp[i][k] %= MOD;
            }

        }
    }

    cout << dp[0][0] << endl;

    return 0;
}

