          others(j-2)*others(W-j-2)*dp[i-1][j-1] % p) % p;
      } else if (j == 0 && j < W-1) {
        dp[i][j] = (others(j-1)*others(W-j-3)*dp[i-1][j+1] % p +
          others(j-1)*others(W-j-2)*dp[i-1][j] % p) % p;
      } else if (j > 0 && j >= W-1) {
        dp[i][j] = (others(j-1)*others(W-j-2)*dp[i-1][j] % p +
          others(j-2)*others(W-j-2)*dp[i-1][j-1] % p) % p;
      } else {
