	std::vector<int> vec(W);
	for (int i : boost::irange(0, 1 << (W - 1)))
	{
		for (int k : boost::irange(0, W))
		{
			vec[k] = k;
		}
		for (int k : boost::irange(0, W - 1))
		{
			if (i&(1 << k))
			{
				if (vec[k] != k)
				{
					goto next;
				}
				std::swap(vec[k], vec[k + 1]);
			}
		}
		for (int k : boost::irange(0, W))
		{
			dual[k][vec[k]] += 1;
		}
