ll rec(int r, int c){
    if(r == H){
        return c == K;
    }

    if(dp2[r][c] != -1){
        return dp2[r][c];
    }

    ll cnt = 0;

    if(c == 0 || c == W - 1){
        cnt = dp1[std::max(W-2, 0)] * rec(r + 1, c) % MOD;
    }else{
        cnt = dp1[std::max(c-1, 0)] * dp1[std::max(W-c-2, 0)] % MOD * rec(r + 1, c) % MOD;
    }

    if(c + 1 < W){
        cnt = (cnt + dp1[std::max(c-1, 0)] * dp1[std::max(W-c-3, 0)] % MOD * rec(r + 1, c + 1) % MOD) % MOD;
    }

    if(c - 1 >= 0){
        cnt = (cnt + dp1[std::max(c-2, 0)] * dp1[std::max(W-c-2, 0)] % MOD * rec(r + 1, c - 1) % MOD) % MOD;
    }

    return dp2[r][c] = cnt;
}

