/////////////         modの計算

static int mod = 1000000007;
int mod_add(int a, int b) {
	long long k = a%mod; k += b%mod; k %= mod;
	return k;
}
int mod_sub(int a, int b) {
	long long k = a%mod; k += (mod - (b%mod)) % mod; k %= mod;
	return k;
}
int mod_multi(int a, int b) {
	long long k = a%mod; k *= b%mod; k %= mod;
	return k;
}
int mod_div(int a, int b) {
	int X = mod, Y = b, X1 = 1, X2 = 0, Y1 = 0, Y2 = 1;
	while (1) {
		int q = X / Y;
		int r = X - Y*q;
		X1 = mod_sub(X1, mod_multi(q, Y1));
		X2 = mod_sub(X2, mod_multi(q, Y2));

		if (a%r == 0) {
			int k = a / r;
			return mod_multi(X2, k);
		}

		int z;
		z = X1; X1 = Y1; Y1 = z;
		z = X2; X2 = Y2; Y2 = z;
		X = Y; Y = r;
	}
}
int mod_combination(int n, int r) {
	int a = 1, b = 1;
	for (int i = 1; i <= r; i++) {
		a = mod_multi(a, n - i + 1);
		b = mod_multi(b, i);
	}
	return mod_div(a, b);
}

int __n[8] = { 0,0,2,3,5,8,13,21 };
int product(int a, int b, int W) {
	if (__n[a] == 0) {
		return __n[W - 1 - b];
	}
	if (__n[W - 1 - b] == 0) {
		return __n[a];
	}
	return __n[a] * __n[W - 1 - b];
}
int main() {
