	}
	n1[0] = 1;

	for (int i = 0; i < H; i++) {
		for (int x = 0; x < W; x++) {
			n2[x] = mod_multi(n1[x], product(x, x, W));

			if (x > 0) {
				n2[x] = mod_add(n2[x], mod_multi(n1[x - 1], product(x - 1, x, W)));
			}
			if (x < W - 1) {
				n2[x] = mod_add(n2[x], mod_multi(n1[x + 1], product(x, x + 1, W)));
			}
		}
		for (int x = 0; x < W; x++) {
			n1[x] = n2[x];
		}
	}

	cout << n1[K - 1];
	delete[] n1;
	delete[] n2;
	return 0;
