  REP(_, y) {
    res *= x;
    res %= MOD;
  }
  return res;
}

lint take(vector<vector<lint>>& DP, lint h, lint w, lint W) {
  if(DP[h][w] != -1) {
    return DP[h][w];
  }

  if(w == 0) {
    lint right = take(DP, h-1, w+1, W)*modpow(2, W-3)%MOD;
    lint straight = take(DP, h-1, w, W)*modpow(2, W-2)%MOD;
    lint res = right + straight;
    res %= MOD;
    DP[h][w] = res;
    return res;
  }

  if(w == W-1) {
    lint right = take(DP, h-1, w-1, W)*modpow(2, W-3)%MOD;
    lint straight = take(DP, h-1, w, W)*modpow(2, W-2)%MOD;
    lint res = right + straight;
    res %= MOD;
    DP[h][w] = res;
    return res;
  }
  lint right = take(DP, h-1, w+1, W)*modpow(2, W-4)%MOD;
  lint left = take(DP, h-1, w-1, W)*modpow(2, W-4)%MOD;
  lint straight = take(DP, h-1, w, W)*modpow(2, W-3)%MOD;
  lint res = left + right + straight;
  res %= MOD;

  DP[h][w] = res;
  return res;

}

