#include <bits/stdc++.h>
using namespace std;
#define rep(i,n) for (int i=0; i<(int)(n); ++i)
using ll = long long;
using vi = vector<int>;
using vl = vector<ll>;
using Graph = vector<vl>;  // vi <=> vl
using P = pair<int, int>;  // int <=> ll
const int MOD = 1e9+7;
const double EPS = 1e-9;

ll combination(int n, int r) {
  if (n < r) return 0;
  if (n-r < r) r = n-r;
  if (r == 0) return 1;
  if (r == 1) return n;
  vi numerator(r), denominator(r);
  rep(i,r) {
    numerator[i] = n-r+i+1;
    denominator[i] = i+1;
  }
  for (int p=2; p<=r; ++p) {
    int pivot = denominator[p-1];
    if (pivot > 1) {
      int offset = (n-r)%p;
      for (int j=p-1; j<r; j+=p) {
        numerator[j-offset] /= pivot;
        denominator[j] /= pivot;
      }
    }
  }
  ll ret = 1;
  rep(i,r) (ret *= numerator[i]) %= MOD;
  return ret;
}

void solve() {
  int H, W, K; cin >> H >> W >> K;

  Graph G(H+1, vl(W+2, 0));
  G[0][1] = 1;

  vector<vi> comb(W+1, vi(W+1));  // nCr = comb[n][r]
  rep(i,W+1) rep(j,W+1) comb[i][j] = combination(i,j);

  vi draw(W, 0);
  rep(i,W) rep(j,(i/2)+1) draw[i] += comb[i-j][j];

  for (int i=1; i<=H; ++i) {
    for (int j=1; j<=W; ++j) {
      // stay
      (G[i][j] += G[i-1][j] * draw[j-1] * draw[W-j]) %= MOD;
      // ->
      (G[i][j] += G[i-1][j-1] * draw[j-2] * draw[W-j]) %= MOD;
      // <-
      (G[i][j] += G[i-1][j+1] * draw[j-1] * draw[W-j-1]) %= MOD;
    }
  }

  cout << G[H][K] << endl;
  return;
}

int main() {
  solve();
  return 0;
}

