bool is_valid_bit_set(int bit_set, int W){
    for(int i = 0; i < W - 2; i++){
        if(((((bit_set >> i)) & 1) == 1) && (((bit_set >> (i + 1)) & 1) == 1)){
            return false;
        }
    }
    return true;
}

bool is_zero_bit(int bit_set, int pos){
    if(((bit_set >> pos) & 1) == 1){
        return false;
    }
    return true;
}

