constexpr int mod = 1e9 + 7;
constexpr int wlim = 10, hlim = 100;

ll dp[hlim+1][wlim+1];

ll fib(int n){
  if(n == 0 || n == 1) return 1;
  else return fib(n-1) + fib(n-2);
}

tp calcWeight(int i, int w){
  tp ret {0, 0, 0};

  get<1>(ret) = (fib(i-1) * fib(w-i)) % mod;
  if(i != 1) get<0>(ret) = (fib(i-2) * fib(w-i)) % mod;
  if(i != w) get<2>(ret) = (fib(i-1) * fib(w-i-1)) % mod;
  return ret;
}

int main(){
  int h, w, k; cin >> h >> w >> k;

  dp[0][1] = 1;

  FOR(i, 0, h)FOR(j, 1, w+1){
    tp weight = calcWeight(j, w);
    (dp[i+1][j-1] += (get<0>(weight) * dp[i][j]) % mod) %= mod;
    (dp[i+1][j] += (get<1>(weight) * dp[i][j]) % mod) %= mod;
    (dp[i+1][j+1] += (get<2>(weight) * dp[i][j]) % mod) %= mod;
  }

  cout << dp[h][k] << endl;

  return 0;
}

