#define NTH_BIT(bits, i) ((((bits) >> (i) & 1)))

int main()
{
  // 1 <= H <= 100, 1 <= K <= W <= 8
  cin >> H >> W >> K;

  ll dp[9][101] = {};
  dp[0][0] = 1;

  for (int h = 1; h <= H; h++) {
    for (int bits = 0; bits < (1 << (W - 1)); bits++) {
      for (int w = 0; w < W - 1; w++) {
        if (NTH_BIT(bits, w) != 0 && NTH_BIT(bits, w + 1) != 0) {
          goto next; // 条件に合わなかったのでやりなおし
        }
      }

      for (int w = 0; w < W; w++) {
        if (0 < w && NTH_BIT(bits, w - 1)) {
          dp[w][h] += dp[w - 1][h - 1];
        } else if (w < W - 1 && NTH_BIT(bits, w)) {
          dp[w][h] += dp[w + 1][h - 1];
        } else {
          dp[w][h] += dp[w][h - 1];
        }
      }

      next: ;
    }
    for (int w = 0; w < W; w++) {
      dp[w][h] %= 1000000007;
    }
  }

  cout << dp[K-1][H] << endl;
}

