ll memo[10];
ll me(int n) {
  if (n == 0) {
    return 1;
  } else if (n == 1) {
    return 1;
  } else {
    if (memo[n-1] == -1) memo[n-1] = me(n-1);
    if (memo[n-2] == -1) memo[n-2] = me(n-2);
    memo[n] = memo[n-1] + memo[n-2];
    return memo[n];
  }
}

