      ll cur = dp[h-1][w];

      if ((w-1) > 0) {
        dp[h][w-1] += cur * me(w-2) * me(W-w);
        dp[h][w-1] %= MOD;
      }
      if ((w+1) <= W) {
        dp[h][w+1] += cur * me(w-1) * me(W-w-1);
        dp[h][w+1] %= MOD;
      }
      dp[h][w] += cur * me(w-1) * me(W-w);
      dp[h][w] %= MOD;
    }
