                if(flag) {  // 2つの横棒が端点を共有するときはダメ
                    continue;
                }

                // 右から左に横棒を通過する場合
                if(j > 0 && v[j-1]) {
                    dp[i+1][j-1] += dp[i][j];
                    dp[i+1][j-1] %= mod;
                }
                // 左から右に横棒を通過する場合
                else if(j < w-1 && v[j]) {
                    dp[i+1][j+1] += dp[i][j];
                    dp[i+1][j+1] %= mod;
                }
                // 横棒を通過しない場合
                else {
                    dp[i+1][j] += dp[i][j];
                    dp[i+1][j] %= mod;
                }
            }
        }
    }

    out(dp[h][K]);
    re0;
}

