int main() {
    ll h, w, k;
    cin >> h >> w >> k;
    if(w == 1) {
        cout << 1 << endl;
        return 0;
    }
    vector<int> pm(w);
    for(int i = 0; i < w; i++) {
        pm[i] = i;
    }
    vector<vector<int>> pats;
    for(int i = 0; i < (1LL << (w - 1)); i++) {
        auto tmp = tobit(i, w - 1);
        bool flag = true;
        for(int j = 0; j < tmp.size() - 1; j++) {
            if(tmp[j] == 1 && tmp[j + 1] == 1) {
                flag = false;
                break;
            }
        }
        if(flag) {
            pats.push_back(tmp);
        }
    }
    vector<vector<int>> state;
    do {
        state.push_back(pm);
    } while(next_permutation(all(pm)));

    int sn = state.size();
    vector<vector<int>> seni(sn);
    map<vector<int>, int> mp;
    for(int i = 0; i < state.size(); i++) {
        mp[state[i]] = i;
    }
    for(int i = 0; i < state.size(); i++) {
        for(auto &pat : pats) {
            auto next = state[i];
            for(int x = 0; x < pat.size(); x++) {
                if(pat[x] == 1) {
                    swap(next[x], next[x + 1]);
                }
            }
            seni[i].push_back(mp[next]);
        }
    }
    vector<vector<ll>> dp(h + 1, vector<ll>(sn, 0));
    dp[0][0] = 1;
    for(int i = 0; i < h; i++) {
        for(int j = 0; j < sn; j++) {
            for(int x = 0; x < seni[j].size(); x++) {
                dp[i + 1][seni[j][x]] += dp[i][j];
                dp[i + 1][seni[j][x]] %= MOD;
            }
        }
    }
    k--;
    ll ans = 0;
    for(int i = 0; i < sn; i++) {
        if(state[i][k] == 0) {
            ans += dp[h][i];
            ans %= MOD;
        }
    }
    cout << ans << endl;
}

