void solve(istream &cin) {
    ll H, W, K;
    cin >> H >> W >> K;
    if(!cin) return;
    K--;

    vector<vector<ll>> s_to_s(W,vector<ll>(W));
    for (int i = 0; i < W; ++i) {
        s_to_s[i][i] = 1;
    } // end i
    vector<int> perm(W); iota(perm.begin(), perm.end(), 0);
    do{
        auto sw = split_swap(perm);
        if(!sw.empty()){
            for (auto &&p : sw) {
                s_to_s[p.first][p.second]++;
                s_to_s[p.second][p.first]++;
            } // end p
            for (int i = 0; i < perm.size(); ++i) {
                if(i == perm[i]){
                    s_to_s[i][i]++;
                }
            } // end i
        }
    }while(next_permutation(perm.begin(), perm.end()));

    vector<RCR> dp(W);
    dp[0] = 1;
    for (int i = 0; i < H; ++i) {
        vector<RCR> dp2(W);
        for (int i = 0; i < W; ++i) {
            for (int j = 0; j < W; ++j) {
                dp2[i] += dp[j] * s_to_s[j][i];
            } // end j
        } // end i
        dp = dp2;
    } // end i
    cout << dp[K] << endl;

}

