using namespace std;



int main(){
    Init();
    // 入力(0-Based)
    ll h, w, k;
    cin >> h >> w >> k; k--;

    if(w == 1){
        cout << 1 << endl;
        return 0;
    }

    // 2^wroot[i][j]; i列目からj列目に行ける本数
    vvi root(w+1, vi(w+1, 0));
    for(ll i=0; i<(1LL<<w-1); i++){
        vi line(w-1, 0);
        for(ll m=0; m<w-1; m++){
            if(i&(1LL<<m)){
                if(m == 0) line[m] = 1;
                else if(line[m-1] == 0) line[m] = 1;
                else{
                    line[0] = INFLL;
                    break;
                }
            }
        }
        if(line[0] == INFLL) continue;
        for(ll m=0; m<w-1; m++){
            if(line[m] == 1){
                root[m][m+1]++;
                root[m+1][m]++;
            }
            else{
                if(m == 0) root[m][m]++;
                else{
                    if(m == w-2) root[w-1][w-1]++;
                    if(line[m-1] == 0) root[m][m]++;
                }
            }
        }
    }

    // dp[i][j]; i行j列にいる場合の数
    vvi dp(h+2, vi(w+2, 0)); dp[0][0]++;
    for(ll i=0; i<=h; i++){
        for(ll j=0; j<=w; j++){
            dp[i+1][j] += (dp[i][j]*root[j][j])%MODV;
            dp[i+1][j+1] += (dp[i][j]*root[j][j+1])%MODV;;
            if(j != 0) dp[i+1][j-1] += (dp[i][j]*root[j][j-1])%MODV;
        }
    }
    cout << dp[h][k]%MODV << endl;
}

