    finv.resize(mint_len);
    inv.resize(mint_len);
    inv[1] = fac[0] = finv[0] = 1;
    for (int i = tn; i < mint_len; ++i) inv[i] = inv[MOD % i] * (MOD - MOD / i) % MOD;
