            dp_only_side[i][j+1] += dp[i][j];
            dp_only_side[i][j-1] += dp[i][j];
        }
        for(int j = 1; j <= w; j++){
            dp[i+1][j] += (dp[i][j] + dp_only_side[i][j]);
        }
