long long twoSqr[11];

void init()
{
	twoSqr[0] = 1;
	twoSqr[1] = 1;
	for (int i = 2 ; i < 11 ; i++)
		twoSqr[i] = twoSqr[i - 1] * 2;
}

int main()
{
	init();

	scanf("%d%d%d", &h, &w, &k);

	for (int i = 0 ; i < 15 ; i++)
		f[1][i] = 0;
	f[1][1] = 1;

	for (int i = 2 ; i <= h + 1 ; i++)
	{
		for (int j = 1 ; j <= w ; j++)
		{
			long long a, b, c;
			long long countL, countR;
			long long wl, wr;
			//与左侧链接 
			countL = (j - 1) - 1;	//((j-1)-1)-1
			wl = countL < 0 ? 0 : twoSqr[countL];
			countR = w - j;
			wr = countR < 0 ? 0 : twoSqr[countR];
			a = f[i - 1][j - 1] * ((wl * wr) % MOD) % MOD;

			//与右侧链接
			countL = j - 1;
			wl = countL < 0 ? 0 : twoSqr[countL];
			countR = w - (j + 1);
			wr = countR < 0 ? 0 : twoSqr[countR];
			c = f[i - 1][j + 1] * ((wl * wr) % MOD) % MOD;

			//中间直接
			countL = j - 1;
			wl = countL < 0 ? 0 : twoSqr[countL];
			countR = (w - j);
			wr = countR < 0 ? 0 : twoSqr[countR];
			b = f[i - 1][j] * ((wl * wr) % MOD) % MOD;

			f[i][j] = (a + b + c) % MOD;
		}
	}

	printf("%lld\n", f[h + 1][k]);

	return 0;
}

