const long long MOD = 1000000007;

void solve(long long H, long long W, long long K){
	vector<vector<long long>> input;
	for (int i = 0; i < (1 << (W-1)); ++i) {
		vector<long long> now;
		int top = i;
		for (int q = 0; q < W; ++q) {
			now.push_back(top % 2);
			top /= 2;
		}
		int tere = 0;
		for (int q = 1; q < W; ++q) {
			if (now[q] == 1 && now[q - 1] == 1) tere = 1;
		}
		if (tere == 0) input.push_back(now);
	}
	long long ans[10] = {};
	ans[0] = 1;
	for (int i = 0; i < H; ++i) {
		int next_ans[10] = {};
		for (int q = 0; q < input.size(); ++q) {
			for (int j = 0; j < W; ++j) {
				if (input[q][j] == 1) {
					next_ans[j + 1] += ans[j];
					next_ans[j + 1] %= MOD;
				}else
				if (j != 0 && input[q][j - 1] == 1) {
					next_ans[j - 1] += ans[j];
					next_ans[j - 1] %= MOD;
				}
				else {
					next_ans[j] += ans[j];
					next_ans[j] %= MOD;
				}
				next_ans[j] %= MOD;
			}
		}
		REP(q, 10) {
			ans[q] = next_ans[q] % MOD;
		}
	}
	cout << ans[K - 1]%MOD << endl;
}

