    tdp[0][0] = 1;
    tdp[1][0] = 1;
    tdp[1][1] = 1;

    for (i64 i = 2; i <= w; i++) {
        tdp[i][0] = tdp[i - 1][0] + tdp[i - 1][1];
        tdp[i][1] = tdp[i - 1][0];
    }
}

i64 f(i64 x) {
    return tdp[x][0] + tdp[x][1];
}

i64 L[10];
i64 R[10];
i64 E[10];

void fill_pre(i64 w) {
    for (i64 i = 1; i <= w; i++) {
        i64 l = max(0ll, i - 3);
        i64 r = max(0ll, w - (i + 1));

        L[i] = f(l) * f(r);
    }

    for (i64 i = 1; i <= w; i++) {
        i64 l = max(0ll, i - 2);
        i64 r = max(0ll, w - (i + 2));

        R[i] = f(l) * f(r);
    }

    for (i64 i = 1; i <= w; i++) {
        i64 l = max(0ll, i - 2);
        i64 r = max(0ll, w - (i + 1));

        E[i] = f(l) * f(r);
    }
}

int main() {
    i64 h, w, k;
    cin >> h >> w >> k;

    fill_cnk();
    //cerr << C[100][50] << endl;

    fill_tdp(w);
    //for (i64 i = 0; i <= 8; i++) {
    //    cerr << i << ": " << f(i) << endl;
    //}

    fill_pre(w);

    dp[0][1] = 1;

    for (i64 y = 1; y <= h; y++) {
        for (i64 x = 1; x <= w; x++) {
            if (x > 1) {
                dp[y][x - 1] += (dp[y - 1][x] * L[x]) % mod;
                dp[y][x - 1] %= mod;
            }

            if (x < w) {
                dp[y][x + 1] += (dp[y - 1][x] * R[x]) % mod;
                dp[y][x + 1] %= mod;
            }

            dp[y][x] += (dp[y - 1][x] * E[x]) % mod;
            dp[y][x] %= mod;
        }
    }

    cout << dp[h][k];

    return 0;
}

