const int INF = 1e18;
const int MOD_N = 1e9+7;

struct ModRing {
   int mod, x;
   // constructor
   ModRing(int mod_n) : mod(mod_n), x(0) {}
   ModRing(int a, int mod_n) : mod(mod_n) { x = ((a % mod) + mod) % mod; }

   // methods
   ModRing& operator=(int a) {
      return *this = ModRing(a, mod);
   }
   ModRing operator-() const {
      return ModRing((-x + mod) % mod, mod);
   }
   ModRing& operator+=(const ModRing& a) {
      (x += a.x) %= mod;
      return *this;
   }
   ModRing& operator-=(const ModRing& a) {
      return *this += -a;
   }
   ModRing& operator*=(const ModRing& a) {
      (x *= a.x) %= mod;
      return *this;
   }
   const ModRing operator+(const ModRing& a) const {
      return ModRing(x, mod) += a;
   }
   const ModRing operator-(const ModRing& a) const {
      return ModRing(x, mod) -= a;
   }
   const ModRing operator*(const ModRing& a) const {
      return ModRing(x, mod) *= a;
   }
   ModRing& operator+=(int a) {
      return *this += ModRing(a, mod);
   }
   ModRing& operator-=(int a) {
      return *this -= ModRing(a, mod);
   }
   ModRing& operator*=(int a) {
      return *this *= ModRing(a, mod);
   }
   const ModRing operator+(int a) const {
      return ModRing(x, mod) += a;
   }
   const ModRing operator-(int a) const {
      return ModRing(x, mod) -= a;
   }
   const ModRing operator*(int a) const {
      return ModRing(x, mod) *= a;
   }
   const ModRing power(int n) const {
      ModRing tmp(x, mod), res(1, mod);
      while (n > 0) {
         if ((n & 1) == 1) res *= tmp;
         tmp *= tmp;
         n >>= 1;
      }
      return res;
   }
};
auto&operator<<(ostream&s,const ModRing&a){s<<a.x;return s;}
struct FiniteField : ModRing {
   // constructor
   FiniteField(int mod_n) : ModRing(mod_n) {}
   FiniteField(int a, int mod_n) : ModRing(a, mod_n) {}
   FiniteField(const ModRing& a) : ModRing(a) {}

   // super class
   FiniteField& operator=(int a) {
      return *this = FiniteField(ModRing::operator=(a));
   }
   FiniteField operator-() const {
      return FiniteField(ModRing::operator-());
   }
   FiniteField& operator+=(const FiniteField& a) {
      return *this = FiniteField(ModRing::operator+=(a));
   }
   FiniteField& operator-=(const FiniteField& a) {
      return *this = FiniteField(ModRing::operator-=(a));
   }
   FiniteField& operator*=(const FiniteField& a) {
      return *this = FiniteField(ModRing::operator*=(a));
   }
   const FiniteField operator+(const FiniteField& a) const {
      return FiniteField(ModRing::operator+(a));
   }
   const FiniteField operator-(const FiniteField& a) const {
      return FiniteField(ModRing::operator-(a));
   }
   const FiniteField operator*(const FiniteField& a) const {
      return FiniteField(ModRing::operator*(a));
   }
   FiniteField& operator+=(int a) {
      return *this = FiniteField(ModRing::operator+=(a));
   }
   FiniteField& operator-=(int a) {
      return *this = FiniteField(ModRing::operator-=(a));
   }
   FiniteField& operator*=(int a) {
      return *this = FiniteField(ModRing::operator*=(a));
   }
   const FiniteField operator+(int a) const {
      return FiniteField(ModRing::operator+(a));
   }
   const FiniteField operator-(int a) const {
      return FiniteField(ModRing::operator-(a));
   }
   const FiniteField operator*(int a) const {
      return FiniteField(ModRing::operator*(a));
   }
   const FiniteField power(int n) const {
      return FiniteField(ModRing::power(n));
   }

   // methods
   FiniteField inverse() const {
      try { if (x == 0) throw "0 have no inverse"; }
      catch (const char* e) { cerr << e << endl; }
      return power(mod-2);
   }
   FiniteField& operator/=(const FiniteField& a) {
      // *this *= a.inverse();
      // return *this;
      return *this *= a.inverse();
   }
   const FiniteField operator/(const FiniteField& a) const {
      return FiniteField(x, mod) /= a;
   }
   FiniteField& operator/=(int a) {
      return *this /= FiniteField(a, mod);
   }
   const FiniteField operator/(int a) const {
      return FiniteField(x, mod) /= a;
   }
};
