        cout << 1 << endl;
        return 0;
    }
    for (int I = 0; I <= h; ++I) {
        for (int J = 0; J < w; ++J) {
            for (int bit = 0; bit < (1<<(w-1)); ++bit) {
                bitset<7> st(bit);
                bool nex = false;
                if (w != 2) {
                    for (int i = 1; i < 8; ++i) {
                        if (st[i] && st[i-1]) {
                            nex = true;
                            break;
                        }
                    }
                }
