                if (J-1 >= 0 && J+1 < w) {
                    if (!st[J-1] && !st[J]) dp[I+1][J] = (dp[I+1][J]+dp[I][J])%MOD;
                    else if (st[J-1] && !st[J]) dp[I+1][J] = (dp[I+1][J]+dp[I][J-1])%MOD;
                    else if (!st[J-1] && st[J]) dp[I+1][J] = (dp[I+1][J]+dp[I][J+1])%MOD;
                    else if (st[J-1] && st[J]) dp[I+1][J] = (dp[I+1][J]+(dp[I][J+1]+dp[I][J-1])%MOD)%MOD;
                }
                else if (J-1 >= 0 && J+1 >= w) {
                    if (!st[J-1]) dp[I+1][J] = (dp[I+1][J]+dp[I][J])%MOD;
                    else if (st[J-1]) dp[I+1][J] = (dp[I+1][J]+dp[I][J-1])%MOD;
                }
                else if (J-1 < 0 && J+1 < w) {
                    if (!st[J]) dp[I+1][J] = (dp[I+1][J]+dp[I][J])%MOD;
                    else if (st[J]) dp[I+1][J] = (dp[I+1][J]+dp[I][J+1])%MOD;
