bool invalid(ll ptn)
{
    ll prev_bit = 1e18;
    while (ptn) {
        ll bit = (ptn & -ptn);
        if ((bit>>1LL) == prev_bit) return true;
        prev_bit = bit;
        ptn &= ~bit;
    }
    return false;
}

void _main()
{
