    rep (xx, h) {

        ll dp_prev[10];
        memcpy(dp_prev, dp, sizeof(dp_prev));
        memset(dp, 0, sizeof(dp));

        rep (ptn, (1LL<<(w-1))) {
            if (invalid(ptn)) continue;
            rep (ww, w) {
                if (ww && (ptn & (1LL<<(ww-1)))) {
                    dp[ww-1] += dp_prev[ww];
                    dp[ww-1] %= MOD;
                }
                else if ((ww < w-1) && (ptn & (1LL<<ww))) {
                    dp[ww+1] += dp_prev[ww];
                    dp[ww+1] %= MOD;
                }
                else {
                    dp[ww] += dp_prev[ww];
                    dp[ww] %= MOD;
                }
            }
        }
    }

