ll solve()
{

    ll h, w, k;
    cin >> h >> w >> k;

    dp[0][0] = 1;
    for (int i = 0; i < h; i++)
    {
        for (int j = 0; j < w; j++)
        {
            w--;
            for(int k=0; k < (1 << w); k++){
                bool f = false;
                for(int t=0; t < w - 1; t++){
                    if((k & ( 1 << t)) && (k & (1 <<(t + 1)))){
                        f = true;
                    }
                }
                if(f){
                    continue;
                }

                if(k & ( 1 << j)){
                    dp[i + 1][j + 1] += dp[i][j];
                    dp[i + 1][j + 1] %= MOD;
                }else if(k & (1 << (j - 1)) && j != 0){
                    dp[i + 1][j - 1] += dp[i][j];
                    dp[i + 1][j - 1] %= MOD;
                }else{
                    dp[i + 1][j] += dp[i][j];
                    dp[i + 1][j] %= MOD;
                }

            }
            w++;
        }
    }

    cout << dp[h][k - 1] << endl;
    return 0;
}

