typedef long long LL;

#define REP(i, n) for (int i = 0; i < (int)(n); i++)
#define FOR(i, a, b) for (int i = (a); i < (b); ++i)
#define ALL(x) (x).begin(), (x).end()
const int IINF = 1e9;
const LL LINF = 1e18;
const LL mod = 1e9 + 7;

bool check(int x) {
    bool p = false;
    bool res = true;
    for(;x;) {
        bool q = p;
        p = x&1 == 1;
        res = res && !(p&&q);
        x = x>>1;
    }
    return res;
}

int main() {
    LL H, W, K;
    cin >> H >> W >> K;
    vector<vector<LL>> dp(H + 1, vector<LL>(W, 0));
    dp[0][0] = 1;
    FOR(i, 1, H + 1) {
        REP(j, W) {
            // k のxビット目が立っている <=> 縦棒x,x+1間が繋がっている
            REP(k, 1<<(W - 1)) {
                bool p = check(k);
                if(p) {
                    int left = k&(1<<(j - 1));
                    int right = k&(1<<j);

                    if(j + 1 < W && right) {
                        dp[i][j] = (dp[i][j] + dp[i - 1][j + 1])%mod;
                    }else if(0 <= j - 1 && left){
                        dp[i][j] = (dp[i][j] + dp[i - 1][j - 1])%mod;
                    }else if((j == 0 || left == 0) && (j == W - 1 || right == 0)) {
                        dp[i][j] = (dp[i][j] + dp[i - 1][j])%mod;
                    }
                }
            }
        }
    }
    cout << dp[H][K - 1] << endl;
    return 0;
}

