      }
      if (!judge) continue;
      for (int k = 0; k < W; k++) {
        if ((j >> k) & 1)
          dp[i + 1][k + 1] += dp[i][k];
        else if (k > 0 && ((j >> (k - 1)) & 1))
          dp[i + 1][k - 1] += dp[i][k];
        else
          dp[i + 1][k] += dp[i][k];
      }
    }
  }
  // for (auto &col : dp) cout << col << endl;
  cout << dp[H][K] << endl;
  return;
