void solve() {
	int H, W, K; cin >> H >> W >> K;
	vector<bitset<10>> bits;

	REP(i, (1 << (W-1))) {
		bitset<10> bit = i;
		bool f = true;
		REP(i, bit.size()-1) {
			if (bit[i] == true and bit[i + 1] == true) {
				f = false;
				break;
			}
		}
		if (not f) continue;
		bits.push_back(bit);
	}

	vector<int> cnt(W);
	cnt[0] = 1;

	vector<int> old = cnt;
	REP(_, H) {
		cnt = vector<int>(cnt.size());
		for (auto bit : bits) {
			vector<int> temp = old;
			REP(i, bit.size()) {
				if (bit[i]) {
					swap(temp[i], temp[i + 1]);
				}
			}
			REP(i, old.size()) {
				cnt[i] += temp[i];
				cnt[i] %= MOD;
			}
		}
		swap(old, cnt);
	}

	cout << old[K-1] << endl;
}

