constexpr long long int mod = 1'000'000'007;

long long int H, W, K;
vector<long long int> tmp = {1, 1, 2, 3, 5, 11, 17, 24, 36};

long long int calcPattern(long long int h, long long int w, long long int k, long long int res) {
    if(w == 1) {
        return res;
    } else if(h == 1) {
        if(k == 1) {
            return tmp[w-1];
        } else if(k == 2) {
            return tmp[w-2];
        } else {
            return 0;
        }
    } else {
        if(k == 1) {
            return ((calcPattern(h-1LL, w, k, res) * tmp[w-1LL]) % mod + (calcPattern(h-1LL, w, k+1LL, res) * tmp[w-2LL]) % mod) % mod;
        } else if(k == W) {
            return ((calcPattern(h-1LL, w, k, res) * tmp[w-1LL]) % mod + (calcPattern(h-1LL, w, k-1LL, res) * tmp[w-2LL]) % mod) % mod;
        } else {
            return ((calcPattern(h-1LL, w, k-1LL, res) * tmp[k-2LL] * tmp[W-k]) % mod + (calcPattern(h-1LL, w, k, res) * tmp[w-1LL]) % mod + (calcPattern(h-1LL, w, k+1LL, res) * tmp[k-1LL] * tmp[w-k-1LL]) % mod) % mod;
        }
    }
}

