typedef long long ll;

const int  mod = 1000000007;

struct mint{
    ll x;
    mint (ll x=0) : x((x%mod+mod)%mod){}//カッコの中で初期化している
    mint& operator+=(const mint a){//operatorは構造体同士の比較に用いられる
        if((x +=a.x)>=mod) x-=mod;
        return *this;//thisとは現在のオブジェクトのこと
    }
    mint& operator-=(const mint a){
        if((x +=mod-a.x)>=mod) x-=mod;
        return *this;
    }
    mint& operator*=(const mint a){
        (x*=a.x)%=mod;
        return *this;
    }
    mint operator+(const mint a){
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a){
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a){
        mint res(*this);
        return res*=a;
    }
    mint pow(ll t) const{
        if(!t) return 1;
        mint a=pow(t>>1);
        a*=a;
        if(t&1) a*=*this;
        return a;
    }
    mint inv() const{
        return pow(mod-2);//逆元
    }

    mint&operator/=(const mint a) {
        return (*this)*=a.inv();
    }
    mint&operator/(const mint a) const{
        mint res(*this);
        return res/=a;
    }
};

pair<ll, ll> f(int l){
    /*0, 1の順に返している*/
    if(l<1) return pair<ll, ll>(0, 0);
    if(l==1) return pair<ll, ll>(1, 1);
    return pair<ll, ll>(f(l-1).first+f(l-1).second, f(l-1).first);
}

int main(void){
    int h, w, k;
    cin>>h>>w>>k;
    --k;
    vector<vector<mint> > dp(h+1, vector<mint>(w));
    if(w==1) {
        cout<<1<<endl;
        return 0;
    }
    dp[1][0]=f(w-2).first+f(w-2).second;
    dp[1][1]=max((ll)1, f(w-3).first+f(w-3).second);
    for(int i=2;i<=h;i++){
        rep(j, w){
            if(j==0) {
                pair<ll, ll> fw=f(w-2);
                pair<ll, ll> fw_1=f(w-3);
                mint a=dp[i-1][j]*max((ll)1, fw.first+fw.second);
                mint b=dp[i-1][j+1]*max((ll)1, fw_1.first+fw_1.second);
                dp[i][j]=a+b;
            }
            else if(j==w-1) {
                pair<ll, ll> fw=f(w-2);
                pair<ll, ll> fw_1=f(w-3);
                mint a=dp[i-1][j]*max((ll)1, fw.first+fw.second);
                mint b=dp[i-1][j-1]*max((ll)1, fw_1.first+fw_1.second);
                dp[i][j]=a+b;
            }
            else {
                pair<ll, ll> fk=f(j-1);
                pair<ll, ll> fw=f(w-j-2);
                pair<ll, ll> fk_1=f(j-2);
                pair<ll, ll> fw_1=f(w-j-3);
                mint a=dp[i-1][j]*max((ll)1, fk.first+fk.second)*max((ll)1, fw.first+fw.second);
                mint b=dp[i-1][j-1]*max((ll)1, fk_1.first+fk_1.second)*max((ll)1, fw.first+fw.second);
                mint c=dp[i-1][j+1]*max((ll)1, fk.first+fk.second)*max((ll)1, fw_1.first+fw_1.second);
                dp[i][j]=a+b+c;
            }
            //cout<<dp[i][j].x<<", ";
        }
        //cout<<endl;
    }
    cout<<dp[h][k].x<<endl;
    return 0;
}

