                int p = (dp2[j][0] * dp2[W - 2 - j][0]) % mod;
                dp[i + 1][j] += dp[i][j + 1] * p;
                dp[i + 1][j] %= mod;
            }
            int p = (dp2[j][0] * dp2[W - 1 - j][0]) % mod;
            dp[i + 1][j] += dp[i][j] * p;
            dp[i + 1][j] %= mod;
        }
    }
    cout << dp[H][K];

    return 0;
}

