					else {
						dp[i][j][pattern] += ruisekiwa[i - 1][j];
 					}
				}
				else {
					if (pattern & (1 << (j - 1))) {
						dp[i][j][pattern] += ruisekiwa[i - 1][j - 1];
					}
					else if (pattern & (1 << j)) {
						dp[i][j][pattern] += ruisekiwa[i - 1][j + 1];
					}
					else {
						dp[i][j][pattern] += ruisekiwa[i - 1][j];
					}
				}

				dp[i][j][pattern] %= MOD;
				ruisekiwa[i][j] += dp[i][j][pattern];
				ruisekiwa[i][j] %= MOD;
			}

		}
	}

	ll ans = 0;
	for (int j = 0; j < hikikata.size(); j++) {
		ans += dp[H][K - 1][hikikata[j]];
		ans %= MOD;
	}


	cout << ans << endl;

	return 0;
}

