const int MOD = 1000 * 1000 * 1000 + 7;

int subcount(int n)
{
	if (n <= 0) {
		return 1;
	}
	int c = 0;
	for (int i = 0; i < (1 << n); ++i) {
		bool ok = true;
		for (int k = 0; k + 1 < n; ++k) {
			if ((i & (1 << k)) && (i & (1 << (k + 1)))) {
				ok = false;
				break;
			}
		}
		if (ok) {
			++c;
		}
	}
	return c;
}

int main()
{
	int H, W, K;
	cin >> H >> W >> K;

	long long dp[100][8 + 1] = {};
	dp[1][1] = subcount(W - 2);
	dp[1][2] = subcount(W - 3);
	for (int j = 3; j <= W; ++j) {
		dp[1][j] = 0;
	}

	for (int i = 2; i <= H; ++i) {
		for (int j = 1; j <= W; ++j) {
			if (1 < j) {
				dp[i][j - 1] += 1LL * subcount(j - 3) * subcount(W - j - 1) * dp[i - 1][j];
				dp[i][j - 1] %= MOD;
			}
			dp[i][j] += 1LL * subcount(j - 2) * subcount(W - j - 1) * dp[i - 1][j];
			dp[i][j] %= MOD;
			if (j < W) {
				dp[i][j + 1] += 1LL * subcount(j - 2) * subcount(W - j - 2) * dp[i - 1][j];
				dp[i][j + 1] %= MOD;
			}
		}
	}

	cout << dp[H][K] << endl;
}

