		vector<int> v( W );
		for( int j = 0; j < W; j++ ) {
			v[j] = j;
		}
		for( int j = 0; j < W; j++ ) {
			if( bit & (1 << j) ) {
				swap( v[j], v[j + 1] );
			}
		}
		for( int j = 0; j < W; j++ ) {
			mul[j][v[j]]++;
		}
	}

	dp[0][0] = 1;
	for( int i = 0; i < H; i++ ) {
		for( int j = 0; j < W; j++ ) {
			for( int k = 0; k < W; k++ ) {
				dp[i + 1][k] += dp[i][j] * mul[j][k] % MOD;
				dp[i + 1][k] %= MOD;
			}
		}
	}

	cout << dp[H][K - 1] << endl;

	return 0;
}

