int fib(int j){
  if ((j==0)||(j==1)){return 1;}
  else{
    return (fib(j-1)+fib(j-2))%mod;
  }
}

int fib_inv(int j, int W){
  if ((j==W-1)||(j==W-2)){return 1;}
  else{
    return (fib_inv(j+1)+fib_inv(j+2))%mod;
  }
}


int main(){
  int H, W, K;cin>>H>>W>>K;
