  for (int i=0;i<H;++i){
    for (int j=0;j<W;++j){
      dp[i+1][j]=dp[i][j]*fib(j)*fib_inv(j, W);
      if (j!=0){
        dp[i+1][j]+=dp[i][j-1]*fib(j-1)*fib_inv(j,W);
      }
      if(j!=W-1){
        dp[i+1][j]+=dp[i][j+1]*fib(j)*fib_inv(j+1,W);
      }
      dp[i+1][j]%=mod;
    }
  }
  cout << dp[H][K-1]<< endl;
  return 0;
}

