						dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % MOD;
					}
				}
				else
				{
					if ((bit&(1 << j)))
					{
						dp[i + 1][j] = (dp[i + 1][j] + dp[i][j + 1]) % MOD;
					}
					else if (0 < j && (bit&(1 << (j - 1))))
					{
						dp[i + 1][j] = (dp[i + 1][j] + dp[i][j - 1]) % MOD;
					}
					else
					{
						dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % MOD;
					}
				}
			}
		}
	}

	cout << dp[H][K - 1] << endl;

	return 0;
}

