typedef long long ll;

ll calc(int W, vector<ll>& dp, ll mod)
{
	if (W <= 1)
	{
		dp[W] = 1;
	}
	else if(dp[W] <= 0)
	{
		dp[W] += calc(W - 1, dp, mod);
		dp[W] += calc(W - 2, dp, mod);
		dp[W] %= mod;
	}

	return dp[W];
}

int main()
{
	int H, W, K;
	cin >> H >> W >> K;
	--K;

	auto mod = (ll)1e9 + 7;
	vector<ll> dp((H + 1) * W);
	vector<ll> dp2(W + 1);
	calc(W, dp2, mod);
	dp2[0] = 1;

	dp[0] = 1;
	for (auto h = 0; h < H; ++h)
	{
		for (auto w = 0; w < W; ++w)
		{
			auto current = dp[W * h + w];
			auto mul = dp2[w] * dp2[W - w - 1];
			dp[W * (h + 1) + w] = (dp[W * (h + 1) + w] + current * mul) % mod;
			if (w < W - 1)
			{
				mul = dp2[w] * dp2[W - w - 2];
				dp[W * (h + 1) + w + 1] = (dp[W * (h + 1) + w + 1] + current * mul) % mod;
			}
			if (w > 0)
			{
				mul = dp2[w - 1] * dp2[W - w - 1];
				dp[W * (h + 1) + w - 1] = (dp[W * (h + 1) + w - 1] + current * mul) % mod;
			}
		}
	}

	cout << dp[W * H + K] << endl;

	return 0;
}

