int main() {
    int H, W, K;
    cin >> H >> W >> K;
    --K;

    ll dp[H + 1][W];
    fill(dp[0], dp[H + 1], 0);
    dp[0][0] = 1;
    // dp[h][w] = 横線をh段引いたときに0がwに来るパターン数

    for (int h = 0; h < H; ++h) {
        for (int b = 0; b < (1 << (W - 1)); ++b) {
            // 横線が隣り合っていないかチェック
            bool judge = true;
            for (int i = 0; i < W - 2; ++i) {
                if ((b >> i) % 4 == 3) judge = false;
            }

            if (!judge) continue;

            // 各始点がどこへ移動するか求める
            int perm[W];
            for (int i = 0; i < W; ++i)
                perm[i] = i;
            for (int i = 0; i < W - 1; ++i) {
                if ((b >> i) & 1) swap(perm[i], perm[i + 1]);
            }

            for (int i = 0; i < W; ++i) {
                dp[h + 1][perm[i]] += dp[h][i];
                dp[h + 1][perm[i]] %= MOD;
            }
        }
    }

    cout << dp[H][K] << endl;
    return 0;
}

