struct Xorshift {
  uint64_t x = 88172645463325252LL;
  unsigned next_int() {
    x = x ^ (x << 7);
    return x = x ^ (x >> 9);
  }
  unsigned next_int(unsigned mod) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % mod;
  }
  unsigned next_int(unsigned l, unsigned r) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % (r - l + 1) + l;
  }
  double next_double() {
    return double(next_int()) / UINT_MAX;
  }
} rnd;

template<typename T>
void shuffle_vector(vector<T>& v, Xorshift& rnd) {
  int n = v.size();
  for (int i = n - 1; i >= 1; i--) {
    int r = rnd.next_int(i);
    swap(v[i], v[r]);
  }
}



pair<bool, vector<bool>> isvalid(int mask, int W) {
  vector<bool> v;
  for (int i = 0; i < W - 1; i++) {
    v.push_back(mask >> i & 1);
  }
  for (int i = 0; i < (int)v.size() - 1; i++) {
    if (v[i] && v[i + 1]) return { false, v };
  }
  return { true, v };
}

int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(0);

  ll H, W, K, MOD = 1000000007;
  cin >> H >> W >> K;
  K--;

  // i 行目において 0 が j 列目にある場合の数
  vector<vector<ll>> dp(H + 1, vector<ll>(W, 0));
  pair<bool, vector<bool>> valid[256] = {};
  for (int mask = 0; mask < (1 << (W - 1)); mask++) valid[mask] = isvalid(mask, W);

  dp[0][0] = 1;
  for (ll i = 0; i < H; i++) {
    for (ll j = 0; j < W; j++) {
      for (ll mask = 0; mask < (1 << (W - 1)); mask++) {
        if (!valid[mask].first) continue;
        const auto& v = valid[mask].second;
        if (j > 0 && v[j - 1]) (dp[i + 1][j - 1] += dp[i][j]) %= MOD;
        if ((j > 0 ? !v[j - 1] : true) && (j < W - 1 ? !v[j] : true)) (dp[i + 1][j] += dp[i][j]) %= MOD;
        if (j < W - 1 && v[j]) (dp[i + 1][j + 1] += dp[i][j]) %= MOD;
      }
    }
  }

  cout << dp[H][K] << endl;

  return 0;
}

