vector<ll> vec;
ll total = 0;
ll memo[110][10];

ll rec(ll i, ll j){
    if(i == 0 && j == 0) return 1;
    if(i == 0) return 0;
    if(memo[i][j] != -1) return memo[i][j];
    ll res = 0;

    if(j + 1 < w){
        res += rec(i - 1, j + 1) * vec[j];
    }
    res %= MOD;
    if(j - 1 >= 0){
        res += rec(i - 1, j - 1) * vec[j - 1];
    }
    res %= MOD;
    res += rec(i - 1, j) * (total - ((j+1<w?vec[j]:0) + (j-1>=0?vec[j - 1]:0)));
    res %= MOD;
    return memo[i][j] = res;

}
