long dp[101][8] = {};
int H, W;
vector<vector<int>> v;  // 横棒のパターン
int bit[8] = {};

void addBit() {
  int l = W - 1;
  for (int i = 1; i < l; i++) {
    if (bit[i - 1] == 1 && bit[i] == 1) return;
  }
  vector<int> tmp(l);
  for (int i = 0; i < l; i++) {
    tmp[i] = bit[i];
  }
  v.push_back(tmp);
}

void makeBit(int k) {
  if (k == W - 1) {
    addBit();
    return;
  }
  makeBit(k + 1);
  bit[k] = 1;
  makeBit(k + 1);
  bit[k] = 0;
}

void swap(long a[], vector<int> b, long c[]) {
  for (int i = 0; i < W - 1; i++) {
    if (b[i] == 1) {
      c[i] = a[i + 1];
      c[i + 1] = a[i];
    } 
  }
}

