  dp[0][0] = 1;
  makeBit(0);

  int l = v.size();
  for (int i = 1; i <= H; i++) {
    for (int j = 0; j < l; j++) {
      long* c = new long[W]();
      for (int k = 0; k < W; k++) {
        c[k] = dp[i - 1][k];
      }
      swap(dp[i - 1], v[j], c);
      for (int k = 0; k < W; k++) {
        dp[i][k] += c[k];
        dp[i][k] %= mod;
      }
    }
  }
  cout << dp[H][K - 1] << "\n";
  return 0;
}

