				dp[i][j]+=dp[i-1][j+1]*f[j]%MOD*f[w-(j+2)]%MOD;
				if(dp[i][j]>=MOD) dp[i][j]-=MOD;
			}

		}
	}


	cout<<dp[h][k-1]<<'\n';
	return 0;
}

