	const ll MOD = 1000000007;

	// dp[i][j] : i 行目までで j に到達する場合の数
	vector<vector<ll>> dp(H + 1, vector<ll>(W, 0));
	dp[0][0] = 1;

	for (int h = 1; h <= H; h++) {
		// 線を引くパターンを全探索
		for (int mask = 0; mask < (1 << (W - 1)); mask++) {
			bool flag = true;
			for (int b = 0; b < W - 2; b++) {
				if (((mask >> b) & 1) && ((mask >> (b + 1)) & 1)) {
					flag = false;
					break;
				}
			}
			if (!flag)
				continue;

			for (int b = 0; b < W; b++) {
				if ((mask >> b) & 1) {
					// (b, b + 1)
					dp[h][b + 1] = (dp[h][b + 1] + dp[h - 1][b]) % MOD;
					dp[h][b] = (dp[h][b] + dp[h - 1][b + 1]) % MOD;
					b++;
				}
				else {
					dp[h][b] = (dp[h][b] + dp[h - 1][b]) % MOD;
				}
			}
		}
	}
