// Topological Sort {{{
bool _visit(ll n, vector<ll> &marks, vector<vector<ll>> &edges, vector<ll> &res) {
    if (marks[n] == 1) {
        return false;
    } else if (marks[n] == 0) {
        marks[n] = 1;
        for (ll nxt : edges[n]) {
            if (!_visit(nxt, marks, edges, res)) {
                return false;
            }
        }
        marks[n] = 2;
        res.push_back(n);
    }
    return true;
}

// 出力辺が存在しない頂点から順に，トポロジカルソート
// つまり，edgesには後に続く頂点を記述する
// 返値は，頂点番号を要素とするベクトル
// 閉路があれば返値の要素数を0にする
vector<ll> topologicalSort(vector<vector<ll>> edges) {
    ll N = edges.size();
    // 結果
    vector<ll> res;

    // 頂点に対する情報
    // 0: 印なし
    // 1: 一時的
    // 2: 恒久的
    vector<ll> marks(N, 0);

    bool ok = true;
    for (ll i=0; i<N; i++)
        if (marks[i] == 0)
            if (!_visit(i, marks, edges, res)) {
                ok = false;
                break;
            }
    reverse(begin(res), end(res));
    return (ok ? res : vector<ll>());
}
