ll H,W,K;

bool isset(ll bit, ll pos) {
    if (pos<0 || pos>=W) return false;
    return (bit >> pos) & 1;
} 

ll bitcount(ll bit) {
    ll r=0;
    while(bit != 0) {
        r += bit & 1;
        bit >>= 1;
    }
    return 1;
}

// 図解はW=4の場合
//   0 1 2 3 <-- [0 W)
//  sta
//   ↓
//   |0|1|2| <-- bit
//   | | | |
//   | | | |
//   | | | |
//   | | | |
//         ↑
//         fin
ll solve (ll h, ll start, ll finish) {
    static map<pair<ll,PLL>, ll> memo;
    auto t = pair<ll,PLL>(h, PLL(start,finish));

    auto it = memo.find(t);
    if (it != memo.end()) {
        return it->second;
    }

    if (h==0){
        return memo[t] = (start == finish);
    }

    ll ans = 0;
    for (ll bit=0; bit<pow(2, W-1); bit++) {

        bool valid = true;
        for (ll t=0b11; t<0b110000000; t <<= 1) if ( (bit&t) == t) valid = false;
        if (!valid) continue;

        ll nextstart;
        if (isset(bit, start-1)) { // 左へ移動
            nextstart = start - 1;
        } else if (isset(bit,start)) { //右へ移動
            nextstart = start + 1;
        } else { // 下へ移動
            nextstart = start;
        }

        ans += solve(h-1, nextstart, finish);
        ans %= (ll)(1e9+7);
    }

    // printf("solve: %d %d %d, ans: %d\n", h, start ,finish, ans);
    return memo[t]=ans;
} 

