    for (int bit = 0; bit < 1<<W-1; bit++) {
        int n = bit;
        if (f(n)) continue;
        for (int i = 0; i < W-1; i++) {
            if (n % 2) v[i]++;
            n /= 2;
        }
        N++;
    }

    vector<vector<ll>> dp(H+1, vector<ll>(W));
    dp[0][0] = 1;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            int x = 0;
            if (j > 0) {
                dp[i+1][j-1] += dp[i][j] * v[j-1] % MOD;
                dp[i+1][j-1] %= MOD;
                x += v[j-1];
