            if (j < W-1) {
                dp[i+1][j+1] += dp[i][j] * v[j] % MOD;
                dp[i+1][j+1] %= MOD;
                x += v[j];
            }
            dp[i+1][j] += dp[i][j] * (N - x) % MOD;
            dp[i+1][j] %= MOD;
        }
