const int MAX = 101;
const int MOD = 1000000007;

int h, w, k;
int dyn[MAX][MAX];

int recurse(int row, int col) {
    if (row == h)
        return col == k - 1;
    int& ans = dyn[row][col];
    if (ans != -1)
        return ans;

    ans = 0;
    for (int nmask = 0; nmask < (1 << (w - 1)); nmask++) {
        bool valid = true;
        for (int i = 1; i < w - 1; i++) {
            if ((nmask & (1 << (i - 1))) && (nmask & (1 << i))) {
                valid = false;
                break;
            }
        }
        if (!valid)
            continue;

        int ncol = col;
        if (col + 1 < w && (nmask & (1 << col)))
            ncol = col + 1;
        if (col - 1 >= 0 && (nmask & (1 << (col - 1))))
            ncol = col - 1;
        ans += recurse(row + 1, ncol);
        if (ans >= MOD) ans -= MOD;
    }

    return ans;
}

