int w,k;
map<pi,long long>m;
map<pi,long long>::iterator it;
int hashing(vector<int>&arr){
	int curr = 1;
	int ret = 0;
	for(int i=0; i<w; i++){
		ret+=curr*arr[i];
		curr*=9;
	}
	return ret;
}
void unhashing(vector<int>&arr,int state){
	for(int i=0; i<arr.size(); i++){
		arr[i] = state%9;
		state/=9;
	}
}
long long f(int state,int line){
	it = m.find(pi(state,line));
	if(it!=m.end()) return it->second;
	long long ret = 0;
	vector<int>temp(w);
	unhashing(temp,state);
	if(temp[0]==k && !line) ret++;
	if(line){
		int ledder[8]={0};
		for(int lstate = 0; lstate<(1<<(w-1)); lstate++){
			for(int j=0; j<w-1; j++){
				if((1<<j)&lstate) ledder[j] = 1;
				else ledder[j] = 0;
			}
			bool pos = true;
			for(int j=1; j<w-1; j++){
				if(ledder[j-1] && ledder[j]) pos = false;
			}
			if(!pos) continue;

			for(int j=0; j<w-1; j++){
				if(ledder[j]) swap(temp[j],temp[j+1]);
			}
			ret+=f(hashing(temp),line-1);
			ret%=mod;
			unhashing(temp,state);
		}
	}
	m.insert(make_pair(pi(state,line),ret));
	return ret;
}
