// AtCoder Beginner Contest 113 - Problem D: Number of Amidakuji (https://beta.atcoder.jp/contests/abc113/tasks/abc113_d)
#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ii = pair<ll, ll>;

#define REPN(i, N) for (int (i) = 0; (i) < N; (i)++)

const int MAXH { 110 }, MAXW { 10 };
const int MOD { 1000000007 };

// dp[h][k] = # de Amidakuji com altura h que terminam na coluna k (indexada em 0, não 1)
// O Amidakuji é construído de cima para baixo, (o topo tem altura h = 0)
ll dp[MAXH][MAXW];

void solve(int H, int W, int K)
{
    // Corner case: uma única coluna
    dp[0][0] = 1;

    // DP bottom-up
    REPN(h, H)
    {
        REPN(w, W)
        {
            // Todas as possíveis escolhas de barras horizontais para a altura h
            // Há W - 1 barras horizontais possíveis entre W barras verticais
            // As novas barras entram em baixo das anteriores
            REPN(k, 1 << (W - 1))
            {
                // Duas linhas horizontais não podem ser conectar
                bool share = false;

                REPN(i, W - 2)
                {
                    if (k & (1 << i) and k & (1 << (i + 1)))
                    {
                        share = true;
                        break;
                    }
                }

                if (share)
                    continue;

                if (w and k & (1 << (w - 1)))
                {
                    // Há uma conexão para a esquerda: quem terminava em w agora termina em (w - 1)
                    dp[h + 1][w - 1] += dp[h][w];
                    dp[h + 1][w - 1] %= MOD;
                } else if (w < W - 1 and k & (1 << w))
                {
                    // Há uma conexão para a direita: quem terminava em w agora termina em (w + 1)
                    dp[h + 1][w + 1] += dp[h][w];
                    dp[h + 1][w + 1] %= MOD;
                } else
                {
                    // Não há conexões: segue diretamente em w
                    dp[h + 1][w] += dp[h][w];
                    dp[h + 1][w] %= MOD;
                }
            }
        }
    }

    auto ans = dp[H][K - 1];

    cout << ans << endl;
}

int main()
{
    ios::sync_with_stdio(false);

    int H, W, K;
    cin >> H >> W >> K;

    solve(H, W, K);

    return 0;
}

