const ll MOD = 1000000007;
ll dp[105][10];
ll dp1[2000][10];

ll rec1(int b, int i) {
    if (i >= W) return 1;
    if (dp1[b][i] != -1) return dp1[b][i];
    if (b & (1 << i)) {
        return dp1[b][i] = rec1(b, i + 1);
    } else {
        return dp1[b][i] = (rec1(b, i + 1) + rec1(b, i + 2)) % MOD;
    }
}

ll rec(int h, int w) {
    if (h == H + 1 && w == K) return 1;
    if (h == H + 1) return 0;
    if (dp[h][w] != -1) return dp[h][w];
    ll ans = 0;

    if (w < W) {
        int b = 0;
        if (w > 1) b |= (1 << (w - 1));
        b |= (1 << w);
        b |= (1 << (w + 1));
        ll c = rec1(b, 1);
        ans = (ans + ((c * rec(h + 1, w + 1)) % MOD)) % MOD;
    }

    if (w > 1) {
        int b = 0;
        b |= (1 << (w - 1));
        b |= (1 << w);
        b |= (1 << (w - 2));
        ll c = rec1(b, 1);
        ans = (ans + ((c * rec(h + 1, w - 1)) % MOD)) % MOD;
    }

    int b = 0;
    if (w > 1) b |= (1 << (w - 1));
    b |= (1 << w);
    ll c = rec1(b, 1);
    ans = (ans + ((c * rec(h + 1, w)) % MOD)) % MOD;

    return dp[h][w] = ans;
}


