llong solve() {
    dp[0][0] = 1;

    for(int h = 1; h <= H; ++h) {
        for(int w = 0; w < W; ++w) {

            dp[h][w] += dp[h - 1][w] * dummy_paths(w) * dummy_paths(W - 1 - w);
