ll dpf(ll n, ll h){
  if(dp[n][h]>=0){
    return dp[n][h];
  }else{
    dp[n][h]=0;
    if(h==1){
      if(n==0)dp[n][h]=1;
    }else{
      ll tmp = prop;
      if(n-1>=0){
        dp[n][h] =mod(dp[n][h] +dpf(n-1, h-1)*num[n-1], MOD);
        tmp -= num[n-1];
      }
      if(n+1<=W-1){
        dp[n][h] =mod(dp[n][h]+ dpf(n+1, h-1)*num[n], MOD);
        tmp -= num[n];
      }
      dp[n][h] =mod(dp[n][h] + dpf(n, h-1)*tmp, MOD);
    }
    return mod(dp[n][h], MOD);
  }
}

