int main()
{
	//H+1cm,W本の線,到着はKに.
	int H, W, K;
	cin >> H >> W >> K;
	//dp[i][j]=縦棒を上からi刻み分についての入れ方のうち、
	//1からスタートしてjで終わるようなものの個数。
	vector<vector<int>> dp(H + 1, vector<int>(W, 0));
	dp[0][0] = 1;
	for (int i = 0;i < H;i++) {
		for (int j = 0;j < W;j++) {
			//bitは横棒の存在を表す.W本の縦線があるため、横線はW-1本であるのは当然である。
			for (int bit = 0;bit < (1 << (W - 1));bit++) {
				bool ok = true;
				for (int k = 0;k < W - 2;k++) {
					//横棒が被っている場合は抜ける。
					if ((bit & (1 << k)) && (bit & (1 << (k + 1)))) {
						ok = false;
					}
				}
				if (!ok) {
					continue;
				}
				//左からj本目を見ているとき、j本目からj+1本目へ横線が引かれていた時はdp[i+1][j+1]を変更し、
				//j-1本目からj本目へ横線が引かれていた時にはdp[i+1][j-1]を変更する。
				int nj = j;
				if (bit & (1 << j)) {
					nj = j + 1;
				}
				else if (j > 0 && (bit & (1 << (j - 1)))) {
					nj = j - 1;
				}
				//
				dp[i + 1][nj] = (dp[i + 1][nj] + dp[i][j]) % MOD;
			}
		}
	}

	//K-1は、入力は1始まりで数えているため。
	cout << dp[H][K-1] << endl;


	return 0;
}

