void solve(int h, int w, int k) {
  vi fact(w, 1);
  rep(i, 2, w) {
    fact[i] = fact[i - 1] + fact[i - 2];
  }
  vvi dp(h + 1, vi(w));
  dp[0][0] = 1;
  rep(i, h)rep(j, w) {
    dp[i + 1][j] = m_mul(dp[i][j], fact[w - 1 - j] * fact[j]);
    if(j > 0)dp[i + 1][j] = m_add(
      dp[i + 1][j],
      m_mul(dp[i][j - 1], fact[w - 1 - j] * fact[j - 1])
    );
    if(j < w - 1)dp[i + 1][j] = m_add(
      dp[i + 1][j],
      m_mul(dp[i][j + 1], fact[w - 1 - j - 1] * fact[j])
    );
  }
  COUT(dp[h][k - 1]);
}


