const int mod = 1e9 + 7;

// WARN : use H with larger N
/// --- Modulo Factorial {{{ ///
template < int N, int mod = (int) 1e9 + 7 >
struct Factorial {
  constexpr ll extgcd(ll a, ll b, ll &x, ll &y) {
    ll d = 0;
    return b == 0 ? (x = 1, y = 0, a) : (d = extgcd(b, a % b, y, x), y -= a / b * x, d);
  }
  constexpr ll modinv(ll a) {
    ll x = 0, y = 0;
    extgcd(a, mod, x, y);
    return (x + mod) % mod;
  }
  int arr[N + 1], inv[N + 1];
  ll operator[](int i) const { return arr[i]; }
#if !defined(DEBUG)
  constexpr
#endif
    Factorial()
    : arr(), inv() {
      arr[0] = 1;
      for(int i = 1; i <= N; i++) {
        arr[i] = (ll) i * arr[i - 1] % mod;
      }
      inv[N] = modinv(arr[N]);
      for(int i = N - 1; i >= 0; i--) {
        inv[i] = (ll)(i + 1) * inv[i + 1] % mod;
      }
    }
  ll C(int n, int r) const {
    if(n < 0 || r < 0 || n < r) return 0;
    return (ll) arr[n] * inv[r] % mod * inv[n - r] % mod;
  }
  ll H(int n, int r) const { return C(n + r - 1, r); }
};
/// }}}--- ///

const int N = 30;
Factorial < N, mod > fact;

int h, w, k;

int main() {
	#ifndef ONLINE_JUDGE
    freopen("../input.txt", "r", stdin);
    freopen("../output.txt", "w", stdout);
	#endif
  std::ios::sync_with_stdio(false), std::cin.tie(0);
  cin >> h >> w >> k;

  vector<ll> x(w + 1); // x[i] := when there's i vertical-lines, how many ways to make pairs?
  // O(W^2)
  for(int i = 0; i <= w; i++) {
    for(int j = 0; j * 2 <= i; j++) { // make j pairs
      // C(i - j, j)
      x[i] += fact.C(i - j, j);
    }
    x[i] %= mod;
  }
  vector<ll> dp(w);
  dp[0] = 1;

  vector<ll> dp2(w);
  // O(WH)
  for(int i = 0; i < h; i++) {
    dp2.assign(w, 0);
    for(int a = 0; a < w; a++) { // before
      // no. of RIGHT-side free vertical-lines = w - 1 - a
      // no. of LEFT-side  free vertical-lines = a
      // after = a
      dp2[a] += dp[a] * x[w - 1 - a] % mod * x[a] % mod;
      // after = a - 1
      if(a - 1 >= 0) dp2[a-1] += dp[a] * x[w - 1 - a] % mod * x[a - 1] % mod;
      // after = a + 1
      if(a + 1 < w) dp2[a+1] += dp[a] * x[w - 1 - a - 1] % mod * x[a] % mod;
    }
    for(auto &e : dp2) e %= mod;
    swap(dp, dp2);
  }

  // dp[k-1]

  cout << dp[k-1] << endl;

  return 0;
}

