lint rz[105][10][10];
lint fibo[105];

lint mlt(lint x)
{
    if(x < 0) { x = 0; }
    return fibo[x];
}

lint ans(lint h, lint w, lint k)
{
    if(rz[h][w][k] != 0) {
        return rz[h][w][k];
    }

    if(k - 1 > h) { return 0; }

    if(h == 0) { return 1; }

    lint rez = 0, r1 = 1, r2 = 1, st = 0, dr = 0, r3 = 1;

    if(k >= 2)
    {
        st = k - 1 - 1 - 1;
        dr = w - k - 1;

        r1 *= mlt(st); r1 %= mod;
        r1 *= mlt(dr); r1 %= mod;

        r1 *= ans(h-1, w, k-1); r1 %= mod;
    }
    else
    {
         r1 = 0;
    }

    if(k <= w - 1)
    {
        st = k-1 - 1;
        dr = w - (k + 1) - 1;

        r2 *= mlt(st); r2 %= mod;
        r2 *= mlt(dr); r2 %= mod;

        r2 *= ans(h-1, w, k+1); r2 %= mod;
    }
    else
    {
        r2 = 0;
    }

    // free fall
    {
        st = k - 2; dr = w - k - 1;
        r3 *= mlt(st); r3 %= mod;
        r3 *= mlt(dr); r3 %= mod;
        r3 *= ans(h-1, w, k); r3 %= mod;
    }

    rez = r1 + r2; rez %= mod;
    rez += r3; rez %= mod;
    return rz[h][w][k] = rez;
}

