      if ((i & (1ll << j)) && (i & (1ll << (j + 1)))) {
        ok = false;
      }
    }
    if (ok) {
      v.push_back(i);
    }
  }

  vvi dp(H + 1, vi(W));
  dp[0][0] = 1;
  for (ll i = 1; i <= H; i++) {
    for (ll j: v) {
      for (ll k = 0; k < W - 1; k++) {
        if (j & (1ll << k)) {
          dp[i][k] += dp[i - 1][k + 1];
          dp[i][k + 1] += dp[i - 1][k];
        }
      }
      for (ll k = 0; k < W; k++) {
        if (k == 0) {
          if (!(j & (1ll << k))) {
            dp[i][k] += dp[i - 1][k];
          }
        } else if (k == W - 1) {
          if (!(j & (1ll << (k - 1)))) {
            dp[i][k] += dp[i - 1][k];
          }
        } else {
          if (!(j & (1ll << k)) && !(j & (1ll << (k - 1)))) {
            dp[i][k] += dp[i - 1][k];
          }
        }
      }
      for (ll k = 0; k < W; k++) {
        dp[i][k] %= MOD;
      }
    }
  }

  cout << dp[H][K] << endl;
}

