long long const MOD = 1000000007LL;

int power[8];

long countCases(int left, int right) {
    if (left <= 0 && right <= 0) {
        return 1;
    } else if (left > 0 && right <= 0) {
        if (left % 2 == 0) return power[left / 2 + 1] - 1;
        else return 3 * power[left / 2] - 1;
    } else if (left <= 0 && right > 0) {
        if (right % 2 == 0) return power[right / 2 + 1] - 1;
        else return 3 * power[right / 2] - 1;
    } else {
        if (left % 2 == 0 && right % 2 == 0) return (power[left / 2 + 1] - 1) * (power[right / 2 + 1] - 1);
        else if (left % 2 != 0 && right % 2 == 0) return (3 * power[left / 2] - 1) * (power[right / 2 + 1] - 1);
        else if (left % 2 == 0 && right % 2 != 0) return (power[left / 2 + 1] - 1) * (3 * power[right / 2] - 1);
        else return (3 * power[left / 2] - 1) * (3 * power[right / 2] - 1);
    }
}

int main() {
    int height, width, goal;
    cin >> height >> width >> goal;

    power[0] = 1;
    for (int i = 1; i < 8; i++) power[i] = 2 * power[i - 1];

    long dp[height + 1][width];
    for (int i = 0; i <= height; i++) {
        for (int j = 0; j < width; j++) dp[i][j] = 0;
    }
    dp[0][0] = 1;

    // ループ開始
    // イメージとしては、i へ行くためにはその前の場所が i - 1, i, i + 1 のいずれかである必要がある。
    // それぞれの状態から、 i へ行く通り数を掛け合わせて行くと DP で表現することができそう。
    for (int i = 1; i <= height; i++) {
        for (int j = 0; j < width; j++) {
            if (j > 0) dp[i][j] += countCases(j - 2, width - j - 2) * dp[i - 1][j - 1] % MOD;
            if (j < width - 1) dp[i][j] += countCases(j, width - j - 3) * dp[i - 1][j + 1] % MOD;
            dp[i][j] += countCases(j - 1, width - j - 2) * dp[i - 1][j] % MOD;
            dp[i][j] %= MOD;
        }
    }

    for (int i = 0; i <= height; i++) {
        for (int j = 0; j < width; j++) cout << "dp[" << i << "][" << j << "] = " << dp[i][j] << " ";
        cout << endl;
    }

    cout << dp[height][goal - 1] << endl;
}

