/**
@brief あみだくじのvalidを調べる関数
@param np あみだくじパターン(2進数で表現)
@param w あみだくじの幅
**/
bool ValidNP(BaseNP& np, ll w)
{
	string s = np(w - 1);
	rep(i, 0, size(s) - 1)
	{
		if (s[i] == '1' && s[i + 1] == '1')
			return false;
	}

	return true;
}

int main(void)
{
	ll h, w, k;
	cin >> h >> w >> k; k--;

	vector<string> vnp;
	BaseNP np(2);
	rep(i, 0, (1LL << w - 1))
	{	// validな1列あみだくじの全パターンを列挙して保存
		if (ValidNP(np, w))
			vnp.push_back(np(w - 1));
		np++;
	}

	vector<vector<mll>> dp(h+1, vector<mll>(w));
	dp[0][0] = 1;
	rep(i, 0, h)
	{
		rep(j, 0, w)
		{
			each(e, vnp)
			{
				if (j + 1 < w && e[j] == '1')
					dp[i + 1][j + 1] += dp[i][j];
				else if (0 <= j - 1 && e[j - 1] == '1')
					dp[i + 1][j - 1] += dp[i][j];
				else
					dp[i + 1][j] += dp[i][j];
			}
		}
	}

	cout << dp.back()[k];
	return 0;
}

