using namespace std;
const int mod = 1000000007;

int main()
{
  int H, W, K;
  cin >> H >> W >> K;

  uint64_t A[H+1][W];
  for (int h=0; h<=H; ++h)
    for (int w=0; w<W; ++w)
      A[h][w] = 0;

  A[0][0] = 1;
  for (int w=1; w<W; ++w)
    A[0][w] = 0;

  for (int h=1; h<=H; ++h) {
    for (int w=0; w<W; ++w) {
      for (int p=0; p<1<<(W-1); ++p) {
	// check amidakuji path validity
	bool exist_consecutive_digit_1 = false;
	for (int bit=0; !exist_consecutive_digit_1 && bit<(W-1); ++bit) {
	  if (((p >> bit) & 1) == 1 && ((p >> (bit+1)) & 1) == 1) {
	    exist_consecutive_digit_1 = true;
	    break; // invalid amidakuji path found
	  }
	}

	if (exist_consecutive_digit_1) {
	  continue; // invalid amidakuji path
	}

	if (w<W-1 && ((p>>w)&1)==1) {// go left
	  A[h][w] += A[h-1][w+1];
	  A[h][w] %= mod;
	} else if (w>0 && ((p>>(w-1))&1)==1) {// go right
	  A[h][w] += A[h-1][w-1];
	  A[h][w] %= mod;
	} else {
	  A[h][w] += A[h-1][w];
	  A[h][w] %= mod;
	}	
      }
    }
  }

  cout << A[H][K-1] << endl;

  return 0;
}

