//進数変換
class base_convert
{
private:
    const char *s;
    int a[128];

public:
    base_convert(const char *s = "0123456789ABCDEF") : s(s)
    {
        int i;
        for (i = 0; s[i]; ++i)
            a[(int)s[i]] = i;
    }
    std::string to(long long p, int q)
    {
        int i;
        if (!p)
            return "0";
        char t[64] = {};
        for (i = 62; p; --i)
        {
            t[i] = s[p % q];
            p /= q;
        }
        return std::string(t + i + 1);
    }
    std::string to(const std::string &t, int p, int q)
    {
        return to(to(t, p), q);
    }
    long long to(const std::string &t, int p)
    {
        int i;
        long long sm = a[(int)t[0]];
        for (i = 1; i < (int)t.length(); ++i)
            sm = sm * p + a[(int)t[i]];
        return sm;
    }
};

//Nビット全探索
vector<vector<ll>> bit_zentansaku(ll base, ll n)
{
    vector<vector<ll>> res(llpow(base, n), vector<ll>(n));
    base_convert r;
    for (ll mask = 0; mask < res.size(); mask++)
    {
        string tmp = r.to(mask, base);

        while (tmp.size() < n)
        {
            tmp.insert(0, "0");
        }
        for (ll i = 0; i < n; i++)
        {
            res[mask][i] = tmp[i] - '0';
        }
    }
    return (res);
}

int main()
{
    ll h, w, k;
    cin >> h >> w >> k;
    vector<vector<ll>> dp(h + 1, vector<ll>(w, 0));
    dp[0][0] = 1;
    for (ll i = 0; i < h; i++)
    {
        for (ll j = 0; j < w; j++)
        {
            for (auto f : bit_zentansaku(2, w - 1))
            {
                if (j < w - 1 && f[j] && f[j + 1])
                {
                    continue;
                }
                if (j > 0 && f[j - 1])
                {
                    dp[i + 1][j - 1] += dp[i][j];
                    dp[i + 1][j - 1] %= mod;
                }
                else if (j < w - 1 && f[j])
                {
                    dp[i + 1][j + 1] += dp[i][j];
                    dp[i + 1][j + 1] %= mod;
                }
                else
                {
                    dp[i + 1][j] += dp[i][j];
                    dp[i + 1][j] %= mod;
                }
            }
        }
    }
    cout << dp[h][k - 1] << endl;
    return 0;
}

