#define M 1000000007

long long fib(int m) {
    long long a = 2, b = 1;
    //cerr << m << ' ';
    if (m <= 0) return 1;
    while (--m) { long long t = a; a = a + b; b = t; if (a >= M) a -= M; }
    //cerr << a << ' ' << b << endl;
    return a;
}

int main(int argc, char** argv) {
    int h, w, k; cin >> h >> w >> k;
    long long dp[h+1][w+1] = {};
    dp[0][1] = 1;
    for (int i = 0; i < h; i++)
        for (int j = 1; j <= w; j++) {
            (dp[i+1][j] += dp[i][j] * fib(j-2) % M * fib(w-j-1) % M) %= M;
            if (j > 1) (dp[i+1][j-1] += dp[i][j] * fib(j-3) % M * fib(w-j-1) % M) %= M;
            if (j < w) (dp[i+1][j+1] += dp[i][j] * fib(j-2) % M * fib(w-j-2) % M) %= M;
        }
    cout << dp[h][k] << endl;
}

