typedef long long ll;
#define MOD 1000000007
using namespace std;
vector<int> tobit(ll n, int keta) {
    vector<int> res(keta, 0);
    for(int i = 0; i < keta; i++) {
        res[i] = n % 2;
        n /= 2;
    }
    return res;
}
int main() {
    ll h, w, k;
    cin >> h >> w >> k;
    if(w == 1) {
        cout << 1 << endl;
        return 0;
    }
    vector<int> pm(w);
    for(int i = 0; i < w; i++) {
        pm[i] = i;
    }
    vector<vector<int>> pats;
    for(int i = 0; i < (1LL << (w - 1)); i++) {
        auto tmp = tobit(i, w - 1);
        bool flag = true;
        for(int j = 0; j < tmp.size() - 1; j++) {
            if(tmp[j] == 1 && tmp[j + 1] == 1) {
                flag = false;
                break;
            }
        }
        if(flag) {
            pats.push_back(tmp);
        }
    }
    vector<vector<int>> state;
    do {
        state.push_back(pm);
    } while(next_permutation(all(pm)));
    int sn = state.size();
    vector<map<vector<int>, ll>> dp(h + 1, map<vector<int>, ll>());
    dp[0][state[0]] = 1;
    for(int i = 0; i < h; i++) {
        for(auto &stat : state) {
            for(auto &pat : pats) {
                auto next = stat;
                for(int x = 0; x < pat.size(); x++) {
                    if(pat[x] == 1) {
                        swap(next[x], next[x + 1]);
                    }
                }
                dp[i + 1][next] += dp[i][stat];
                dp[i + 1][next] %= MOD;
            }
        }
    }
    k--;
    ll ans = 0;
    for(auto &e : dp[h]) {
        if(e.first[k] == 0) {
            ans += e.second;
            ans %= MOD;
        }
    }
    cout << ans << endl;
}

