        if (j > 1) {
            f[i][j] += 1ll * f[i - 1][j - 1] * fib[j - 1] % MOD * fib[w - j + 1] % MOD;
            f[i][j] >= MOD ? f[i][j] -= MOD : 0;
        }
        if (j < w) {
            f[i][j] += 1ll * f[i - 1][j + 1] * fib[j] % MOD * fib[w - j] % MOD;
            f[i][j] >= MOD ? f[i][j] -= MOD : 0;
        }
    }

