#include <bits/stdc++.h>

using namespace std;

long long prime = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int H, W, K;
    cin >> H >> W >> K;
    int N = 20;
    vector<long long> fib(N, 0);
    fib[0] = 1;
    fib[1] = 1;
    for (int i = 2; i < N; ++i) {
        fib[i] = (fib[i-1] + fib[i-2]) % prime;
    }
    vector<long long> u(W, 0LL);
    u[0] = 1LL;
    for (int i = 0; i < H; ++i) {
        vector<long long> v(W, 0LL);
        for (int j = 0; j < W; ++j) {
            // 0 .. j-1 NO j NO j+1 .. W-1
            v[j] += fib[j] * fib[W-j-1] % prime * u[j] % prime;
            // 0 .. j-2 NO j-1 YES j NO j+1 .. W-1
            if (j > 0) {
                v[j-1] += fib[j-1] * fib[W-j-1] % prime * u[j] % prime;
            }
            // 0 .. j-1 NO j YES j+1 NO j+2 .. W-1
            if (j < W-1) {
                v[j+1] += fib[j] * fib[W-j-2] % prime * u[j] % prime;
            }
        }
        for (int j = 0; j < W; ++j) {
            u[j] = v[j] % prime;
            // cerr << u[j] << " ";
        }
        // cerr << endl;
    }
    cout << u[K-1] << endl;
    return 0;
}

