int main(){
  int mod=1000000007;
  int H,W,K;
  cin>>H>>W>>K;
  int dp[H+1][W];
  for(int h=0;h<H+1;++h){
    for(int w=0;w<W;++w){
      dp[h][w]=0;
    }
  }
  dp[0][0]=1;
  for(int i=0;i<H;++i){
    for(int j=0;j<W;++j){
    for(int k=0;k<(1<<(W-1));++k){
      bool ok=true;
      for(int l=0;l<W-2;++l){
        if(((k>>l)&1)&&((k>>l+1)&1)){
          ok=false;
        }}
      if(ok){
        if(j>=1 && ((k>>(j-1))&1)){
          //move to left
          dp[i+1][j-1]+=dp[i][j];
          dp[i+1][j-1]%=mod;
        }
        else if(j<=W-2 && ((k>>j)&1)){
          //move to right
          dp[i+1][j+1]+=dp[i][j];
          dp[i+1][j+1]%=mod;
        }
        else{
          //not move
          dp[i+1][j]+=dp[i][j];
          dp[i+1][j]%=mod;
        }
      }
      }

  }}
  cout<<dp[H][K-1]<<'\n';
return 0;
}

