typedef long long ll;

const int md = 1000000007;

ll fib(ll n){
  if(n==0){return 1;}
  else if(n==1){return 1;}
  else {return (fib(n-1) + fib(n-2))%md;}
}

int main(){
  int h,w,k;
  cin >> h >> w >> k;

  if( w == 1 || h == 1){
    cout << 1 << endl;
    return 0;
  }

  ll a[h+1][w];

  a[0][0] = 1;

  for(int i=1; i<w; i++){a[0][i]=0;}

  for(int i=1; i<=h; i++){
    a[i][0] = a[i-1][0] * fib(w-1) + a[i-1][1] * fib(w-2);
    a[i][w-1] = a[i-1][w-1] * fib(w-1) + a[i-1][w-2] * fib(w-2);
    for(int j=1; j<w-1; j++){
      a[i][j] = a[i-1][j-1] * fib(j-1) * fib(w-j-1) + a[i-1][j] * fib(j) * fib(w-j-1) + a[i-1][j+1] * fib(j) * fib(w-j-2);
      a[i][j] = a[i][j] % md;
    }
  }
  cout << a[h][k-1];
}

