      else dp[i][j]=dp[i][j-1]*a[i-1]*a[W-i]+dp[i-1][j-1]*a[W-i]*a[max(0,i-2)]+dp[i+1][j-1]*a[W-i-1]*a[i-1];
      dp[i][j]%=MOD;
    }
  }
    cout<<dp[K][H]<<endl;
  }


}

