VL prime_decomposition(ll n) {
	ll i = 2;
	VL table{};
	while (i * i <= n) {
		while (n % i == 0) {
			n /= i;
			table.emplace_back(i);
		}
		++i;
	}
	if (n > 1) {
		table.emplace_back(n);
		return table;
	}
}

ll p(ll n) {

	static map<ll, ll> memo;
	if (n <= 0) { return 1; }
	if (memo.find(n) != memo.end()) {
		return memo[n];
	}
	if (n == 1) {
		memo[1] = 2;
		return 2;
	}
	if (n == 2) {
		memo[2] = 3;
		return 3;
	}
	ll tmp = p(n - 1) + p(n - 2);
	memo[n] = tmp;
	return tmp;

}

