ll power_mod(ll n, ll m)
{
    ll res = 1;
    ll base = n;
    while (m > 0)
    {
        if (m&1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        m >>= 1;
    }
    return res;
}
ll inv_mod(ll n)
{
    return power_mod(n, MOD-2);
}
ll comb_mod(ll n, ll m)
{
    ll res = 1;
    rep(i, n - m + 1, n + 1)
        res = (res * i) % MOD;
    rep(i, 1, m + 1)
        res = (res * inv_mod(i)) % MOD;
    return res;
}

