  for (int i = 1; i <= 7; ++i) {
    bar[i] = row(i);
  }

  int h, w, k; cin >> h >> w >> k;

  vector<int> left(w+2, 0), center(w+2, 0), right(w+2, 0); // 1-based
  int temp[4];
  for (int i= 1; i <= w; ++i) {
    temp[0] = bar[max(w-2-i, 0)];
    temp[1] = bar[max(w-1-i, 0)];
    temp[2] = bar[max(i-2, 0)];
    temp[3] = bar[max(i-3, 0)];
    left[i] = max(max(max(temp[1], temp[3]), temp[1] * temp[3]), 1);
    center[i] = max(max(max(temp[2], temp[1]), temp[2] * temp[1]), 1);
    right[i] = max(max(max(temp[2], temp[0]), temp[2] * temp[0]), 1);
  }
  left[1] = 0;
  right[w] = 0;

