void update(int r)
{
	rep(i, 1 << (W-1)) {
		if (i & (i >> 1)) continue;
		int bit = 1;
		bool f = false;
		rep(j, W-1) {
			if (bit & i) {
				dp[r][j+1] += dp[r-1][j];
				dp[r][j] += dp[r-1][j+1];
				dp[r][j+1] %= MOD;
