	ddp[1][1] = 1;
	rep(i, 2, 7){
		ddp[i][0] = ddp[i-1][0] + ddp[i-1][1];
		ddp[i][1] = ddp[i-1][0];
	}
	auto Ddp = [&](ll i)->ll{
		if (i<1) return 1;
		return ddp[i][0]+ddp[i][1];
	};


