	dp[0][0]=1;

	rep(h, 0, H-1){
		rep(i, 0, W-1){
			ll D = W-2-(i+2)+1;
			ll DD= i-1;
			//右
			if (i+1<=W-1){
				dp[h+1][i+1] += dp[h][i] * Ddp(D) * Ddp(DD);
			}
			//左
			if (0<=i-1){
				dp[h+1][i-1] += dp[h][i] * Ddp(D+1) * Ddp(DD-1);
			}
			//まっすぐ
			dp[h+1][i]   += dp[h][i] * Ddp(D+1) * Ddp(DD);
