typedef long long ll;
typedef pair<int, int> pii;
typedef pair<int, pii> pipii;
typedef pair<double, double> pdd;

map<pii, int> amtDP;
ll dp[10];
ll ndp[10];
void solve() {
  int h, w, k;
  cin >> h >> w >> k;
  int totalInc = 0;
  {
    vector<pii> v;
    for(int i = 2; i <= w; i++) {
      v.push_back({i-1, i});
    }
    for(int mask = 0; mask < (1 << v.size()); mask++) {
      set<int> seen;
      bool good = true;
      for(int i = 0; i < v.size(); i++) {
        if((mask&(1<<i)) == 0) continue;
        if(seen.count(v[i].first) || seen.count(v[i].second)) good = false;
        seen.insert(v[i].first);
        seen.insert(v[i].second);
      }
      if(!good) continue;
      totalInc++;
      for(int i = 0; i < v.size(); i++) {
        if(mask&(1<<i)) amtDP[v[i]]++;
      }
    }
  }
  dp[1] = 1;
  while(h--) {
    memset(ndp, 0, sizeof(ndp));
    for(int i = 1; i <= w; i++) {
      int scale = totalInc;
      pii key = {i-1, i};
      scale -= amtDP[key];
      ndp[i-1] += amtDP[key] * dp[i];
      key = {i, i+1};
      scale -= amtDP[key];
      ndp[i+1] += amtDP[key] * dp[i];
      ndp[i] += scale * dp[i];
    }
    for(int i = 1; i <= w; i++) ndp[i] %= 1000000007;
    memcpy(dp, ndp, sizeof(dp));
  }
  cout << dp[k] << "\n";
}

