int F(int n) {
    if (n <= 2) return 1;
    else return F(n - 1) + F(n - 2);
}

long long C(int a, int b) {
    if (b == 0 || b == w + 1) return 0;
    else if (min(b - 1, w - b) >= 2) return F(b) * F(a - b + 1);
    else if (b == 1 || b == a) return F(a);
    else return F(a - 1);
}

long long solve(int p, int q, int r) {
    if (dp[p][q][r] >= 0) return dp[p][q][r];
    else {
        dp[p][q][r] = 0;
        if (r == 0 || r == w + 1) return dp[p][q][r];
        if (p >= r - 1) dp[p][q][r] += C(q - 1, r - 1) * solve(p - 1, q, r - 1);
        if (p >= r) dp[p][q][r] += C(q, r) * solve(p - 1, q, r);
        if (p >= r + 1) dp[p][q][r] += C(q - 1, r) * solve(p - 1, q, r + 1);
    }
    if (dp[p][q][r] >= inf) dp[p][q][r] %= inf;
//    cout << p << "," << q << "," << r << " " << dp[p][q][r] << endl;
    return dp[p][q][r];
}

