   ios::sync_with_stdio(false);
   cin.tie(0);
   ll H, W, K; cin >> H>> W >> K;
   ll natu = 0, used[10]; rep(i, W - 1) used[i] = 0;
   for(int bit = 0; bit < (1<<(W - 1)); bit++) {
       bool flag = true;
       rep(j, W - 2) {
           if((bit & (1<<j)) && (bit & (1<<(j + 1)))) {
               flag = false;
           }
       }
       if(flag == true) natu ++;
   }
   rep(i, W - 1) {
        for(int bit = 0; bit < (1<<(W - 1)); bit++) {
            bool flag = true;
            if(!(bit & (1<<i))) flag = false;
            rep(j, W - 2) {
            if((bit & (1<<j)) && (bit & (1<<(j + 1)))) {
                flag = false;
            }
            }
            if(flag == true) used[i] ++;
        }
   }
   ll dp[110][10];
   rep(i, H) rep(j, W) dp[i][j] = 0;
   dp[0][0] = 1;
   rep(i, H) {
       rep(j, W) {
           dp[i + 1][j] += dp[i][j] * (natu - used[j] - (j != 0 ? used[j - 1] : 0));
           dp[i + 1][j] %= mod;
           if(j != 0) dp[i + 1][j] += dp[i][j - 1] * used[j - 1];
           dp[i + 1][j] %= mod;
           if(j != W - 1) dp[i + 1][j] += dp[i][j + 1] * used[j];
           dp[i + 1][j] %= mod;
       }
   }
