int main(int argc, char* argv[]) {
  ll h, w, k;
  cin >> h >> w >> k;

  dp[0][0] = 1;
  rep(i, 0, h) rep(j, 0, w) {
    ll x = 0, y = 0, z = 0;
    rep(k, 0, (1 << (w - 1))) {
      if (k & (k << 1)) continue;
      bool right = (j == w - 1) ? false : k & (1 << j);
      bool left = (!j) ? false : k & (1 << (j - 1));

      if (right) z++;
      if (left) x++;
      if (!(right || left)) y++;
    }

    dp[i + 1][j] = (dp[i + 1][j] + dp[i][j] * y) % MOD;
    if (j) dp[i + 1][j - 1] = (dp[i + 1][j - 1] + dp[i][j] * x) % MOD;
    if (j != w - 1) dp[i + 1][j + 1] = (dp[i + 1][j + 1] + dp[i][j] * z) % MOD;
  }

  put(dp[h][k - 1]);
  return 0;
}

