#define repi(i,a,b) for(ll i=a;i<b;i++)
#define rep(i,a) repi(i,0,a)
#define MOD 1000000007
#define W_MAX 8

void calc_moves(ll (*arr)[W_MAX], int w){
  ll dp[w+1] = {};
  dp[0] = 1;
  dp[1] = 1;
  repi(i, 2, w+1) dp[i] = dp[i-2] + dp[i-1];
  rep(i, w){
    if(i == 0){
      arr[i][i] = dp[w-1];
      arr[i][i+1] = dp[w-2];
    }
    else if(i == (w-1)){
      arr[i][i] = arr[0][0];
      arr[i][i-1] = arr[0][1];
    }
    else{
      arr[i][i] = dp[i] * dp[w-i-1];
      arr[i][i+1] = dp[i] * dp[w-i-2];
      arr[i][i-1] = arr[i-1][i];
    }
  }
}

int main(){
  int H, W, K;
  scanf("%d %d %d", &H, &W, &K);
  K--;

  if(W == 1) cout << 1 << endl;
  else{
    ll n_moves[W_MAX][W_MAX] = {};
    calc_moves(n_moves, W);
    ll dp[H][W] = {};
    rep(i, H){
      rep(j, W){
        if(i == 0) dp[i][j] = n_moves[0][j];
        else rep(k, W) dp[i][j] = (dp[i][j] + dp[i-1][k] * n_moves[k][j]) % MOD;
      }
    }
    cout << dp[H-1][K] << endl;
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const long mod = 1000'000'007;

int main() {
    int h, w, k;
    cin >> h >> w >> k;

    // 0-index
    --k;

    vector<ll> dp(w, 0);
    dp[0] = 1;
    for(int i = 1; i <= h; i++){
        vector<ll> dpNext(w, 0);
        for(int j = 0; j < (1 << (w-1)); ++j){
            bitset<8> bs(j);
            bool ng = false;
            for(int m = 0; m < w - 2; ++m){
                if(bs[m] == 1 && bs[m + 1] == 1){
                    ng = true;
                }
            }

            if(ng){
                continue;
            }

            // mは縦棒を表す
            for(int m = 0; m < w; ++m){
                // mの左側に横棒
                if(m > 0 && bs[m - 1]){
                    (dpNext[m] += dp[m - 1]) %= mod;
                }
                // mの右側に横棒
                else if(m < w - 1 && bs[m]){
                    (dpNext[m] += dp[m + 1]) %= mod;
                }
                // mに接触している横棒なし
                else{
                    (dpNext[m] += dp[m]) %= mod;
                }
            }
        }

        dpNext.swap(dp);
    }

    cout << dp[k] << endl;

    return 0;
}

