#include <iostream>
#include <cmath>
#define MOD 1000000007
using namespace std;
int H, W, K, meta[8] = {1,1,2,3,5,8,13,21};
long meta2[9][2], answer = 0;

void Map(int X, int Y, long result) {
	if (Y == H) {
		if (X == K+1) {
			answer = (answer + result * meta2[X-1][1]) % MOD;
		} else if (X == K) {
			answer = (answer + result * meta2[X][0]) % MOD;
		} else if ( X == K-1 ) {
			answer = (answer + result * meta2[X][1]) % MOD;
		}
		return;
	}

	if (abs(X-K) > abs(H-Y+1)) return;

	Map(X, Y+1, result * meta2[X][0]);

	if (X > 1) {
		Map(X-1, Y+1, result * meta2[X-1][1]);
	}

	if (X < W) {
		Map(X+1, Y+1, result * meta2[X][1]);
	}
}

int main(void) {
	cin >> H >> W >> K;
	for(int i=1; i<=W; i++)
		for(int j=0; j<2; j++)
			meta2[i][j] = meta[i - 1] * meta[W - i - j];
	Map(1, 1, 1);
	cout << answer;

}

