			else if (j == '1' || i[&j - &i[0] - 1] == '1' || j == to_string(w)[0] || i[&j - &i[0] - 1] == to_string(w)[0]) {
				ct *= pow(2, w - 3);
			}
			else ct *= pow(2, w - 4);
			ct %= mod;
		}
		ans += ct; ans %= mod;
	}
	cout << ans << endl;
	return 0;

}

