ll dp[110][10];
int main()
{
    cout << fixed << setprecision(30);
    ll H, W, K;
    cin >> H >> W >> K;
    dp[0][0] = 1;
    loop(i, H)
    {
        loop(j, W)
        {
            ll X = 0, Y = 0, Z = 0;
            loop(bit, 1 << (W - 1))
            {
                bool ng = false;
                loop(k, W - 2)
                {
                    if (flagon(bit, k) && flagon(bit, k + 1))
                        ng = true;
                }
                if (ng)
                    continue;
                if (j > 0)
                {
                    if (flagon(bit, j - 1))
                    {
                        X++;
                        continue;
                    }
                }
                if (j < W - 1)
                {
                    if (flagon(bit, j))
                    {
                        Z++;
                        continue;
                    }
                }
                Y++;
            }
            if (j > 0)
            {
                dp[i + 1][j - 1] += X * dp[i][j];
                dp[i + 1][j - 1] %= mod;
            }
            dp[i + 1][j] += Y * dp[i][j];
            dp[i + 1][j] %= mod;
            if (j < W - 1)
            {
                dp[i + 1][j + 1] += Z * dp[i][j];
                dp[i + 1][j + 1] %= mod;
            }
        }
    }
    putout(dp[H][K - 1]);
    return 0;
}

