#include <bits/stdc++.h>

#define REP(i, n) for(int (i)=0;(i)<(n);++(i))
#define MOD 1000000007

using namespace std;

typedef long long ll;

ll A[102][9] = {0};

int main()
{
    int H, W, K;
    cin >> H >> W >> K;

    vector<int> validPattern;
    validPattern.push_back(0);
    for (int i = 1; i <= pow(2, W - 1) - 1; ++i)
    {
        bool prev = false;
        bool now;
        REP(j, W)
        {
            int bit = 1 << j;
            now = (i & bit) == bit;
            if (prev && now) break;
            prev = now;
            if (j == W - 1) validPattern.push_back(i);
        }
    }

    A[1][1] = 1;
    for (int h = 1; h <= H; ++h)
    {
        for (int x = 1; x <= W; ++x)
        {
            for (auto iter = validPattern.begin(); iter != validPattern.end(); ++iter)
            {
                if (x - 1 >= 1)
                {
                    int bit = 1 << (x - 2);
                    if ((*iter & bit) == bit)
                    {
                        A[h + 1][x - 1] = (A[h + 1][x - 1] + A[h][x]) % MOD;
                        continue;
                    }
                }
                if (x + 1 <= W)
                {
                    int bit = 1 << (x - 1);
                    if ((*iter & bit) == bit)
                    {
                        A[h + 1][x + 1] = (A[h + 1][x + 1] + A[h][x]) % MOD;
                        continue;
                    }
                }
                A[h + 1][x] = (A[h + 1][x] + A[h][x]) % MOD;
            }
        }
    }

    cout << A[H + 1][K] << endl;
}

