                    if(b[l] == 1 && b[l+1] == 1){
                        isValid = false;
                        break;
                    }
                }
                if(!isValid){
                    continue;
                }
                // left
                if(j - 1 >= 0 && b[j - 1] == 1){
                    dp[i + 1][j - 1] += dp[i][j];
                    dp[i + 1][j - 1] = dp[i + 1][j - 1] % MOD;
                }
                // right
                else if(j + 1 < w && b[j] == 1){
                    dp[i + 1][j + 1] += dp[i][j];
                    dp[i + 1][j + 1] = dp[i + 1][j + 1] % MOD;
                }
                // down
                else {
                    dp[i + 1][j] += dp[i][j];
                    dp[i + 1][j] = dp[i + 1][j] % MOD;
                }
            }
        }
    }
    cout << dp[h][k] << endl;
    return;
}

