          else (dp[i + 1][j] += dp[i][j]) %= mod;
        }
        else if (j == w - 1) {
          if (bit >> (w - 2) & 1) (dp[i + 1][j - 1] += dp[i][j]) %= mod;
          else (dp[i + 1][j] += dp[i][j]) %= mod;
        }
        else {
          if (bit >> (j - 1) & 1) (dp[i + 1][j - 1] += dp[i][j]) %= mod;
          else if (bit >> j & 1) (dp[i + 1][j + 1] += dp[i][j]) %= mod;
          else (dp[i + 1][j] += dp[i][j]) %= mod;
        }
      }
    }
  }


  cout << dp[h][k - 1] << endl;


  return 0;
}

