void calcFibonacci(int *nums, int numsSize, int s, int n1, int n2) {
	int i = 0,tmp;
	int startPoint = s;
	int t1 = n1;
	int t2 = n2;

	nums[startPoint++] = t1;
	nums[startPoint++] = t2;

	FOR(i, startPoint, numsSize) {
		nums[i] = t1+t2;
		tmp = t2;
		t2 = nums[i];
		t1 = tmp;
	}

	// FOR(i, 0, numsSize) {
