}

void _solver(long long int *dp, int h, int w, int k) {
	int i,r = 0;
	long long int n1,n2,n3;
	int a[MAXW] = {0};
	calcFibonacci(a, w+1, 0, 1, 1);

	FOR(i, 1, w+1) {
		dp[i] *= a[w-i];
	}

	// FOR(i, 0, w+1) {
