		dp[1] = MOD(dp[1]*a[w-1] + dp[2]*a[w-2]);

		FOR(i, 2, w) {
			dp[i] = MOD(n1*a[w-i]*a[i-2] + n2*a[w-i]*a[i-1] + n3*a[w-i-1]*a[i-1]);
			n1 = n2;
			n2 = n3;
			n3 = dp[i+2];
		}

		dp[i] = MOD(n1*a[i-2] + n2*a[i-1]);

		// FOR(i, 0, w+1) {
