ll search(int x, int y, int h, int w, int k) {
  if(y==h) {
    if(x==k) return 1;
    else return 0;
  }
  if(dp[y][x] != -1) {
    return dp[y][x];
  }

  ll count = 0;
  if (x == 0) {
    count = (search(x, y+1, h, w, k) * c[0][w-x] +
             search(x+1, y+1, h, w, k) * c[1][w-x]) % MOD;
  } else if (x == w) {
    count = (search(x, y+1, h, w, k) * c[0][x] +
             search(x-1, y+1, h, w, k) * c[1][x]) % MOD;
  } else {
    count = (search(x-1, y+1, h, w, k) * c[1][x] * c[0][w-x] +
             search(x, y+1, h, w, k) * c[0][x] * c[0][w-x] |
             search(x+1, y+1, h, w, k) * c[0][x] * c[1][w-x]) % MOD;
  }

  // cerr << x << " " << y << " " << count << endl;
  return dp[y][x] = count;
}

