const int MOD = 1000 * 1000 * 1000 + 7;

int subcount(int n)
{
	if (n <= 0) {
		return 1;
	}
	int c = 0;
	for (int i = 0; i < (1 << n); ++i) {
		bool ok = true;
		for (int k = 0; k + 1 < n; ++k) {
			if ((i & (1 << k)) && (i & (1 << (k + 1)))) {
				ok = false;
				break;
			}
		}
		if (ok) {
			++c;
		}
	}
	return c;
}

int main()
{
