	cin >> H >> W >> K;

	long long dp[101][8 + 1] = {};
	dp[1][1] = subcount(W - 2);
	dp[1][2] = subcount(W - 3);
	for (int j = 3; j <= W; ++j) {
		dp[1][j] = 0;
	}

	for (int i = 2; i <= H; ++i) {
		for (int j = 1; j <= W; ++j) {
			if (1 < j) {
				dp[i][j - 1] += 1LL * subcount(j - 3) * subcount(W - j - 1) * dp[i - 1][j];
				dp[i][j - 1] %= MOD;
			}
			dp[i][j] += 1LL * subcount(j - 2) * subcount(W - j - 1) * dp[i - 1][j];
			dp[i][j] %= MOD;
			if (j < W) {
				dp[i][j + 1] += 1LL * subcount(j - 2) * subcount(W - j - 2) * dp[i - 1][j];
				dp[i][j + 1] %= MOD;
			}
		}
