            dp[i + 1][j] += dp[i][j - 1] * (com(w - j - 1) * com(j - 2));
        if (j <= w - 2)
            dp[i + 1][j] += dp[i][j + 1] * (com(w - j - 2) * com(j - 1));
        dp[i + 1][j] %= MOD;
    }
    cout << dp[h][k - 1] << endl;

    return 0;
}

