                    (dp[h+1][w-1] += dp[h][w]) %= MOD;
                } else if (w+1 <= W && ((p >> w) & 1)) {
                    (dp[h+1][w+1] += dp[h][w]) %= MOD;
                } else {
                    (dp[h+1][w] += dp[h][w]) %= MOD;
