const int MOD = 1000000007;


int H, W, K;
ll nop1[10], nop2[10];    //num of patterns
ll dp[101][10];

void enum_pattern(int W){
    REP(i, 10) nop1[i] = nop2[i] = 0;
    REP(i, (1 << W)){
        bool skip = false;
        REP(j, W - 1){
            if(((i >> j) & 3) == 3){
                skip = true;
                break;
            }
        }
        if(skip) continue;
        REP(j, W){
            if(((i >> j) & 1) == 1){
                nop1[j + 1]++;
            }
            if(j == 0 && ((i >> j) & 1) == 0){
                nop2[j + 1]++;
            }
            if(((i >> j) & 3) == 0){
                nop2[j + 2]++;
            }
        }
    }
}

ll solve(){
    REP(i, 101) REP(j, 10) dp[i][j] = 0;
    dp[0][1] = 1;
    FOR(i, 1, H + 1){
        FOR(j, 1, W + 1){
            dp[i][j] = dp[i - 1][j - 1] * nop1[j - 1] % MOD + dp[i - 1][j + 1] * nop1[j] % MOD + dp[i - 1][j] * nop2[j];
            dp[i][j] %= MOD;
        }
    }
    return dp[H][K];
}

