void DP() {
	for (int i = 1; i <= H; ++i) {
		for (int j = 0; j < W; ++j) {
			if (j) { // 直前 j-1 にいる
				int cnt = 0;
				for (int f = 0; f < (1 << (W - 1)); ++f) {
					if ((f & (f >> 1)) || (f & (f << 1))) continue;
					if (f & (1 << (j - 1))) ++cnt;
				}
				dp[i][j] += cnt * dp[i - 1][j - 1] % mod;
			}
			if (j != W - 1) { // 直前 j+1 にいる
				int cnt = 0;
				for (int f = 0; f < (1 << (W - 1)); ++f) {
					if ((f & (f >> 1)) || (f & (f << 1))) continue;
					if (f & (1 << j)) ++cnt;
				}
				dp[i][j] += cnt * dp[i - 1][j + 1] % mod;
			}
			{ // 引かない
				int cnt = 0;
				for (int f = 0; f < (1 << (W - 1)); ++f) {
					if ((f & (f >> 1)) || (f & (f << 1))) continue;
					if (f & (1 << j)) continue;
					if (f & (1 << (j - 1))) continue;
					++cnt;
				}
				dp[i][j] += cnt * dp[i - 1][j] % mod;
			}
			dp[i][j] %= mod;
		}
	}
}

int main() {
	input();
	DP();
	cout << dp[H][K] << endl;
	return 0;
}

