		for(int mask=0; mask<(1<<(W-1)); mask++) {
			bool ng = false;
			for(int b=0; b<W-2; b++)
				if(get_bit(mask, b) && get_bit(mask, b+1)) ng = true;
			if(ng) continue;
			for(int j = 0; j < W; j++) {
				if(j>0 && get_bit(mask, j-1)) (ndp[j-1] += dp[j]) %= mod;
				else if(j+1<W && get_bit(mask, j)) (ndp[j+1] += dp[j]) %= mod;
				else (ndp[j] += dp[j]) %= mod;
			}
		}
        swap(dp, ndp);
	}

	cout << dp[K-1] << endl;
	return 0;
}

