int main() {
    int h, w, K;
    cin >> h >> w >> K;
    K--;  // Kを0-indexにする

    vector<vector<ll>> dp(h+1, vector<ll>(w));  // dp[i+1][j] : i行目を通過した直後にj列目にいる場合の数のmodでの剰余(i,jは0-index)

    dp[0][0] = 1LL;
    rep(i, h) {
        rep(j, w) {
            for(int b = 0; b < (1 << (w-1)); b++) {  // bのjビット目が1ならj列目とj+1列目の間に横棒を引き、0なら引かない

                // 横棒がつながっていないか調べる
				int flag = 1;
				rep(L, w-1) {
					if ( (b & (1 << L)) && (b & (1 << (L+1))) ) {  // bのLビット目もL+1ビット目も1のとき
						flag = 0;  // 横棒はつながっている
					}
				}

                //横棒がつながっていないとき
                if(flag) {
                    // bのj-1ビット目が1だったら、j列目からj-1列目に移動する(左方向に横棒を通過する場合)
                    if( j >= 1 && (b & (1 << (j-1))) ) {
                        dp[i+1][j-1] += dp[i][j];
                        dp[i+1][j-1] %= mod;
                    }
                    // bのjビット目が1だったら、j列目からj+1列目に移動する(右方向に横棒を通過する場合)
                    else if( j <= w-2 && (b & (1 << j)) ) {
                        dp[i+1][j+1] += dp[i][j];
                        dp[i+1][j+1] %= mod;
                    }
                    // 横棒を通過せず下に降りる場合
                    else {
                        dp[i+1][j] += dp[i][j];
                        dp[i+1][j] %= mod;
                    }
                }

            }
        }
    }

    cout << dp[h][K] << endl;
    return 0;
}

