int H, W, K;

int rec(int w, int c) {

  if (w == W - 1) {
    for (int i = 0; i < w; i++) {
      if((c>>i & 1) == 1) a[w - i]++;
    }

    if ((c>>0 & 1) == 0) b[w + 1]++;
    if ((c>>(w-1) & 1) == 0) b[1]++;
    for (int i = 0; i < w - 1; i++) {
      if (((c>>(i) & 1) == 0) & ((c>>(i+1) & 1) == 0)) b[w - i]++;
    }

    return 0;
  }

  if (!(c & 1)) rec(w + 1, (c<<1) + 1);
  rec(w + 1, (c<<1) + 0);

  return 0;
}

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);

  cin >> H >> W >> K;

  if (W == 1) {
    cout << 1 << endl;
    return 0;
  }

  rec(1, 0);
  rec(1, 1);

  dp[0][1] = 1;

  for (int i = 1; i <= H; i++) {
    for (int j = 1; j <= W; j++) {

      if (j == 1) {
	dp[i][j] += (dp[i-1][j]   * b[j]) % MOD;
	dp[i][j] %= MOD;
	dp[i][j] += (dp[i-1][j+1] * a[j]) % MOD;
	dp[i][j] %= MOD;
      }
      else if (j == W) {
	dp[i][j] += (dp[i-1][j-1] * a[j-1]) % MOD;
	dp[i][j] %= MOD;
	dp[i][j] += (dp[i-1][j]   * b[j]) % MOD;
	dp[i][j] %= MOD;	
      }
      else {
	dp[i][j] += (dp[i-1][j-1] * a[j-1]) % MOD;
	dp[i][j] %= MOD;	
	dp[i][j] += (dp[i-1][j]   * b[j]) % MOD;
	dp[i][j] %= MOD;	
	dp[i][j] += (dp[i-1][j+1] * a[j]) % MOD;
	dp[i][j] %= MOD;	
      }
    }
  }

  cout << dp[H][K] << endl;
  return 0;
}

