bool valid(int v) {
    bool prev_on = false;
    while (v > 0) {
        if (v % 2 == 1) {
            if (prev_on) return false;
            prev_on = true;
        } else {
            prev_on = false;
        }
        v >>= 1;
    }
    return true;
}

vector<bool> decompose(int v, int w) {
    vector<bool> dec(w);
    REP(i, w) {
        dec[w-i-1] = v % 2;
        v >>= 1;
    }
    return dec;
}

auto solve() {
    int H, W, K;
    cin >> H >> W >> K;

    auto dp = vector<vll>(H + 1, vll(W, 0));
    dp[0][0] = 1;

    const int MOD = 1000000007;

    REP(r, H) {
        REP(v, pow(2, (W - 1))) {
            if (valid(v)) {
                vector<bool> d = decompose(v, W-1);
                REP(c, W) {
                    if (c != 0 && d[c - 1])
                        dp[r + 1][c - 1] = (dp[r + 1][c - 1] + dp[r][c]) % MOD;
                    else if (c != W - 1 && d[c])
                        dp[r + 1][c + 1] = (dp[r + 1][c + 1] + dp[r][c]) % MOD;
                    else
                        dp[r + 1][c] = (dp[r + 1][c] + dp[r][c]) % MOD;
                }
            }
        }
    }

    return dp[H][K - 1];
}

