int main() {
    int H, W, K;
    cin >> H >> W >> K;

    int w = W-1;
    for (int bit=0; bit<(1<<w); ++bit) {
        bool ok = true;
        for (int i=0; i<w-1; ++i) {
            if (bit&(1<<i) and bit&(1<<(i+1))) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;

        vector<int> P(W, 0);
        iota(P.begin(), P.end(), 0);
        for (int i=0; i<W-1; ++i) {
            if (bit&(1<<i)) swap(P[i], P[i+1]);
        }
        for (int i=0; i<W; ++i) num[i][P[i]]++;
    }

    dp[0][0] = 1;
    for (int i=0; i<H; ++i) {
        for (int k=0; k<W; ++k) {
            for (int j=0; j<W; ++j) {
                dp[i+1][k] += (dp[i][j] * num[j][k] % mod);
            }
        }
    }
    cout << dp[H][K-1]%mod << endl;
}

