bool ok(int mask)
{
    for (int i = 0; i < 20; ++i)
        if ((mask & (1 << i)) > 0 && (mask & (1 << (i + 1))) > 0)
            return false;
    return true;
}

int main()
{
    ios_base::sync_with_stdio(0);
    int n, m, k;
    cin >> n >> m >> k;
    if (m == 1)
    {
        cout << "1";
        return 0;
    }
    vector< vector<ll> > dp(n, vector<ll>(m, 0));
    for (int mask = 0; mask < (1 << (m - 1)); ++mask)
    {
        if (ok(mask))
        {
            if ((mask & (1 << 0)) > 0)
                ++dp[0][1];
            else
                ++dp[0][0];
        }
    }
    for (int i = 0; i < n - 1; ++i)
    {
        for (int j = 0; j < m; ++j)
        {
            for (int mask = 0; mask < (1 << (m - 1)); ++mask)
            {
                if (ok(mask))
                {
                    if (j - 1 >= 0 && (mask & (1 << (j - 1))) > 0)
                        dp[i + 1][j - 1] = (dp[i + 1][j - 1] + dp[i][j]) % MOD;
                    else
                    {
                        if (j < m - 1 && (mask & (1 << j)) > 0)
                            dp[i + 1][j + 1] = (dp[i + 1][j + 1] + dp[i][j]) % MOD;
                        else
                            dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % MOD;
                    }
                }
            }
        }
    }
    cout << dp[n - 1][k - 1];
    return 0;
}

