//番号x -> x+1の間に線を引くとき、その高さの線の引き方が何通りあるか？（0-indexed）
int count1(int x) {
	int i, j;
	int cnt = 0;

	rep(i, 1 << (w - 1)) {
		if ((i >> x) % 2 == 0) continue;
		rep(j, w - 2) {
			if ((i >> j) % 2 == 1 && (i >> (j + 1)) % 2 == 1) break;
		}
		if (w >= 3 && j < w - 2) continue;
		cnt++;
	}
	return cnt;
}

//番号x(>=0)の縦棒と隣接する場所に線を引かないとき、その高さの線の引き方が何通りあるか？
int count2(int x) {
	int i, j;
	int cnt = 0;

	rep(i, 1 << (w - 1)) {
		if ((i >> x) % 2 == 1) continue;
		if (x > 0 && (i >> (x - 1)) % 2 == 1) continue;
		rep(j, w - 2) {
			if ((i >> j) % 2 == 1 && (i >> (j + 1)) % 2 == 1) break;
		}
		if (w >= 3 && j < w - 2) continue;
		cnt++;
	}
	return cnt;
}

signed main() {
	int i, j;

	cin >> h >> w >> k;
	if (w == 1) { cout << 1 << endl; return 0; }
	k--;

	dp[0][0] = 1;
	rep(i, h) {
		rep(j, w) {
			//左にいく
			if (j > 0) {
				dp[i + 1][j - 1] += dp[i][j] * count1(j - 1);
				dp[i + 1][j - 1] %= mod;
			}
			//右に行く
			if (j + 1 < w) {
				dp[i + 1][j + 1] += dp[i][j] * count1(j);
				dp[i + 1][j + 1] %= mod;
			}
			//直進する
			dp[i + 1][j] += dp[i][j] * count2(j);
			dp[i + 1][j] %= mod;
		}
	}

	cout << dp[h][k] << endl;
	return 0;
}

