  for (int i = 0; i < h; ++i) {
    for (int bit = 0; bit < 1 << w - 1; ++bit) {
      bool ok = true;
      for (int x = 0; x < w - 2; ++x) if (bit & 1 << x and bit & 1 << x + 1) ok = false;
      if (!ok) continue;
      auto v = dp[i];
      for (int x = 0; x < w - 1; ++x) if (bit & 1 << x) swap(v[x], v[x + 1]);
      for (int j = 0; j < w; ++j) (dp[i + 1][j] += v[j]) %= mod;
    }
  }
  cout << emod(dp[h][k]) << '\n';
}

