int fib(int x){
  if(x<0){return 0;}
  else if (x==1){return 1;}
  else{ return (fib(x-1)+fib(x-2))%M;}
}

int solve(int y, int W, int x){
  if (x<=0){return 0;}
  else if (x>=W+1){return 0;}
  else if (y==0&&x==1){return 1;}
  else if (y==0){return 0;}
  else{
    int a=(solve(y, W, x-1)*fib(x-2)*fib(W-(x-1)))%M;
    int b=(solve(y, W, x+1)*fib(x-1)*fib(W-x))%M;
    int c=(solve(y, W, x)*fib(x-1)*fib(W-(x-1)))%M;
    return (a+b+c)%M;
  }
}

