int main() {
  int h, w, k;
  scanf("%d%d%d", &h, &w, &k);
  w--, k--;
  int wbits = 1 << w;

  for (int bits = 0; bits < wbits; bits++) {
    bool ok = true;
    for (int i = 0, bi = 3; ok && i < w - 1; i++, bi <<= 1)
