      for (int j = 0; j <= w; j++) {
	if (j > 0 && (bits & (1 << (j - 1))))
	  addmod(dp[i + 1][j - 1], dp[i][j]);
	else if (j < w && (bits & (1 << j)))
	  addmod(dp[i + 1][j + 1], dp[i][j]);
	else
	  addmod(dp[i + 1][j], dp[i][j]);
      }
    }
  }

  printf("%d\n", dp[h][k]);
