		if (msk & (1 << k)) dp[h + 1][k + 1] += dp[h][k];
		else if (0 < k and msk & (1 << (k - 1))) dp[h + 1][k - 1] += dp[h][k];
		else dp[h + 1][k] += dp[h][k];
	}

	cout << dp[H][K] << endl;
	return 0;
}

