typedef long long ll;

const ll MOD = 1e9+7;
const int MAX_H = 1e3 + 10, MAX_W = 10;

ll fib[1000];

void calcFib(){
	fib[0] = 1;
	fib[1] = 1;
	for (int i = 2; i < 1000; ++i) {
		fib[i] = fib[i-1]+fib[i-2] % MOD;
	}
}

vector<vector<ll>> matmul(vector<vector<ll>> a, vector<vector<ll>> b){
	int l = a[0].size();

	vector<vector<ll>> ret(l, vector<ll>(l,0));

	for (int i = 0; i < l; ++i) {
		for (int j = 0; j < l; ++j) {
			for (int k = 0; k < l; ++k) {
				ret[i][j] += a[i][k] * b[k][j];
				ret[i][j] %= MOD;
			}
		}
	}
	return ret;
}

vector<vector<ll>> matpow(vector<vector<ll>> m, int n){
	int l = m[0].size();

	if (n==0) {
		for (int i = 0; i < l; ++i) {
			for (int j = 0; j < l; ++j) {
				m[i][j] = (i==j);
			}
		}
		return m;
	}

	if (n==1) return m;

	if (n%2) {
		return matmul(matpow(m, n-1), m);
	}
	else {
		return matpow(matmul(m,m), n/2);
	}
}

int main(int argc, char const *argv[])
{
	calcFib();

	int H, W, K;
	cin >> H >> W >> K;
	K--;

	vector<vector<ll>> M(W, vector<ll>(W,0));

	for (int i = 2; i <= W; ++i) {
		M[i-2][i-1] = fib[i-2]*fib[W-i] % MOD;
	}

	for (int i = 1; i < W; ++i) {
		M[i][i-1] = fib[i-1]*fib[W-i-1] % MOD;
	}

	for (int i = 1; i < W; ++i) {
		M[i-1][i-1] = fib[i-1]*fib[W-i]%MOD;
	}

	auto res = matpow(M, H);
	cout << res[K][0] << endl;
	return 0;
}

