        if(v[min(from, to)]){
            bool ok = true;
            rep(i, sz-1) if(v[i] == 1 && v[i+1] == 1) ok = false;
            return ok;
        }
        else return false;
    }
    else{
        //v[from]とv[from-1]は1だと駄目
        if((from < sz && v[from] == 1) || (0 <= from-1 && v[from-1] == 1)) return false;
        else{
