static void ABC113D_NumOfAmida()
{
	//	写経させていただきました。力不足でお恥ずかしい。こんな発想出てこないっす
	int H, W, K;
	static ULLONG dp[101][8] = { 0 };
	dp[0][0] = 1;

	scanf(" %d %d %d", &H, &W, &K);

	for (int h = 0; h < H; h++) {
		for (int x = 0; x < W; x++) {
			//	賢いなあ。あみだくじの横線ありなしををビットの 1/0 で表現なんて思いつかないわ
			for (int line = 0; line < (1 << (W - 1)); line++) {
				//	で，ビット列が 11 になっているものがないかをチェックするのね
				bool connected = false;
				for (int chk = 0; chk < (W - 2); chk++) {
					if (((line >> chk) & 1) && ((line >> (chk + 1)) & 1)) {
						//	ビット列が 11 の並びがあったらこのパターンはダメ，と
						connected = true;
					}
				}
				//	横線がつながっちゃってるんで，パス
				if (connected) continue;

				if ((x >= 1) && ((line >> (x - 1)) & 1)) {
					//	x より左側に 1 があれば，左に向かって移動した，と
					dp[h + 1][x - 1] += dp[h][x];
					dp[h + 1][x - 1] %= UL_HUGE_DIVIDER;
				}
				else if ((x <= (W - 2)) && ((line >> x) & 1)) {
					//	x より右側に 1 があれば，右に向かって移動した，と
					dp[h + 1][x + 1] += dp[h][x];
					dp[h + 1][x + 1] %= UL_HUGE_DIVIDER;
				}
				else {
					//	右でも左でもなく，連続した横線もない
					dp[h + 1][x] += dp[h][x];
					dp[h + 1][x] %= UL_HUGE_DIVIDER;
				}
			}
		}
	}

	printf("%llu\n", dp[H][K - 1]);
}

