                    dp[i][j-1]+=dp[i-1][j]*pow(2,w-1-2)%mod;//pow(2,w-1-2)＝どうでもよい場所の組み合わせ
                    dp[i][j+1]+=dp[i-1][j]*pow(2,w-1-2)%mod;
                    dp[i][j-1]%=mod;
                    dp[i][j+1]%=mod;
                    dp[i][j]+=dp[i-1][j]*pow(2,w-1-1)%mod;
                    dp[i][j]%=mod;
                }
            }
        }
    }
    printf("%lld\n",dp[h][k-1]);
}

