	for (int i = 2; i <= W; ++i) {
		M[i-2][i-1] = fib[i-2]*fib[W-i] % MOD;
	}

	for (int i = 1; i < W; ++i) {
		M[i][i-1] = fib[i-1]*fib[W-i-1] % MOD;
	}

	for (int i = 1; i <= W; ++i) {
		M[i-1][i-1] = fib[i-1]*fib[W-i]%MOD;
	}

	auto res = matpow(M, H);
	cout << res[K][0] << endl;
	return 0;
}

