            if(!(bit & 1)){
                dp[i+1][0] += dp[i][0];
                dp[i+1][0] %= MOD;
            }

            for(int j=0; j+1<w-1; j++){
                if(!(bit & (1 << j)) && !(bit & (1 << (j + 1)))){
                    dp[i+1][j+1] += dp[i][j+1];
                    dp[i+1][j+1] %= MOD;
                }
            }

            if(!(bit & (1 << (w - 2)))){
                dp[i+1][w-1] += dp[i][w-1];
