    dp[0][0] = 1;
    REP(i,h){
        REP(j,w){
            if(!dp[i][j])continue;
            REP(k, 1<<(w-1)){

                if(k&(k<<1))
                    continue;
                bool r = j ? (k & (1 << (j - 1))) : 0;
                bool l = j != w - 1 ? (k & (1 << j)) : 0;

                dp[i + 1][j - r + l] += dp[i][j];
                dp[i + 1][j - r + l] %= MOD;
            }
        }
    }
    COUT(dp[h][k-1]);

}

