int exists(const int w, const int p) {
    vector<vector<int>> f(w, vector<int>(2, 0));
    f[0][0] = 1;
    for (int i = 0; i + 1< w; ++i) {
        if (f[i][0]) {
            MOD_ADD(&f[i + 1][1], f[i][0]);
            if (i != p) {
                MOD_ADD(&f[i + 1][0], f[i][0]);
            }
        }
        if (f[i][1]) {
            if (i != p){
                MOD_ADD(&f[i + 1][0], f[i][1]);
            }
        }
    }
    return MOD_STD(MOD_ADD(f[w - 1][0], f[w - 1][1]));
}

int free(const int w, const int p) {
    vector<vector<int>> f(w, vector<int>(2, 0));
    f[0][0] = 1;
    for (int i = 0; i + 1 < w; ++i) {
        if (f[i][0]) {
            if (i != p && i != p - 1) {
                MOD_ADD(&f[i + 1][1], f[i][0]);
            }
            MOD_ADD(&f[i + 1][0], f[i][0]);
        }
        if (f[i][1]) {
            MOD_ADD(&f[i + 1][0], f[i][1]);
        }
    }
    return MOD_STD(MOD_ADD(f[w - 1][0], f[w - 1][1]));
}


int solution(const int h, const int w, const int k) {
    vector<vector<int>> f(h + 1, vector<int>(w, 0));
    f[0][0] = 1;
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            if (!f[i][j]) continue;
            //int total = 0;
            // <--
            if (j > 0) {
                MOD_ADD(&f[i + 1][j - 1], MOD_MUL(f[i][j], exists(w, j - 1)));
                //MOD_ADD(&total, exists(w, j - 1));
            }
            // ===
            MOD_ADD(&f[i + 1][j], MOD_MUL(f[i][j], free(w, j)));
            //MOD_ADD(&total, free(w, j));
            // -->
            if (j + 1 < w) {
                MOD_ADD(&f[i + 1][j + 1], MOD_MUL(f[i][j], exists(w, j)));
                //MOD_ADD(&total, exists(w, j));
            }
            //fprintf(stderr, "total: %d\n", MOD_STD(total));
        }
    }
    return MOD_STD(f[h][k]);
}

int main(){
    int h, w, k;
    while (scanf("%d%d%d", &h, &w, &k)!=EOF) {
        printf("%d\n", solution(h, w, k - 1));
    }
    return 0;
}

