    for(int j=1; j<w-1; j++){
      a[i][j] = (a[i-1][j-1] * fib(j-1) * fib(w-j-1)) % md + (a[i-1][j] * fib(j) * fib(w-j-1)) % md + (a[i-1][j+1] * fib(j) * fib(w-j-2)) % md;
