    for (int i=2;i<9;i++){
        predp[i] = 0;
        for (int j=i-2;j>=0;j--){
            predp[i] += predp[j];
        }
        predp[i] += 2;
    }


    int h,w,k;
    cin >> h >> w >> k;
    static const int H = h;
    static const int W = w;

    long long dp[H][W];
    for (int i=0;i<H;i++){
        for (int j=0;j<W;j++){
            dp[i][j] = 0;
        }
    }
    if(w-2 >= 0) {
        dp[0][0] = predp[w - 2];
    }else{
        dp[0][0] = 1;
    }
    if(w-3 >= 0 and w > 1){
        dp[0][1] = predp[w-3];
    }else if(w > 1) {
        dp[0][1] = 1;
    }

    for (int i=0;i<h-1;i++){
        for (int x=0;x<w;x++){
            if(x-2 >= 0 and w-x-2 >= 0){
                dp[i+1][x] += dp[i][x] * predp[x-2] * predp[w-x-2];
            }else if(x-2 >= 0){
                dp[i+1][x] += dp[i][x] * predp[x-2];
            }else if (w-x-2 >= 0){
                dp[i+1][x] += dp[i][x] * predp[w-x-2];
            }else {
                dp[i+1][x] += dp[i][x];
            }
            if(x-1 >= 0) {
                if (x - 3 >= 0 and w - x - 2 >= 0) {
                    dp[i + 1][x] += dp[i][x - 1] * predp[x - 3] * predp[w - x - 2];
                } else if (x - 3 >= 0) {
                    dp[i + 1][x] += dp[i][x - 1] * predp[x - 3];
                } else if (w - x - 2 >= 0) {
                    dp[i + 1][x] += dp[i][x - 1] * predp[w - x - 2];
                } else {
                    dp[i + 1][x] += dp[i][x - 1];
                }
            }
            if(x+1 < w){
                if (x - 2 >= 0 and w - x - 3 >= 0) {
                    dp[i + 1][x] += dp[i][x+1] * predp[x-2] * predp[w-x-3];
                } else if (x - 2 >= 0) {
                    dp[i + 1][x] += dp[i][x+1] * predp[x-2];
                } else if (w - x - 3 >= 0) {
                    dp[i + 1][x] += dp[i][x+1] * predp[w-x-3];
                } else {
                    dp[i + 1][x] += dp[i][x+1];
                }
            }
            dp[i+1][x] %= 1000000007;

        }
    }
    cout << dp[h-1][k-1] << endl;



