void solve()
{
	READ(llong, H, W, K);

	K--;

	vector<llong> dp(W);
	dp[K] = 1;
	llong MOD = 1000000007;
	REP(h, H)
	{
		vector<llong> next(W);

		REP(i, W)
		{
			if (dp[i] == 0)
			{
				continue;
			}

			for (int lines = 0; lines < 1 << (W - 1); lines++)
			{
				{
					int l = lines;
					bool ok = true;
					while (l)
					{
						if ((l & 3) == 3)
						{
							ok = false; break;
						}
						l >>= 1;
					}
					if (!ok) { continue; }
				}

				if ((i > 0) && (lines & 1 << i-1))
				{
					next[i - 1] = (next[i - 1] + dp[i]) % MOD;
				}
				else if ((i < W-1) && (lines & 1 << i))
				{
					next[i + 1] = (next[i + 1] + dp[i]) % MOD;
				}
				else
				{
					next[i] = (next[i] + dp[i]) % MOD;
				}
			}
		}

		dp.swap(next);
	}

	WRITE(dp[0]);

}

