using mint = Fp<MOD>;

i64 H, W, K;
mint dp[MAX_H + 1][MAX_W];
mint fact[2 * MAX_W];

mint modfact(i64 n) {
    if (fact[n] > (mint)0) return fact[n];

    mint p = 1;
    REPS(i, n) {
        p *= (mint)i;
        fact[i] = p;
    }

    return fact[n] = p;
}

mint modcomb(i64 n, i64 k) {
    if (n < k) return (mint)0;
    return modfact(n) / (modfact(k) * modfact(n - k));
}

int main() {
    cin >> H >> W >> K;
    K--;

    i64 N_GAP = W - 1;

    vector<mint> C(N_GAP, 0);
    REP(i, N_GAP) {
        REP(k, N_GAP) {
            i64 n = i - k + 1;
            if (n < k) break;
            C[i] += modcomb(n, k);
        }
        if (N_GAP <= 0) C[i] = 1;
    }

    REP(i, H + 1) REP(j, W) dp[i][j] = 0;
    dp[0][0] = 1;

    REP(i, H) {
        REP(j, W) {
            auto comb = [&](i64 n) {
                if (n <= 0) return (mint)1;
                return C[n];
            };
            i64 left_gap = j;
            i64 right_gap = W - 1 - j;
            if (j > 0) dp[i + 1][j - 1] += dp[i][j] * comb(left_gap - 2) * comb(right_gap - 1);
            if (j < W - 1) dp[i + 1][j + 1] += dp[i][j] * comb(left_gap - 1) * comb(right_gap - 2);

            dp[i + 1][j] += dp[i][j] * comb(left_gap - 1) * comb(right_gap - 1);
        }
    }

    cout << dp[H][K] << endl;

    return 0;
}

