const int INF = 1e18;
const int MOD_N = 1e9+7;

int GF_MOD = MOD_N;
struct GF {
   int mod, x;
   GF() : mod(GF_MOD), x(0) {}
   GF(int a) : mod(GF_MOD) { x = ((a % mod) + mod) % mod; }
   GF& operator=(const GF& a) {
      x = a.x;
      return *this;
   }
   GF& operator=(int a) {
      return *this = GF(a);
   }
   GF operator-() const {
      return GF((-x + mod) % mod);
   }
   GF power(int n) const {
      GF tmp = x, res = 1;
      while (n > 0) {
         if ((n & 1) == 1) res *= tmp;
         tmp *= tmp;
         n >>= 1;
      }
      return res;
   }
   GF inverse() const {
      return GF(power(mod-2));
   }
   GF& operator+=(const GF& a) {
      (x += a.x) %= mod;
      return *this;
   }
   GF& operator-=(const GF& a) {
      return *this += -a;
   }
   GF& operator*=(const GF& a) {
      (x *= a.x) %= mod;
      return *this;
   }
   GF& operator/=(const GF& a) {
      return *this *= a.inverse();
   }
   const GF operator+(const GF& a) const {
      return GF(x) += a;
   }
   const GF operator-(const GF& a) const {
      return GF(x) -= a;
   }
   const GF operator*(const GF& a) const {
      return GF(x) *= a;
   }
   const GF operator/(const GF& a) const {
      return GF(x) /= a;
   }
   GF& operator+=(int a) {
      return *this += GF(a);
   }
   GF& operator-=(int a) {
      return *this -= GF(a);
   }
   GF& operator*=(int a) {
      return *this *= GF(a);
   }
   GF& operator/=(int a) {
      return *this /= GF(a);
   }
   const GF operator+(int a) const {
      return GF(x) += a;
   }
   const GF operator-(int a) const {
      return GF(x) -= a;
   }
   const GF operator*(int a) const {
      return GF(x) *= a;
   }
   const GF operator/(int a) const {
      return GF(x) /= a;
   }
};
auto&operator<<(ostream&s,const GF&a){s<<a.x;return s;}

