int saiki(int takasa,int yoko){
	if(takasa==h){
		return yoko==k-1;
	}
	if(dp[takasa][yoko]!=-1) return dp[takasa][yoko];

	int cnt=0;
	for(int bit=0; bit<1<<(w-1); bit++){
		bool ok=true;
