			if(bit&(1<<k)&&bit&(1<<(k+1))){
				ok=false;
				break;
			}
		}
		if(!ok) continue;
		if(yoko>=1&&bit&(1<<(yoko-1))) cnt+=saiki(takasa+1, yoko-1);
		else if(bit&(1<<(yoko))) cnt+=saiki(takasa+1, yoko+1);
		else cnt+=saiki(takasa+1, yoko);
	}
	return dp[takasa][yoko]=cnt%MOD;
}

