const int MOD = 1e9 + 7;


void solve(LL H, LL W, LL K){
	int dp[H + 1][W];
	CLR(dp);
	dp[0][0] = 1;
	FOR(i, 1, H + 1) {
		REP(j, 1 << (W - 1)) {
			if (j & (j << 1)) {
				continue;
			}
			REP(k, W) {
				if (k < (W - 1) && j & (1 << k)) {
					dp[i][k + 1] += dp[i - 1][k];
					dp[i][k + 1] %= MOD;
				} else if (k > 0 && j & (1 << (k - 1))) {
					dp[i][k - 1] += dp[i - 1][k];
					dp[i][k - 1] %= MOD;
				} else {
					dp[i][k] += dp[i - 1][k];
					dp[i][k] %= MOD;
				}
			}
		}
	}
	cout << dp[H][K - 1] << endl;
}


int main(){	
	LL W;
	LL H;
	LL K;
	scanf("%lld",&H);
	scanf("%lld",&W);
	scanf("%lld",&K);
	solve(H, W, K);
	return 0;
}

