ll h, w, k;
ll memo[110][10];

ll rec(ll i, ll j){
    if(i == 0 && j == 0) return 1;
    if(i == 0) return 0;
    if(memo[i][j] != -1) return memo[i][j];
    ll res = 0;
    //cout << i << " " << j << endl;
    for(ll bit = 0; bit < (1LL << (w - 1)); bit++){
        bool ok = true;
        for(ll ii = 0; ii < w - 2; ii++){
            if((bit & (1LL << ii)) && (bit & (1LL << (ii + 1)))){
                ok = false;
                break;
            }
        }
        if(ok){
            if(bit & (1LL << j) && j + 1 < w){
                res += rec(i - 1, j + 1);
            } else if(bit & (1 << (j - 1)) && j - 1 >= 0){
                res += rec(i - 1, j - 1);
            } else {
                res += rec(i - 1, j);
            }
            res %= MOD;
        }
    }
    return memo[i][j] = res;

}
