using namespace std ;

int H , W , K , D ; 
int F[105][135][9] ; // ÁÐÊý¡¢¸ÃÁÐ×´Ì¬¡¢Ð¡ÇòÐÐÊý 

inline bool Judge( int i ) { // ÅÐ¶ÏÒ»¸ö×´Ì¬ÊÇ·ñºÏ·¨ 

	for(register int j = 1 ; j < W - 1 ; ++j ) 
		if( ( i & ( 1 << j ) ) and ( i & ( 1 << j - 1 ) ) )
			return false ;
	return true ;

}
inline void Update( int &A , int B ) {
	A = ( A + B ) % Mod ;
}

int main() {

	scanf( "%d%d%d" , &H , &W , &K ) ;
	D = 1 << W - 1 ;
	for(register int i = 0 ; i < D ; ++i ) { // Ã¶¾ÙµÚÒ»ÁÐµÄ×´Ì¬ 
		if( not Judge( i ) ) continue ;
		if( i & 1 ) F[1][i][2] = 1 ;
			else F[1][i][1] = 1 ;
	}
	for(register int i = 1 ; i < H ; ++i ) { // Ïòºó×ªÒÆ  
		for(register int j = 0 ; j < D ; ++j ) { // Ã¶¾Ù×´Ì¬ 
			if( not Judge( j ) ) continue ;
			for(register int k = 1 ; k <= W ; ++k ) { // Ã¶¾ÙÐ¡ÇòËùÔÚµÄÐÐ 
				for(register int tj = 0 ; tj < D ; ++tj ) { // Ã¶¾Ù×ªÒÆºóµÄ×´Ì¬ 
					if( not Judge( tj ) ) continue ;
					if( k != 1 )
						if( tj & ( 1 << k - 2 ) ) {
							Update( F[i+1][tj][k-1] , F[i][j][k] ) ;
							continue ;
						}
					if( k != W )
						if( tj & ( 1 << k - 1 ) ) {
							Update( F[i+1][tj][k+1] , F[i][j][k] ) ;
							continue ;
						}
					Update( F[i+1][tj][k] , F[i][j][k] ) ;
				}
			}
		}
	}
	int Ans = 0 ;
	for(register int i = 0 ; i < D ; ++i )
		if( Judge( i ) ) Update( Ans , F[H][i][K] ) ;
	return not printf( "%d\n" , Ans ) ;

}

