template <int64_t Mod>
struct ModInt {
  int64_t x;

  ModInt() : x(0) {}

  ModInt(int64_t y) : x(y >= 0 ? y % Mod : (Mod - (-y) % Mod) % Mod) {}

  ModInt &operator+=(const ModInt &p) {
    if ((x += p.x) >= Mod) x -= Mod;
    return *this;
  }

  ModInt &operator-=(const ModInt &p) {
    if ((x += Mod - p.x) >= Mod) x -= Mod;
    return *this;
  }

  ModInt &operator*=(const ModInt &p) {
    x = int64_t(1LL * x * p.x % Mod);
    return *this;
  }

  ModInt &operator/=(const ModInt &p) {
    *this *= p.Inverse();
    return *this;
  }

  ModInt operator-() const { return ModInt(-x); }

  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

  bool operator==(const ModInt &p) const { return x == p.x; }

  bool operator!=(const ModInt &p) const { return x != p.x; }

  ModInt Inverse() const {
    int64_t a = x, b = Mod, u = 1, v = 0, t;
    while (b > 0) {
      t = a / b;
      swap(a -= t * b, b);
      swap(u -= t * v, v);
    }
    return ModInt(u);
  }

  ModInt Pow(int64_t n) const {
    ModInt ret(1), mul(x);
    while (n > 0) {
      if (n & 1) ret *= mul;
      mul *= mul;
      n >>= 1;
    }
    return ret;
  }

  friend ostream &operator<<(ostream &os, const ModInt &p) { return os << p.x; }

  friend istream &operator>>(istream &is, ModInt &a) {
    int64_t t;
    is >> t;
    a = ModInt<Mod>(t);
    return (is);
  }

  static int64_t GetMod() { return Mod; }
};

signed main(int argc, char *argv[]) {
  (void)argc;
#ifdef USE_STACK_TRACE_LOGGER
  google::InitGoogleLogging(argv[0]);
  google::InstallFailureSignalHandler();
#else
  (void)argv;
#endif  // USE_STACK_TRACE_LOGGER
  int64_t H, W, K;
  In(H, W, K);

  using Mi = ModInt<1000000007>;

  auto hoge  = MakeNdVector(W + 1, 2, Mi(0));
  hoge[1][0] = hoge[1][1] = 1;
  rep(i, 1, W) {
    hoge[i + 1][0] += hoge[i][0];
    hoge[i + 1][0] += hoge[i][1];
    hoge[i + 1][1] += hoge[i][0];
  }

  auto dp  = MakeNdVector(H + 1, W, Mi(0));
  dp[0][0] = 1;
  rep(i, H) {
    rep(j, W) {
      {
        Mi l = 1;
        if (j > 1) {
          l = hoge[j - 1][0].x + hoge[j - 1][1].x;
        }
        Mi r = 1;
        if (W - j - 2 > 0) {
          r = hoge[W - j - 2][0].x + hoge[W - j - 2][1].x;
        }
        dp[i + 1][j] += dp[i][j] * l * r;
      }

      if (j + 1 < W) {
        Mi l = 1;
        if (j - 1 > 0) {
          l = hoge[j - 1][0].x + hoge[j - 1][1].x;
        }
        Mi r = 1;
        if (W - j - 3 > 0) {
          r = hoge[W - j - 3][0].x + hoge[W - j - 3][1].x;
        }
        dp[i + 1][j + 1] += dp[i][j] * l * r;
      }
      if (j - 1 >= 0) {
        Mi l = 1;
        if (j - 2 > 0) {
          l = hoge[j - 2][0].x + hoge[j - 2][1].x;
        }
        Mi r = 1;
        if (W - j - 2 > 0) {
          r = hoge[W - j - 2][0].x + hoge[W - j - 2][1].x;
        }
        dp[i + 1][j - 1] += dp[i][j] * l * r;
      }
    }
  }
  cout << dp[H][K - 1].x << endl;
  return EXIT_SUCCESS;
}

