int main () {
  long H, W, K;
  cin >> H >> W >> K;
  long a, flag = 0;
  string sub;
  vector<string> data;
  for(int i = 0; i < pow(2, W - 1); i++){
    a = i;
    sub = "";
    flag = 0;
    for(int j = 0; j < W - 1; j++){
      if(flag == 1){
        if(a % 2 == 1){
          flag = 0;
          break;
        } else flag = 0;
      } else {
        if(a % 2 == 1)flag = 1;
      }
      sub += a % 2 + '0';
      a /= 2;
      if(j == W - 2)flag = 1;
    }
    if(flag == 1){
      data.push_back(sub);
      cout << sub << endl;
    }
  }
  vector<long> path(W - 1);
  for(int i = 0; i < data.size(); i++){
    for(int j = 0; j < W - 1; j++){
      path.at(j) += data.at(i).at(j) - '0';
    }
  }
  for(int i = 0; i < W - 1; i++)cout << path.at(i) << ' ';
  vector<vector<long>> dp(H + 1, vector<long>(W + 1));
  dp.at(0).at(1) = 1;
  for(int i = 0; i < H; i++){
    for(int j = 0; j < path.size(); j++){
      dp.at(i + 1).at(j + 2) += dp.at(i).at(j + 1) * path.at(j);
      dp.at(i + 1).at(j + 1) += dp.at(i).at(j + 2) * path.at(j);
      dp.at(i + 1).at(j + 2) %= 1000000007;
      dp.at(i + 1).at(j + 1) %= 1000000007;
    }
    for(int j = 1; j < W + 1; j++){
      if(i == 1)dp.at(i + 1).at(j) += dp.at(i).at(j) * (data.size() - path.at(i - 1));
      else if(i == W)dp.at(i + 1).at(j) += dp.at(i).at(j) * (data.size() - path.at(i - 2));
      else dp.at(i + 1).at(j) += dp.at(i).at(j) * (data.size() - path.at(i - 1) - path.at(i - 2));
    }
  }
  cout << dp.at(H).at(K) << endl;
  return 0;
}

