#define MAX_PAT_NUM 1000000007

uint64_t getBridgePatternNum(int32_t colNum)
{
    if (colNum <= 0) {
        return 0;
    } else if (colNum == 1) {
        return 1;
    } else if (colNum == 2) {
        return 2;
    } else {
        return getBridgePatternNum(colNum-1) + getBridgePatternNum(colNum-2);
    }
}

int main(void)
{
    uint32_t h,w,k;
    cin >> h >> w >> k;

    uint64_t patternVec[w] = {};
    patternVec[0] = 1;

    for (uint32_t i = 0; i < h; ++i) {
        uint64_t prePatternVec[w] = {};
        memcpy(prePatternVec, patternVec, sizeof(prePatternVec));
        memset(patternVec, 0, sizeof(patternVec));
        for (int32_t j = 0; j < w; ++j) {
            int32_t preCol[3] = {j, j+1, j-1};
            for (uint32_t n = 0; n < 3; ++n) {
                if (0 <= preCol[n] && preCol[n] < w) {
                    int32_t leftColNum = ((j < preCol[n]) ? j : preCol[n]);
                    int32_t rightColNum = w - ((j > preCol[n]) ? j : preCol[n]) - 1;
                    uint64_t leftBridgePatNum = getBridgePatternNum(leftColNum);
                    uint64_t rightBridgePatNum = getBridgePatternNum(rightColNum);
                    patternVec[j] += (prePatternVec[preCol[n]] 
                                        * (leftBridgePatNum != 0 ? leftBridgePatNum : 1)
                                        * (rightBridgePatNum != 0 ? rightBridgePatNum : 1)
                                        );
                    patternVec[j] = patternVec[j] % MAX_PAT_NUM;
                }
            }
        }
    }

    cout << patternVec[k-1] << endl;

    return 0;
}

