    rep(i,h+1){
        rep(j,w){
            dp[i][j] = 0;
        }
    }
    dp[0][0] = 1;
    srep(i,1,h+1){
        rep(j,w){
            dp[i][j] = dp[i-1][j  ] * fib(j-1) * fib(w-1-(j+1)); 
            if(1<=j)dp[i][j] += dp[i-1][j-1] * fib(j-2) * fib(w-1-(j+1));
            if(j<=w-2)dp[i][j] += dp[i-1][j+1] * fib(j-1) * fib(w-1-(j+2));
            dp[i][j] %= MOD;
        }
    }

    cout << dp[h][k] << endl;

    return 0;
}

