// dpテーブル(何行目か, 何番目の縦棒か)
ll dp[110][10];

int main(){
    int H, W, K;
    cin >> H >> W >> K;

    dp[0][1] = 1;

    for(int i = 0; i < H; ++i){

        // i+1行目のdpテーブルを埋めていく
        for(int j = 1; j <= W; ++j){
            // 横棒の並べ方に関するbit全探索
            for(int b = 0; b < (1 << (W - 1)); ++b){
                // 2つの横棒がつながっていればcontinue
                bool flag = true;
                for(int l = 0; l < W - 2; ++l){
                    if(((b >> l) & 1) && ((b >> (l + 1)) & 1)){
                        flag = false;
                        break;
                    }
                }
                if(!flag)       continue;

                // 左方向に縦線をたどる
                if(j >= 2 && ((b >> (W - j)) & 1)){
                    dp[i + 1][j - 1] += dp[i][j];
                    dp[i + 1][j - 1] %= mod;
                }
                // 右方向に縦棒をたどる
                else if(j <= W - 1 && ((b >> (W - 1 - j)) & 1)){
                    dp[i + 1][j + 1] += dp[i][j];
                    dp[i + 1][j + 1] %= mod;
                }
                // 横棒をたどらない
                else{
                    dp[i + 1][j] += dp[i][j];
                    dp[i + 1][j] %= mod;
                }
            }
        }
    }

    cout << dp[H][K] << endl;
}

