using namespace std;

long int C = 1000000007;

int ipow2(int n){
  int ans = 1;
  for(int i = 0; i < n; i++){
    ans *=2;
  }
  return ans;
}

int get_rungs(int W, int rungs[128][7]){

  int ans=0;

  int rung_tmp[7];
  int tmp = 0;
  for(int i = 0; i < ipow2(W-1); i++){
    /* generate all combination of rungs*/
    tmp = i;
    for(int j = 0; j < W-1; j++){
      rung_tmp[j] = tmp%2;
      tmp /= 2;
    }
    //for(int j = 0; j < W-1; j++)printf("%d", rung_tmp[j]); printf("\n");
    /* check the combination*/
    int check = 1;
    for(int i = 0; i < W-2; i++){
      if(rung_tmp[i] == 1 && rung_tmp[i+1] == 1){
        check = 0;
      }
    }
    if(check == 1){
      /*copy possible rung*/
      for(int i = 0; i < W-1; i++){
        rungs[ans][i] = rung_tmp[i];
      }
      ans++;
    }
  }

  return ans;
}



int main(){
  /* read problem from input*/
  int H;
  int W;
  int K;
  scanf("%d", &H);
  scanf("%d", &W);
  scanf("%d", &K);

  if(W==1){
    printf("1");
  }
  else{

  int rungs[128][7];
  int num_rungs;
  num_rungs = get_rungs(W, rungs);

  /* print rungs*/
  /*printf("%d\n", num_rungs);
  for(int i = 0; i < num_rungs; i++){
    for(int j = 0; j < W-1; j++){
      printf("%d", rungs[i][j]);
    }printf("\n");
  }*/

  /* solve problem using DPA*/
  long int table[101][8];
  // initialize
  for(int i = 0; i < 101; i++){
    for(int j = 0; j < 8; j++){
      table[i][j] = 0;
    }
  }
  table[0][0] = 1;

  // DPA
  for(int i = 1; i <= H; i++){
    for(int j = 0; j < num_rungs; j++){
      if(rungs[j][0] == 1){
        table[i][0] += table[i-1][1];
      }
      else table[i][0] += table[i-1][0];
      table[i][0] %= C;

      if(rungs[j][W-2] == 1){
        table[i][W-1] += table[i-1][W-2];

      }
      else table[i][W-1] += table[i-1][W-1];
      table[i][W-1] %= C;

      for(int k = 1; k <= W-2; k++){
        if(rungs[j][k-1] == 1){
          table[i][k] += table[i-1][k-1];
        }
        else if(rungs[j][k] == 1){
          table[i][k] += table[i-1][k+1];
        }
        else table[i][k] += table[i-1][k];
        table[i][k] %= C;
      }
    }
    //for(int k = 0; k < W; k++)printf("%ld", table[i][k]);printf("\n");
  }

  printf("%ld", table[H][K-1]);
  }

  return 0;
}

