const int64_t MOD = 1000000007;
int h, w, k;
int64_t dp[MAX_H+1][MAX_W];
int64_t l[MAX_W][2], r[MAX_W][2];

int main()
{
  cin >> h >> w >> k;
  k--;

  l[0][0] = 1, l[0][1] = 0;
  for (int i = 1; i < w; i++) {
    l[i][0] = l[i-1][0] + l[i-1][1];
    l[i][1] = l[i-1][0];
    //cout << l[i][0] << " " << l[i][1] << endl;
  }
  r[w-1][0] = 1; r[w-1][1] = 0;
  for (int i = w-2; i >= 0; i--) {
    r[i][0] = r[i+1][0] + r[i+1][1];
    r[i][1] = r[i+1][0];
    //cout << r[i][0] << " " << r[i][1] << endl;
  }

  for (int i = 0; i < w; i++) {
    dp[0][i] = i == k ? 1 : 0;
  }
  for (int i = 1; i <= h; i++) {
    for (int j = 0; j < w; j++) {
      int64_t x = 0;
      if (j > 0) {
        x = l[j][1] * r[j][0] * dp[i-1][j-1] % MOD;
      }

      x = (x + l[j][0] * r[j][0] * dp[i-1][j] % MOD) % MOD;

      if (j < w-1) {
        x = (x + l[j][0] * r[j][1] * dp[i-1][j+1] % MOD) % MOD;
      }

      dp[i][j] = x;
    }
  }

  cout << dp[h][0] << endl;

  return 0;
}

