void solve(void)
{
	int H, W, K;
	cin >> H >> W >> K;

	vec ans(W, 0);

	mat dp(H+1, vec(W, 0));

	dp[0][0] = 1;

	rep(H, h)
	{
		rep((1<<(W-1)), bit)
		{
			bool ok = 1;
			rep(W-2, i)
			{
				if (bit >> i & 1 && bit >> (i+1) & 1)
				{
					ok = 0;
					break;
				}
			}

			if (!ok) continue;

			rep(W, i)
			{
				if (i == 0)
				{
					if (bit & 1)
					{
						dp[h+1][i] += dp[h][i+1];
						dp[h+1][i] %= MOD;
					}
					else
					{
						dp[h+1][i] += dp[h][i];
						dp[h+1][i] %= MOD;
					}
					continue;
				}
				if (i == W-1)
				{
					if (bit >> (i-1) & 1)
					{
						dp[h+1][i] += dp[h][i-1];
						dp[h+1][i] %= MOD;
					}
					else
					{
						dp[h+1][i] += dp[h][i];
						dp[h+1][i] %= MOD;
					}
					continue;
				}
				if (bit >> (i-1) & 1)
				{
					dp[h+1][i] += dp[h][i-1];
					dp[h+1][i] %= MOD;
				}
				else if (bit >> i & 1)
				{
					dp[h+1][i] += dp[h][i+1];
					dp[h+1][i] %= MOD;
				}
				else
				{
					dp[h+1][i] += dp[h][i];
					dp[h+1][i] %= MOD;
				}
			}
		}
	}

	//cout << dp[H] << endl;

	cout << dp[H][K-1] << endl;

}

