const int MOD = 1e9 + 7; // 998244353; // 1e9 + 9;
ll rem(ll x) {
	x %= MOD; if(x < 0) x += MOD;
	return x;
}
ll madd(ll x, ll y) {
	return (rem(x) + rem(y)) % MOD;
}
ll msub(ll x, ll y) {
	return madd(x, -y);
}
ll mmul(ll x, ll y) {
	return rem(x) * rem(y) % MOD;
}
ll mpow(ll x, ll n) {
	assert(n >= 0);
	ll res = 1;
	while (n > 0) {
		if (n & 1) res = mmul(res, x);
		x = mmul(x, x);
		n >>= 1;
	}
	return res;
}
ll inv(ll x) {
	assert(x % MOD != 0);
	return mpow(x, MOD - 2);
}
ll mdiv(ll x, ll y) {
	return mmul(x, inv(y));
}

