	if(w==1){cout << 1 << endl;return 0;}
	for(int i=0;i<(1<<(w-1));i++){
		bool flag=true;
		for(int j=0;j<w-2;j++){
			if((i>>j)&(i>>(j+1))&1) flag=false;
		}
		if(!flag) continue;

		for(int j=0;j<w-1;j++){
			if((i>>j)&1){
				l[j+2]++;
				r[j+1]++;
			}else if(j==0){
				c[j+1]++;
			}else{
				if(((i>>(j-1))&1)==0) c[j+1]++;
				if(j==w-2) c[j+2]++;
			}
		}
	}
	ll dp[h+1][w+2]={};
	dp[0][1]=1;
	for(int i=1;i<=h;i++){
		for(int j=1;j<=w;j++){
			dp[i][j]=dp[i-1][j-1]*r[j-1]%mod+dp[i-1][j]*c[j]%mod+dp[i-1][j+1]*l[j+1]%mod;
			dp[i][j]%=mod;
		}
	}
	cout << dp[h][k] << endl;
