  scanf("%d %d %d", &H, &W, &K);

  int num_of_amida[H + 1][W];
  for(int i = 0; i <= H; i++) for(int j = 0; j < W; j++) num_of_amida[i][j] = 0;
  num_of_amida[0][0] = 1;

  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      for(int b = 0; b < (1 << (W - 1)); b++){
        int valid = 1;
        for(int l = 0; l < W - 2; l++){
          if((b & (1 << l)) && (b & (1 << (l + 1)))){
            valid = 0;
            break;
          }
        }
        if(!valid) continue;

        if(j > 0 && (b & (1 << (j - 1)))){
          (num_of_amida[i + 1][j - 1] += num_of_amida[i][j]) %= mod;
        }else if(j < W - 1 && (b & (1 << j))){
          (num_of_amida[i + 1][j + 1] += num_of_amida[i][j]) %= mod;
        }else{
          (num_of_amida[i + 1][j] += num_of_amida[i][j]) %= mod;
        }
      }
    }
  }

  printf("%d", num_of_amida[H][K - 1]);

  return 0;
}

