#include<stdio.h>
long long int c1(long long int k)
{
	if (k <= 0)
		return 1;
	long long int res1[10], res2[10];
	res1[0] = res2[0] = 1;
	int i;
	for (i = 1; i < k; i++)
	{
		res1[i] = res2[i - 1];
		res2[i] = res2[i - 1] + res1[i - 1];
	}
	return res1[k - 1];
}
long long int c2(long long int k)
{
	if (k <= 0)
		return 1;
	long long int res1[10], res2[10];
	res1[0] = res2[0] = 1;
	int i;
	for (i = 1; i < k; i++)
	{
		res1[i] = res2[i - 1];
		res2[i] = res2[i - 1] + res1[i - 1];
	}
	return res2[k - 1];
}
int main()
{
	long long int h, w, k;
	scanf("%lld %lld %lld", &h, &w, &k);
	long long int p = 1000000007;
	long long int dp[102][10];
	k--;
	int i, j;
	for (i = 0; i <= h; i++)
		for (j = 0; j < w; j++)
			dp[i][j] = 0;
	dp[0][0] = 1;
	for (i = 0; i < h; i++)
	{
		for (j = 0; j < w; j++)
		{
			dp[i + 1][j] += dp[i][j] * c2(j) * c2(w - j - 1);
			dp[i + 1][j] %= p;
			if (j > 0)
				dp[i + 1][j] += dp[i][j - 1] * c1(j) * c2(w - j - 1);
			dp[i + 1][j] %= p;
			if (j < w - 1)
				dp[i + 1][j] += dp[i][j + 1] * c2(j) * c1(w - j - 1);
			dp[i + 1][j] %= p;
		}
	}
	printf("%lld\n", dp[h][k]);
	return 0;
}

