int amida(h,w,des){
    if(h < des-1){
        return 0;
    }else if(w == 1){
        return 1;
    }else{
        int A[8] = {1,1,2,3,5,8,13,21};
        if(h == 0){
            return 1;
        }else{
            if(des == 1){
                return A[des-1]*A[w-des]*amida(h-1,w,des) + A[des-1]*A[w-des-1]*amida(h-1,w,des+1);
            }else if(des == w){
                return A[des-1]*A[w-des]*amida(h-1,w,des) + A[des-2]*A[w-des]*amida(h-1,w,des-1);
            }else{
                return A[des-2]*A[w-des]*amida(h-1,w,des-1) + A[des-1]*A[w-des]*amida(h-1,w,des) + A[des-1]*A[w-des-1]*amida(h-1,w,des+1);
            }
        }
    }
}

