long int move(int h,int w,int k,int W1,int Amida[][W1]){
    long int c=0;
    int x=0,y=1;
    for(int i=0;i<h+2;i++){
        if(x==0 && Amida[y][x+1]==1){
            x=x+2;
            y++;
        }else if(x==0 && Amida[y][x+1]!=1 ){
            y++;
        }else if(x!=0 && x!=W1-1 && Amida[y][x+1]==1){
            x=x+2;
            y++;
        }else if(x!=0 && x!=W1-1 && Amida[y][x-1]==1){
            x=x-2;
            y++;
        }else if(x!=0 && x!=W1-1 && (Amida[y][x-1]!=1 && Amida[y][x+1]!=1)){
            y++;
        }else if(x==W1-1 && Amida[y][x-1]==1){
            x=x-2;
            y++;
        }else if(x==W1-1 && Amida[y][x-1]!=1){
            y++;
        }
        if(y==h+1)break;
    }
    if(x==(2*k-2) && y==h+1)c++;
                 return c;
}


