		for (j = 2; j <= W; j++) dp[i][j-1] += dp[i-1][j] * comb[j-2] * comb[W-j];
		for (j = 1; j <= W; j++) dp[i][j] %= Mod;
	}

	printf("%lld\n", dp[H][K]);
	fflush(stdout);
	return 0;
}

