long amida(int w, int h, int k)
{
	long n;
	long mod=1000000007;
	long b[9] = {0, 1, 1, 2, 3, 5, 8, 13, 21};

	if (h==0 && k==1)
	{
		return 1;
	} else if (k-1>h || k==0 || k==w+1)
	{
		return 0;
	} else
	{
		n = ((amida(w, h-1, k+1)*b[w-k]+mod)%mod*b[k]+mod)%mod + ((amida(w, h-1, k-1)*b[k-1]+mod)%mod*b[w-k+1]+mod)%mod + ((amida(w, h-1, k)*b[k]+mod)%mod*b[w-k+1]+mod)%mod;
		n = (n+mod)%mod;
		return n;
	}
}

