fun solve() {
    val h = nextLong()
    val w = nextLong()
    val k = nextLong() - 1

    val dp = longAry2(h + 1, w)
    dp[0][0] = 1L
    val border = 1 shl (w.toInt() - 1)
    for (i in 0 until h) {
        loop@for (bit in 0 until border) {
            val flag = boolAry(w - 1)
            for (j in 0 until w.toInt() - 1) {
                if(((bit shr j) and 1) == 1) flag[j] = true
            }
            for (j in 0 until w.toInt() - 2) {
                if(flag[j] && flag[j + 1]) continue@loop
            }
            for (j in 0 until w.toInt()) {
                if(j > 0L && flag[j - 1]) dp[i + 1][j - 1] = modAdd(dp[i + 1][j - 1], dp[i][j])
                if(j < w - 1 && flag[j]) dp[i + 1][j + 1] = modAdd(dp[i + 1][j + 1], dp[i][j])
                val res1 = if(j == 0) true else !flag[j - 1]
                val res2 = if(j == w.toInt() - 1) true else !flag[j]
                if(res1 && res2) dp[i + 1][j] = modAdd(dp[i + 1][j], dp[i][j])
            }
        }
    }

    println(dp[h][k])

