// Global

fun solve() {
    val h = nextLong()
    val w = nextLong()
    val k = nextLong()
    val dp = longAry2(h + 1, w)
    dp[0][0] = 1L

    for (i in 0 until h) {
        val border = 1 shl (w.toInt() - 1)
        loop@for (bit in 0 until border) {
            val flag = boolAry(w - 1)
            for (i in 0 until w.toInt() - 1) {
                if(((bit shr i) and 1) == 1) flag[i] = true
            }
            for (i in 0 until w.toInt() - 2) {
                if(flag[i] && flag[i + 1]) continue@loop
            }
            for (j in 0 until w) {
                if(j > 0 && flag[j - 1]) {
                    dp[i + 1][j - 1] = modAdd(dp[i + 1][j - 1], dp[i][j])
                }
                if(j < w - 1 && flag[j]) {
                    dp[i + 1][j + 1] = modAdd(dp[i + 1][j + 1], dp[i][j])
                }
                val res1 = if(j == 0L) true else !flag[j - 1]
                val res2 = if(j == w - 1) true else !flag[j]
                if(res1 && res2) dp[i + 1][j] = modAdd(dp[i + 1][j], dp[i][j])
            }
        }

    }

    println(dp[h][k - 1])

}



