fun main() {
    val mod = 1e9.toInt() + 7
    val (h, w, k) = readLine()!!.split(' ').map { it.toInt() }
    val dp = Array(h + 1) { IntArray(w) }
    dp[0][0] = 1

    val bitsSequence = sequence {
        for (bits in 0 until (1 shl w - 1)) {
            var invalid = false
            for (i in 0 until w - 2) {
                val l = (bits shr i) and 1
                val r = (bits shr i + 1) and 1
                if (l and r == 1) {
                    invalid = true
                }
            }
            if (invalid) continue
            yield(bits)
        }
    }

    for (i in 0 until h) {
        for (j in 0 until w) {
            for (bits in bitsSequence) {
                var nj = j
                if (bits shr j and 1 == 1) nj = j + 1
                else if (j > 0 && bits shr j - 1 and 1 == 1) nj = j - 1
                dp[i + 1][nj] += dp[i][j]
                dp[i + 1][nj] %= mod
            }
        }
    }

    println(dp[h][k - 1])
}

fun main(args: Array<String>) {
    val MOD = (1e9).toLong() + 7
    val (H, W, K) = readLine()!!.split(" ").map {it.toInt() }

    val dp1 = Array(W + 1) { ModInt(0, MOD) }

    dp1[0] = ModInt(1, MOD)

    for (i in 1..W) {
        dp1[i] += dp1[i - 1]
        if (i > 1) {
            dp1[i] += dp1[i - 2]
        }
    }

    val dp = Array(H + 1) { Array(W) { ModInt(0, MOD)} }

    dp[0][0] = ModInt(1, MOD)

    fun f(x: Int, n: Int): ModInt {
        if (x == 0 || x + n == W - 1) {
            return dp1[W - 1 - n]
        }

        return dp1[x] * dp1[W - n - x - 1]
    }

    for (i in 1..H) {
        for (j in 0 until W) {
            dp[i][j] += dp[i - 1][j] * f(j, 0)

            if (j > 0) {
                dp[i][j] += dp[i - 1][j - 1] * f(j - 1, 1)
            }

            if (j < W - 1) {
                dp[i][j] += dp[i - 1][j + 1] * f(j, 1)
            }
        }
    }

    println(dp[H][K - 1].value)
}

class ModInt (value: Long, val mod: Long) {
    init {
        if (mod <= 0) {
            throw IllegalArgumentException("ModInt cannot be created for non-positive modulus: $mod")
        }
    }

    val value = (value % mod + mod) % mod

    private fun assertSameMod(other: ModInt) {
        if (mod != other.mod) {
            throw IllegalArgumentException(
                "You cannot operate summation, subtraction and multiplication for ModInts with different moduli: $mod, ${other.mod}"
            )
        }
    }

    operator fun unaryMinus() = ModInt(mod - value, mod)

    operator fun plus(other: ModInt): ModInt {
        assertSameMod(other)

        return ModInt((value + other.value) % mod, mod)
    }

    operator fun plus(other: Long) = plus(ModInt(other, mod))

    operator fun minus(other: ModInt): ModInt {
        assertSameMod(other)

        return plus(-other)
    }

    operator fun minus(other: Long) = minus(ModInt(other, mod))

    operator fun times(other: ModInt): ModInt {
        assertSameMod(other)

        return ModInt((value * other.value) % mod, mod)
    }

    operator fun times(other: Long) = times(ModInt(other, mod))

    fun pow(k: Long): ModInt {
        var res = 1L
        var a = value
        var l = k

        while (l > 0) {
            if ((l and 1L) == 1L) {
                res = (res * a) % mod
            }

            a = a * a % mod
            l /= 2L
        }

        return ModInt(res, mod)
    }

    /**
     * Returns an inverse element of the value.
     * To ensure `m * m.inv() = 1`, the modulus should be prime, since it uses Fermat's little theorem.
     */
    fun inv() = pow(mod - 2)

    operator fun div(other: ModInt): ModInt {
        assertSameMod(other)
        if (other.value == 0L) {
            throw ArithmeticException()
        }

        return times(other.inv())
    }

    operator fun div(other: Long) = div(ModInt(other, mod))
}

