		for(int i=1; i<=h; i++){
			for(int j=w-1; j>=0; j--){
				for(int k=0; k<Math.pow(2,w-1); k++){
					boolean a=false;
					boolean b=false;
					boolean jud=false;
					int count=0;
					int y=k;
