                            amida[i][k] += amida[i-1][k+1];
                        }else{
                            amida[i][k] += amida[i-1][k];
                        }
                    }else if(k == w-1){
                        if((j >> (k-1))%2 == 1){
                            amida[i][k] += amida[i-1][k-1];
                        }else{
                            amida[i][k] += amida[i-1][k];
                        }
                    }else{
                        if((j >> k)%2 == 1){
                            amida[i][k] += amida[i-1][k+1];
                        }else if((j >> (k-1))%2 == 1){
                            amida[i][k] += amida[i-1][k-1];
                        }else{
                            amida[i][k] += amida[i-1][k];
                        }
                    }
                    amida[i][k] %= mod;
                }
            }
        }
        System.out.println(amida[h][kk-1]);
    }
