import java.util.Scanner;

public class Main {

    private static final long MOD = 1_000_000_007;

    private static int nextUnitAmida(int x) {
        int mask1 = 1;
        int mask2 = 3;
        ++x;
        for (;;) {
            int ck = x & mask2;
            if (ck == mask1) {
                break;
            } else if (ck == mask2) {
                x += mask1;
            } else {
                ;
            }
            mask1 <<= 1;
            mask2 <<= 1;
        }
        return x;
    }

    private static int[] createUnitAmida(int w) {
        List<Integer> uAmidas = new ArrayList<>();
        int x = 0;
        int limit = (1 << (w - 1));
        do {
            uAmidas.add(x);
            x = nextUnitAmida(x);
        } while (x < limit);

        int[] result = new int[uAmidas.size()];
        for (int i = 0; i < result.length; ++i) {
            result[i] = uAmidas.get(i);
        }
        return result;
    }

    private final int height;

    private final int width;

    private final int[] unitAmidas;

    private Main(int h, int w) {
        height = h;
        width = w;
        unitAmidas = createUnitAmida(w);
    }

    long countIt(int goal) {
        return countSub(height, 1, goal);
    }

    private long countSub(int h, int start, int goal) {
        if (Math.abs(start - goal) > h) {
            return 0;
        }
        if (h > 1) {
            final int h1 = h / 2;
            final int h2 = h - h1;
            long result = 0;
            for (int k = 0; k < width; ++k) {
                long r1 = countSub(h1, start, k + 1);
                long r2 = countSub(h2, k + 1, goal);
                result += r1 * r2;
            }
            return result % MOD;
        }

        assert h == 0;

        final int rMask = (1 << (start - 1));
        final int lMask = (rMask >> 1);

        int rCase = 0;
        int lCase = 0;
        int mCase = 0;

        for (int unitAmida : unitAmidas) {
            if ((unitAmida & rMask) != 0) {
                ++rCase;
            } else if ((unitAmida & lMask) != 0) {
                ++lCase;
            } else {
                ++mCase;
            }
        }

        long result = 0;
        if (start == goal) {
            result = mCase;
        } else if (start == goal - 1) {
            result = rCase;
        } else {
            result = lCase;
        }
        return result;
    }

    public static void main(String[] args) {
        try (
                Scanner in = new Scanner(System.in);
                PrintWriter out = new PrintWriter(System.out))
        {
            final int H = in.nextInt();
            final int W = in.nextInt();
            final int K = in.nextInt();

            long result = new Main(H, W).countIt(K);
            out.println(result);
        }
    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {

	public static Set<boolean[]> amida = new HashSet<>();
	public static boolean[] amicre;
	public static int H, W, K;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		H = sc.nextInt();
		W = sc.nextInt();
		K = sc.nextInt();
		amicre = new boolean[H * W];
		amida.removeIf(o -> filter(o));
		long count = 0;
		for(boolean[] ami : amida) {
			if(K == play(ami)) {
				count++;
			}
		}
		System.out.println(count % 1000000007);
	}

	public static int play(boolean[] ami) {
		int tmp = 1;
		while(tmp <= H * W) {
			if(ami[tmp - 1]) {
				tmp--;
			} else if(ami[tmp]) {
				tmp++;
			}
			tmp += W;
		}
		int ret = 0;
		if(tmp % W == 0) {
			ret = W;
		} else {
			ret = tmp % W;
		}
		return ret;
	}

	public static boolean filter(boolean[] ami) {
		boolean ans = false;
		for(int i = 0; i < H * W; i += W) {
			if(ami[i]) {
				ans = true;
				break;
			}
		}
		if(!ans) {
			for(int i = 1; i < H * W; i++) {
				if(ami[i] && (ami[i - 1] || ami[i + 1])) {
					ans = true;
					break;
				}
			}
		}
		return ans;
	}

	public void create(int i) {
		if(i <= H * W) {
			amicre[i] = true;
			create(i + 1);
			amicre[i] = false;
			create(i + 1);
		} else {
			amida.add(amicre);
		}
	}

}

