        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        int mod = 1000000007;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int h = in.nextInt();
            int w = in.nextInt();
            int k = in.nextInt();

            if (w == 1) {
                out.println(1);
                return;
            }

            long[][][] dp = new long[h + 1][1 << (w - 1)][w];

            for (int i = 0; i < w; i++) {
                for (int j = 0; j < (1 << (w - 1)); j++) {
                    if (valid(j, w)) {
                        if (i == k - 1) {
                            dp[h][j][i] = 1;
                        }
                    }
                }
            }

            for (int i = h - 1; i >= 0; i--) {
                for (int j = 0; j < (1 << (w - 1)); j++) {
                    if (!valid(j, w))
                        continue;
                    for (int l = 0; l < w; l++) {
                        for (int m = 0; m < (1 << (w - 1)); m++) {
                            if (!valid(m, w))
                                continue;

                            if (l == w - 1) {
                                if ((m & (1 << (l - 1))) != 0) {
                                    dp[i][j][l] += dp[i + 1][m][l - 1];
                                    dp[i][j][l] %= mod;
                                } else {
                                    dp[i][j][l] += dp[i + 1][m][l];
                                    dp[i][j][l] %= mod;
                                }
                            } else if (l == 0) {
                                if ((m & (1 << l)) != 0) {
                                    dp[i][j][l] += dp[i + 1][m][l + 1];
                                    dp[i][j][l] %= mod;
                                } else {
                                    dp[i][j][l] += dp[i + 1][m][l];
                                    dp[i][j][l] %= mod;
                                }
                            } else {
                                if ((m & (1 << l)) != 0) {
                                    dp[i][j][l] += dp[i + 1][m][l + 1];
                                    dp[i][j][l] %= mod;
                                } else if ((m & (1 << (l - 1))) != 0) {
                                    dp[i][j][l] += dp[i + 1][m][l - 1];
                                    dp[i][j][l] %= mod;
                                } else {
                                    dp[i][j][l] += dp[i + 1][m][l];
                                    dp[i][j][l] %= mod;
                                }
                            }
                        }
                    }
                }
            }

            out.println(dp[0][0][0]);
        }

        boolean valid(int num, int w) {
            int cnum = num;

            int co = 0;
            for (int i = 0; i < w; i++) {
                if (((1 << i) & num) != 0) {
                    co++;
                    if (co > 1) {
                        return false;
                    }
                } else {
                    co = 0;
                }
            }

            return true;
        }

    }

