import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {

	public static Set<boolean[]> amida = new HashSet<>();
	public static boolean[] amicre;
	public static int H, W, K;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		H = sc.nextInt();
		W = sc.nextInt();
		K = sc.nextInt();
		amicre = new boolean[H * W];
		create(0);
		amida.removeIf(o -> filter(o));
		long count = 0;
		for(boolean[] ami : amida) {
			if(K == play(ami)) {
				count++;
			}
		}
		System.out.println(count % 1000000007);
	}

	public static int play(boolean[] ami) {
		int tmp = 1;
		while(tmp <= H * W) {
			if(ami[tmp - 1]) {
				tmp--;
			} else if(ami[tmp]) {
				tmp++;
			}
			tmp += W;
		}
		int ret = 0;
		if(tmp % W == 0) {
			ret = W;
		} else {
			ret = tmp % W;
		}
		return ret;
	}

	public static boolean filter(boolean[] ami) {
		boolean ans = false;
		for(int i = 0; i < H * W; i += W) {
			if(ami[i]) {
				ans = true;
				break;
			}
		}
		if(!ans) {
			for(int i = 1; i < H * W; i++) {
				if(ami[i] && (ami[i - 1] || ami[i + 1])) {
					ans = true;
					break;
				}
			}
		}
		return ans;
	}

	public static void create(int i) {
		if(i <= H * W) {
			amicre[i] = true;
			create(i + 1);
			amicre[i] = false;
			create(i + 1);
		} else {
			amida.add(amicre);
		}
	}

}

import java.util.Scanner;

public class Main {

    static final long MOD = 1000000007;

    static int H, W, K;
    static long[][] dp = new long[110][10];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        K = sc.nextInt() - 1;
        dp[0][0] = 1;
        for(int h=1; h<=H; ++h) {
            for(int w=0; w<W; ++w) {
                int[] kuji = new int[W-1];
                //mannaka
                if(w < W-1) kuji[w] = -1;
                if(w-1 >= 0) kuji[w-1] = -1;
                dp[h][w] += (kumi(kuji, 0) * dp[h-1][w]) % MOD;
                dp[h][w] %= MOD;
                //left
                if(w > 0) {
                    kuji = new int[W-1];
                    kuji[w-1] = 2;
                    dp[h][w] += (kumi(kuji, 0) * dp[h-1][w-1]) % MOD;
                    dp[h][w] %= MOD;
                }
                if(w < W-1) {
                    kuji = new int[W-1];
                    kuji[w] = 2;
                    dp[h][w] += (kumi(kuji, 0) * dp[h-1][w+1]) % MOD;
                    dp[h][w] %= MOD;
                }
            }
        }
        System.out.println(dp[H][K]);
    }

    static long kumi(int[] kuji, int n) {
        if(n == W-1) {
            for(int i=0; i<kuji.length-1; ++i) {
                if(kuji[i] > 0 && kuji[i+1] > 0) {
                    return 0;
                }
            }
            return 1;
        }
        long pos = 0;
        if(kuji[n] > 1) pos = kumi(kuji, n+1);
        else if(kuji[n] == 0) {
            kuji[n] = 1;
            pos = kumi(kuji, n+1);
            kuji[n] = 0;
        }
        long neg = 0;
        if(kuji[n] < 2) neg = kumi(kuji, n+1);
        return (neg + pos) % MOD;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.Random;
import java.util.StringTokenizer;

public final class Main {

    private static final int MOD = (int) (1e9 + 7);

    public static void main(String[] args) {
        final FastScanner fs = new FastScanner();
        final int h = fs.nextInt();
        final int w = fs.nextInt();
        final int k = fs.nextInt();
        System.out.println(solve(h, w, k));
    }

    static int solve(int h, int w, int k) {
        final int[][] dp = new int[h + 1][w];
        dp[0][0] = 1;

        for (int i = 0; i < h; i++) {
            for (int mask = 0; mask < 1 << (w - 1); mask++) {
                if (isValid(mask)) {
                    for (int pos = 0; pos < w; ++pos) {
                        final int nextPos = computeNextPos(pos, mask);
                        dp[i + 1][nextPos] = (dp[i + 1][nextPos] + dp[i][pos]) % MOD;
                    }
                }
            }
        }

        return dp[h][k - 1];
    }

    static boolean isValid(int code) {
        return !Integer.toBinaryString(code).contains("11");
    }

    static int computeNextPos(int pos, int code) {
        if ((code & (1 << pos)) != 0) {
            return pos + 1;
        } else if (pos != 0 && (code & (1 << (pos - 1))) != 0) {
            return pos - 1;
        } else {
            return pos;
        }
    }

    static final class Utils {
        public static void shuffleSort(int[] arr) {
            shuffle(arr);
            Arrays.sort(arr);
        }

        public static void shuffleSort(long[] arr) {
            shuffle(arr);
            Arrays.sort(arr);
        }

        public static void shuffle(int[] arr) {
            final Random r = new Random();

            for (int i = 0; i <= arr.length - 2; i++) {
                final int j = i + r.nextInt(arr.length - i);
                swap(arr, i, j);
            }
        }

        public static void shuffle(long[] arr) {
            final Random r = new Random();

            for (int i = 0; i <= arr.length - 2; i++) {
                final int j = i + r.nextInt(arr.length - i);
                swap(arr, i, j);
            }
        }

        public static void swap(int[] arr, int i, int j) {
            final int t = arr[i];
            arr[i] = arr[j];
            arr[j] = t;
        }

