        for (int i = 0; i < h; i++) {
            for (int j = 1; j <= w; j++) {
                if (j != 1) dp[i + 1][j - 1] = (int) ((dp[i + 1][j - 1] + (long) dp[i][j] * func(j - 3) * func(w - j - 1)) % mod);
                dp[i + 1][j] = (int) ((dp[i + 1][j] + (long) dp[i][j] * func(j - 2) * func(w - j - 1)) % mod);
                if (j != w) dp[i + 1][j + 1] = (int) ((dp[i + 1][j + 1] + (long) dp[i][j] * func(j - 2) * func(w - j - 2)) % mod);
            }
