    }
    public static int func(int x) {
        if (x <= 0) return 1;
        int[][] dp = new int[x + 1][2];
        dp[0][0] = 1;
        for (int i = 0; i < x; i++) {
            dp[i + 1][0] = dp[i][0] + dp[i][1];
            dp[i + 1][1] = dp[i][0];
        }
        return dp[x][0] + dp[x][1];
    }
}

