	static long[] swap(long []a, int []b) {
		long []c = new long[W];
		System.arraycopy(a, 0, c, 0, W);
		for(int i = 0; i < W - 1; i++) {
			if(b[i] == 1) {
				c[i] = a[i + 1];
				c[i + 1] = a[i];
			}
		}
		return c;
	}
	static void rec(int k) {
        if(k == bit.length) {
        	addBit();
            return;
        }
        rec(k + 1);
        bit[k] = 1;
        rec(k + 1);
        bit[k] = 0;
    }
	static void addBit() {
		int l = bit.length;
		for(int i = 1; i < l; i++) {
			if(bit[i - 1] == 1 && bit[i] == 1) {
				return;
			}
		}
		int []vBit = new int[l];
		System.arraycopy(bit, 0, vBit, 0, l);
		list.add(vBit);
		return;
	}
