    for (int i = 1; i <= h; i++) {
      for (int j = 0; j < w; j++) {
        for (int hl : horizontalLine) {
          if (j < w - 1 && ((hl >> j) & 1) == 1) {
            dp[i][j] += dp[i - 1][j + 1];
          } else if (j - 1 >= 0 && ((hl >> (j - 1)) & 1) == 1) {
            dp[i][j] += dp[i - 1][j - 1];
          } else {
            dp[i][j] += dp[i - 1][j];
          }
          dp[i][j] %= mod;
        }
      }
    }
    System.out.println(dp[h][k - 1]);
  }
