	}
	static void dfs(int now, boolean te, boolean mae, boolean ato) {
		if (now == w) {
			if (mae) {
				dp[i][j] += dp[i - 1][j - 1];
				dp[i][j] %= mod;
			} else if (ato) {
				dp[i][j] += dp[i - 1][j + 1];
				dp[i][j] %= mod;
			} else {
				dp[i][j] += dp[i - 1][j];
				dp[i][j] %= mod;
			}
			return;
		}
		if (te) {
			dfs(now + 1, false, mae, ato);
		} else if (now == j - 1) {
			dfs(now + 1, true, true, false);
			dfs(now + 1, false, mae, ato);
		} else if (now == j) {
			dfs(now + 1, true, mae, true);
			dfs(now + 1, false, mae, ato);
