	public static final long MOD = 1000000007L;

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int h = sc.nextInt();
		int w = sc.nextInt();
		int k = sc.nextInt();

		if (w == 1) {
			System.out.println(1);
			return;
		}

		ArrayList<boolean[]> list = new ArrayList<boolean[]>();
		list.add(new boolean[w-1]);
		boolean[] b = new boolean[w-1];
		for (int i = 0; i < w - 1; i++) {
			ArrayList<boolean[]> tlist = new ArrayList<boolean[]>();
			for (boolean[] arr : list) {
				if (i == 0 || !arr[i - 1]) {
					boolean[] tmp = arr.clone();
					tmp[i] = true;
					tlist.add(tmp);
				}
			}
			list.addAll(tlist);
		}

		long[][] count = new long[w][h+1];
		count[0][0] = 1;
		for (int i = 1; i < h + 1; i++) {
			for (int j = 0; j < w; j++) {
				int stay = 0;
				int left = 0;
				int right = 0;
				for (boolean[] arr : list) {
					if (j != 0 && arr[j - 1]) {
						left++;
					}
					if (j != w - 1 && arr[j]) {
						right++;
					}
					if (j != 0 && j != w - 1) {
						if (!arr[j - 1] && !arr[j]) {
							stay++;
						}
					} else if (j == 0) {
						if (!arr[j]) {
							stay++;
						}
					} else if (j == w - 1) {
						if (!arr[j - 1]) {
							stay++;
						}
					}

				}
				count[j][i] += count[j][i - 1] * stay;
				if (j != 0) {
					count[j][i] += count[j - 1][i - 1] * left;
				}
				if (j != w - 1) {
					count[j][i] += count[j + 1][i - 1] * right;
				}
				count[j][i] %= MOD;
			}
		}

		System.out.println(count[k - 1][h] % MOD);
	}
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in)) {
            solve(in);
        }
    }

    private static void solve(Scanner in) {
        final long mod = 1_000_000_007;
        final int H = in.nextInt();
        final int W = in.nextInt();
        final int K = in.nextInt();
        final long[] dp = new long[W];
        final long[] cl = new long[W]; // current line. reset every iteration.
        dp[0] = 1;
        for (int h = 0; h < H; h++) {
            for (int i = 0; i < W; i++) {
                cl[i] = 0;
            }
            for (int i = 0; i < W; i++) {
                int leftOff = count(i - 1, false);
                int leftOn = count(i - 1, true);
                int rightOff = count(W - i - 2, false);
                int rightOn = count(W - i - 2, true);
                if (dp[i] > 0) {
                    cl[i] += dp[i] * (leftOff * rightOff);
                    cl[i] %= mod;
                }
                if (i - 1 >= 0 && dp[i - 1] > 0) {
                    cl[i] += dp[i - 1] * (leftOn * rightOff);
                    cl[i] %= mod;
                }
                if (i + 1 < W && dp[i + 1] > 0) {
                    cl[i] += dp[i + 1] * (leftOff * rightOn);
                    cl[i] %= mod;
                }
            }
            for (int i = 0; i < W; i++) {
                dp[i] = cl[i];
            }
            // System.out.println(Arrays.toString(dp));
        }
        System.out.println(dp[K - 1]);
    }

    private static int count(int len, boolean on) {
        if (len <= 0) {
            return 1;
        }
        int ret = count(len - 1, false);
        if (!on) {
            ret += count(len - 1, true);
        }
        return ret;
    }
}

