          continue;
        }
        for (int j = 0; j < W; j++) {
          if (j - 1 >= 0 && arr[j - 1] == 1) {
            dp[i + 1][j - 1] += dp[i][j];
          }
          if (j + 1 < W && arr[j] == 1) {
            dp[i + 1][j + 1] += dp[i][j];
          }
          boolean left = j == 0 ? true : arr[j - 1] == 0;
          boolean right = j == W - 1 ? true : arr[j] == 0;
          if (left && right) {
            dp[i + 1][j] += dp[i][j];
          }
        }
        for (int j = 0; j < W; j++) {
          dp[i + 1][i] %= MOD;
        }
      }
    }
    System.out.println(dp[H][K - 1] % MOD);
  }
}

