final class IO {
	private static final InputStream in = System.in;
		PrintWriter out = new PrintWriter(new BufferedOutputStream(new FileOutputStream(FileDescriptor.out)), false);
	private static final byte[] buffer = new byte[1024];
	private static int ptr = 0;
	private static int len = 0;

	private static boolean hasNextByte() {
		if (ptr < len)
			return true;
		ptr = 0;
		try {
			len = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		return len > 0;
	}

	private static int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	static boolean hasNext() {
		byte c;
		while (hasNextByte() && ((c = buffer[ptr]) < '!' || c > '~'))
			ptr++;
		return hasNextByte();
	}

	static String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (b >= '!' && b <= '~') {
			sb.append((char) b);
			b = readByte();
		}
		return sb.toString();
	}

	static char nextChar() {
		if (!hasNext())
			throw new NoSuchElementException();
		return (char) readByte();
	}

	static long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static int nextInt() {
		if (!hasNext())
			throw new NoSuchElementException();
		int n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static double nextDouble() {
		return Double.parseDouble(next());
	}

	static void out(String val) {
		out.println(val);
	}

	static void flush() {
		out.flush();
	}
}

import java.util.Scanner;

public class Main {
    private static final long MOD = 1_000_000_007;
    private int sum = 0;

    public void main(Scanner sc) {
        int h = sc.nextInt();
        int w = sc.nextInt();
        int k = sc.nextInt();

        int cnt[] = new int[w + 1];
        init(w, cnt);

        long dp[][] = new long[h + 1][w];
        dp[0][0] = 1;
        for (int i = 1; i <= h; i++) {
            for (int j = 0; j < w; j++) {
                // 左
                if (j > 0) {
                    dp[i][j - 1] += cnt[j] * dp[i - 1][j];
                    dp[i][j - 1] %= MOD;
                }

                // 中
                dp[i][j] += (sum - cnt[j] - cnt[j + 1]) * dp[i - 1][j];
                dp[i][j] %= MOD;

                // 右
                if (j + 1 < w) {
                    dp[i][j + 1] += cnt[j + 1] * dp[i - 1][j];
                    dp[i][j + 1] %= MOD;
                }
            }
        }

        System.out.println(dp[h][k - 1]);
    }

    private void init(int w, int cnt[]) {
        for (int n = 0; n < (1 << (w - 1)); n++) {
            int tmp = n;
            int bi[] = new int[w];
            boolean ok = true;
            for (int i = 0; i < w - 1; i++) {
                bi[i + 1] = tmp % 2;
                if (bi[i] * bi[i + 1] == 1) {
                    ok = false;
                    break;
                }
                tmp /= 2;
            }

            if (ok) {
                sum++;
                for (int i = 1; i < w; i++) {
                    cnt[i] += bi[i];
                }
            }
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            new Main().main(sc);
        } catch (Exception e) {
            throw e;
        }
    }
}

