import java.util.*;
class Main
{
    static int mod = 1000000007;
    static int h, w, k;
    static int[] p;
    static long[][] dp;
    public static void main (String[] args)
    {
        Scanner sc = new Scanner(System.in);
        h = sc.nextInt();
        w = sc.nextInt();
        k = sc.nextInt();
        p = new int[w + 2];
        p[0] = 1; p[1] = 1;
        for(int i = 2; i < w + 2; i++){
            p[i] = p[i-1] + p[i-2];
        }
        dp = new long[h+1][w+1];
        for(int i = 1; i <= h; i++){
            for(int j = 1; j <= w; j++){
                dp[i][j] = calc(i, j);
            }
        }
        System.out.println(dp[h][k]);
    }
    public static long calc(int height, int width){
        if(height == 1 && width == 1) return p[w - 1];
        else if(height == 1 && width == 2) return p[w-2];
        else if(height + 1< width) return 0;
        else{
            long res = 0;
            res += dp[height - 1][width] * p[width - 1] * p[w - width];
            res %= mod;
            if(width > 1){
                res += dp[height - 1][width - 1] * p[width - 2] * p[w - width];
                res %= mod;
            }
            if(width < w){
                res += dp[height - 1][width + 1] * p[width - 1] * p[w - 1 - width];
                res %= mod;
            }
            return res;
        }
    }
}

import java.util.Scanner;

public class Main {
    static final int MODULUS = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int H = sc.nextInt();
        int W = sc.nextInt();
        int K = sc.nextInt();

        System.out.println(solve(H, W, K));

        sc.close();
    }

    static int solve(int H, int W, int K) {
        int[] wayNums = new int[W];
        wayNums[0] = 1;

        for (int i = 0; i < H; ++i) {
            int[] nextWayNums = new int[wayNums.length];
            for (int code = 0; code < 1 << (W - 1); ++code) {
                if (isValid(code)) {
                    for (int pos = 0; pos < W; ++pos) {
                        int nextPos = computeNextPos(pos, code);

                        nextWayNums[nextPos] = addMod(nextWayNums[nextPos], wayNums[pos]);
                    }
                }
            }

            wayNums = nextWayNums;
        }

        return wayNums[K - 1];
    }

    static int addMod(int x, int y) {
        return (x + y) % MODULUS;
    }

    static boolean isValid(int code) {
        return !Integer.toBinaryString(code).contains("11");
    }

    static int computeNextPos(int pos, int code) {
        if ((code & (1 << pos)) != 0) {
            return pos + 1;
        } else if (pos != 0 && (code & (1 << (pos - 1))) != 0) {
            return pos - 1;
        } else {
            return pos;
        }
    }
}

