class Main{
	static final long MOD = 1000000007;

	static int H, W, K;
	static long[][] dp = new long[110][10];
	static int ans = 0;
	static long n = 0;





	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);			//文字の入力
		int H = sc.nextInt();
		int W = sc.nextInt();
		int K = sc.nextInt();
		long MOD = 1000000007;

		int[][] dp = new int[H+1][W];				//dp[i][j] = i列目のj行目への経路の総数
		dp[0][0] = 1;		
		for(int h = 1;h <= H;h++){
			for(int w = 0;w < W;w++){
				for(int i = 0;i < (1 << W-1);i++){		//ビット全探索 h行目について横棒を全通り列挙
					int mask = 3;
					boolean flag = true;
					while(true){		//隣同士が繋がっていないか確認

						if((mask & i) == mask){
							flag = false;
						}

						if(mask == 3<<W-1){				//端っこまでシフトしたら終了
							break;
						}
						mask =mask << 1;					//右へ1シフト
					}

					if(flag){				//横同士が繋がっていない時

						if(w > 0 && (i & (1 << w-1)) > 0){			//左端でなく、wとw-1列目が繋がっている
							dp[h][w] += dp[h-1][w-1];
						}else if(w < W-1 && (i & (1 << w)) > 0){	//右端でなく、wとw+1列目が繋がっている
							dp[h][w] += dp[h-1][w+1];
						}else{										//真上から降りてくるパターン
							dp[h][w] += dp[h-1][w];

						}
						dp[h][w] %= MOD;


					}

				}
			}
		}
		System.out.println(dp[H][K-1]);

	}
}







