							dp[i + 1][j] += dp[i][j];
							dp[i + 1][j] %= MOD;
						}
					}
				}
			}
		}
		System.out.println(dp[h][K - 1]);
	}

	boolean validate(int num, int w) {
		//validであるかどうかを返す。
		int n = num;
		for(int i = 0; i < 1 << (w - 2); i++) {
			if(((n >> i) & 1) == ((n >> (i + 1)) & 1)){
				return false;
			}
		}
		return true;
	}

	Main(){doIt();}
