		dp[0][1]=1;
		for(int i = 0; i<h; i++){
			for(int j = 1; j<=w; j++){
				long left = j-2;
				long right = w-j-1;
				long straight = bit(left)*bit(right);
				long Left = bit(left-1)*bit(right);
				long Right = bit(left)*bit(right-1);
				dp[i+1][j]=(dp[i][j]*straight+dp[i][j-1]*Left+dp[i][j+1]*Right)%mod;
			}
		}
