	public static long bit(long number){
		if(number<=0){
			return 1;
		}
		long ans=0;

	as:for(long i=0; i<Math.pow(2,number); i++){
			for(long k = 0; k<number; k++){
				if(k!=0){
					if((i>>k & 1)==1 && (i>>k-1 & 1)==1 ){
						continue as;
					}
				}
			}
			ans++;
		}
		return ans;
	}
