import java.util.*;
import java.io.*;

public class Main {
	static final int MOD = 1_000_000_007;
    public static long addMod(long a, long b){
    	long tmp = (a+b)%MOD;
    	return tmp>=0 ? tmp : tmp+MOD;
    }
    public static long subMod(long a, long b){
    	return addMod(a,-b);
    }
    public static long multMod(long a, long b){
    	long tmp = (a*b)%MOD;
    	return tmp>=0 ? tmp : tmp+MOD;
    }
    public static long powerMod(long a, long x){ //calculate a^x
        if(x<0)return 0;
        if(x==0)return 1;
        if(x%2==0) {
        	long half = powerMod(a,x/2);
        	return multMod(half,half);
        }
        return (a*powerMod(a,x-1)) % MOD;
    }
    public static long inverseMod(long a){
        return powerMod(a,MOD-2);
    }
    public static long divMod(long a, long b){
    	return multMod(a, inverseMod(b));
    }
    public static long[] makeFactorialArray(int size){
        long[] array = new long[size];
        array[0]=1;
        for(int i=1;i<size;i++){
        	array[i]=multMod(array[i-1],i);
        }
        return array;
    }
    public static long[] makeInversedArray(long[] original){
        long[] array = new long[original.length];
        for(int i=0;i<original.length;i++){
        	array[i] = inverseMod(original[i]);
        }
        return array;
    }
    public static long combination(int n, int r, long[] fact, long[] factInv){
        return multMod(fact[n], multMod(factInv[r],factInv[n-r]));
    }

    public static long access(long[] array, int index){
    	if(index<0 || index>=array.length) return 1;
    	else return array[index];
    }

    public static long solve(int H, int W, int K){
    	long[][] dp = new long[H+1][W];
    	Arrays.fill(dp[0], 0); dp[0][0]=1;
    	//System.out.println(Arrays.toString(dp[0]));

    	long[] simpleBar = new long[]{1,2,3,5,8,13,21,34,55};

    	for(int h=1;h<=H;h++){
    		for(int w=0;w<W;w++){
    			dp[h][w] += multMod(dp[h-1][w], multMod(access(simpleBar,w-1), access(simpleBar,W-w-2)));
    			dp[h][w] %= MOD;
    			if(w>0) {
    				dp[h][w-1] += multMod(dp[h-1][w], multMod(access(simpleBar,w-2), access(simpleBar,W-w-2)));
    			    dp[h][w-1] %= MOD;
    			}
    			if(w<W-1){
    			    dp[h][w+1] += multMod(dp[h-1][w], multMod(access(simpleBar,w-1), access(simpleBar,W-w-3)));
    			    dp[h][w] %= MOD;	
    			} 
    		}
    		//System.out.println(Arrays.toString(dp[h]));
    	}
    	return dp[H][K];
    }

    public static void main(String[] args) {
    	long[] fact = makeFactorialArray(200001);
        long[] factInv = makeInversedArray(fact);
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt();
        int W = sc.nextInt();
        int K = sc.nextInt()-1;
        System.out.println(solve(H,W,K));

    }
}

import java.math.BigInteger;
import java.util.Scanner;

public class Main {

	// 横線の引き方(縦がi+1本)
	static final BigInteger X[] = {
		new BigInteger("0"),
		new BigInteger("2"),
				new BigInteger("3"),
						new BigInteger("4"),
								new BigInteger("7"),
										new BigInteger("13"),
												new BigInteger("21"),
	};

	static BigInteger ONE = new BigInteger("1");
	static BigInteger TWO = new BigInteger("2");
	static BigInteger mod = new BigInteger("1000000007");
	//---------------------------------------------------------------------------------------------------
	static BigInteger[] f = new BigInteger[101010];
	static void init() {
		f[0] = new BigInteger("1");
		for (BigInteger i = new BigInteger("1"); i.compareTo(new BigInteger("101010")) < 0; i.add(ONE)) f[i.intValue()] = (f[i.intValue() - 1].multiply(i)).mod(mod);
	}
	//---------------------------------------------------------------------------------------------------
	static BigInteger inv(BigInteger x) {
		BigInteger res = ONE;
		BigInteger k = mod.subtract(TWO);
		BigInteger y = x;
		while (k.compareTo(BigInteger.ZERO) != 0) {
			if (k.equals(ONE)) res = (res.multiply(y)).mod(mod);
			y = (y.multiply(y)).mod(mod);
			k = k.subtract(TWO);
		}
		return res;
	}
	//---------------------------------------------------------------------------------------------------
	static BigInteger C(int n, int k) {
		BigInteger a = f[n]; // = n!
		BigInteger b = f[n - k]; // = (n-k)!
		BigInteger c = f[k]; // = k!

		BigInteger bc = (b.multiply(c)).mod(mod);

		return (a.multiply(inv(bc))).mod(mod);
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int H = sc.nextInt();
		int W = sc.nextInt();
		int K = sc.nextInt();
		sc.close();

		solve(H, W, K);

	}

	public static BigInteger toBigInteger(int x) {
		return new BigInteger(String.valueOf(x));
	}

	public static void solve(int H, int W, int K) {

		BigInteger sum = BigInteger.ZERO;
		for (int i = 1; i <= H; i += 2) {
			BigInteger x = C(H, i);
			int leftTate = K - 2;
			int rightTateNotI = W - K;
			int rightTateI = rightTateNotI - 1;
			if (leftTate < 0) leftTate = 0;
			if (rightTateNotI < 0) rightTateNotI = 0;
			if (rightTateI < 0) rightTateI = 0;
			BigInteger left = X[leftTate].multiply(toBigInteger(H));
			BigInteger rightNotI = X[rightTateNotI].multiply(toBigInteger(H - i));
			BigInteger rightI = X[leftTate].multiply(toBigInteger(i));
			sum = sum.add(left.multiply(rightNotI.add(rightI)).multiply(x));
		}
		System.out.println(sum.mod(new BigInteger("1000000007")));
	}

}

import java.util.*;
import java.io.*;

public class Main{
    static final long MOD=1000000007;
    static int w, h;
    static int combination[];
    static long dp[][];
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        h=fsc.nextInt();
        w=fsc.nextInt();
        int k=fsc.nextInt();
        fsc.close();
        if(w==1){
            System.out.println(1);
            System.exit(0);
        }
        combination=new int[w];
        for(int i=0;i<w;i++){
            combination[i]=0;
            for(int j=0;j<w;j++){
                combination[i]+=comb(i-j+1, j);
            }
        }
        dp=new long[h+1][w];
        boolean[][] bs=sel(w-1);
        boolean[] b;
        for(int t=0;t<h+1;t++){
            if(t==0){
                for(int i=0;i<w;i++){
                    if(i==0) dp[t][i]=1;
                    else dp[t][i]=0;
                }
                continue;
            }
            for(int l=0;l<combination[w-1];l++){
                b=bs[l];
                for(int s=0;s<w-1;s++){
                    //System.out.print(b[s]);
                    if(b[s]){
                        dp[t][s]+=dp[t-1][s+1];
                        dp[t][s+1]+=dp[t-1][s];
                        dp[t][s]%=MOD;
                        dp[t][s+1]%=MOD;
                    }
                    else{
                        if(s==0){
                            dp[t][0]+=dp[t-1][0];
                            dp[t][0]%=MOD;
                        }
                        else if(s==w-2){
                            dp[t][w-1]+=dp[t-1][w-1];
                            dp[t][w-1]%=MOD;
                        }
                        else if(!b[s+1]){
                            dp[t][s+1]+=dp[t-1][s+1];
                            dp[t][s+1]%=MOD;
                        }
                    }
                }
                //System.out.print("\n");
            }
        }
        System.out.println(dp[h][k-1]);
    }
    static boolean[][] sel(int w){
        boolean b[][]=new boolean[combination[w]][w];
        if(w==1){
            b[0][0]=true;
            b[1][0]=false;
        }
        else if(w==2){
            b[0][0]=true; b[0][1]=false;
            b[1][0]=false; b[1][1]=true;
            b[2][0]=false; b[2][1]=false;
        }
        else{
            boolean tf[][]=sel(w-2);
            boolean f[][]=sel(w-1);
            int tfl=tf.length, fl=f.length;
            for(int i=0;i<tfl;i++){
                b[i][0]=true; b[i][1]=false;
                for(int j=2;j<w;j++) b[i][j]=tf[i][j-2];
            }
            for(int i=tfl;i<tfl+fl;i++){
                b[i][0]=false;
                for(int j=1;j<w;j++) b[i][j]=f[i-tfl][j-1];
            }
        }
        return b;
    }

    static long comb(int n, int r){
        if(n<r) return 0;
        r=Math.min(r, n-r);
        long res=1;
        for(int d=1;d<=r;d++){
            res*=n;
            n--;
            res/=d;
        }
        return res;
    }
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

