    List<List<Integer>> gr = new ArrayList<>();

    long MOD = 1_000_000_007;



    public void solve() {
        int H = io.ri();
        int W = io.ri();
        int K = io.ri()-1;

        long[] count = new long[W];
        count[0] = 1;
        for(int i = 0;i<H;i++){
            long[] next = new long[W];
            for(int mask = 0;mask<(1<<(W-1));mask++){
                boolean good = true;
                for(int j = 1;j<W-1;j++) {
                    if ((mask & (1 << j)) > 0 && (mask & (1 << (j-1))) > 0) {
                        good = false;
                        break;
                    }
                }
                if(!good)
                    continue;
                for(int j = 0;j<W-1;j++) {
                    if ((mask & (1 << j)) > 0) {
                        next[j] = (next[j] + count[j + 1]) % MOD;
                        next[j + 1] = (next[j + 1] + count[j]) % MOD;
                    }
                    if (j > 0 && (mask & (1 << j)) == 0 && (mask & (1 << (j - 1))) == 0) {
                        next[j] = (next[j] + count[j]) % MOD;
                    }
                }
                if((mask & 1) ==0){
                    next[0] = (next[0] + count[0]) % MOD;
                }
                if(W > 1 && (mask & (1<<(W-2))) ==0){
                    next[W-1] = (next[W-1] + count[W-1]) % MOD;
                }
            }
            count = next;
        }
        io.writeLine(count[K] + "");
    }

}


