public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DNumberOfAmidakuji solver = new DNumberOfAmidakuji();
        solver.solve(1, in, out);
        out.close();
    }

    static class DNumberOfAmidakuji {
        private static final int MOD = (int) 1e9 + 7;
        private static int h;
        private static int w;
        private static long[][] dp;

        public void solve(int testNumber, LightScanner in, PrintWriter out) {
            h = in.ints();
            w = in.ints();
            int k = in.ints() - 1;

            List<Integer> patterns = new ArrayList<>();
            outer:
            for (int i = 0; i < (1 << (w - 1)); i++) {
                for (int j = 0b11; j < (1 << (w - 1)); j = (j << 1)) {
                    if ((i & j) == j) {
                        continue outer;
                    }
                }
                patterns.add(i);
            }

            // System.out.println(patterns.stream().map(Integer::toBinaryString).collect(Collectors.joining(",")));

            dp = new long[h + 1][w];
            dp[0][k] = 1;
            for (int y = 1; y <= h; y++) {
                for (int x = 0; x < w; x++) {
                    for (int p : patterns) {
                        if (x < w - 1 && (p & 1 << x) > 0) {
                            dp[y][x] += dp[y - 1][x + 1];
                        } else if (x > 0 && (p & 1 << (x - 1)) > 0) {
                            dp[y][x] += dp[y - 1][x - 1];
                        } else {
                            dp[y][x] += dp[y - 1][x];
                        }
                        dp[y][x] %= MOD;
                    }
                }
            }

            // Arrays.stream(dp).map(Arrays::toString).forEach(System.out::println);
            out.println(dp[h][0]);
        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        final int DIV = 1000000007;
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt();
        int w = sc.nextInt();
        int k = sc.nextInt();
        sc.close();

        if(w == 1){
            System.out.println(1);
            return;
        }else if(w == 2){
            System.out.println((int)Math.pow(2, h-1));
            return;
        }

        long[] row = new long[w-1];
        long num = 0;
        out: for(int i=0; i<(int)Math.pow(2, w-1); i++){
            char[] set = String.format("%" + (w-1) + "s", Integer.toString(i, 2)).replace(' ', '0').toCharArray();
            for(int j=0; j<w-2; j++){
                if(set[j] == '1' && set[j+1] == '1') continue out;
            }
            num++;
            for(int j=0; j<w-1; j++){
                if(set[j] == '1') row[j]++;
            }
        }

        long[][] dp = new long[h+1][w];
        // Arrays.fill(dp[0], 1);
        dp[0][0] = 1;

        for(int i=0; i<h; i++){
            dp[i+1][0] = dp[i][0] * (num - row[0]) + dp[i][1] * row[0];
            dp[i+1][w-1] = dp[i][w-1] * (num - row[w-2]) + dp[i][w-2] * row[w-2];
            for(int j=1; j<w-1; j++){
                dp[i+1][j] = dp[i][j] * (num - row[j-1] - row[j])
                            + dp[i][j-1] * row[j-1] + dp[i][j+1] * row[j];
            }
            for(int j=0; j<w; j++){
                dp[i+1][j] %= DIV;
            }
        }

        System.out.println(dp[h][k-1]);
    }
}

