	{
		static void Main(string[] args)
		{
			long[] x = Console.ReadLine().Split().Select(long.Parse).ToArray();
			long[,] dp = new long[x[0] + 2, x[1]]; dp[0, 0] = 1;
			long mod = 1000000007;
			for (int i = 0; i <= x[0]; i++)
			{
				for (int j = 0; j < x[1]; j++)
				{
					if (j > 0)
					{
						if (j - 1 == 0 || j == x[1] - 1)
							dp[i + 1, j - 1] += dp[i, j] * Math.Max(1, 1 << (int)x[1] - 3);
						else
							dp[i + 1, j - 1] += dp[i, j] * Math.Max(1, 1 << (int)x[1] - 4);
						dp[i + 1, j - 1] %= mod;
					}
					if (j == 0 || j == x[1] - 1)
						dp[i + 1, j + 0] += dp[i, j] * Math.Max(1, 1 << (int)x[1] - 2);
					else
						dp[i + 1, j + 0] += dp[i, j] * Math.Max(0, 1 << (int)x[1] - 3);
					dp[i + 1, j + 0] %= mod;
					if (j < x[1] - 1)
					{
						if (j == 0 || j + 1 == x[1] - 1)
							dp[i + 1, j + 1] += dp[i, j] * Math.Max(1, 1 << (int)x[1] - 3);
						else
							dp[i + 1, j + 1] += dp[i, j] * Math.Max(1, 1 << (int)x[1] - 4);
						dp[i + 1, j + 1] %= mod;
					}
				}
			}
