        static void Solve()
        {
            int H, W, K;
            Input(out H, out W, out K);
            var dp = new ModInt[H + 1, W];
            for(var i = 0; i < H + 1; i++)
            {
                for(var j = 0; j < W; j++)
                {
                    dp[i, j] = 0;
                }
            }
            dp[0, 0] = 1;
            var cnt = new ModInt[W + 1, 2];
            cnt[0, 0] = 1;
            for(var i = 0; i < W; i++)
            {
                cnt[i + 1, 0] = cnt[i, 1] + cnt[i, 0];
                cnt[i + 1, 1] = cnt[i, 0];
            }
            for(var i = 0; i < H; i++)
            {
                for(var j = 0; j < W; j++)
                {
                    int L = j;
                    int R = W - 1 - j;

                    //no move
                    dp[i + 1, j] += dp[i, j] * cnt[L, 0] * cnt[R, 0];

                    //to left
                    if (j > 0)
                    {
                        dp[i + 1, j - 1] += dp[i, j] * cnt[L - 1, 0] * cnt[R, 0];
                    }

                    //to right
                    if (j + 1 < W)
                    {
                        dp[i + 1, j + 1] += dp[i, j] * cnt[L, 0] * cnt[R - 1, 0];
                    }
                }
            }
            OutL(dp[H, K - 1].value);
        }

