            var p = 1000000007;

            var rows = new long[h + 1, w];
            var fib = new long[w];
            fib[0] = 1;
            fib[1] = 1;
            for (int i = 2; i < w; i++)
            {
                fib[i] = fib[i - 1] + fib[i - 2];
            }
            var c = new long[w];
            c[0] = fib[w-1];
            c[w - 1] = fib[w-1];
            for (int i = 1; i < w-1; i++)
            {
                c[i] = fib[i - 1] * fib[w - i - 1];
            }

            rows[0, 0] = 1;
            for (int i = 1; i < h+1; i++)
            {
                for (int j = 0; j < w; j++)
                {
                    var r = (rows[i - 1, j] * c[j]) % p;
                    if (j>0)
                    {
                        r = (r + rows[i - 1, j - 1] * fib[j-1]) % p;
                    }
                    if (j<w-1)
                    {
                        r = (r + rows[i - 1, j + 1] * fib[w - j - 1]) % p;
                    }
                    rows[i, j] = r;
                }
            }

            Console.WriteLine(rows[h, k - 1]);
