using System;
using System.Collections.Generic;
using System.Linq;

class Procon
{
    public Procon() { }
    static void Main(string[] agrs)
    {
        new Procon().Do();
    }

    Scanner cin;

    int H;
    int W;
    int K;

    long M = 1000000007;

    public void Do()
    {
        cin = new Scanner();
        H = cin.nextInt();
        W = cin.nextInt();
        K = cin.nextInt();

        long[,] DP = new long[H + 1, W];

        DP[0, 0] = 1;
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                for (int k = 0; k < 1 << (W - 1); k++)
                {
                    bool ok = true;
                    for (int l = 0; l < W - 2; l++)
                    {
                        if (((k >> l & 1) == 1) && ((k >> (l + 1) & 1) == 1))
                        {
                            ok = false;
                        }
                    }
                    if (ok)
                    {
                        if (j >= 1 && ((k >> (j - 1)) & 1) == 1)
                        {
                            DP[i + 1, j - 1] += DP[i, j];
                            DP[i + 1, j - 1] %= M;
                        }
                        else if (j <= W - 2 && ((k >> j) & 1) == 1)
                        {
                            DP[i + 1, j + 1] += DP[i, j];
                            DP[i + 1, j + 1] %= M;
                        }
                        else
                        {
                            DP[i + 1, j] += DP[i, j];
                            DP[i + 1, j] %= M;
                        }
                    }
                }
            }
        }

        Console.WriteLine(DP[H, K - 1]);
    }

    public long pow(long a, long b)
    {
        long ans = 1;
        for (int i = 0; i < b; i++)
        {
            ans = (ans * a) % M;
        }

        return ans;
    }
}

