public class Solver
{
    const int MOD = 1000000007;
    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();
        int k = ReadInt();

        if (m == 1)
        {
            Write(1);
            return;
        }

        var o = new List<int>();
        for (int i = 0; i < 1 << m - 1; i++)
        {
            bool f = true;
            for (int j = 0; j < m - 2; j++)
                if ((i >> j & 1) == 1 && (i >> j + 1 & 1) == 1)
                    f = false;
            if (f)
                o.Add(i);
        }

        var dp = new int[m];
        dp[0] = 1;
        for (int i = 0; i < n; i++)
        {
            var ndp = new int[m];
            foreach (int e in o)
            {
                for (int j = 0; j < m; j++)
                {
                    int nj = j;
                    if (j < m - 1 && (e >> j & 1) == 1)
                        nj++;
                    else if (j > 0 && (e >> j - 1 & 1) == 1)
                        nj--;
                    ndp[nj] = (ndp[nj] + dp[j]) % MOD;
                }
            }
            dp = ndp;
        }

        Write(dp[k - 1]);
    }

