		int h = int.Parse(input[0]);
		int w = int.Parse(input[1]);
    int k = int.Parse(input[2]);
		long[,] dp = new long[h+1,w];//見た行数と何列目にいるか
    dp[0,0] = 1;

    if(w > 1)
    {
      for(int i = 1; i <= h; i++)
      {
        for(int j = 0; j < w; j++)
        {
          for(int x = 0; x < Math.Pow(2,w-1); x++)
          {
            List<int> rowMemo = BinaryToNum(w-1,x);
            bool rowContinue = false;
            for(int y = 1; y < w-1; y++)
            {
              if(rowMemo[y-1] + rowMemo[y] == 2) rowContinue = true;
            }
            if(rowContinue) continue;

            if(j == 0)
            {
              if(rowMemo[j] == 1) dp[i,j] += dp[i-1,j+1];
              else dp[i,j] += dp[i-1,j];
            }else if(j == w-1)
            {
              if(rowMemo[j-1] == 1) dp[i,j] += dp[i-1,j-1];
              else dp[i,j] += dp[i-1,j];
            }else
            {
              if(rowMemo[j] == 1) dp[i,j] += dp[i-1,j+1];
              else if(rowMemo[j-1] == 1) dp[i,j] += dp[i-1,j-1];
              else dp[i,j] += dp[i-1,j];
            }
            dp[i,j] %= mod;
