  static List<int> FactorialToNum(int n, int num)
  {//n個の数を並べ替えた方法をリストに直す。
  //n=1でnum=0なら{0}。 n=2でnum=0なら{0,1}、num=1なら{1,0}
    List<int> answersNum = new List<int>();
    List<int> answers = new List<int>();
    List<int> answersRest = new List<int>();
    int rest = 1;
    for(int i = 2; i < n; i++)
    {
      rest *= i;
    }

    for(int i = n-1; i > 0; i--)
    {
      answersNum.Add(num/rest);
      num %= rest;
      rest /= i;
    }
    answersNum.Add(0);

    for(int i = 0; i < n; i++)
    {
      answersRest.Add(i);
    }
    for(int i = 0; i < n; i++)
    {
      answers.Add(answersRest[answersNum[i]]);
      answersRest.RemoveAt(answersNum[i]);
    }

    return answers;
  }

  static List<int> BinaryToNum(int n, int num)
  {//2進数でn桁の数numをリストに直す。
  //n=2でnum=0なら{0,0}、num=1なら{0,1}、num=2なら{1,0}。
    List<int> answers = new List<int>();
    int rest = 1;
    for(int i = 0; i < n-1; i++)
    {
      rest *= 2;
    }

    for(int i = 0; i < n; i++)
    {
      answers.Add(num/rest);
      num %= rest;
      rest /= 2;
    }

    return answers;
  }  

}

