    class Program2
    {
        static long mod = 1000000007;
        static long[,] stic;
        static void Main(string[] args)
        {
            var HWK = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            var H = HWK[0];
            var W = HWK[1];
            var K = HWK[2];


            stic = new long[W+1,2];
            stic[1, 0] = 1;
            stic[1, 1] = 1;
            var num = new long[H + 1, W + 1];
            num[0, 1] = 1;
            culstic(W, 0);
            culstic(W, 1);

            for (int i = 1; i <= H; i++)
            {
                for (int j = 1; j <= W; j++)
                {
                    if (j == 1)
                    {
                        num[i, j] = num[i - 1, j] * (culsticsum(Max(W - 2, 0)) % mod);
                        num[i, j] %= mod;
                        num[i, j] += W >= 2 ? (num[i - 1, Min(j + 1, W)] * culsticsum(Max(W - 3, 0))) % mod : 0;
                        num[i, j] %= mod;
                    }
                    else if (j == W)
                    {
                        num[i, j] = (num[i - 1, j] * culsticsum(Max(W - 2, 0))) % mod + (num[i - 1, j - 1] * culsticsum(Max(W - 3, 0))) % mod;
                        num[i, j] %= mod;
                    }
                    else
                    {
                        num[i, j] = ((num[i - 1, j] * culsticsum(Max(j-2, 0))%mod)* culsticsum(Max(W - j-1, 0))) % mod;
                        if (j == 2)
                        {
                            num[i, j] += num[i - 1, j - 1] * culsticsum(Max(W - 3, 0)) % mod;
                        }
                        else
                        {
                            num[i, j] += (num[i - 1, j - 1] * culsticsum(Max(j - 3, 0))%mod)*culsticsum(Max(W - j-1, 0)) % mod;
                        }
                        num[i, j] %= mod;

                        if (j == W - 1)
                        {
                            num[i, j] += num[i - 1, j + 1] * culsticsum(Max(W - 3, 0)) % mod;
                        }
                        else
                        {
                            num[i, j] += (num[i - 1, j + 1] * culsticsum(Max(j - 2, 0))%mod)*culsticsum(Max(W - j-2, 0)) % mod;
                        }
                        num[i, j] %= mod;
                    }
                }
            }
            Console.WriteLine(num[H, K] % mod);
        }

        static long culsticsum(int num)
        {
            if(num == 0)
            {
                return 1;
            }
            return (stic[num, 0] + stic[num, 1])%mod;
        }

        static long culstic(int num,int type)
        {

            if( stic[num,type] > 0)
            {
                return stic[num, type];
            }
            else
            {
                stic[num, type] = culstic(num-1,0)%mod;
                if(num == 0)
                {
                    stic[num, type] += culstic(num - 1, 1) % mod;
                }
            }
            return stic[num, type]%mod;
        }

        public static long RepPow(long x, long p, long m = 1000000007)
        {
            if (p == 1) return x % m;
            if (p == 0) return 1 % m;
            long b = RepPow(x, p / 2, m) % m;
            if (p % 2 == 0) { return (b * b) % m; }
            else { return (x * ((b * b) % m)) % m; }
        }
    }
