namespace ProconExpt181108
{
    class Program
    {
        static void Main(string[] args)
        {
            int H = int.Parse(args[0]);
            int W = int.Parse(args[1]);
            int K = int.Parse(args[2]);

            CalcAmida(H, W, K);


        }

        static void CalcAmida(int H,int W, int K)
        {
            Amida ami = new Amida(H, W, K);

            ulong lTotal = ami.CalcTotal();

            Console.WriteLine(lTotal % 1000000007);
        }



    }

    class Amida
    {
        int H;
        int W;
        int K;

        int PlaMax;
        int MinusMax;
        int ZeroMax;
        int[] aiPattern;

        ulong[] aiFibon;

        public Amida(int a_H, int a_W, int a_K)
        {
            H = a_H;
            W = a_W;
            K = a_K;
            aiPattern = new int[H];

            //フィボナッチ数列を計算しておく
            aiFibon = new ulong[W];
            aiFibon[0] = 1;
            if (W > 1) aiFibon[1] = 2;

            for (int i = 2; i < W; i++)
            {
                aiFibon[i] = aiFibon[i-1] + aiFibon[i-2];
            }
        }

        public ulong CalcTotal()
        {
            ulong lTotal = 0;

            for (int iPla = K - 1; iPla <= (H + K - 1) / 2; iPla++)
            {
                PlaMax = iPla;
                MinusMax = iPla - K + 1;
                ZeroMax = H - PlaMax - MinusMax;

                lTotal += CalcPatterns(0,0,0,0);
            }

            return lTotal;
        }

        ulong CalcPatterns(int PlaCur, int MinusCur, int ZeroCur, int iCurIdx)
        {

            if (iCurIdx == aiPattern.Length)
            {
                return CalcCurrentPattern();
            }

            ulong lCalc = 0;

            if (PlaCur < PlaMax && PlaCur - MinusCur < W - 1)
            {
                aiPattern[iCurIdx] = 1;
                lCalc += CalcPatterns(PlaCur + 1, MinusCur, ZeroCur, iCurIdx + 1);
            }
            if (MinusCur < MinusMax && PlaCur - MinusCur > 0)
            {
                aiPattern[iCurIdx] = -1;
                lCalc += CalcPatterns(PlaCur, MinusCur+1, ZeroCur, iCurIdx + 1);
            }
            if (ZeroCur < ZeroMax)
            {
                aiPattern[iCurIdx] = 0;
                lCalc += CalcPatterns(PlaCur, MinusCur, ZeroCur + 1, iCurIdx + 1);
            }

            return lCalc % 1000000007;
        }

        ulong CalcCurrentPattern()
        {
            ulong lCalc = 1;
            int iPos = 0;

            for (int iRow = 0; iRow < aiPattern.Length ; iRow++)
            {
                int iLeft = aiPattern[iRow] == -1 ? iPos - 2 : iPos - 1;
                if (iLeft < 0) iLeft = 0;
                int iRight = aiPattern[iRow] == 1 ? (W - iPos - 3) : (W - iPos - 2);
                if (iRight < 0) iRight = 0;

                lCalc *= aiFibon[iLeft];
                lCalc *= aiFibon[iRight];

                iPos += aiPattern[iRow];
            }

            return lCalc;
        }


    }

}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        H = sc.ReadInt();
        W = sc.ReadInt();
        K = sc.ReadInt();
        DP = new long[H + 1, W];
        for (int i = 0; i < H + 1; i++)
        {
            for (int j = 0; j < W; j++)
            {
                DP[i, j] = -1;
            }
        }
        var ans = Rec(0, 0);
        Console.WriteLine(ans);
    }
    static long Rec(int h, int w)
    {
        // 範囲外
        if (w < 0 || W <= w) return 0;
        // ゴール
        if (h == H)
        {
            if (w == K - 1) return 1;
            else return 0;
        }
        // メモしてる
        if (DP[h, w] >= 0) return DP[h, w];

        // 現在の高さの横棒の引き方を全探索
        long res = 0;
        for (int i = 0; i < (1 << (W - 1)); i++)
        {
            // 隣接して線が引かれているかどうか
            var ok = true;
            for (int k = 0; k < W; k++)
            {
                var x = (i >> k) & 1;
                var y = (i >> (k + 1)) & 1;
                if (x == 1 && y == 1) ok = false;
            }
            if (!ok) continue;

            if (w != W - 1 && ((i >> w) & 1) == 1)
            {
                // 右へ進む
                res += Rec(h + 1, w + 1);
            }
            else if (w != 0 && ((i >> (w - 1)) & 1) == 1)
            {
                // 左に進む
                res += Rec(h + 1, w - 1);
            }
            else
            {
                // 下に進む
                res += Rec(h + 1, w);
            }
            res %= (int)1e9 + 7;
        }
        DP[h, w] = res;
        return res;
    }
    static long[,] DP;
    static int H, W, K;
    static Scanner sc = new Scanner();
}
