class Program
{
    static void Main()
    {
        //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
        new Program().solve();
        Out.Flush();
    }
    readonly Scanner cin = new Scanner();
    readonly int[] dd = { 0, 1, 0, -1, 0 }; //→↓←↑
    readonly int mod = 1000000007;
    readonly int dom = 998244353;
    bool chmax<T>(ref T a, T b) where T : IComparable<T> { if (a.CompareTo(b) < 0) { a = b; return true; } return false; }
    bool chmin<T>(ref T a, T b) where T : IComparable<T> { if (b.CompareTo(a) < 0) { a = b; return true; } return false; }

    void solve()
    {
        int H = cin.nextint;
        int W = cin.nextint;
        int K = cin.nextint - 1;
        var C = new int[W];
        var fact = 1;
        for (int i = 0; i < W; i++)
        {
            C[i] = i;
            fact *= i + 1;
        }
        var memo = new int[int.Parse(C.Reverse().concat()) + 1];
        var list = new List<int>[fact];
        for (int j = 0; j < fact; j++)
        {
            memo[int.Parse(C.concat())] = j;
            list[j] = new List<int>();
            next_permutation(C);
        }

        for (int j = 0; j < fact; j++)
        {
            for (int s = 0; s < 1 << (W - 1); s++)
            {
                bool before = false;
                var S = new int[W];
                C.CopyTo(S, 0);
                var ok = true;
                var first = true;
                for (int k = 0; k < W - 1; k++)
                {
                    var mode = (s >> k & 1) == 1;
                    if (mode)
                    {
                        if (before || (first && S[k] > S[k + 1]))
                        {
                            ok = false;
                            continue;
                        }
                        swap(ref S[k], ref S[k + 1]);
                        first = false;
                    }

                    before = mode;
                }
                if (ok)
                {
                    var to = memo[int.Parse(S.concat())];
                    list[j].Add(to);
                    if (j != to) list[to].Add(j);
                }
            }
            next_permutation(C);
        }

        var dp = new int[H + 1][];
        for (int i = 0; i < H + 1; i++)
        {
            dp[i] = new int[fact];
        }
        dp[0][0] = 1;
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < fact; j++)
            {
                long sum = 0;
                foreach (var v in list[j])
                {
                    sum += dp[i][v];
                }
                dp[i + 1][j] = (int)(sum % mod);
                next_permutation(C);
            }
        }
        long ans = 0;
        for (int j = 0; j < fact; j++)
        {
            if (C[0] == K)
            {
                ans += dp[H][j];
            }
            next_permutation(C);
        }

        WriteLine(ans % mod);
    }

    void swap<T>(ref T a, ref T b)
    {
        var t = a;
        a = b;
        b = t;
    }
    bool next_permutation<T>(T[] array) where T : IComparable<T>
    {
        return next_permutation(array, 0, array.Length);
    }
    bool next_permutation<T>(T[] array, int start, int length) where T : IComparable<T>
    {
        int end = start + length - 1;
        if (end <= start) return false;
        int last = end;
        while (true)
        {
            int pos = last--;
            if (array[last].CompareTo(array[pos]) < 0)
            {
                int i;
                for (i = end + 1; array[last].CompareTo(array[--i]) >= 0;) { }
                T tmp = array[last]; array[last] = array[i]; array[i] = tmp;
                Array.Reverse(array, pos, end - pos + 1);
                return true;
            }
            if (last == start)
            {
                Array.Reverse(array, start, end - start + 1);
                return false;
            }
        }
    }
}

