            foreach(int x in Enumerable.Range(0, w))
            {
                if(dp[y][x] >= 1000000007)
                    dp[y][x] %= 1000000007;
                int p = maxPattern;
                if(x != 0)
                {
                    p -= pattern[x - 1];
                    dp[y + 1][x - 1] += dp[y][x] * pattern[x - 1];
                }
                if(x != w - 1)
                {
                    p -= pattern[x];
                    dp[y + 1][x + 1] += dp[y][x] * pattern[x];    
                }
                dp[y + 1][x] += dp[y][x] * p;

            }
        Console.WriteLine(dp[h][k] % 1000000007);
    }
