    class Program2
    {
        static long mod = 1000000007;
        static void Main(string[] args)
        {
            var HWK = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            var H = HWK[0];
            var W = HWK[1];
            var K = HWK[2];

            var num = new long[H+1,W+1];
            num[0, 1] = 1;

            for (int i = 1; i <= H; i++)
            {
                for (int j = 1; j <= W; j++)
                {
                    if(j == 1)
                    {
                        num[i, j] = num[i - 1, j] * RepPow(2, Max(W - 2, 0)) % mod;
                        num[i, j] %= mod;
                        num[i, j] += W >= 2 ? num[i - 1, Min(j + 1, W)] * RepPow(2, Max(W - 3, 0)) % mod : 0;
                        num[i, j] %= mod;
                    }
                    else if (j == W)
                    {
                        num[i, j] = num[i - 1, j] * RepPow(2, Max(W - 2, 0)) % mod + num[i - 1, j - 1] * RepPow(2, Max(W - 3, 0)) % mod;
                        num[i, j] %= mod;
                    }
                    else
                    {
                        num[i, j] =  num[i - 1, j] * RepPow(2, Max(W - 3, 0)) % mod;
                        if(j == 2)
                        {
                            num[i, j] += num[i - 1, j - 1] * RepPow(2, Max(W - 3, 0)) % mod;
                        }
                        else
                        {
                            num[i, j] += num[i - 1, j - 1] * RepPow(2, Max(W - 4, 0)) % mod;
                        }                        
                        num[i, j] %= mod;

                        if(j == W - 1)
                        {
                            num[i, j] += num[i - 1, j + 1] * RepPow(2, Max(W - 3, 0)) % mod;
                        }
                        else
                        {
                            num[i, j] += num[i - 1, j + 1] * RepPow(2, Max(W - 4, 0)) % mod;
                        }
                        num[i, j] %= mod;
                    }
                }
            }
            Console.WriteLine(num[H,K]%mod);
        }

        public static long RepPow(long x, long p, long m = 1000000007)
        {
            if (p == 1) return x % m;
            if (p == 0) return 1 % m;
            long b = RepPow(x, p / 2, m) % m;
            if (p % 2 == 0) { return (b * b) % m; }
            else { return (x * ((b * b) % m)) % m; }
        }
    }
}

