class K
{
	int[] G => ReadLine().Split().Select(int.Parse).ToArray();
	public const int MOD = 1000000007;
	public K()
	{
		var I = G;
		int H = I[0], W = I[1], K = I[2] - 1;
		if (W == 1) { WriteLine(1); return; }
		var fib = new int[W + 1];
		fib[1] = fib[2] = 1;
		for (var n = 3; n <= W; n++) fib[n] = (fib[n - 1] + fib[n - 2]) % MOD;
		var M = new Matrix(W);
		for (var i = 0; i < W; i++) M[i, i] = fib[i + 1] * fib[W - i] % MOD;
		for (var i = 0; i < W - 1; i++) M[i, i + 1] = M[i + 1, i] = fib[i + 1] * fib[W - i - 1] % MOD;
		WriteLine(M.Pow(H)[0, K]);
	}
}
class Matrix
{
	const long MOD = K.MOD;
	public readonly int Size;
	readonly long[,] a;
	public long this[int r, int c] { get { return a[r, c]; } set { a[r, c] = value; } }
	public Matrix(int s) { Size = s; a = new long[s, s]; }
	public Matrix(int s, Func<int, int, long> f) : this(s) { for (var i = 0; i < s; i++) for (var j = 0; j < s; j++) a[i, j] = f(i, j); }
	public static Matrix operator *(Matrix p, Matrix q)
		=> new Matrix(p.Size, (i, j) => { var sum = 0L; for (var k = 0; k < p.Size; k++) sum = (sum + p.a[i, k] * q.a[k, j] % MOD) % MOD; return sum; });
	public static Matrix One(int size) => new Matrix(size, (i, j) => i == j ? 1 : 0);
	public Matrix Pow(long n)
	{
		var p = One(Size);
		var x = this;
		while (n > 0)
		{
			if ((n & 1) == 1) p *= x;
			n >>= 1;
			x *= x;
		}
		return p;
	}
}

