namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
#if DEBUG
            Solve(Console.In, Console.Out);
            Console.ReadLine();
#else
            Solve(Console.In, Console.Out);
#endif
        }

        public static void Solve(TextReader ci, TextWriter co)
        {
            int h, w, k;
            ReadInts(ci, out h, out w, out k);
            co.WriteLine(Solve(h, w, 0, k-1));
            co.Flush();
        }

        private static long Solve(int h, int w, int start, int goal)
        {
            int d = Math.Abs(start - goal);
            if (d > h) {
                return 0;
            }

            int key = (h << 16) | (start << 4) | (goal);
            long numTotalAns = 0;
            if (memo1.TryGetValue(key , out numTotalAns)) {
                return numTotalAns;
            }

            else if (h == 1) {
                int min = Math.Min(start, goal);
                int max = Math.Max(start, goal);
                return BarPattern(min - 1) * BarPattern(w - max - 2);
            }
            else {
                int h0 = h / 2;
                int h1 = h - h0;
                numTotalAns = 0;
                for (int mid = 0; mid < w; ++mid) {
                    long numAns =
                        Solve(h0, w, start, mid) *
                        Solve(h1, w, mid, goal);
                    numTotalAns = (numTotalAns + numAns) % 1000000007;
                }
                memo1.Add(key, numTotalAns);
                return numTotalAns;
            }
        }

        private static Dictionary<int, long> memo1 = new Dictionary<int, long>();


        private static long BarPattern(int n)
        {
            int numPattern;
            if (n <= 0) {
                return 1;
            }
            else if (memo2.TryGetValue(n, out numPattern)) {
                return numPattern;
            }
            else {
                numPattern = 0;
                int max = 1 << n;
                for (int i = 0; i < max; ++i) {
                    if ((i & (i << 1)) == 0) ++numPattern;
                }
                memo2.Add(n, numPattern);
                return numPattern;
            }
        }

        private static Dictionary<int, int> memo2 = new Dictionary<int, int>();

        public static int ReadInt(TextReader ci) => int.Parse(ci.ReadLine());

        public static void ReadInts(TextReader ci, out int a, out int b)
        {
            var array = IntArrayFrom(ci.ReadLine());
            a = array[0];
            b = array[1];
        }

        public static void ReadInts(TextReader ci, out int a, out int b, out int c)
        {
            var array = IntArrayFrom(ci.ReadLine());
            a = array[0];
            b = array[1];
            c = array[2];
        }

        public static int[] IntArrayFrom(string s)
            => s.Split(' ').Select(p => int.Parse(p)).ToArray();
    }
}

using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
  static void Main(string[] args)
  {

    var line = Console.ReadLine().Split(" ").Select(Int32.Parse).ToArray();
    var H = line[0];
    var W = line[1];
    var K = line[2];

    var dp = new int[H + 1, W];
    dp[0, 0] = 1;
    for (var hi = 0; hi < H; hi++)
    {
      for (var wi = 0; wi < W; wi++)
      {
        for (var bit = 0; bit < (1 << (W - 1)) - 1; bit++)
        {
          var invalid = false;
          for (var i = 0; i < W - 2; i++)
          {
            if ((bit & (1 << i)) != 0 && (bit & (1 << (i + 1))) != 0)
            {
              invalid = true;
            }
          }
          if (invalid) continue;

          var mod = 1000000007;
          if ((bit & (1 << (wi - 1))) != 0 && wi - 1 >= 0)
          {
            dp[hi + 1, wi - 1] += dp[hi, wi];
            dp[hi + 1, wi - 1] %= mod;
          }
          else if ((bit & (1 << wi)) != 0 && wi + 1 < W)
          {
            dp[hi + 1, wi + 1] += dp[hi, wi];
            dp[hi + 1, wi + 1] %= mod;
          }
          else
          {
            dp[hi + 1, wi] += dp[hi, wi];
            dp[hi + 1, wi] %= mod;
          }

          showDP(dp, H, W);
        }
      }
    }
  }

  static void showDP(int[,] dp, int h, int w)
  {
    for (var i = 0; i < h + 1; i++)
    {
      for (var j = 0; j < w; j++)
      {
        Console.Write("{0} ", dp[i, j]);
      }
      Console.WriteLine();
    }
    Console.WriteLine("----");
  }
}

