            int W = input[1];
            int K = input[2];

            long[,] dp = new long[H + 1, W];

            dp[0, 0] = 1;

            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    int keta = W - 1;
                    int maxBit = 1 << keta;
                    for (int bit = 0; bit < maxBit; bit++)
                    {
                        for (int k = 0; k < keta - 1; k++)
                        {
                            // 横棒が連続していたら飛ばす
                            if (((bit & (1 << k)) > 0) &&
                                ((bit & (1 << (k + 1))) > 0))
                            {
                                goto CONTINUE;
                            }
                        }

                        int nj = j;
                        if ((bit & (1 << j)) > 0)
                            nj++;
                        else if ((j > 0) &&
                                 ((bit & (1 << (j - 1))) > 0))
                            nj--;

                        ModAdd(ref dp[i + 1, nj], dp[i, j]);

                    CONTINUE:;
                    }
                }
            }

            long ans = dp[H, K - 1];
            WriteLine(ans);
        }

