namespace AtCoder.ABC113.D
{
    class Program
    {
        static void Main()
        {
            var sc = new Scanner();
            var H = sc.Nextint();
            var W = sc.Nextint();
            var K = sc.Nextint() - 1;
            var mod = (long) 1e9 + 7;

            var modPatterns = new long[H, W];
            for (int i = H - 1; i >= 0; i--)
            {
                for (int j = 0; j < W; j++)
                {
                    if (i == H - 1)
                    {
                        if (j == K)
                        {
                            modPatterns[i, j] = NumOfPatterns(W, j);
                        }
                        else if (Math.Abs(j - K) == 1)
                        {
                            modPatterns[i, j] = NumOfPatterns(W, j, K);
                        }
                    }
                    else
                    {
                        modPatterns[i, j] = (NumOfPatterns(W, j)) * modPatterns[i + 1, j];
                        if (j != 0) modPatterns[i, j] += NumOfPatterns(W, j, j - 1) * modPatterns[i + 1, j - 1];
                        if (j != W - 1) modPatterns[i, j] += NumOfPatterns(W, j, j + 1) * modPatterns[i + 1, j + 1];
                    }
                    modPatterns[i, j] %= mod;
                }
            }
            if (modPatterns[0, 0] == 0) modPatterns[0, 0] = 1;
            Console.WriteLine(modPatterns[0, 0]);
        }

        static long NumOfPatterns(int w, int a, int? b = null)
        {
            if (b.HasValue) return Count(Math.Min(a, (int) b)) * Count(w - Math.Max(a, (int) b) - 1);
            else return Count(a) * Count(w - a - 1);
        }
        static long Count(int num)
        {
            return FibonacciSequence().Take(num + 2).Last();
        }

        public static IEnumerable<long> FibonacciSequence()
        {
            var a = 0L;
            var b = 1L;
            while (true)
            {
                yield return a;
                yield return b;
                a += b;
                b += a;
            }
        }
    }

