			if (!flag) continue;
			for (var j = 0; j < W - 1; j++)
				if ((i & (1 << j)) == 0) A[j, j]++;
				else
				{
					A[j, j + 1]++;
					A[j + 1, j]++;
					j++;
				}
			if ((i & (1 << (W - 2))) == 0) A[W - 1, W - 1]++;
		}
		var M = new Matrix(A);
		M = M.Pow((ulong)H, MOD);
