using System.Collections.Generic;
using System.Linq;



namespace CSharpSample01
{



    class Program
    {

        static List<string> h_posi;
        const int MOD = 1000000007;
        static int[] h_posi_case;
        static int[] stay_case;


        static void H_Posi(int W, bool left, int w, string str)
        {

            if(w >= W)
            {
                h_posi.Add(str);
                return;
            }

            if (!left) H_Posi(W, true, w + 1, str + "1");
            H_Posi(W, false, w + 1, str + "0");
        }

        static long DP(int H, int W, int K)
        {
            long[,] dp = new long[H + 2, W + 1];

            dp[0, 1] = 1;


            for(int h = 0; h <= H - 1; h++)
            {
                for(int w = 1; w <= W; w++)
                {
                    dp[h + 1, w] += dp[h, w] * stay_case[w] % MOD;
                    dp[h + 1, w] %= MOD;
                    if (w - 1 >= 1)
                    {
                        dp[h + 1, w - 1] += (dp[h, w] * h_posi_case[w - 1]) % MOD;
                        dp[h + 1, w - 1] %= MOD;
                    }
                    if (w + 1 <= W)
                    {
                        dp[h + 1, w + 1] += (dp[h, w] * h_posi_case[w]) % MOD;
                        dp[h + 1, w + 1] %= MOD;
                    }

                }
            }


            return dp[H, K];
        }

        static void Get_h_case(int W)
        {
            foreach(string str in h_posi)
            {
                for(int j = 0; j <= W - 2; j++)
                {                
                    if (str[j] == '1') h_posi_case[j + 1]++;
                }
            }

        }

        static void Get_stay_case(int W)
        {
            foreach(string str in h_posi)
            {
                for(int j = 0; j <= W - 1; j++)
                {
                    if(j == 0)
                    {
                        if(str[j] == '0') stay_case[j + 1]++;
                    }
                    else if(j == W - 1)
                    {
                        if(str[j - 1] == '0') stay_case[j + 1]++;
                    }
                    else
                    {
                        if(str[j - 1] == '0' && str[j] == '0')
                        {
                            stay_case[j + 1]++;
                        }
                    }
                }
            }

        }


        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' ');
            int H = int.Parse(input[0]);
            int W = int.Parse(input[1]);
            int K = int.Parse(input[2]);

            h_posi = new List<string>();
            h_posi_case = new int[W];
            stay_case = new int[W + 1];

            H_Posi(W, true, 2, "1");  
            H_Posi(W, false, 2, "0");  

            Get_h_case(W);
            Get_stay_case(W);

            Console.WriteLine(DP(H, W, K));


        }
    }
}

