        int W = line[1].Int();
        int K = line[2].Int();

        var dp = new int[H + 1, W]; dp[0, 0] = 1;

        //  隣あってないbit
        var status = Enumerable.Range(0, 1 << (W - 1)).Where(i => !i.NeighboringBit(W - 1)).ToArray();

        //  どこの列
        foreach (int i in Enumerable.Range(0, H))
        {
            //  その列におけるスタート地点
            foreach(int j in Enumerable.Range(0, W))
            {
                //  その列における棒があるかないかbit
                foreach(int k in status)
                {
                    //  一番左でない、かつ、左側のbitが存在すれば移動する
                    if (j > 0 && (k.GetBit(j - 1)))
                    {
                        dp[i + 1, j - 1] += dp[i, j];
                        dp[i + 1, j - 1] %= mod;
                    }
                    //  一番右でない、かつ、右側のbitが存在すれば移動する
                    else if (j < W - 1 && k.GetBit(j))
                    {
                        dp[i + 1, j + 1] += dp[i, j];
                        dp[i + 1, j + 1] %= mod;
                    }
                    //  素通り
                    else
                    {
                        dp[i + 1, j] += dp[i, j];
                        dp[i + 1, j] %= mod;
                    }
                }
            }
        }

        Console.WriteLine(dp[H, K - 1]);
        Console.ReadLine();
    }
}

