        return true;
    }

    public void Run() {
        var h = ni();
        var w = ni(); // 1-8
        var k = ni();
        var dp = new long[w];
        int mod = 1000000007;
        dp[0] = 1;
        var swapped = new bool[w];
        for (int i = 0; i < h; i++) {
            var next = new long[w];
            for (int b = 0; b < (1 << (w - 1)); b++) {
                if (!Check(b)) continue;
                Array.Clear(swapped, 0, swapped.Length);
                for (int j = 0; j < w - 1; j++) {
                    if ((b & (1 << j)) != 0) { // swap j and j+1
                        next[j] += dp[j + 1];
                        next[j + 1] += dp[j];
                        next[j] %= mod;
                        next[j + 1] %= mod;
                        swapped[j] = swapped[j + 1] = true;
                    }
                }
                for (int j = 0; j < w; j++) {
                    if (!swapped[j]) {
                        next[j] += dp[j];
                        next[j] %= mod;
                    }
                }
            }
            dp = next;
        }
        cout.WriteLine(dp[k - 1]);
    }
}

