	{
		static void Main(string[] a_asArgs)
		{
			int[] l_aiInput = Console.ReadLine().Split(' ').Select(l_sItem => int.Parse(l_sItem)).ToArray();
			int l_iH = l_aiInput[0];
			int l_iW = l_aiInput[1];
			int l_iK = l_aiInput[2];

			if (l_iW == 1)
			{
				Console.WriteLine("1");
				return;
			}

			List<int[]> l_lPattern = null;
			for (int l_iX = 0; l_iX < l_iW - 1; l_iX++)
			{
				l_lPattern = MakePattern(l_lPattern);
			}

			int[,] l_aiMatrix = new int[l_iH + 1, l_iW];
			l_aiMatrix[0, 0] = 1;

			for (int l_iY = 1; l_iY < l_iH + 1; l_iY++)
			{
				foreach (int[] l_aiPattern in l_lPattern)
				{
					for (int l_iX = 0; l_iX < l_iW; l_iX++)
					{
						if (l_iX > 0 && l_aiPattern[l_iX - 1] == 1)
						{
							l_aiMatrix[l_iY, l_iX] += l_aiMatrix[l_iY - 1, l_iX - 1];
						}
						else if (l_iX < l_iW - 1 && l_aiPattern[l_iX] == 1)
						{
							l_aiMatrix[l_iY, l_iX] += l_aiMatrix[l_iY - 1, l_iX + 1];
						}
						else
						{
							l_aiMatrix[l_iY, l_iX] += l_aiMatrix[l_iY - 1, l_iX];
						}
						l_aiMatrix[l_iY, l_iX] = l_aiMatrix[l_iY, l_iX] % 1000000007;
					}

				}
			}
			Console.WriteLine(l_aiMatrix[l_iH, l_iK - 1]);
		}

		static List<int[]> MakePattern(List<int[]> a_List)
		{
			List<int[]> l_lResult = new List<int[]>();
			if (a_List == null)
			{
				l_lResult.Add(new int[] { 0 });
				l_lResult.Add(new int[] { 1 });
				return l_lResult;
			}
			int[] l_aiDst;
			foreach (int[] l_aiSrc in a_List)
			{
				l_aiDst = new int[l_aiSrc.Length + 1];
				l_aiSrc.CopyTo(l_aiDst, 1);
				l_lResult.Add(l_aiDst);
				if (l_aiSrc[0] == 0)
				{
					l_aiDst = new int[l_aiSrc.Length + 1];
					l_aiSrc.CopyTo(l_aiDst, 1);
					l_aiDst[0] = 1;
					l_lResult.Add(l_aiDst);
				}
			}
			return l_lResult;
		}
	}
}

