        /// O(HW)
        /// </summary>
        private static void NumberOfAmidakuji3()
        {
            int[] input = ReadIntArray();
            int H = input[0];
            int W = input[1];
            int K = input[2];

            int[] fib = new int[9];
            fib[0] = 1;
            fib[1] = 1;
            for (int i = 2; i < 9; i++)
            {
                fib[i] = fib[i - 1] + fib[i - 2];
            }

            long[,] dp = new long[H + 1, W + 1];

            dp[0, 1] = 1;

            for (int i = 0; i < H; i++)
            {
                for (int j = 1; j <= W; j++)
                {
                    // 左に移動
                    if (j >= 2)
                        ModAdd(ref dp[i + 1, j - 1], (fib[j - 2] * fib[W - j]) * dp[i, j]);

                    // 右に移動
                    if (j <= W - 1)
                        ModAdd(ref dp[i + 1, j + 1], (fib[j - 1] * fib[W - j - 1]) * dp[i, j]);

                    // そのまま下に移動
                    ModAdd(ref dp[i + 1, j], (fib[j - 1] * fib[W - j]) * dp[i, j]);
                }
            }

            long ans = dp[H, K];
            WriteLine(ans);
        }

        /// <summary>
        /// ビット全探索
        /// O(HW2^W)
        /// </summary>
        private static void NumberOfAmidakuji2()
        {
            int[] input = ReadIntArray();
            int H = input[0];
            int W = input[1];
            int K = input[2];

            long[,] dp = new long[H + 1, W];

            dp[0, 0] = 1;

            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    int keta = W - 1;
                    int maxBit = 1 << keta;
                    for (int bit = 0; bit < maxBit; bit++)
                    {
                        for (int k = 0; k < keta - 1; k++)
                        {
                            // 横棒が連続していたら飛ばす
                            if (((bit & (1 << k)) > 0) &&
                                ((bit & (1 << (k + 1))) > 0))
                            {
                                goto CONTINUE;
                            }
                        }

                        int nj = j;
                        if ((bit & (1 << j)) > 0)
                            nj++;
                        else if ((j > 0) &&
                                 ((bit & (1 << (j - 1))) > 0))
                            nj--;

                        ModAdd(ref dp[i + 1, nj], dp[i, j]);

                    CONTINUE:;
                    }
                }
            }

            long ans = dp[H, K - 1];
            WriteLine(ans);
        }

