namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }

        static long Solve(int H, int W, int K)
        {
            const int M = 1000000007;
            var counts = new int[W][];
            for (int i = 0; i < W; ++i) { counts[i] = new int[W]; }
            for (int i = 0; i < (1 << (W - 1)); ++i)
            {
                bool valid = true;
                for (int j = 0; j < W - 1; ++j)
                {
                    int mask = 3 << j;
                    if ((i & mask) == mask) { valid = false; }
                }
                if (valid)
                {
                    for (int j = 0; j < W; ++j)
                    {
                        int L = (j - 1 >= 0) ? 1 << (j - 1) : 0;
                        int R = (j < W - 1) ? 1 << j : 0;
                        if ((i & L) != 0)
                        {
                            ++counts[j][j - 1];
                        }
                        else if ((i & R) != 0)
                        {
                            ++counts[j][j + 1];
                        }
                        else
                        {
                            ++counts[j][j];
                        }
                    }
                }
            }
            var sum1 = new long[W];
            sum1[0] = 1;
            for (int i = 0; i < H; ++i)
            {
                var sum2 = new long[W];
                for (int j = 0; j < W; ++j)
                {
                    for (int k = 0; k < W; ++k)
                    {
                        sum2[k] += (sum1[j] * counts[j][k]) % M;
                        sum2[k] %= M;
                    }
                }
                sum1 = sum2;
            }
            return sum1[K - 1];
        }
        static void Main(string[] args)
        {
            var V = ReadInts();
            Console.WriteLine(Solve(V[0], V[1], V[2]));
        }
    }
}

