    bool chmin<T>(ref T a, T b) where T : IComparable<T> { if (b.CompareTo(a) < 0) { a = b; return true; } return false; }

    void solve()
    {
        int H = cin.nextint;
        int W = cin.nextint;
        int K = cin.nextint - 1;
        var C = new int[W];
        var fact = 1;
        for (int i = 0; i < W; i++)
        {
            C[i] = i;
            fact *= i + 1;
        }
        var tmp = new Dictionary<int, List<int>>();
        for (int j = 0; j < fact; j++)
        {
            tmp[int.Parse(C.concat())] = new List<int>();
            next_permutation(C);
        }
        for (int j = 0; j < fact; j++)
        {
            for (int s = 0; s < 1 << (W - 1); s++)
            {
                bool before = false;
                var S = new int[W];
                C.CopyTo(S, 0);
                var ok = true;
                for (int k = 0; k < W - 1; k++)
                {
                    var mode = (s >> k & 1) == 1;
                    if (mode)
                    {
                        if (before)
                        {
                            ok = false;
                            continue;                           
                        }

                        swap(ref S[k], ref S[k + 1]);
                    }

                    before = mode;
                }
                if (ok)
