            else return Y.CompareTo(other.Y);
        }
    }


    Scanner cin;

    long mod = 1000000007;
    int H, W, K;

    void calc()
    {
        cin = new Scanner();


        H = cin.nextInt();
        W = cin.nextInt();
        K = cin.nextInt() - 1;

        dp = new long[H, W, W];
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                for (int k = 0; k < W; k++)
                {
                    dp[i, j, k] = -1;
                }
            }
        }

        Console.WriteLine(dfs(0, 0, 0));
    }

    long[,,] dp;

    //上からy、右からxまで引いてみた時に、今kにいるよってとこまで計算したやつ。
    long dfs(int y, int x, int k)
    {

        if(y >= H)
        {
            if (k == K) return 1;
            else return 0;
        }
        if(x >= W - 1)
        {
            return dfs(y + 1, 0, k);
        }

        if (dp[y, x, k] != -1) return dp[y, x, k];


        //上からy, 横からxで、右側に伸ばすか決める

        long ans = 0;

        //伸ばさない
        ans += dfs(y, x + 1, k);

        //伸ばす
        int nextk = k;
        if (x == k) nextk++;
        else if (x + 1 == k) nextk--;
        ans += dfs(y, x + 2, nextk);

        ans %= mod;

        dp[y, x, k] = ans;
        return ans;
    }

}




