        int mod = ModInt.SetModValue(1000000007);

        var mat = new ModMatrix(w, w);

        for (int b = 0; b < (1 << (w - 1)); b++) {
            if (!Check(b)) continue;
            var swapped = new bool[w];
            for (int j = 0; j < w - 1; j++) {
                if ((b & (1 << j)) != 0) { // swap j and j+1
                    mat[j, j + 1]++;
                    mat[j + 1, j]++;
