public struct ModInt : IEquatable<ModInt> {
    private static int mod = 0;
    private long _value;

    public ModInt(long x) {
        _value = x;
        Normalize();
    }

    private static long RegularMod(long x, int mod) {
        if (x >= mod) {
            if (x < 2 * mod) {
                return x - mod;
            }

            return x % mod;
        }
        if (x >= 0) {
            return x;
        }

        x = mod - RegularMod(-x, mod);
        if (x == mod) {
            return 0;
        }

        return x;
    }

    public static int SetModValue(int m) {
        return mod = m;
    }

    private void Normalize() {
        _value = RegularMod(_value, mod);
    }

    public override string ToString() {
        return _value.ToString(CultureInfo.InvariantCulture);
    }

    public int ToInt() {
        return (int)_value;
    }

    public static bool operator ==(ModInt c1, ModInt c2) {
        return c1._value == c2._value;
    }

    public static bool operator !=(ModInt c1, ModInt c2) {
        return !(c1 == c2);
    }

    public static ModInt operator +(ModInt x, ModInt y) {
        return new ModInt(x._value + y._value);
    }
    public static ModInt operator -(ModInt x, ModInt y) {
        return new ModInt(x._value - y._value);
    }
    public static ModInt operator -(ModInt x) {
        return new ModInt(-x._value);
    }
    public static ModInt operator *(ModInt x, ModInt y) {
        return new ModInt(x._value * y._value);
    }
    public static ModInt operator /(ModInt x, ModInt y) {
        return new ModInt(x._value * Inverse(y._value, mod));
    }
    public static ModInt operator ++(ModInt x) {
        return x + 1;
    }
    public static ModInt operator --(ModInt x) {
        return x - 1;
    }
    public static ModInt Pow(ModInt x, long n) {
        ModInt r = 1;
        while (n > 0) {
            if ((n & 1) != 0) {
                r *= x;
            }

            x *= x;
            n >>= 1;
        }
        return r;
    }
    private static long ExtendedGcd(long a, long b, ref long x, ref long y) {
        if (b == 0) {
            x = 1; y = 0;
            return a;
        } else {
            var d = ExtendedGcd(b, a % b, ref y, ref x);
            y -= a / b * x;
            return d;
        }
    }

    private static long Inverse(long a, long mod) {
        long x = 0, y = 0;
        if (ExtendedGcd(a, mod, ref x, ref y) == 1) {
            return (x + mod) % mod;
        } else {
            throw new Exception("Invalid inverse " + a + " " + mod);
        }
    }

    public static implicit operator ModInt(long x) {
        return new ModInt(x);
    }

    public override bool Equals(object obj) {
        if (obj == null) {
            return false;
        }
        return _value.Equals(((ModInt)obj)._value);
    }

    public override int GetHashCode() {
        return _value.GetHashCode();
    }

    public bool Equals(ModInt other) {
        return _value.Equals(other._value);
    }
}

public class ModMatrix {
    public int Row { get; private set; }
    public int Col { get; private set; }
    private ModInt[] Data;
    public ModMatrix(int row, int col) {
        Row = row;
        Col = col;
        Data = new ModInt[Row * Col];
    }

    public ModMatrix(ModInt[,] array)
        : this(array.GetLength(0), array.GetLength(1)) {
        var index = 0;
        for (var i = 0; i < Row; i++) {
            for (var j = 0; j < Col; j++) {
                Data[index++] = array[i, j];
            }
        }
    }

    public static ModMatrix TransposeFrom(IReadOnlyList<ModInt> list) {
        var count = list.Count;
        var result = new ModInt[count, 1];
        for (int i = 0; i < count; i++) {
            result[i, 0] = list[i];
        }
        return new ModMatrix(result);
    }

    public ModInt this[int row, int col] {
        set {
            Data[row * Col + col] = value;
        }
        get {
            return Data[row * Col + col];
        }
    }

    public static ModMatrix UnitMatrix(int n) {
        var matrix = new ModMatrix(n, n);
        for (var i = 0; i < n; i++) {
            matrix[i, i] = 1;
        }
        return matrix;
    }

    public static ModMatrix operator +(ModMatrix A, ModMatrix B) {
        var C = new ModMatrix(A.Row, A.Col);
        for (var i = 0; i < C.Data.Length; i++) {
            C.Data[i] = A.Data[i] + B.Data[i];
        }
        return C;
    }

    public static ModMatrix operator -(ModMatrix A, ModMatrix B) {
        var C = new ModMatrix(A.Row, A.Col);
        for (var i = 0; i < C.Data.Length; i++) {
            C.Data[i] = A.Data[i] - B.Data[i];
        }
        return C;
    }

    public static ModMatrix operator *(ModMatrix A, ModMatrix B) {
        var C = new ModMatrix(A.Row, B.Col);
        for (var i = 0; i < A.Row; i++) {
            for (var j = 0; j < B.Col; j++) {
                var val = C[i, j];
                for (var k = 0; k < A.Col; k++) {
                    val += A[i, k] * B[k, j];
                }
                C[i, j] = val;
            }
        }
        return C;
    }

    public static ModMatrix Pow(ModMatrix A, long n) {
        if (n == 0) {
            return UnitMatrix(A.Row);
        }

        if (n == 1) {
            return A;
        }

        ModMatrix result = A.Clone(), t = A.Clone(); n--;
        while (n > 0) {
            if ((n & 1) != 0) {
                result = result * t;
            }
            t = t * t;
            n >>= 1;
        }

        return result;
    }

    public ModMatrix Clone() {
        return new ModMatrix(Row, Col) { Data = Data.Clone() as ModInt[] };
    }

    private static void Swap<T>(ref T a, ref T b) { var t = a; a = b; b = t; }

    public static ModInt Determinant(ModMatrix matrix) {
        if (matrix.Row != matrix.Col) {
            throw new ArgumentException();
        }

        var n = matrix.Col;

        var m = new ModInt[n][];
        for (var i = 0; i < n; i++) {
            var r = new ModInt[n];
            for (var j = 0; j < n; j++) {
                r[j] = matrix[i, j];
            }
            m[i] = r;
        }

        ModInt d = 1;

        for (var i = 0; i < n; i++) {
            var targetRow = -1;
            ModInt pivot = 0;
            for (var r = i; r < n; r++) {
                var row = m[r];
                if (row[i] != 0) {
                    targetRow = r;
                    pivot = row[i];
                    break;
                }
            }
            if (targetRow == -1) {
                return 0;
            }

            if (i != targetRow) {
                Swap(ref m[i], ref m[targetRow]);
                d = -d;
            }
            d *= pivot;
            var mi = m[i];
            var invPivot = 1 / pivot;
            for (var r = i + 1; r < n; r++) {
                var row = m[r];
                var weight = row[i] * invPivot;
                if (weight == 0) continue;
                for (var k = i + 1; k < n; k++) {
                    row[k] -= weight * mi[k];
                }
            }
        }

        return d;
    }
}
