public class D
{
	public static void Main()
	{
		int H = GetInt();
		int W = GetInt();
		int K = GetInt();

		if(W == 1)
		{
			Console.WriteLine(1);
			return;
		}

		// hereafter, W >= 2
		long mod = 1000000007;
		long[,] A = new long[H+1, W+1];
		A[0, 1] = 1;
		for(int h = 0; h < H; h++)
		{
			for(int s = 0; s < (1 << (W-1)); s++)
			{
				if(!isCorrectAmida(W-1, s))
					continue;

				int t = s << 1;
				for(int w = 1; w <= W; w++)
				{
					if((w != 1) && ((t >> (w-1)) & 1) == 1)
					{
						A[h+1, w-1] = (A[h+1, w-1] + A[h, w]) % mod;
						continue;
					}

					if((w != W) && ((t >> w) & 1) == 1)
					{
						A[h+1, w+1] = (A[h+1, w+1] + A[h, w]) % mod;
						continue;
					}

					A[h+1, w] = (A[h+1, w] + A[h, w]) % mod;					
				}				
			}
		}

		Console.WriteLine(A[H,K]);
	}

	private static bool isCorrectAmida(int W, int s)
	{
		int t = s << 1;

		for(int i = 1; i <= W; i++)
		{
			if((((s >> i) & 1) & ((s >> (i + 1)) & 1)) == 1)
				return false;

			if((((s >> i) & 1) & ((s >> (i - 1)) & 1)) == 1)
				return false;
		}

		return true;
	}
}


