using System;
using System.Linq;
using System.Collections.Generic;

class Dmondai
{
    static void Main()
    {
        const long Mod= 1000000007;
        var line=Console.ReadLine().Split(' ').Select(x => Int32.Parse(x)).ToArray();
        var H = line[0];
        var W = line[1];
        var K = line[2];

        //縦棒が一つしかない場合は1
        if (W == 1) { Console.WriteLine(1); return; }

        //ビット探索
        //横の線のあるなしを全列挙する
        var bitList = new List<string>();
        for (int i=0;i<(1<<(W-1));++i)
        {
            //二進数に変換、
            var value=Convert.ToString((i), 2);
            //空いている桁は0埋めする
            var bit =value.PadLeft(W-1,'0');

            //横棒が二つ続いた場合、処理をスキップさせるためのフラグ
            var isContinue = true;

            //横棒が二つ続くことはないので、その場合を除く
            for (int j=0;j<W-2;++j)
            {
                if (bit[j] == '1' && bit[j + 1] == '1')
                {
                    isContinue = false;
                    break;
                }
            }

            //横棒が二つ続かないパターン（正当なあみだくじ）
            if (isContinue)
            {
                bitList.Add(bit);
            }
        }

        //ビットりすと内にある数を保存（横棒のパターン）
        //１を引いて後ですぐ使えるようにする
        long bitCount = bitList.Count()-1;

        //動的計画法
        //各ポイントにおいて何通りのパターンがあるかを保存し、
        //それを利用しつつ下へ下る
        //保存する器を用意
        //H横棒の数、いま行でどこにいるか、0～H-1
        //W横棒の数、いま列でどこにいるか、0～W-1
        var ansArray = new long[H+1,W];
        //行のループ
        for (int i=0;i<=H;++i)
        {
            //列のループ
            for (int j=0;j<W;++j)
            {
                if (i == 0)
                {
                    //0,0地点は始点＝1
                    if (j == 0) ansArray[i, j] = 1;
                    else ansArray[i, j] = 0;
                }
                //横棒が0のとき
                else if (j==0)
                {
                    var temp = ansArray[i - 1, j] * bitCount % Mod;
                    temp = (temp + ansArray[i - 1, j + 1]) % Mod;
                    ansArray[i, j] = temp;

                }
                //横棒がW-1のとき（一番右端）
                else if (j == W - 1)
                {
                    var temp = ansArray[i - 1, j] * bitCount % Mod;
                    temp = (temp + ansArray[i - 1, j - 1]) % Mod;
                    ansArray[i, j] = temp;
                }
                //それ以外
                else
                {
                    var temp = (ansArray[i - 1, j] + ansArray[i - 1, j - 1] + ansArray[i - 1, j + 1]) % Mod ;
                    ansArray[i, j] = temp;
                }
            }
        }
        Console.WriteLine(ansArray[H,K-1]);

    }
}

