        Out.Flush();
    }
    readonly Scanner cin = new Scanner();
    readonly int[] dd = { 0, 1, 0, -1, 0 }; //→↓←↑
    readonly int mod = 1000000007;
    readonly int dom = 998244353;
    bool chmax<T>(ref T a, T b) where T : IComparable<T> { if (a.CompareTo(b) < 0) { a = b; return true; } return false; }
    bool chmin<T>(ref T a, T b) where T : IComparable<T> { if (b.CompareTo(a) < 0) { a = b; return true; } return false; }

    void solve()
    {
        int H = cin.nextint;
        int W = cin.nextint;
        int K = cin.nextint - 1;

        var L = new List<int>();
        for (int s = 0; s < 1 << (W - 1); s++)
        {
            var ok = true;
            for (int k = 1; k < W - 1; k++)
            {
                var now = (s >> k & 1) == 1;
                var before = (s >> (k - 1) & 1) == 1;
                if (now && before)
                {
                    ok = false;
                }
            }
            if (ok)
            {
                L.Add(s);
            }
        }

        //i階でjにいる置き方
        var dp = new long[H + 1][];
        for (int i = 0; i < H + 1; i++)
        {
            dp[i] = new long[W];
        }
        dp[0][0] = 1;

        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                foreach (var s in L)
                {
                    int from = j;
                    if (0 <= j - 1 && (s >> (j - 1) & 1) == 1)
                    {
                        from = j - 1;
                    }
                    else if (j + 1 < W && (s >> j & 1) == 1)
                    {
                        from = j + 1;
                    }
                    dp[i + 1][j] += dp[i][from];
                }
                dp[i + 1][j] %= mod;
            }
        }
        WriteLine(dp[H][K]);
    }

}


