    class Program
    {
        static void Main(string[] args)
        {
            new Program().Solve(new ConsoleInput(Console.In, ' '));
        }

        public void Solve(ConsoleInput cin)
        {
            int h = cin.ReadInt;
            int w = cin.ReadInt;
            int k = cin.ReadInt;

            long result = calc(h, w, 1, k);

            Console.WriteLine(result % 1000000007);
        }

        public long calc(int h, int w, int s, int k)
        {

            if (s == 0 || k > w || Math.Abs(s - k) > h)
            {
                return 0;
            }
            else if (h == 1)
            {
                if (s < k)
                {
                    return calc2(s - 2) * calc2(w - k - 1);
                }
                else if (s > k)
                {
                    return calc2(k - 2) * calc2(w - s - 1);
                }
                else
                {
                    return calc2(s - 2) * calc2(w - s - 1);
                }
            }
            else
            {
                return calc(1, w, s, s - 1) * calc(h - 1, w, s - 1, k)
                    + calc(1, w, s, s) * calc(h - 1, w, s, k)
                    + calc(1, w, s, s + 1) * calc(h - 1, w, s + 1, k);
            }
        }

        public long calc2(int i)
        {
            switch (i)
            {
                case 1:
                    return 2;
                case 2:
                    return 3;
                case 3:
                    return 5;
                case 4:
                    return 8;
                case 5:
                    return 13;
                case 6:
                    return 21;
                default:
                    return 1;
            }
        }
    }

