namespace D
{
    class Program
    {
        static void Main(string[] args)
        {
            int[] In = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            int h = In[0];//横線が引ける段
            int w = In[1];//本数
            int e = In[2];//終点
            var Dp = new long[h+1, w];
            //最初は左の棒(0)からスタートし、二本目(1)に移動する
            Dp[0, 0] = 1;
            if (w > 1)
            {
                for (int i = 1; i < w; i++)
                {
                    Dp[0, i] = 0;
                }
            }
            int mod=1000000007;
            //左の棒に行く、とどまる、右の棒
            for(int i = 0; i < h; i++)
            {
                for(int j = 0; j < w; j++)
                {
                    //ある高さの横線の引き方は2^(w-1)
                    for(int k=0; k < 1 << (w - 1); k++)
                    {
                        //２連続で横線はダメ
                        bool ok = true;
                        for(int l = 0; l < w - 2; l++)
                        {
                            if(((k>>l) & 1)==1 && (((k >> (l + 1)) & 1)==1))
                            {
                                ok = false;
                            }
                        }
                        if (!ok) continue;
                        //左、下に行く
                        if(j>=1 && (((k >> (j - 1)) & 1) == 1))
                        {
                            Dp[i + 1, j - 1] += Dp[i, j];
                            Dp[i + 1, j - 1] %= mod;
                        }
                        //右、下に行く
                        else if(j<=w-2 && (((k >> j) & 1) == 1))
                        {
                            Dp[i + 1, j + 1] += Dp[i, j];
                            Dp[i + 1, j + 1] %= mod;
                        }
                        //そのまま下に行く
                        else
                        {
                            Dp[i + 1, j] += Dp[i, j];
                            Dp[i + 1, j] %=mod;
                        }
                    }
                }
            }
            Console.WriteLine(Dp[h, e - 1]);
        }
    }
}

