    public class Program
    {
        public object Calc()
        {
            var line = consoleReader.SplitInt32();
            var H = line[0];
            var W = line[1];
            var K = line[2];
            var dp = new long[H + 1, W + 1];

            dp[0, 1] = 1;

            for (int h = 1; h <= H; h++)
            {
                for (int w = 1; w <= W; w++)
                {
                    long left, right, center;

                    if (w - 1 <= 0) left = 0;
                    else if (w - 1 == 1 || w == W) left = honsu[W - 2] * dp[h - 1, w - 1];
                    else left = honsu[w - 2] * honsu[W - w] * dp[h - 1, w - 1];

                    if (w + 1 > W) right = 0;
                    else if (w + 1 == W || w == 1) right = honsu[W - 2] * dp[h - 1, w + 1];
                    else right = honsu[w - 1] * honsu[W - w - 1] * dp[h - 1, w + 1];

                    if (w == 1 || w == W) center = honsu[W - 1] * dp[h - 1, w];
                    else center = honsu[w - 1] * honsu[W - w] * dp[h - 1, w];

                    dp[h, w] = (left + center + right) % mod;
                }
            }

            return dp[H, K] ;
        }

        static long[] honsu = new long[9];
        static Program()
        {
            honsu[0] = honsu[1] = 1;
            long prev = honsu[2] = 2;
            long rightEmpty = 1;
            for (int l = 3; l <= 8; l++)
            {
                honsu[l] = prev + rightEmpty;
                rightEmpty = prev;
                prev = honsu[l];
            }
        }

        public const int mod = 1000000007;
        private readonly ConsoleReader consoleReader;
        public Program() : this(new ConsoleReader()) { }
        public Program(ConsoleReader consoleReader) { this.consoleReader = consoleReader; }
        static void Main() => Console.WriteLine(new Program().Calc());
        public static string MultiLine<T>(IEnumerable<T> source) => string.Join("\n", source);
    }

