const mod int = 1e9 + 7

func main() {
	var h, w, k int
	fmt.Scan(&h, &w, &k)

	dp := [101][8]int{}
	dp[0][0] = 1

	for i := 0; i < h; i++ {
		for bits := 0; bits < 1<<(w-1); bits++ {
			ls := fmt.Sprintf("%0"+strconv.Itoa(w-1)+"b", bits)
			if strings.Contains(ls, "11") {
				continue
			}
			for j := 0; j < w; j++ {
				if 1 <= j && ls[j-1] == '1' {
					dp[i+1][j-1] += dp[i][j]
					dp[i+1][j-1] %= mod
				} else if j < len(ls) && ls[j] == '1' {
					dp[i+1][j+1] += dp[i][j]
					dp[i+1][j+1] %= mod
				} else {
					dp[i+1][j] += dp[i][j]
					dp[i+1][j] %= mod
				}
			}
		}
	}

	fmt.Println(dp[h][k-1])
}

