	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	var H, W, K int
	fmt.Sscanf(scanner.Text(), "%d %d %d", &H, &W, &K)

	var dp [][]int
	dp = make([][]int, H+1)
	for i := 0; i < len(dp); i++ {
		dp[i] = make([]int, W+1)
	}

	dp[0][1] = 1
	for h := 0; h < H; h++ {
		for w := 1; w <= W; w++ {
			if dp[h][w] == 0 {
				continue
			}
			// no
			dp[h+1][w] = (dp[h+1][w] + dp[h][w]*allComb(w-2)*allComb(W-w-1)) % 1000000007

			if w > 1 {
				// left
				dp[h+1][w-1] = (dp[h+1][w-1] + dp[h][w]*allComb(w-3)*allComb(W-w-1)) % 1000000007
			}
			if w < W {
				// right
				dp[h+1][w+1] = (dp[h+1][w+1] + dp[h][w]*allComb(w-2)*allComb(W-w-2)) % 1000000007
			}
		}
	}

	for i := 1; i <= H; i++ {
		fmt.Print(i, " : ")
		for k := 1; k <= W; k++ {
			fmt.Print(dp[i][k], ",")
		}
		fmt.Println()
	}

	fmt.Println(dp[H][K])
}

func allComb(size int) int {
	if size < 0 {
		return 1
	}
	if size == 0 {
		return 1
	}
	if size == 1 {
		return 2
	}
	a := allComb(size - 2)
	b := allComb(size - 1)
	return a + b
}

