func main() {
	defer wr.Flush()
	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, 10000), 1001001)

	h := scanInt()
	w := scanInt()
	k := scanInt() - 1

	cnt := make([]int, w+1)
	for i := 1; i <= w; i++ {
		bitExhaustiveSearch(i, func(arr []bool) {
			f := true
			for j := 0; j < i-1; j++ {
				if arr[j] && arr[j+1] {
					f = false
				}
			}
			if f {
				cnt[i]++
			}
		})
	}

	cnt[0] = 1

	memo := make([][]int, h+1)
	for i := 0; i < h+1; i++ {
		memo[i] = make([]int, w)
		for j := 0; j < w; j++ {
			memo[i][j] = -1
		}
	}
	for i := 0; i < w; i++ {
		memo[h][i] = 0
	}
	memo[h][k] = 1

	var dfs func(y, x int) int
	dfs = func(y, x int) int {
		if memo[y][x] != -1 {
			return memo[y][x]
		}
		res := 0
		res += dfs(y+1, x) * (cnt[max(0, x-1)] * cnt[max(0, w-2-x)] % mod) % mod
		if x > 0 {
			res += dfs(y+1, x-1) * (cnt[max(0, x-2)] * cnt[max(0, w-2-x)] % mod) % mod
		}
		if x < w-1 {
			res += dfs(y+1, x+1) * (cnt[max(0, x-1)] * cnt[max(0, w-3-x)] % mod) % mod
		}
		res %= mod
		memo[y][x] = res
		return res
	}

	fmt.Fprintln(wr, dfs(0, 0))
}

const mod = 1000000007

func bitExhaustiveSearch(n int, fn func(a []bool)) {
	all := 1 << uint(n)
	a := make([]bool, n)
	for i := 0; i < all; i++ {
		for j := 0; j < n; j++ {
			if i>>uint(j)&1 == 1 {
				a[j] = true
			} else {
				a[j] = false
			}
		}
		fn(a)
	}
}

