func getNextLine(scanner *bufio.Reader) string {
	var buffer string
	for {
		line, isPrefix, _ := scanner.ReadLine()
		buffer += string(line)
		if isPrefix == false {
			break
		}
	}
	return buffer
}

func getIntList(scanner *bufio.Reader) []int {
	list := strings.Split(getNextLine(scanner), " ")
	l := len(list)
	result := make([]int, l)
	for i := 0; i < l; i++ {
		result[i], _ = strconv.Atoi(list[i])
	}
	return result
}

func mint(a int) int {
	return (a + 1000000007) % 1000000007
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := bufio.NewReader(fp)

	var h, w, k int

	fmt.Sscan(getNextLine(scanner), &h, &w, &k)
	dp := make([][]int, 2)
	prev, current := 0, 1
	for i := 0; i < 2; i++ {
		dp[i] = make([]int, w+2)
	}
	dp[prev][1] = 1
	for i := 0; i < h; i++ {
		for lw := 1; lw <= w; lw++ {
			dp[current][lw] = 0
			for j := 0; j < 1<<uint(w-1); j++ {
				if w > 2 {
					nextTo := false
					for bits := 3; bits < 1<<uint(w-1); bits <<= 1 {
						nextTo = nextTo || (bits&j) == bits
					}
					if nextTo {
						continue
					}
				}
				x1, x2, x3 := 1, 1, 1
				if lw == 1 {
					if (1 << uint(w-lw-1) & j) > 0 {
						x2 = 0
					} else {
						x3 = 0
					}
				} else if lw == w {
					if (1 << uint(w-lw) & j) > 0 {
						x2 = 0
					} else {
						x1 = 0
					}
				} else {
					if (1 << uint(w-lw-1) & j) > 0 {
						x2 = 0
					} else {
						x3 = 0
					}
					if (1 << uint(w-lw) & j) > 0 {
						x2 = 0
					} else {
						x1 = 0
					}
				}
				if w == 1 {
					x1 = 0
					x3 = 0
				}
				dp[current][lw] += dp[prev][lw-1] * x1
				dp[current][lw] += dp[prev][lw] * x2
				dp[current][lw] += dp[prev][lw+1] * x3
				dp[current][lw] = mint(dp[current][lw])
			}
		}
		prev, current = current, prev
	}
	fmt.Println(dp[prev][k])
}

