	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			for b := 0; b < 1<<uint(w-1); b++ {
				if !isOK(b) {
					continue
				}

				// 左へ
				if j >= 1 && NthBit(b, j-1) == 1 {
					dp[i+1][j-1] += dp[i][j]
					dp[i+1][j-1] %= MOD
				}

				// 右へ
				if j < w-1 && NthBit(b, j) == 1 {
					dp[i+1][j+1] += dp[i][j]
					dp[i+1][j+1] %= MOD
				}

				// 真下へ
				if ((j >= 1 && NthBit(b, j-1) == 0) && (j < w-1 && NthBit(b, j) == 0)) || (j == 0 && NthBit(b, 0) == 0) || (j == w-1 && NthBit(b, w-2) == 0) {
					dp[i+1][j] += dp[i][j]
					dp[i+1][j] %= MOD
				}
