	row, col := h, w-1
	amida := Ints2d(row, col)
	n2 := 1 << uint(row*col)

	cnt := 0
	for i := 0; i < n2; i++ {
		for j := 0; j < row*col; j++ {
			amida[j/col][j%col] = i >> uint(j) & 1
		}

		pos := 0
		flag := false
		for j := 0; j < row; j++ {
			for k := 0; k < col-1; k++ {
				if amida[j][k] == 1 && amida[j][k+1] == 1 {
					flag = true
					break
				}
			}
			if flag {
				continue
			}

			if pos < col && amida[j][pos] == 1 {
				pos++
			} else if pos > 0 && amida[j][pos-1] == 1 {
				pos--
			}
		}
		if flag {
			continue
		}
		if pos == k-1 {
			cnt++
		}
	}
	fmt.Println(cnt)
