		}
		return
	}
	var z [9][2]int64
	z[0][0] = 1
	z[0][1] = 1
	z[1][0] = 1
	z[1][1] = 1
	for i := range iter(2, 9) {
		z[i][0] = z[i-1][0] + z[i-1][1]
		z[i][1] = z[i-1][0]
	}

	var dp [101][8]int64
	dp[0][0] = 1
	for i := range iter(1, h+1) {
		for j := range iter(0, w) {
			l := z[j][0]
			r := z[w-j-1][0]
			dp[i][j] = (dp[i-1][j] * (l * r)) % m
		}
		for j := range iter(0, w-1) {
			l := z[j][0]
			r := z[w-j-2][0]
			dp[i][j] = (dp[i][j] + (l*r)*dp[i-1][j+1]) % m
			dp[i][j+1] = (dp[i][j+1] + (l*r)*dp[i-1][j]) % m
		}
	}
	fmt.Println(dp[h][k-1])
}

func iter(l int64, r int64) chan int64 {
	var i int64 = l
	c := make(chan int64)
	run := func() {
		for i < r {
			c <- i
			i += 1
		}
		close(c)
	}
	go run()
	return c
}

