func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	H, W, K := sc.nextInt(), sc.nextInt(), sc.nextInt()
	dp := make([][]int, H+1)
	for i := 0; i < H+1; i++ {
		dp[i] = make([]int, W)
	}
	dp[0][0] = 1
	for i := 0; i < H; i++ {
		for j := 0; j < W; j++ {
			var X, Y, Z int
			for bit := 0; bit < 1<<uint(W-1); bit++ {
				ok := true
				for k := 0; k < W-2; k++ {
					// 横棒が並んでいる場合
					if 1<<uint(k)&bit > 0 && 1<<uint(k+1)&bit > 0 {
						ok = false
					}
				}
				if !ok {
					continue
				}
				if j >= 1 && 1<<uint(j-1)&bit > 0 {
					X++
				}
				if 1<<uint(j-1)&bit == 0 && 1<<uint(j)&bit == 0 {
					Y++
				}
				if 1<<uint(j)&bit > 0 {
					Z++
				}
			}
			//fmt.Fprintln(wtr, i, j, X, Y, Z)
			if j >= 1 {
				dp[i+1][j-1] += X * dp[i][j] % MOD
				dp[i+1][j-1] %= MOD
			}
			dp[i+1][j] += Y * dp[i][j] % MOD
			dp[i+1][j] %= MOD
			if j+1 < W {
				dp[i+1][j+1] += Z * dp[i][j] % MOD
				dp[i+1][j+1] %= MOD
			}
		}
	}
	fmt.Fprintln(wtr, dp[H][K-1])
}

