func fibnatch(max int) []int {

	ret := make([]int, max+1)

	ret[0] = 1
	ret[1] = 1

	for i := 2; i < max+1; i++ {
		ret[i] = ret[i-1] + ret[i-2]
	}

	return ret
}

func add(a, b int) int {
	return (a + b) % 1000000007
}

func mul(a, b int) int {
	return (a * b) % 1000000007
}

func cacheKey(start, goal, height int) int {
	return height*100 + start*10 + goal
}

func calc(start, goal, height int) int {

	if goal < start {
		return calc(goal, start, height)
	}

	if height < goal-start {
		return 0
	}

	if height == 1 {
		if start == goal {
			return mul(fibs[start-1], fibs[w-start])
		} else {
			return mul(fibs[start-1], fibs[w-start-1])
		}
	}

	if c := cache[cacheKey(start, goal, height)]; 0 < c {
		return c
	}

	ret := mul(mul(fibs[start-1], fibs[w-start]), calc(start, goal, height-1))

	if 1 < start {
		tmp := mul(mul(fibs[start-2], fibs[w-start]), calc(start-1, goal, height-1))
		ret = add(tmp, ret)
	}

	if start < w {
		tmp := mul(mul(fibs[start-1], fibs[w-start-1]), calc(start+1, goal, height-1))
		ret = add(tmp, ret)
	}

	cache[cacheKey(start, goal, height)] = ret

	return ret
}

