func calc(h int, w int, k int) int {
	if w == 1 {
		return 1
	}
	mod := 1000000007
	f := []int{1, 1, 2, 3, 5, 8, 13, 21, 34}
	arr := make([][]int, h+1)
	for i := 0; i < h+1; i++ {
		arr[i] = make([]int, w)
	}
	arr[0][0] = 1
	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			right, left := 0, 0
			if j < w-1 {
				right = f[w-j-2] * f[j]
				arr[i+1][j+1] += (arr[i][j] * right) % mod
			}
			if 0 < j {
				left = f[w-j-1] * f[j-1]
				arr[i+1][j-1] += (arr[i][j] * left) % mod
			}
			center := f[w] - right - left
			arr[i+1][j] += (arr[i][j] * center) % mod
		}
	}
	return arr[h][k-1] % mod
}

