//横棒の配置を全探索する関数
func serch(w int) [][]int {
	var ls [][]int
	for i:=uint(0);i<uint(math.Pow(float64(2),float64(w)));i++{
		n := uint(1)
		c := make([]int,w)
		check := false
		for j:=0;j<w;j++{
			if i & n != uint(0){
				c[j] = 1
				if j >= 1{
					if  c[j] == c[j-1] {
						check = true
						break
					}
				}
			}
			n <<= 1
		}
		if check{continue}
		ls = append(ls,c)
	}
	return ls
}

