func main() {
	tmp := NextIntsLine()
	h, w, k = tmp[0], tmp[1], tmp[2]
	mod := 1000000007

	patterns := sub(w)
	dp[1][0] = 1
	for i := 1; i <= h; i++ {
		for j := 0; j < w; j++ {
			X, Y, Z := 0, 0, 0
			for _, p := range patterns {
				if isOKAsAmida(p) {
					if p[j] == 0 {
						Y++
					} else if j < w-1 && p[j] == 1 && p[j+1] == 1 {
						Z++
					} else if j > 0 && p[j] == 1 && p[j-1] == 1 {
						X++
					}
				}
			}

			if j-1 >= 0 {
				dp[i+1][j-1] += X * dp[i][j] % mod
				dp[i+1][j-1] %= mod
			}
			dp[i+1][j] += Y * dp[i][j] % mod
			dp[i+1][j] %= mod
			if j+1 < w {
				dp[i+1][j+1] += Z * dp[i][j] % mod
				dp[i+1][j+1] %= mod
			}
		}
	}

