bool isCont(int x) {
    int p = 0;

    while (x > 0) {
        if (p == 0) {
            p = x & 1;
            x >>= 1;
        }
        else {
            if (x & 1) {
                return true;
            }
            p = 0;
            x >>= 1;
        }
    }

    return false;
}


