# 横棒は 0-ordered (0, 1, ..., W - 1)

const p = 10 ^ 9 + 7

var (H, W, K) = readInts.unpack(3)
var dp = newSeqWith(H + 1, newSeq[int](W))

proc main: int =
  dp[0][0] = 1

  for h in 1..H:
    # 横棒の配置を 00...0 から 11...1 (< 100...0) まで全探索
    # bit[i] が 1 なら、 i から i + 1 に行く横棒がある
    for bit in 0..<(1 shl (W - 1)):
      var valid = true
      var ladder = newSeq[bool](W - 1)
      for i in 0..(W - 2):
        if ((bit shr i) and 1) == 1:
          ladder[i] = true
      for i in 0..(W - 3):
        if ladder[i] and ladder[i + 1]:
          valid = false
      if not valid:
        continue

      for i in 0..(W - 1):
        if i == 0:
          if ladder[i]:
            dp[h][i] = (dp[h][i] + dp[h - 1][i + 1]) mod p
          else:
            dp[h][i] = (dp[h][i] + dp[h - 1][i]) mod p
        elif i < W - 1:
          if ladder[i - 1]:
            dp[h][i] = (dp[h][i] + dp[h - 1][i - 1]) mod p
          elif ladder[i]:
            dp[h][i] = (dp[h][i] + dp[h - 1][i + 1]) mod p
          else:
            dp[h][i] = (dp[h][i] + dp[h - 1][i]) mod p
        else: # i == W - 1
          if ladder[i - 1]:
            dp[h][i] = (dp[h][i] + dp[h - 1][i - 1]) mod p
          else:
            dp[h][i] = (dp[h][i] + dp[h - 1][i]) mod p

  return dp[H][K - 1]

