def Map(X, Y, M):
    if Y == H:
        if X == K + 1:
            M.append((X - 1, 1))
            return Calc(M)
        if X == K:
            M.append((X, 0))
            return Calc(M)
        if X == K - 1:
            M.append((X, 1))
            return Calc(M)
        return 0

    XnM = M.copy()
    XnM.append((X, 0))
    result = Map(X, Y + 1, XnM)

    if X > 1:
        XmM = M.copy()
