class DP2D(object):

    def __init__(self, item_n: int, border: int, initializer: int = 0):
        self.item_n = item_n
        self.border = border
        self.table = [[initializer for _ in range(self.item_n + 1)] for _ in range(self.border + 1)]

    def __str__(self):
        return "\n".join(list(map(lambda l:
                                  " ".join(list(map(str, l)))
                                  , self.table)))

    def __repr__(self):
        return "DynamicProgramming object:\n" + \
               "item_n: " + str(self.item_n) + ", border: " + str(self.border) + "\n" + \
               "table:\n" + self.__str__()

    def solve(self, expr: callable) -> list:
        raise NotImplementedError

    def fill_0_idx_with(self, value: int) -> "DP2D":
        self.table[0] = [value for _ in range(self.item_n + 1)]
        for i in range(1, self.border + 1):
            self.table[i][0] = value
        return self


class BitDP2D(DP2D):
    def __init__(self, item_n: int, border: int, bit_n: int):
        super(BitDP2D, self).__init__(item_n, border)
        self.bit_n = bit_n

    def solve(self, expr: callable) -> list:
        for sbj_i in range(1, self.border+1):
            for bit in range(2 ** self.bit_n):

                for item_idx in range(1, self.item_n):
                    if (bit >> item_idx) & 1 and (bit >> (item_idx-1)) & 1:
                        break
                else:

                    for item_idx in range(1, self.item_n + 1):
                        if item_idx > 1 and (bit >> (item_idx-2)) & 1:  # from L
                            self.table[sbj_i][item_idx] += self.table[sbj_i - 1][item_idx - 1]
                            self.table[sbj_i][item_idx] %= MOD
                        elif (bit >> (item_idx-1)) & 1:  # from R
                            self.table[sbj_i][item_idx] += self.table[sbj_i - 1][item_idx + 1]
                            self.table[sbj_i][item_idx] %= MOD
                        else:  # from center
                            self.table[sbj_i][item_idx] += self.table[sbj_i - 1][item_idx]
                            self.table[sbj_i][item_idx] %= MOD
        return self.table


