FILL = [1, 2]
MOD = 1000000007

def fill_row(size):
  if size < 0 :
    return 0
  elif size < len(FILL):
    return FILL[size]
  else:
    res = (fill_row(size - 1) + fill_row(size - 2)) % MOD # ye its fibonacci
    FILL.append(res) # the other inds should be filled in by the other calls
    return res

def solve(poses, lines, dest):
  table = [[[None for _ in range(lines + 1)] for _ in range(lines + 1)] for _ in range(poses + 1)]

  def _solve_one(poses, curr, dest):
    if poses == 0: # no more rows left to move
      if curr == dest:
        return 1
      else:
        return 0
    elif poses == 1: # just one row left
      if curr == dest: # already in the right spot, no need to move
        return fill_row(curr - 1) + fill_row(lines - curr - 2) # |?|?| | |?|?|
      elif curr == dest - 1: # move one the the right
        return fill_row(curr - 1) + fill_row(lines - curr - 3) # |?|?| |-| |?|
      elif curr == dest + 1: # one to the left
        return fill_row(curr - 2) + fill_row(lines - curr - 2) # |?| |-| |?|?|
      else:
        return 0
    else:
      res = solve_one(poses - 1, curr, dest) * (fill_row(curr - 1) + fill_row(lines - curr - 2))
      if curr > 0:
        res += solve_one(poses - 1, curr - 1, dest) * (fill_row(curr - 2) + fill_row(lines - curr - 2))
      if curr < lines - 1:
        res += solve_one(poses - 1, curr + 1, dest) * (fill_row(curr - 1) + fill_row(lines - curr - 3))
      return res

  def solve_one(poses, curr, dest):
    if table[poses][curr][dest] is None:
      table[poses][curr][dest] = _solve_one(poses, curr, dest)
    return table[poses][curr][dest]

  return solve_one(poses, 0, dest)

