def func(H, W, K, y, x, v):
    if W == 1:
        return 1 if K == 0 else 0
    if y == H and x == 0:
        xx = 0
        for yy in range(H):
            if (yy, xx) in v:
                xx = xx + 1
            elif xx > 0 and (yy, xx - 1) in v:
                xx = xx - 1

        return 1 if xx == K else 0

    next_y, next_x = y, x + 1
    if next_x >= W - 1:
        next_y = next_y + 1
        next_x = 0

    result = func(H, W, K, next_y, next_x, v.copy())
    if not (x > 0 and (y, x - 1) in v):
        vv = v.copy()
        vv.update({(y, x): True})
        result += func(H, W, K, next_y, next_x, vv)

    return result % 1000000007


