import numpy as np
MOD = 1000000007

def phi(i, m):
    if (i > 0) and (m[i-1] == 1):
        return i-1
    elif (i < len(m)) and (m[i] == 1):
        return i+1
    else:
        return i

def ok(m):
    for i in range(len(m) - 1):
        if (m[i] == 1) and (m[i+1] == 1):
            return False
    return True

def solve(H, W, K):
    M = []
    for bitmask in range(2**(W-1)):
        m = []
        for w in range(W-1):
            m.append(bitmask % 2)
            bitmask /= 2
        M.append(m)
    M = filter(ok, M)
    dp = np.zeros((H+1, W), dtype=np.int64)
    dp[0, K-1] = 1
    for h in range(H):
        for i in range(W):
            for m in M:
                j = phi(i, m)
                dp[h+1, i] = (dp[h+1, i] + dp[h, j]) % MOD
    return dp[H, 0]

H, W, K = map(int, raw_input().split())
