def calc_bincount(w):
    bincount = {}
    for i in range(w - 1):
        bincount[i] = 2**i
        for j in range(2**i):
            while j:
                if j & 3 == 3:
                    bincount[i] -= 1
                    break
                j >>= 1
    bincount[-4] = bincount[-3] = bincount[-2] = bincount[-1] = 1
    return bincount


