import sys

def fib(n):
  if n == 0:
    return 1
  elif n == 1:
    return 1
  else:
    return fib(n-1) + fib(n-2)

def main():
  input = sys.stdin.readline
  H, W, K = map(int, input().split())
  DP = [[0 for _ in range(W)] for _ in range(H+1)]
  DP[0][0] = 1
  for i in range(H):
    for j in range(W):
      if (j-1) >= 0:
        X = fib(j-1) * fib(W-(j+1))
        DP[i+1][j-1] += X * DP[i][j]

      if (j+1) <= (W-1):
        Z = fib(j) * fib(W-(j+2))
        DP[i+1][j+1] += Z * DP[i][j]

      Y = fib(j) * fib(W-(j+1))
      DP[i+1][j] += Y * DP[i][j]

  print(DP[H][K-1] % (10**9 + 7))


