def serch(yokobou=[[None]*(W-1)],depth=0):
    queue = []
    for arrange in yokobou:
        for b in [0,1]:
            if b == 0:
                copy = arrange[:]
                copy[depth] = 0
                queue.append(copy)
            elif b == 1:
                copy = arrange[:]
                if depth == 0:
                    copy[depth] = 1
                elif arrange[depth-1] != 1:
                    copy[depth] = 1
                else:
                    continue
                queue.append(copy)
    yokobou = queue[:]
    if depth == W-2:
        return yokobou
    return serch(yokobou,depth+1)

def possibility(j):
    X,Y,Z = 0,0,0
    for e in serch():
        if j == 0:
            if e[j] == 1:
                Z += 1
            elif e[j] == 0:
                Y += 1
            continue
        elif j == W-1:
            if e[j-1] == 1:
                X += 1
            elif e[j-1] == 0:
                Y += 1 
            continue
        if e[j-1] == 1:
            X += 1
        if e[j] == 1:
            Z += 1
        if e[j-1] == 0 and e[j] == 0:
            Y += 1
    return (X,Y,Z)

