def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap



def C(n, r):
    c = 1
    for i in range(1, r+1):
        c *= n
        c //= i
        n -= 1

    return c

@mt
def slv(H, W, K):
    dp = [[0] * (W+2) for _ in range(H+1)]


    L = [0] * (W+2)
    C = [0] * (W+2)
    R = [0] * (W+2)
    for c in product(range(2), repeat=W-1):
        for i in range(W-2):
            if c[i] * c[i+1] != 0:
                break
        else:
            for j in range(1, W+1):
                if j != 1 and c[j-2] == 1:
                    L[j] += 1
                elif j != W and c[j-1] == 1:
                    R[j] += 1
                else:
                    C[j] += 1

    dp[0][1] = 1
    mod = 10**9 + 7
    for h in range(0, H):
        for w in range(1, W+1):
            dp[h+1][w-1] += dp[h][w] * L[w]
            dp[h+1][w-1] %= mod
            dp[h+1][w] += dp[h][w] * C[w]
            dp[h+1][w] %= mod
            dp[h+1][w+1] += dp[h][w] * R[w]
            dp[h+1][w+1] %= mod


    return dp[H][K]


