def amida_patterns(w):
    # (0, 1, 2, ... , w - 1) -> ?
    ret = list()
    for bars in itertools.product([0, 1], repeat=w-1):
        if sum([b * bb for b, bb in zip(bars[1:], bars[:-1])]) > 0:
            continue
        location = list(range(w))
        for i in range(w):
            if i > 0 and bars[i - 1] == 1:
                location[i] = i - 1
            elif i < w - 1 and bars[i] == 1:
                location[i] = i + 1
        ret.append(location)
    return ret


