            for x in range(0, W):
                if x == 0:
                    if s[x] == '0':
                        res[step][x] += res[step-1][x]
                    elif s[x] == '1':
                        res[step][x+1] += res[step-1][x]
                elif x == W-1:
                    if s[x-1] == '0':
                        res[step][x] += res[step-1][x]
                    elif s[x-1] == '1':
                        res[step][x-1] += res[step-1][x]
                else:
                    # right
                    if s[x] == '0' and s[x-1] == '0':
                        res[step][x] += res[step-1][x]
                    elif s[x] == '1':
