def compute_patterns(n):
    memo = {}
    def compute(n):
        if n in memo:
            return memo[n]
        if n == 2:
            return 2
        if n <= 1:
            return 1
        ret = compute(n-1) + compute(n-2)
        memo[n] = ret
        return ret
    return compute(n)


def gen_patterns(c, h, w, k):
    if h == 1:
        if c == k:
            yield [(c-1, w-c)]
        elif c+1 == k:
            yield [(c-1, w-c-1)]
        elif c-1 == k:
            yield [(c-2, w-c)]
        else:
            yield None
    else:
        for p in gen_patterns(c, h-1, w, k):
            if p is None:
                yield None
            else:
                yield [(c-1, w-c)] + p
        if c != 1:
            for p in gen_patterns(c-1, h-1, w, k):
                if p is None:
                    yield None
                else:
                    yield [(c-2, w-c)] + p
        if c != w:
            for p in gen_patterns(c+1, h-1, w, k):
                if p is None:
                    yield None
                else:
                    yield [(c-1, w-c-1)] + p


