def NegativeZero(x):
    if x<0:
        return 0
    else:
        return x

def MakePatternLeft(y):
    if y==0:
        return pow(2,0) 
    if y==1:
        return pow(2,0) 
    else:
        return pow(2,NegativeZero(y-2))

def MakePatternRight(z):
    if z==wide:
        return pow(2,0) 
    if z==wide-1:
        return pow(2,0) 
    else:
        return pow(2,NegativeZero(wide-z-1))


def amida(h,w,f):
    dp[h][w][2]=MakePatternLeft(w)*MakePatternRight(w)
    if f == 1: #go straight
        if h==high and w==end:
            dp[h][w][f]=1
        elif h==high:
            dp[h][w][f]=0
        else: #sum under
            if dp[h+1][w][1] == -1:
                amida(h+1,w,1)
            if dp[h+1][w][0] == -1:
                amida(h+1,w,0)
            dp[h][w][f]=(dp[h+1][w][0]+dp[h+1][w][1])*dp[h+1][w][2]
