# あみだくじとして妥当かの判定
def check(S):
    for i in range(W-1):
        # 1つでも隣り合う場所に横棒があればNG
        if S & 1<<i and S & 1<<(i+1):
            return False
    return True

# dp[i][S][j] := i段目まで見て、今の段の横棒の状態がSで、j本目の縦棒に行く通り数
dp = list3d(H+1, 1<<W, W+1, 0)
dp[0][0][1] = 1
for i in range(H):
    for S1 in range(1<<W):
        # 左端はただの番兵なので、立っていたらスキップ
        if S1 & 1:
            continue
        # あみだくじとして妥当でない集合は全てスキップ
        if not check(S1):
            continue
        for S2 in range(1<<W):
            if S2 & 1:
                continue
            if not check(S2):
                continue
            for j in range(1, W+1):
                # 左に棒があれば左に遷移
