def powmod(mat, n, mod):
    result = np.eye(len(mat), dtype=np.int64)
    while n > 0:
        if n & 1:
            result = np.dot(result, mat) % mod
        mat = np.dot(mat, mat) % mod
        n >>= 1
    return result


