def amida(h,w,H,W,K,dp):
    j=0
    i=0
    k=0
    if h>=0 and dp[h][w]!=-1:
        return dp[h][w]
    else:
        if (W-3)>0:
            j=fibo(W-3)
            i=fibo(W-2)
        if (W-3)==0 and w!=W:
            i=2
        if w==W:
