            if w==1:
                if h==1:
                    dp[h][w]=k+i
                    return dp[h][w]
                elif h==0:
                    dp[h][w]=1
                    return dp[h][w]
                elif w==W:
                    dp[h][w]=amida(h-1,w,H,W,K,dp)
                    return dp[h][w]
                else:
                    dp[h][w]=amida(h-1,w,H,W,K,dp)+amida(h-1,w+1,H,W,K,dp)+i
                    return dp[h][w]
            elif w==W:
