        pub struct BufScanner<R: ::std::io::BufRead> {
            br: R,
            buf: Vec<u8>,
            pos: usize,
        }

        impl<R: ::std::io::BufRead> BufScanner<R> {
            pub fn new(br: R) -> Self {
                BufScanner {
                    br: br,
                    buf: Vec::new(),
                    pos: 0usize,
                }
            }
            fn fill_line(&mut self) {
                self.buf.clear();
                self.pos = 0;
                self.br
                    .read_until(b'\n', &mut self.buf)
                    .expect("Read a line");
                if let Some(&b'\n') = self.buf.last() {
                    self.buf.pop();
                    if let Some(&b'\r') = self.buf.last() {
                        self.buf.pop();
                    }
                }
            }
            fn skip_space(&mut self) {
                loop {
                    for i in self.pos..self.buf.len() {
                        if self.buf[i] != b' ' {
                            self.pos = i;
                            return;
                        }
                    }
                    self.fill_line();
                }
            }
            pub fn read_token(&mut self) -> &str {
                self.skip_space();
                let start = self.pos;
                while self.pos < self.buf.len() && self.buf[self.pos] != b' ' {
                    self.pos += 1;
                }
                let ret = unsafe { ::std::str::from_utf8_unchecked(&self.buf[start..self.pos]) };
                self.pos += 1; // skip the last space (or len() + 1 which is fine)
                return ret;
            }
            pub fn next<T: ::std::str::FromStr>(&mut self) -> T {
                self.read_token().parse::<T>().ok().expect("Parse")
            }
        }
    }
