fn main() {
	let mut stdin = String::new();
    std::io::Read::read_to_string(
    	&mut std::io::stdin(),
        &mut stdin).unwrap();
	let mut stdin = stdin.split_whitespace();
    let mut get = || stdin.next().unwrap();
    macro_rules! get {
    	($t:ty) => (get().parse::<$t>().unwrap());
        () => (get!(i64));
    }

    let h = get!(usize);
    let w = get!(usize);
    let k = get!(usize);

    // use std::collections::HashMap;
    let md = 1_000_000_007;
    let mut dp = vec![0_i64; w];

    let mut tb = vec![];
    for i in 0..(1<<(w-1)) {
        let mut ok = true;
        for j in 0..w {
            let v = 3 << j;
            if i & v == v {
                ok = false;
                break;
            }
        }
        if ok {
            tb.push(i);
            // for j in 0..w { print!("{}", (i>>j)&1); }
            // println!();

        }
    }

    dp[0] = 1;
    for _ in 0..h {
    	let mut tmp = vec![0; w];
        for i in 0..w {
        	if 0 < i && i+1 < w {
                let mut c = 0;
                let b = 3 << (i-1);
                for &t in tb.iter() {
                    if t&b==0 { c += 1; }
                }
            	let e = dp[i]*c%md;
        		tmp[i] = (tmp[i]+e) % md;
            } else {
                let mut c = 0;
                let b = if i==0 { 1 } else { 1<<(i-1) };
                for &t in tb.iter() {
                    if t&b==0 { c += 1; }
                }
            	let e = dp[i]*c%md;
        		tmp[i] = (tmp[i]+e) % md;
            }
            if i+1 < w {
            	if i==0 || i+2==w {
                    let mut c = 0;
                    let b = if i==0 { 3 } else { 3 << (i-1) };
                    let v = if i==0 { 1 } else { 2 << (i-1) };
                    for &t in tb.iter() {
                        if t & b == v { c += 1; }
                    }
	            	let e = dp[i] * c % md;
    	    		tmp[i+1] = (tmp[i+1]+e) % md;
                } else {
                    let mut c = 0;
                    let b = 7 << (i-1);
                    let v = 2 << (i-1);
                    for &t in tb.iter() {
                        if t&b==v { c += 1; }
                    }
                  	let e = dp[i]*c%md;
                  	tmp[i+1] = (tmp[i+1]+e) % md;
                }
            }
            if i > 0 {
            	if i==1 || i+1==w {
                    let mut c = 0;
                    let b = if i==1 { 3 } else { 3 << (i-1) };
                    let v = if i==1 { 1 } else { 1 << (i-1) };
                    for &t in tb.iter() {
                        if t&b==v { c += 1; }
                    }
	            	let e = dp[i]*c%md;
    	    		tmp[i-1] = (tmp[i-1]+e) % md;
                } else {
                    let mut c = 0;
                    let b = 7 << (i-2);
                    let v = 2 << (i-2);
                    for &t in tb.iter() {
                        if t&b==v { c += 1; }
                    }
                  	let e = dp[i]*c%md;
                  	tmp[i-1] = (tmp[i-1]+e) % md;
                }
            }
        }
        dp = tmp;
        // println!("{:?}", dp);
    }
    println!("{}", dp[k-1]);

}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input!{
        h: usize,    // 縦棒の長さ - 1
        w: usize,    // 縦棒の本数
        k: usize,    // 最終的に辿り着かなければならない縦棒は左から何番目か
    }

    let m = 1_000_000_007;

    // a[h][x] h = 上からh列目を通過した直後, x = 左からx番目の縦棒にいる
    // その場合の数
    let mut a = [[0u64; 1000]; 1000];

    a[0][0] = 1;

    for h in 1..(h+1) {
        for bars in 0u8..(1 << (w-1)) {
            // 連結があるならスキップ
            if bars & (bars << 1) != 0 {
                continue;
            }

            for x in 0..w {
                let left = x > 0 && (bars & (1 << (x-1)) != 0);
                let right = x < w-1 && (bars & (1 << x) != 0);

                // println!("h = {}, x = {}", h, x);
                // println!("bar = {:b}, left = {}, right = {}", bars, left, right);
                // 左へ行くか
                if left {
                    a[h][x-1] += a[h-1][x];
                    a[h][x-1] %= m;
                }
                // 右へ行くか
                else if right {
                    a[h][x+1] += a[h-1][x];
                    a[h][x+1] %= m;
                }
                // まっすぐ降りるか
                else {
                    a[h][x] += a[h-1][x];
                    a[h][x] %= m;
                }

                // for x in 0..w {
                    // print!("{} ", a[h][x]);
                // }
                // println!("");

            }
        }

        // println!("h = {}, result ...", h);
        // for x in 0..w {
            // print!("{} ", a[h][x]);
        // }
        // println!("");
    }

    println!("{}", a[h][k-1] % m);
}

