const MOD: i64 = 1_000_000_007_i64;
fn main() {
    input! {
       H:usize,W:usize,K:Usize1
    }
    if W == 1 {
        println!("1");
        return;
    }
    // ある高さhで、 wとw+1の間を移動した時、
    // 0..w-1の間とw+2..Wの間の棒の存在は自由。
    // 同様に、移動しなかった時
    // 0..w-1の間とw+1..Wの間の棒の存在は自由
    // 縦棒は高々8本。
    let mut free_bars = HashMap::new();
    let fib = |x| match x {
        0 => 1,
        1 => 1,
        2 => 2,
        3 => 3,
        4 => 5,
        5 => 8,
        6 => 13,
        7 => 21,
        8 => 34,
        _ => 1,
    };
    for w in 0..W {
        // w -> w
        free_bars.insert((w, w), fib(w) * fib(W - w - 1));
        if w < W - 1 {
            free_bars.insert((w, w + 1), fib(w) * fib(W - w - 2));
        }
    }
    // 以上、準備
    // 縦棒がW本なので、隙間はW-1かしょ。
    // 上から h cm の位置で、移動前後の位置をペアで表す。
    // H回の遷移で、0からKまで移動する必要がある。
    let mut mv = vec![(0, 0); H];
    // 通過するバーを下記のように表す。
    let mut l = vec![vec![0; W]; H];
    // h 回目の移動後に位置wにいるパターン数をdpとする。
    let mut dp = vec![vec![0; W]; H];
    dp[0][0] = *free_bars.get(&(0, 0)).unwrap();
    dp[0][1] = *free_bars.get(&(0, 1)).unwrap();
    for h in 1..H {
        for w in 0..W {
            if w > 0 {
                dp[h][w] += dp[h - 1][w - 1] * *free_bars.get(&(w - 1, w)).unwrap();
            }
            dp[h][w] += dp[h - 1][w] * *free_bars.get(&(w, w)).unwrap();
            if w < W - 1 {
                dp[h][w] += dp[h - 1][w + 1] * *free_bars.get(&(w, w + 1)).unwrap();
            }
            dp[h][w] = dp[h][w] % MOD;
        }
    }
    //println!("{:?}", dp);
    println!("{}", dp[H - 1][K]);
}

