fn main() {
    let h = input::<usize>();
    let w = input::<usize>();
    let k = input::<usize>();
    const MOD: usize = 1000000007;

    let mut dp = vec![vec![0; w as usize + 1]; h as usize + 1];
    dp[0][1] = 1;
    for i in 0..h {
        for j in 1..w + 1 {
            for k in 0..1 << (w - 1) {
                if w > 1 {
                    let mut ok = true;
                    for l in 0..w - 2 {
                        if k & (1 << l) > 0 && k & (1 << (l + 1)) > 0 {
                            ok = false;
                        }
                    }
                    if !ok {
                        continue;
                    }
                }

                if j > 1 && k & (1 << (j - 2)) > 0 {
                    dp[i + 1][j - 1] += dp[i][j];
                    dp[i + 1][j - 1] %= MOD;
                } else if j < w && k & (1 << j - 1) > 0 {
                    dp[i + 1][j + 1] += dp[i][j];
                    dp[i + 1][j + 1] %= MOD;
                } else {
                    dp[i + 1][j] += dp[i][j];
                    dp[i + 1][j] %= MOD;
                }
            }
        }
    }
    let ans = dp[h][k];
    println!("{}", ans);
}

