fn solve() {
    let (h, w, k) = get!(usize, usize, usize);

    if w == 1 {
        println!("1");
        return;
    }

    let mo = 1_000_000_007;

    let mut dp = vec![vec![0u64; w]; h+1];
    dp[0][0] = 1;

    for row in 0..h {
        for col in 0..w {
            let mut l = 0;
            let mut r = 0;
            let mut n = 0;
            for pat in 0..(1<<(w-1)) {
                let mut tmp = pat;
                let mut flag = false;
                while tmp > 0 {
                    flag = tmp % 2 == 1 && (tmp/2) % 2 == 1;
                    if flag {
                        break;
                    }
                    tmp >>= 1;
                }
                if flag {
                    continue;
                }
                if col == 0 {
                    if pat % 2 == 1 {
                        r += 1;
                    } else {
                        n += 1;
                    }
                } else if (pat >> col) % 2 == 1 {
                    r += 1;
                } else if (pat >> (col-1)) % 2 == 1 {
                    l += 1;
                } else {
                    n += 1;
                }
            }
            dp[row+1][col] += n * dp[row][col];
            dp[row+1][col] %= mo;
            if col >  0  && col < w-1 {
                dp[row+1][col-1] += l * dp[row][col];
                dp[row+1][col+1] += r * dp[row][col];
                dp[row+1][col-1] %= mo;
                dp[row+1][col+1] %= mo;
            } else if col == 0 {
                dp[row+1][col+1] += r * dp[row][col];
                dp[row+1][col+1] %= mo;
            } else {
                dp[row+1][col-1] += l *  dp[row][col];
                dp[row+1][col-1] %= mo;
            }
        }
    }
    println!("{}", dp[h][k-1]);
}

