fn f(bit: usize, w: u32) -> bool {
    for i in 0..w - 2 {
        let a = 2_usize.pow(w - 2 - i);
        let b = 2_usize.pow(w - 2 - i - 1);
        if bit & a == a && bit & b == b {
            return false;
        }
    }
    true
}

