use std::io;
use std::str::FromStr;
use std::cmp::max;

static MOD: u64 = 1_000_000_007;

fn input_tuple() -> (usize, usize, usize) {
    let mut line: String = String::new();
    io::stdin().read_line(&mut line);
    let vec: Vec<usize> = line.split_whitespace().map(|s| s.parse().unwrap()).collect();
    (vec[0], vec[1], vec[2])
}

fn binary_power(x: u64, n: u64) -> u64 {
    if n == 0 {
      return 1;
    }
    if n % 2 == 0 {
      return (binary_power(x, n / 2) % MOD).pow(2) % MOD;
    } else {
      return binary_power(x, n - 1) % MOD * x % MOD;
    }
}

fn main() {
    let (h, w, k) = input_tuple();
    let mut dp = vec![vec![0; w]; h+1];
    dp[0][0] = 1;
    for i in 1..(h+1) {
        for j in 0..w {
            if j > 0 {
                let mut left = max(w as i64 - 2, 0);
                if j < w - 1 {
                    left = max(left - 1, 0);
                }
                if j > 1 {
                    left = max(left - 1, 0);
                }
                dp[i][j] += dp[i-1][j-1] * binary_power(2, left as u64);
                dp[i][j] %= MOD;
            }

            let mut left = max(w as i64 - 1, 0);
            if j > 0 {
                left = max(left - 1, 0);
            }
            if j < w - 1 {
                left = max(left - 1, 0);
            }
            dp[i][j] += dp[i-1][j] * binary_power(2, left as u64);
            dp[i][j] %= MOD;

            if j + 1 < w {
                let mut left = max(w as i64 - 2, 0);
                if j + 1 < w - 1 {
                    left = max(left - 1, 0);
                }
                if j + 1 > 1 {
                    left = max(left - 1, 0);
                }
                dp[i][j] += dp[i-1][j+1] * binary_power(2, left as u64);
                dp[i][j] %= MOD;
            }
        }
    }
    // println!("{:?}", dp);
    println!("{}", dp[h][k - 1]);
}

