#[allow(unused_imports)]
use std::cmp::{min, max};
const MOD : i64 = 1e9 as i64 + 7;

fn solve(h: usize, w: usize, k: usize, hi: usize, wi: usize, dp: &mut Vec<Vec<i64>>) -> i64 {
    // println!("{}-{}", hi, wi);
    if dp[hi][wi] != -1 {
        return dp[hi][wi];
    }

    let mut ans = solve(h, w, k, hi+1, wi, dp);
    assert!(wi >= 1 && wi <= w);
    // println!("{}-{} ans=>{}", hi+1, wi, ans);
    if wi == 1 || wi == w {
        let ww = max(((w as i64 -2) + 1), 1) as i64;
        // println!("{}-{} ans=>{} ww=>{}", hi+1, wi, ans, ww);
        ans = ans * ww % MOD;
    } else {
        let ww = max(((w as i64-3) + 1), 1) as i64;
        // println!("{}-{} ans=>{} ww=>{}", hi+1, wi, ans, ww);
        ans = ans * ww % MOD;
    }
    if wi > 1 { ans = (ans + solve(h, w, k, hi+1, wi - 1, dp)) % MOD; };
    if wi < w { ans = (ans + solve(h, w, k, hi+1, wi + 1, dp)) % MOD; };
    dp[hi][wi] = ans % MOD;
    // println!("{}-{} ans=>{}", hi, wi, ans);
    return ans % MOD;
}

fn main() {
    input!{
      h: usize,
      w: usize,
      k: usize,
    }
    // debug!(h, w, k);
    // println!("{}", "-------------");
    let mut dp = vec![vec![-1; w+1]; h+2];
    for i in 0..w+1 {
        dp[h+1][i] = 0;
    }
    dp[h+1][k] = 1;
    println!("{}", solve(h, w, k, 1, 1, &mut dp));
}

