pub const M: u64 = 1_000_000_007;

#[allow(dead_code)]
pub fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}
#[allow(dead_code)]
pub fn lcm(a: u64, b: u64) -> u64 {
    a / gcd(a, b) * b
}
#[allow(dead_code)]
pub fn extgcd(a: i64, b: i64) -> (i64, i64, i64) {
    if b == 0 {
        (a, 1, 0)
    } else {
        let (gcd, x, y) = extgcd(b, a % b);
        (gcd, y, x - (a / b) * y)
    }
}
#[allow(dead_code)]
pub fn mod_pow(x: u64, n: u64, m: u64) -> u64 {
    let mut res = 1;
    let mut x = x % m;
    let mut n = n;
    while n > 0 {
        if n & 1 == 1 {
            res = (res * x) % m;
        }
        x = (x * x) % m;
        n >>= 1;
    }
    res
}
#[allow(dead_code)]
pub fn mod_inverse(a: u64, m: u64) -> u64 {
    let (_, x, _) = extgcd(a as i64, m as i64);
    ((m as i64 + x) as u64 % m) % m
}
#[allow(dead_code)]
pub fn fact_table(len: usize, m: u64) -> Vec<u64> {
    let mut res = vec![1; len + 1];
    for i in 1..len + 1 {
        res[i] = (i as u64 * res[i - 1]) % m;
    }
    res
}
#[allow(dead_code)]
pub fn fact_inv_table(size: usize, m: u64) -> (Vec<u64>, Vec<u64>) {
    let mut fact = vec![1; size];
    let mut fact_inv = vec![1; size];
    for i in 2..size {
        fact[i] = fact[i - 1] * i as u64 % m;
        fact_inv[i] = m - ((m / i as u64) * fact_inv[(m % i as u64) as usize] % m);
    }
    for i in 1..size {
        fact_inv[i] = fact_inv[i - 1] * fact_inv[i] % m;
    }
    (fact, fact_inv)
}
#[allow(dead_code)]
pub fn mod_fact(n: u64, p: u64, fact: &[u64]) -> (u64, u64) {
    if n == 0 {
        (1, 0)
    } else {
        let (a, b) = mod_fact(n / p, p, fact);
        let pow = b + n / p;
        if n / p % 2 != 0 {
            (a * (p - fact[(n % p) as usize]) % p, pow)
        } else {
            (a * fact[(n % p) as usize] % p, pow)
        }
    }
}
#[allow(dead_code)]
pub fn mod_comb(n: u64, k: u64, p: u64, fact: &[u64]) -> u64 {
    if n < k {
        0
    } else {
        let (a1, e1) = mod_fact(n, p, fact);
        let (a2, e2) = mod_fact(k, p, fact);
        let (a3, e3) = mod_fact(n - k, p, fact);
        if e1 > e2 + e3 {
            0
        } else {
            a1 * mod_inverse(a2 * a3 % p, p) % p
        }
    }
}
#[allow(dead_code)]
pub fn mod_comb_repetition(n: u64, k: u64, p: u64, fact: &[u64]) -> u64 {
    mod_comb(n - 1 + k, n - 1, p, fact)
}

fn f(n: u64, cache: &mut [Option<u64>]) -> u64 {
    if n == 0 {
        return 1;
    }
    if n == 1 {
        return 2;
    }

    if let Some(res) = cache[n as usize] {
        return res;
    }

    let res = (f(n - 1, cache) + f(n - 2, cache)) % M;

    cache[n as usize] = Some(res);
    res
}

fn solve() {
    let (h, w, k) = get!(usize, usize, usize);

    let mut memo = vec![0; w];
    let mut cache = vec![None; w];
    memo[0] = 1;

    for _ in 0..h {
        let mut next = vec![0; w];
        for i in 0..w {
            let x = memo[i];
            let l = if i >= 1 {
                f(i as u64 - 1, &mut cache)
            } else {
                1
            };
            let r = if i + 2 < w {
                f(w as u64 - i as u64 - 2, &mut cache)
            } else {
                1
            };

            if i > 0 {
                let l = if i >= 2 {
                    f(i as u64 - 2, &mut cache)
                } else {
                    1
                };
                next[i - 1] += x * (l * r % M) % M;
                next[i - 1] %= M;
            }

            next[i] += x * (l * r % M) % M;
            next[i] %= M;

            if i + 1 < w {
                let r = if i + 3 < w {
                    f(w as u64 - i as u64 - 3, &mut cache)
                } else {
                    1
                };
                next[i + 1] += x * (l * r % M) % M;
                next[i + 1] %= M;
            }
        }
        memo = next;
    }

    println!("{}", memo[k - 1]);
}

