    let modulo: u64 = 1_000_000_007u64;

    let valid_horizontal: Vec<_> = (0..(1<<(w-1))).filter(|a| {
        (0..w).all(|i|{ 3 != ((a>>i)&3)})
    }).collect();
    let mut dp: Vec<u64> = vec![0u64; w];
    dp[0] = 1;
    for _ in 0..h {
        let mut qb: Vec<u64> = vec![0u64; w];
