use std::cmp::{min, max};
const MOD : usize = 1e9 as usize + 7;

fn solve(h: usize, w: usize, k: usize, hi: usize, wi: usize) -> usize {
    // println!("{}-{}", hi, wi);
    if hi == h+1 {
        // let a = if wi == k { 1 } else { 0};
        // println!("END {}-{} => {}", hi, wi, a);
        return if wi == k { 1 } else { 0};
    }
    let mut ans = solve(h, w, k, hi+1, wi);
    // println!("{}-{} ans=>{}", hi, wi, ans);
    if wi == 1 || wi == w {
        let ww = max(((w as i64 -2) + 1), 1) as usize;
        // println!("{}-{} ans=>{} ww=>{}", hi, wi, ans, ww);
        ans = ans * ww % MOD;
    } else {
        let ww = max(((w as i64-3) + 1), 1) as usize;
        // println!("{}-{} ans=>{} ww=>{}", hi, wi, ans, ww);
        ans = ans * ww % MOD;
    }
    if wi > 1 { ans = (ans + solve(h, w, k, hi+1, wi - 1)) % MOD; };
    if wi < w { ans = (ans + solve(h, w, k, hi+1, wi + 1)) % MOD; };
    return ans % MOD;
}

