fn count(intervals: i8) -> u64 {
    // fibonacci
    if intervals <= 0 { 1 } else { count(intervals - 1) + count(intervals - 2) }
}

use std::collections::HashMap;

fn solve(start: i8, goal: i8, h: i8, w: i8, memo: &mut HashMap<(i8, i8), u64>) -> u64 {
    if let Some(&ans) = memo.get(&(start, h)) {
        return ans;
    }

    let ans = if h == 0 {
        if start == goal { 1 } else { 0 }
    } else {
        let stay = count(start-1) * count((w-1) - (start+1)) * solve(start, goal, h-1, w, memo);
        let left = if start == 0 { 0 } else {
            count(start-2) * count((w-1) - (start+1)) * solve(start-1, goal, h-1, w, memo)
        };
        let right = if start == w-1 { 0 } else {
            count(start-1) * count((w-1) - (start+2)) * solve(start+1, goal, h-1, w, memo)
        };
        (stay + left + right) % 1_000_000_007
    };
    memo.insert((start, h), ans);
    ans
}

fn main() {
    read!(h = i8, w = i8, k = i8);
    println!("{}", solve(0, k-1, h, w, &mut HashMap::new()));
}

