fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let h: usize = sc.read();
    let w: usize = sc.read();
    let k: usize = sc.read();
    let ptn = vec![1, 1, 2, 3, 5, 8, 13, 21, 34];
    let ptn = ptn.iter().map(|&n| Finite(n)).collect();
    // ptn[w] = 幅 w-1 , 高さ 1 のあみだの総数
    memo!{ cm(100, 8) -> Finite };
    format!("{}\n", clc(cm, h, k, w, &ptn))
}
fn_memo! { clc(cm; r, c ; w:usize, ptn:&Vec<Finite>) -> Finite {
    if r == 0 {
        if c == 1 {
            return Finite(1)
        } else {
            return Finite(0)
        }
    }
    let mut ret = ptn[c-1] * ptn[w-c] * clc(cm, r-1, c, w, ptn) ;
    if c > 1 {
        ret += ptn[c-2] * ptn[w-c] * clc(cm, r-1, c-1, w, ptn);
    }
    if c < w {
        ret += ptn[c-1] * ptn[w-c-1] * clc(cm, r-1, c+1, w, ptn);
    }
    ret
}}

