        for j in 0..w.saturating_sub(2) {
            if (i & 1 << j != 0) && (i & 1 << j + 1 != 0) {
                continue 'outer;
            }
        }
        for j in 0..w {
            if j > 0 && i & 1 << j - 1 != 0 {
                mv[j][j - 1] += 1;
            } else if j + 1 < w && i & 1 << j != 0 {
