use std::collections::HashMap;

const MOD: usize = 1_000_000_007;
const COUNTS: [usize; 8] = [1, 1, 2, 3, 5, 8, 13, 21];

fn solve(
    start: usize, goal: usize, h: usize, w: usize,
    memo: &mut HashMap<(usize, usize), usize>
) -> usize {
    if h == 0 {
        if start == goal { 1 } else { 0 }
    } else if start == 0 || start == w+1 {
        0
    } else {
        memo.get(&(start, h)).cloned().unwrap_or_else(|| {
            let stay = solve(start, goal, h-1, w, memo) *
                COUNTS[start - 1] * COUNTS[w - start];
            let left = solve(start-1, goal, h-1, w, memo) *
                COUNTS[start.saturating_sub(2)] * COUNTS[w - start];
            let right = solve(start+1, goal, h-1, w, memo) *
                COUNTS[start - 1] * COUNTS[w.saturating_sub(start+1)];
            let ans = (stay + left + right) % MOD;
            memo.insert((start, h), ans);
            ans
        })
    }
}

fn main() {
    read!(h = usize, w = usize, k = usize);
    println!("{}", solve(1, k, h, w, &mut HashMap::new()));
}

