const MOD: usize = 1_000_000_007;

fn gen_bits(l: usize) -> Vec<usize> {
    let mut v = vec![];
    for mut i in 0..2_usize.pow(l as u32) {
        let ibuf = i;
        let mut flag = true;
        while i != 0 {
            if i & 3 == 3 {
                flag = false;
                break;
            }
            i >>= 1;
        }
        if flag {
            v.push(ibuf);
        }
    }
    v
}

fn main() {
    let (h, w, k): (usize, usize, usize);
    input!(h, w, k);
    let mut dp = vec![vec![0; w + 2]; h + 2];
    let bitlist = gen_bits(w - 1);
    dp[1][0] = 1;
    for i in 1..h + 1 {
        for j in 0..w + 1 {
            for b in &bitlist {
                if (j == 0 || ((*b >> (j - 1) & 1) == 0)) && (*b >> j) & 1 == 0 {
                    dp[i + 1][j] += dp[i][j];
                    dp[i + 1][j] %= MOD;
                }
            }
        }
        for j in 0..w + 1 {
            for b in &bitlist {
                if j != 0 && (*b >> (j - 1)) & 1 == 1 {
                    if j != 0 {
                        dp[i + 1][j - 1] += dp[i][j];
                        dp[i + 1][j - 1] %= MOD;
                    }
                } else if (*b >> j) & 1 == 1 {
                    dp[i + 1][j + 1] += dp[i][j];
                    dp[i + 1][j + 1] %= MOD;
                }
            }
        }
    }
    println!("{}", dp[h + 1][k - 1]);
}

