const MOD: i64 = 1_000_000_007;

#[derive(Copy, Clone, Hash, Debug)]
struct ModInt {
  x: i64
}
impl ModInt {
  fn new(x: i64) -> Self {
    ModInt {
      x: x % MOD
    }
  }
  fn pow(self, e: i64) -> Self {
    if e == 0 {
      Self::new(1)
    } else if e % 2 == 1 {
      self.pow(e - 1) * self
    } else {
      let y = self.pow(e / 2);
      y * y
    }
  }
  #[allow(dead_code)]
  fn inv(self) -> Self {
    self.pow(MOD - 2)
  }
}
impl<T: Into<ModInt>> std::ops::Add<T> for ModInt {
  type Output = Self;
  fn add(self, other: T) -> Self {
    let other = other.into();
    let sum = self.x + other.x;
    ModInt {
      x: if sum >= MOD { sum - MOD } else { sum }
    }
  }
}
impl<T: Into<ModInt>> std::ops::Sub<T> for ModInt {
  type Output = Self;
  fn sub(self, other: T) -> Self {
    let other = other.into();
    let sum = self.x - other.x;
    ModInt {
      x: if sum < 0 { sum + MOD } else { sum }
    }
  }
}
impl<T: Into<ModInt>> std::ops::Mul<T> for ModInt {
  type Output = Self;
  fn mul(self, other: T) -> Self {
    let other = other.into();
    ModInt {
      x: self.x * other.x % MOD
    }
  }
}
impl<T: Into<ModInt>> std::ops::Div<T> for ModInt {
  type Output = Self;
  fn div(self, other: T) -> Self {
    let other = other.into();
    self * other.inv()
  }
}
impl From<i64> for ModInt {
  fn from(x: i64) -> Self {
    ModInt::new(x)
  }
}
impl std::fmt::Display for ModInt {
  fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
    self.x.fmt(f)
  }
}
impl<T: Into<ModInt>> std::ops::AddAssign<T> for ModInt {
  fn add_assign(&mut self, other: T) {
    *self = *self + other;
  }
}
impl<T: Into<ModInt>> std::ops::SubAssign<T> for ModInt {
  fn sub_assign(&mut self, other: T) {
    *self = *self - other;
  }
}
impl<T: Into<ModInt>> std::ops::MulAssign<T> for ModInt {
  fn mul_assign(&mut self, other: T) {
    *self = *self * other;
  }
}
impl<T: Into<ModInt>> std::ops::DivAssign<T> for ModInt {
  fn div_assign(&mut self, other: T) {
    *self = *self / other;
  }
}

fn valid_row(mut x: u32) -> bool {
  while x > 0 {
    if x & 1 != 0 && x & 2 != 0 {
      return false;
    }
    x >>= 1;
  }
  true
}

fn main() {
  input! {
    h: usize,
    w: usize,
    k: usize1,
  }
  let mut dp = vec![vec![ModInt::new(0); w]; h + 1];
  dp[0][0] = 1.into();
  for r in 0 .. h {
    for lines in 0 .. 1 << (w - 1) {
      if ! valid_row(lines) {
        continue;
      }
      if lines & 1 == 0 {
        dp[r+1][0] += dp[r][0];
      }
      for c in 0 .. w - 1 {
        if (lines >> c) & 1 != 0 {
          dp[r+1][c] += dp[r][c+1];
          dp[r+1][c+1] += dp[r][c];
        } else if (lines >> (c + 1)) & 1 == 0 {
          dp[r+1][c+1] += dp[r][c+1];
        }
      }
    }
  }

  println!("{}", dp[h][k]);
}

const MOD: usize = 1e9 as usize + 7;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let h: usize = sc.read();
    let w: usize = sc.read();
    if w == 1 {
        println!("1");
        return;
    }
    let k: usize = sc.read();
    let mut dp = vec![0; w];
    dp[0] = 1;
    for _ in 0..h {
        let mut next = vec![0; w];
        for mask in 0..(1 << (w - 1)) {
            if (0..(w - 2)).any(|i| mask & (1 << i) != 0 && mask & (1 << (i + 1)) != 0) {
                continue;
            }
            for pos in 0..w {
                let is_left = (1 << pos) & mask != 0;
                let is_right = pos > 0 && (1 << (pos - 1)) & mask != 0;
                let next_pos = if is_left {
                    pos + 1
                } else if is_right {
                    pos - 1
                } else {
                    pos
                };
                next[next_pos] += dp[pos];
                next[next_pos] %= MOD;
            }
        }
        dp = next;
    }
    println!("{}", dp[k - 1]);
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

