const MOD: i64 = 1e+9 as i64 + 7;

fn calc(
    y: usize,
    x: usize,
    pos: usize,
    used: usize,
    memo: &mut Vec<Vec<Vec<Vec<i64>>>>,
    k: usize,
) -> i64 {
    let h = memo.len();
    let w = memo[0].len();
    if y == h {
        return if pos == k { 1 } else { 0 };
    }
    if x == w - 1 {
        return calc(y + 1, 0, pos, 0, memo, k);
    }
    if memo[y][x][pos][used] != -1 {
        return memo[y][x][pos][used];
    }
    let mut ret = 0;
    if used == 0 {
        let npos = match pos {
            _ if pos == x => pos + 1,
            _ if pos == x + 1 => pos - 1,
            _ => pos,
        };
        ret = (ret + calc(y, x + 1, npos, 1, memo, k)) % MOD;
    }
    ret = (ret + calc(y, x + 1, pos, 0, memo, k)) % MOD;
    memo[y][x][pos][used] = ret;
    return ret;
}

fn main() {
    let h = read::<usize>();
    let w = read::<usize>();
    let k = read::<usize>() - 1;
    let mut memo = vec![vec![vec![vec![-1; 2]; w]; w]; h];
    let ans = calc(0, 0, 0, 0, &mut memo, k);
    println!("{}", ans);
}

const MOD: usize = 1_000_000_007;

fn memo(cur_h: usize, cur_w: usize, cur_goal: usize, dp: &mut Vec<Vec<Vec<Option<usize>>>>, limit_h: usize, limit_w: usize, target_goal: usize) -> usize {
    if cur_h >= limit_h {
        if cur_goal == target_goal {
            return 1;
        }
        return 0;
    }
    if let Some(memo_value) = dp[cur_h][cur_w][cur_goal] {
        return memo_value;
    }
    let mut result: usize = 0;
    //use
    {
        let mut next_w = cur_w + 2;
        let mut next_h = cur_h;
        let mut next_goal = cur_goal;
        if next_w >= limit_w {
            next_w = 0;
            next_h += 1;
        }
        let left = cur_w;
        let right = cur_w + 1;
        if left == cur_goal {
            next_goal = right;
        } else if right == cur_goal {
            next_goal = left;
        }

        result += memo(next_h, next_w, next_goal, dp, limit_h, limit_w, target_goal);
        result %= MOD;
    }
    //no use
    {
        let mut next_w = cur_w + 1;
        let mut next_h = cur_h;
        if next_w >= limit_w {
            next_w = 0;
            next_h += 1;
        }
        result += memo(next_h, next_w, cur_goal, dp, limit_h, limit_w, target_goal);
        result %= MOD;
    }
    dp[cur_h][cur_w][cur_goal] = Some(result);
    return result;
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let h: usize = sc.read();
    let w: usize = sc.read::<usize>() - 1;
    let k: usize = sc.read::<usize>() - 1;
    //dp[h][w][goal]
    let mut dp: Vec<Vec<Vec<Option<usize>>>> = vec![vec![vec![None; w + 1]; w + 1]; h + 1];
    let res = memo(0, 0, 0, &mut dp, h, w, k);
    println!("{}", res);
}

