const MOD: usize = 1000000007;
fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (h, w, k): (usize, usize, usize) = parse!(it, 3);
    let mut fns: Vec<Vec<usize>> = vec![];
    'outer: for i in 0..(1 << (w - 1)) {
        let mut prev = false;
        let mut func = (0..w).collect::<Vec<usize>>();
        for j in 0..(w - 1) {
            let flag = i & (1 << j) != 0;
            if prev && flag {
                continue 'outer;
            }
            if flag {
                func.swap(j, j + 1);
            }
            prev = flag
        }
        fns.push(func);
    }
    let mut dp = vec![0; w];
    dp[0] = 1;
    for _ in 0..h {
        let mut new = vec![0; w];
        for func in &fns {
            for i in 0..dp.len() {
                new[func[i]] += dp[i];
                new[func[i]] %= MOD;
            }
        }
        dp = new;
    }
    println!("{}", dp[k - 1]);
}

