const P: i64 = 1_000_000_007;

fn main() {
    // dp[y][x][z][b] :
    // 上から y cm 未満の横棒と、左から x cm 未満の高さ y cm の横棒について、引くか引かないか決まった
    // 高さ y cm において z にいる
    // b = 1 <==> (y, x) の横棒を実際に引いた

    let (H, W, K) = read!(usize, usize, usize);

    let mut dp = vec![vec![vec![vec![0_i64; 2]; W]; W]; H + 1];
    dp[0][0][0][0] = 1;

    for y in 0..H {
        for x in 0..W - 1 {
            for z in 0..W {
                let zz = if z == x {
                    x + 1
                } else if z == x + 1 {
                    x
                } else {
                    z
                };
                dp[y][x + 1][zz][1] += dp[y][x][z][0];
                dp[y][x + 1][zz][1] %= P;

                dp[y][x + 1][z][0] += dp[y][x][z][0];
                dp[y][x + 1][z][0] %= P;
                dp[y][x + 1][z][0] += dp[y][x][z][1];
                dp[y][x + 1][z][0] %= P;
            }
        }

        for z in 0..W {
            dp[y + 1][0][z][0] += dp[y][W - 1][z][0];
            dp[y + 1][0][z][0] %= P;
            dp[y + 1][0][z][0] += dp[y][W - 1][z][1];
            dp[y + 1][0][z][0] %= P;
        }
    }

    // debug!({
    //     for y in 0..H + 1 {
    //         debug!(dp[y])
    //     }
    // });

    println!("{}", dp[H][0][K - 1][0]);
}

fn func(input_str: &str) {
    let mut iter = input_str.split_whitespace();
    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    if w == 1 {
        println!("{}", 1);
        return;
    }
    fn rec(a_s: Vec<usize>, pat_0: &mut Vec<usize>, pat_1: &mut Vec<usize>, w: usize) {
        if a_s.len() == w - 1 {
            for i in 1..(w - 1) {
                if a_s[i - 1] + a_s[i] == 0 {
                    pat_0[i] += 1;
                }
            }
            if a_s[0] == 0 {
                pat_0[0] += 1
            }
            if a_s[w - 2] == 0 {
                pat_0[w - 1] += 1
            }
            for i in 0..(w - 1) {
                if a_s[i] == 1 {
                    pat_1[i] += 1;
                }
            }
        } else {
            if let Some(&last) = a_s.last() {
                if last == 0 {
                    let mut n_a_s = a_s.clone();
                    n_a_s.push(1);
                    rec(n_a_s, pat_0, pat_1, w);
                }
            }
            let mut n_a_s = a_s.clone();
            n_a_s.push(0);
            rec(n_a_s, pat_0, pat_1, w);
        }
    }
    let mut pat_0 = vec![0; w];
    let mut pat_1 = vec![0; w - 1];
    rec(vec![0], &mut pat_0, &mut pat_1, w);
    rec(vec![1], &mut pat_0, &mut pat_1, w);
    let mut cnt_s = vec![vec![0; w]; h + 1];
    cnt_s[0][0] = 1;
    for i in 1..(h + 1) {
        for j in 0..w {
            cnt_s[i][j] += cnt_s[i - 1][j] * pat_0[j];
            cnt_s[i][j] %= 1000000007;
            if j < w - 1 {
                cnt_s[i][j] += cnt_s[i - 1][j + 1] * pat_1[j];
                cnt_s[i][j] %= 1000000007;
            }
            if j > 0 {
                cnt_s[i][j] += cnt_s[i - 1][j - 1] * pat_1[j - 1];
                cnt_s[i][j] %= 1000000007;
            }
        }
    }
    println!("{}", cnt_s[h][k-1]);
}

