const MOD: u64 = 1_000_000_000 + 7;

fn main() {
    let mut scanner = Scanner::new(stdin());
    let param = scanner.read_vector::<usize>().unwrap();
    let (h, w, k) = (param[0], param[1], param[2]);
    let mut dp = vec![vec![0; w]; h + 1];
    dp[0][0] = 1;
    for i in 1..(h + 1) {
        for j in 0..w {
            if j > 0 {
                let mut c = dp[i - 1][j - 1];
                if j > 2 {
                    c = (c * calc_rest(j - 2)) % MOD;
                }
                if j + 2 < w {
                    c = (c * calc_rest(w - j - 2)) % MOD;
                }
                dp[i][j] = c;
            }
            if j < w - 1 {
                let mut c = dp[i - 1][j + 1];
                if j > 1 {
                    c = (c * calc_rest(j - 1)) % MOD;
                }
                if j + 3 < w {
                    c = (c * calc_rest(w - j - 3)) % MOD;
                }
                dp[i][j] += c;
            }
            let mut c = dp[i - 1][j];
            if j > 1 {
                c = (c * calc_rest(j - 1)) % MOD;
            }
            if j + 2 < w {
                c = (c * calc_rest(w - j - 2)) % MOD;
            }
            dp[i][j] += c;
            dp[i][j] %= MOD;
        }
    }
    println!("{}", dp[h][k - 1]);
}

fn calc_rest(mut x: usize) -> u64 {
    let mut sum = 1;
    let mut index = 1;
    while index <= x {
        sum += combi(x, index);
        x -= 1;
        index += 1;
    }
    sum as u64
} 

fn combi(n: usize, r: usize) -> usize {
    if r == 0 || n == r {
        return 1;
    }
    combi(n - 1, r - 1) + combi(n - 1, r)
}

