fn calc_fib(n: usize) -> Vec<usize>{
    let mut v: Vec<usize> = vec![0;n];
    v[0] = 1;
    v[1] = 1;
    for i in 2..n{
        v[i]  += v[i-1] + v[i-2];
    }
    v
}


fn main(){
    let line : Vec<usize> = read_as_vec();
    let (h, w, k) = (line[0], line[1], line[2]);

    let mut dp: Vec<Vec<usize>> = vec![vec![0;w];h+1];
    let fib: Vec<usize> = calc_fib(w+1);
    let m = 1000000007;
    dp[0][0] = 1;

    for i in 1..h+1{
        for j in 0..w{
            if j > 0{
                dp[i][j-1] = (dp[i][j-1] + dp[i-1][j] * (fib[j-1] * fib[w-1-j])) % m;
            }

            dp[i][j] = (dp[i][j] + dp[i-1][j] * (fib[j] * fib[w-1-j])) % m;

            if j < w-1{
                dp[i][j+1] = (dp[i][j+1] + dp[i-1][j] * (fib[j] * fib[w-2-j])) % m;
            }
        }
    }

    println!("{}", dp[h][k-1]);
}

macro_rules! memo{
    ($memo:ident ( $($max_arg:expr),* ) -> $out:ty) => {
        let mut $memo = &mut memo!(inner $out; $($max_arg),*);
    };
    (inner $out:ty; $max_arg:expr) => {
        vec![None as Option<$out>; $max_arg + 1]
    };
    (inner $out:ty; $max_arg:expr, $($ma:expr),*) => {
        vec![memo!(inner $out; $($ma),*); $max_arg + 1]
    };
}
macro_rules! fn_memo{
    ($fun:ident ( $memo:ident; $($param:ident),* ; $($ex_param:ident : $ty:ty),* ) -> $out:ty $body:block) => {
        fn $fun($memo:&mut fn_memo!(inner $out; $($param),*), $($param : usize),* , $($ex_param : $ty),*) -> $out{
            if $memo$([$param])*.is_none() {
                $memo$([$param])* = Some($body);
            }
            $memo$([$param])*.unwrap()
        }
    };
    (inner $out:ty ; $param:ident) => {
        Vec<Option<$out>>
    };
    (inner $out:ty ; $param:ident, $($p:ident),*) => {
        Vec<fn_memo!(inner $out; $($p),*)>
    };
}

