#[proconio::fastout]
fn main() {
    input! {
        H: i128,
        W: usize,
        K: usize
    }
    if W == 1 {
        println!("1");
        return;
    }
    const MOD: i128 = 1_000_000_007;

    let mut positions = vec![0i128; W];
    positions[0] = 1;
    for _y in 0..H {
        let mut row = vec![0i128; W];
        for x in 0usize..(1 << (W - 1)) {
            // 同じ端点を共有してはならない
            if x & (x << 1) != 0  { continue }

            // iビット目が立っているとき、i番目の橋が存在する
            // ここでi番目の橋とは、i番目の線から右に伸びるもの

            for i in 0..W {
                // i番目の橋があるなら
                if x & (1 << i) != 0 {
                    // 右へ
                    row[i + 1] += positions[i];
                    row[i + 1] %= MOD;
                } else if i > 0 && x & (1 << (i - 1)) != 0 {
                    // 左へ
                    row[i - 1] += positions[i];
                    row[i - 1] %= MOD;
                } else {
                    // そのまま下へ
                    row[i]= (row[i] + positions[i]) % MOD;
                }
            }
        }
        positions = row;
    }
    println!("{}", positions[K - 1]);
}

