const M: u64 = 1_000_000_007;

fn main() {
    let mut sc = Scanner::new();
    let h: usize = sc.cin();
    let w: usize = sc.cin();
    let k: usize = sc.cin();

    let mut memo = vec![vec![0_u64; w]; h + 1];
    memo[0][0] = 1;

    let mut table = vec![-1; w];

    for i in 1..h+1 {
        for p in 0..1<<(w-1) {
            let edges: Vec<usize> = (0..w-1).filter(|j| p & (1 << j) > 0).collect();
            let mut valid = true;
            if edges.len() >= 2 {
                for i in 0..edges.len() - 1 {
                    if edges[i] + 1 == edges[i+1] {
                        valid = false;
                        break;
                    }
                }
            }
            if !valid { continue }
            for u in 0..w { table[u] = 0; }
            for &u in edges.iter() {
                table[u] = 1;
                table[u+1] = -1;
            }
            for u in 0..w {
                memo[i][u] +=
                    match table[u] {
                        1 => memo[i-1][u+1],
                        -1 => memo[i-1][u-1],
                        _ => memo[i-1][u]
                    };
                memo[i][u] %= M;
            }
        }
    }
    put!(memo[h][k-1]);
}

