// between $target and $target+1
fn enumerate(w: u64, target: u64, previous: bool) ->u64{
    if w ==1 {
        return 1;
    }


    if !previous {
        if target == w-1{
            return enumerate(w-1, target, true);
        }else{
            return enumerate(w-1, target, true) + enumerate(w-1, target, false);
        }
    }else{
        if target == w-1{
            return 0;
        }else{
            return enumerate(w-1, target, false);
        }
    }
}

