fn main() {
    input!{
        H: usize,
        W: usize,
        K: usize,
    }

    if W == 1 {
        println!("1");
        return;
    }

    const MOD: usize = 1_000_000_007;
    let mut count = vec![0; W];
    count[0] = 1;
    count[1] = 2; // '0' or '1'
    if W > 2 {
        for w in 2..W {
            count[w] 
                = count[w-1]  // '0' + 'ind-1 bits' 
                + count[w-2]; // '1' + '0' + 'ind-2 bits'
        }
    }

    let mut dp = vec![vec![0; W+2]; H+1];
    dp[0][1] = 1;
    for h in 0..H {
        for w in 1..W+1 {
            dp[h+1][w] = 
                dp[h][w-1] * count[w.saturating_sub(3)] * count[(W-w).saturating_sub(1)] +
                dp[h][w]   * count[w.saturating_sub(2)] * count[(W-w).saturating_sub(1)] +
                dp[h][w+1] * count[w.saturating_sub(2)] * count[(W-w).saturating_sub(2)];
            dp[h+1][w] %= MOD;
        }
    }

    println!("{}", dp[H][K]);
}

