fn binary_power(x: u64, n: u64) -> u64 {
    if n == 0 {
      return 1;
    }
    if n % 2 == 0 {
      return (binary_power(x, n / 2) % MOD).pow(2) % MOD;
    } else {
      return binary_power(x, n - 1) % MOD * x % MOD;
    }
}

fn main() {
    let (h, w, k) = input_tuple();
    let mut dp = vec![vec![0; w]; h+1];

    let mut amidas: Vec<Vec<bool>> = Vec::new();
    for bit in 0..1<<(w-1) {
        let mut flag = false;
        let mut prev = false;
        let mut amida = vec![false; w-1];
        for k in 0..w-1 {
            if bit & (1<<k) != 0 {
                if prev {
                    flag = true;
                    break;
                }
                amida[k] = true;
                prev = true;
            } else {
                prev = false;
            }
        }
        if !flag {
            amidas.push(amida);
        }
    }
    // println!("{:?}", amidas);
    dp[0][0] = 1;
    for i in 1..(h+1) {
        for j in 0..w {
            let mut from_left = 0;
            let mut from_center = 0;
            let mut from_right = 0;
            for amida in &amidas {
                if j > 0 {
                    if amida[j - 1] {
                        from_left += 1;
                    }
                } else {
                    if !amida[j] {
                        from_center += 1;
                    }
                }
                if j < w-1 {
                    if amida[j] {
                        from_right += 1;
                    }
                } else {
                    if !amida[j-1] {
                        from_center += 1;
                    }
                }
                if j > 0 && j < w-1 && !amida[j-1] && !amida[j] {
                    from_center += 1;
                }
            }
            // println!("j = {}", j);
            // println!("{}, {}, {}", from_left, from_center, from_right);
            if j > 0 {
                dp[i][j] += dp[i-1][j-1] * from_left;
                dp[i][j] %= MOD;
            }
            dp[i][j] += dp[i-1][j] * from_center;
            dp[i][j] %= MOD;
            if j < w-1 {
                dp[i][j] += dp[i-1][j+1] * from_right;
                dp[i][j] %= MOD;
            }
        }
    }
    // println!("{:?}", dp);
    println!("{}", dp[h][k - 1]);
}

