fn fib(n: usize) -> usize {
    if n == 0 { return 1; }
    match n {
        1|2 => n,
        _ => fib(n-1) + fib(n-2)
    }
}

fn main() {
    input! { h: usize, w: usize, k: usize }

    // dp[h][k]: the number that result in k-th line if amida have been traversed by h-th row
    let mut dp = [[0; 8+1]; 100+1];

    for i in 1..h+1 {
        for j in 1..w+1 {
            if i == 1 {
                if j == 1 || j == 2 { dp[i][j] = fib(w-j); }
            } else {
                // to straight
                if w >= j {
                    dp[i][j] += dp[i-1][j] * fib(j-1) * fib(w-j) % 1_000_000_007;
                }
                // to left
                if w-j >= 1 {
                    dp[i][j] += dp[i-1][j+1] * fib(j-1) * fib(w-j-1) % 1_000_000_007;
                }
                // to right
                if j >= 2 {
                    dp[i][j] += dp[i-1][j-1] * fib(j-2) * fib(w-j) % 1_000_000_007;
                }
            }
        }
    }
    println!("{}", dp[h][k] % 1_000_000_007);
}

