fn main() {
    input! {
    h: usize,
    w: usize,
    t: Usize1
    }
    if w == 1 {
        println!("1");
        return
    }
    let p = 1_000_000_007;
    let mut dp = vec![vec![0; w]; h + 1];
    dp[0][0] = 1;
    for i in 0..h {
        for j in 0..1 << (w - 1) {
            let mut flag = true;
            let mut tmp = vec![0; w];
            for k in 0..(w - 2) {
                if j & 1 << k > 0 && j & 2 << k > 0 {
                    flag = false;
                    break;
                }
            }
            if flag {
                for k in 0..(w - 1) {
                    if j & 1 << k > 0 {
                        tmp[k] = dp[i][k + 1];
                        tmp[k + 1] = dp[i][k];
                    } else {
                        if tmp[k] == 0 {
                            tmp[k] = dp[i][k];
                        }
                        if k == w - 2 {
                            tmp[k + 1] = dp[i][k + 1];
                        }
                    }
                }
            }
            for k in 0..w {
                dp[i + 1][k] += tmp[k];
                dp[i + 1][k] %= p;
            }
        }
    }
    let ans = dp[h][t];
    println!("{}", ans);
}

