pub const M: u64 = 1_000_000_007;

fn main() {
    use std::io::Read;
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;


    // dp[x][k] = x-1までの高さでkに出る通り
    let mut dp = vec![vec![0;w];h+1];
    dp[0][0] = 1u64;
    for y in 0..h {
        for ptn in 0..(1<<(w-1)) {
            let mut incorrect = false;
            if w >= 2 {
                for k in 0..w-2 {
                    if ((ptn >> k) & 1) == 1 && ((ptn >> (k+1)) & 1) == 1 {
                        incorrect = true;
                        break;
                    }
                }
            }
            if incorrect {continue;}

            for x in 0..w {
                let mut x2 = x;
                if ((ptn >> x) & 1) == 1 {
                    x2 += 1;
                } else if x>=1 && ((ptn >> (x-1)) & 1) == 1 {
                    x2 -= 1;
                }
                dp[y+1][x2] += dp[y][x];
                dp[y+1][x2] %= M;
            }
        }
    }
    println!("{}", dp[h][k]);
}

use std::cmp::*;
use std::io::*;
use std::ops::*;
use std::str::FromStr;
use utils::*;

pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (h, w, k) = i.read3::<usize, usize, usize>();
    writeln!(o, "{}", solve(h, w, k - 1)).unwrap();
}
fn solve(h: usize, w: usize, k: usize) -> usize {
    let mut c = (vec![Mod(0); w], vec![Mod(0); w]);
    c.0[0] = Mod(1);

    let m = make_count_map(w);

    for _ in 0..h {
        for i in 0..w {
            let ci = c.0[i];
            // 左へ移動
            if i != 0 {
                c.1[i - 1] += ci * count(&m, i, 2, 1);
            }
            // 直進
            c.1[i] += ci * count(&m, i, 1, 1);

            // 右へ移動
            if i != w - 1 {
                c.1[i + 1] += ci * count(&m, i, 1, 2);
            }
        }
        c = (c.1, c.0);
        for j in 0..w {
            c.1[j] = Mod(0);
        }
    }
    c.0[k].0
}
fn count(m: &[Mod], i: usize, l: usize, r: usize) -> Mod {
    let ls = i;
    let rs = m.len() - 1 - i;
    m[ls - min(l, ls)] * m[rs - min(r, rs)]
}
fn make_count_map(n: usize) -> Vec<Mod> {
    let mut c = Vec::new(); // Vec<(左に線がない場合の数、左に線がある場合の数)>
    c.push((Mod(1), Mod(0)));

    for i in 1..n {
        let p = c[i - 1];
        c.push((p.0 + p.1, p.0));
    }
    let mut r = Vec::new();
    for c in c {
        r.push(c.0 + c.1);
    }
    r
}

mod utils {
    use super::*;

    pub struct CpReader<R: BufRead> {
        r: R,
        s: String,
    }

    macro_rules! fn_read {
        { $f:ident($($t:ident),*) } => {
            #[allow(dead_code)]
            pub fn $f<$($t: FromStr),*>(&mut self) -> ($($t),*) {
                let i = &mut self.read_line().split(' ');
                ($(read_next::<$t,_>(i)),*)
            }
        };
    }

    impl<R: BufRead> CpReader<R> {
        pub fn new(r: R) -> Self {
            CpReader {
                r: r,
                s: String::new(),
            }
        }
        pub fn read_line(&mut self) -> &str {
            self.s.clear();
            self.r.read_line(&mut self.s).unwrap();
            self.s.trim()
        }

        fn_read! { read2(T1, T2) }
        fn_read! { read3(T1, T2, T3) }
        fn_read! { read4(T1, T2, T3, T4) }
        fn_read! { read5(T1, T2, T3, T4, T5) }
    }
    fn read_next<'a, T: FromStr, I: Iterator<Item = &'a str>>(i: &mut I) -> T {
        i.next().unwrap().parse().ok().unwrap()
    }

    #[derive(Clone, Copy)]
    pub struct Mod(pub usize);

    use std::fmt;
    impl fmt::Debug for Mod {
        fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
            write!(f, "{:?}", self.0)
        }
    }

    const MOD_BASE: usize = 1000000007;
    const MOD_INV_POW: usize = 1000000005;

    impl Mod {
        pub fn new(n: usize) -> Self {
            Mod(n % MOD_BASE)
        }
        pub fn pow(self, mut exp: usize) -> Self {
            let mut b = self;
            let mut r = Mod(1);
            while exp != 0 {
                if exp % 2 == 1 {
                    r *= b;
                }
                exp /= 2;
                b = b * b;
            }
            r
        }
        pub fn inverse_element(self) -> Self {
            self.pow(MOD_INV_POW)
        }
    }

    macro_rules! mod_op {
        (($ot:ident, $f:ident), ($ot_a:ident, $f_a:ident), $($rhs:ty : $e:expr,)*) => {
            $(
            impl $ot<$rhs> for Mod {
                type Output = Self;
                fn $f(self, rhs: $rhs) -> Self {
                    ($e)(self, rhs)
                }
            }
            impl $ot_a<$rhs> for Mod {
                fn $f_a(&mut self, rhs: $rhs) {
                    *self = ($e)(*self, rhs)
                }
            }
            )*
        }
    }

    mod_op!(
        (Add, add),
        (AddAssign, add_assign),
        Mod : |l: Mod, r: Mod| Mod::new(l.0 + r.0),
        usize : |l: Mod, r: usize| l + Mod::new(r),
    );

    mod_op!(
        (Mul, mul),
        (MulAssign, mul_assign),
        Mod : |l: Mod, r: Mod| Mod::new(l.0 * r.0),
        usize : |l: Mod, r: usize| l * Mod::new(r),
    );

    mod_op!(
        (Sub, sub),
        (SubAssign, sub_assign),
        Mod : |l: Mod, r: Mod| Mod::new(MOD_BASE + l.0 - r.0),
        usize : |l: Mod, r: usize| l - Mod::new(r),
    );

    mod_op!(
        (Div, div),
        (DivAssign, div_assign),
        Mod : |l: Mod, r: Mod| l * r.inverse_element(),
        usize : |l: Mod, r: usize| l / Mod::new(r),
    );

    // std::cmp::Reverseと同じ
    #[derive(PartialEq, Eq)]
    pub struct RevCmp<T>(pub T);

    impl<T: PartialOrd> PartialOrd for RevCmp<T> {
        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
            other.0.partial_cmp(&self.0)
        }
    }
    impl<T: Ord> Ord for RevCmp<T> {
        fn cmp(&self, other: &Self) -> Ordering {
            other.0.cmp(&self.0)
        }
    }

    pub trait Zero: Add<Output = Self> + Sized + Copy {
        fn zero() -> Self;
    }
    pub trait One: Zero {
        fn one() -> Self;
    }

    macro_rules! impl_zero {
        ($t:ty, $e:expr) => {
            impl Zero for $t {
                fn zero() -> Self {
                    $e
                }
            }
        }
    }
    macro_rules! impl_one {
        ($t:ty, $e1:expr, $e0:expr) => {
            impl One for $t {
                fn one() -> Self {
                    $e1
                }
            }
            impl_zero!($t, $e0);
        };
    }

    impl_one!(usize, 1, 0);
    impl_one!(u32, 1, 0);
    impl_one!(i32, 1, 0);
    impl_one!(f64, 1.0, 0.0);
    impl_one!(Mod, Mod(1), Mod(0));

}

